/** 内置语料：《增删卜易》（野鹤老人，公有领域转录，章节层级+句级段）——由 scripts/kb-build.mjs 生成，勿手改 */
import type { CorpusSection } from '../retriever.js';

export const zengshanbuyiCorpus: CorpusSection[] = [{"segId":"zsby.c1.1","text":"野鹤曰：卜易之道，乃伏羲、文王、周公、孔子四大圣人之心法也。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.2","text":"得其精者可以参天量地；","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.3","text":"粗知其理亦可趋吉避凶。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.4","text":"凡学卜者可以深求，亦可浅学。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.5","text":"浅学者只要先学装卦，知道动变及卦之六冲，卦变六冲看熟用神章中占何人占何事以何爻为用神；","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.6","text":"再看何为旬空、月破及春夏秋冬四时衰旺、生克冲刑即知决断祸福。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.7","text":"假令占功名者得旺官持世，或动爻作官星生合世爻，求名如拾芥耳。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.8","text":"倘遇子孙持世，或子孙动于卦中，不拘占入场占升迁悉如水中捞月。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.9","text":"占求财若得财星持世，或日月动爻作子孙生合世爻，或官鬼持世财动生之，或父母持世财动克之世，皆许求财之易如摘枝耳。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.10","text":"若遇兄弟持世及兄弟爻动于卦中，或世临旬空月破，何异缘木求鱼。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.11","text":"如占一年月令现任官者，宜官星持世，财动生之，皆许吉庆。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.12","text":"若遇官鬼相克，日月动爻作子孙冲克世爻，或作官鬼冲克世爻，或世空世、官破官空，或世动化回头克及子孙持世皆为凶兆。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.13","text":"士民而占流年者，最喜财爻及子孙爻持世，管许一岁亨通。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.14","text":"若遇官鬼持世，得日月动爻作财星生合世爻者，必见灾非。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.15","text":"倘世破世空及鬼动克世多见凶灾。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.16","text":"兄动克世，口舌破财。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.17","text":"以上官府士民占流年者，合世之月则吉，冲世之月则凶。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.18","text":"皆不宜世爻变鬼及化回头之克定见凶危。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.19","text":"又不宜财动化父，父化财爻，鬼化父母必有长上之灾。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.20","text":"弟兄变鬼，鬼变弟兄，防手足之厄。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.21","text":"财化鬼，鬼化财，财化兄，兄化财，主伤克妻妾婢仆。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.22","text":"子化鬼，鬼化子，父化子，子化父，小口有伤。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.23","text":"青龙天喜持世生世而有喜。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.24","text":"虎鬼发动主孝服。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.25","text":"腾蛇朱雀临兄，鬼动而克世者，须防口舌。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.26","text":"玄武临兄，鬼动而克世者，防贼盗及阴人。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.27","text":"如占避讼防非、仇人为害及行江漂海、深入险地旅店孤眠，穷乡僻壤，投寺宿庙，或营中贸易，错买盗物，或见邻家火起，或闻瘟疫流行，防虎狼，防盗寇，或夜行早起，或险偷关，或已入是非之场，心忧祸患，或欲管闲事，恐惹灾非，或人病家以防沾染，或误服毒物恐致伤生，或已定重罪而盼郝，或已得险病病而防危，或问此物此药可以服否，或问歹人烈马伤害我否，凡遇一切防火虑患者，但得子孙持世及子孙动于卦中，或世动变出子孙，或世动化回头相生，或官鬼动以相生，即使身坐虎口，管许安如泰山，唯忌官鬼持世，忧疑不解。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.28","text":"鬼克世灾祸必侵。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.29","text":"世动化鬼及化回头克者，祸已及身，避之不及，唯世爻空者无忧，世爻破者不利。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.30","text":"占病者如自占病，若得世爻旺相或日月动爻生合世爻，或子孙持世，或子孙动于卦中，不拘久病近病，或求神或服药，立保安康。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.31","text":"近病者世值旬空或世动化空，或卦逢六冲及卦变六冲，不须服药，即许安痊。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.32","text":"久病者官鬼持世，遇休囚，或遇日月动爻克世，或值旬空月破，世动化空化破或卦逢六冲，卦变六冲，或世动化鬼及化回头克者，速宜救治，迟者扁鹊难医。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.33","text":"占父母病以父母爻为用神。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.34","text":"若得父爻旺相，或日月动爻生父母，或父动化旺，不拘久病近病，求神服药立见安宁，近病者父爻值旬空，父动化空，或卦逢六冲，不药而痊。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.35","text":"久病者父爻值旬空月破，父动化空、化破，父动化财，财化父母，卦逢六冲，卦变六冲，或父爻休囚又出被日月动爻冲克，为子者须宜急急求医，亲尝汤，勿远离也。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.36","text":"占兄弟病者，若得兄爻旺相，或临日月动爻相生，或动化旺化生，不拘病之远近，立许全安。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.37","text":"近病者，兄爻值旬空及动而化空，卦逢六冲，服药即愈。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.38","text":"久病者兄爻值旬空月破及动而化空化破，卦逢六冲，卦变六冲，兄动化鬼，鬼动化兄，或兄爻休囚被日月动爻冲克，急急服药求神，迟则难调理。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.39","text":"占子孙病者，子孙爻旺相，或临日月，或日月动爻生合，或子孙爻化回头生，化旺，不拘病之新久，服药求神即愈，近病者子孙爻值旬空及动而化空，卦逢六冲，卦变六冲，不药而愈，出痘者不宜六冲，久病者子孙逢旬空月破及动而化空化破，卦逢六冲，卦变六冲，子孙动而化鬼，鬼化子孙，父化子，子化父及日月动爻冲克者，速宜服药，心则难于治矣。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.40","text":"占妻妾病者，以财爻为用神，财爻旺相或临日月，或日月动爻相生，或财爻化子孙及化帝旺者，不拘久病近病，治之即愈，近病者妻财逢旬空及动而化空，或爻逢六冲，卦变六冲，何须服药，即许灾除。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.41","text":"久病者财爻逢旬空月破及动而化空化破，卦逢六冲，卦变六冲，或财动化鬼，鬼化财爻，兄动化财，财化兄弟，名医亦难取效。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.42","text":"凡占三党六亲及官长、师生、婢仆诸人之病，皆于用神章内以取用神。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.43","text":"占朋友、外人以应爻为用神，理之常也，往往多有不验者何也？","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.44","text":"疑因不甚关切，不诚之故耳。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.45","text":"野鹤曰：客有问于予曰：\"据尔之言，占卜极易事也，即如占功名得旺官持世以成名，子孙持世而失望。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.46","text":"占疾病近病逢冲逢空，不药而愈；","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.47","text":"外病逢冲逢空灵丹莫救。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.48","text":"如若得此，显然者自是不难知矣。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.49","text":"倘占疾病不逢六冲，用神不遇旬空，旺不旺而衰不衰，凶不凶而吉不吉。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.50","text":"又如占功名，官与子孙皆不持世，六爻乱动，财父同兴，何以决之？","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.51","text":"\"予曰：尔若垂廉卖卜，每日数卜之占，未必尽得显而易见之卦，凶中藏吉,吉处藏凶者有之，必须奥理深求，细心参悟，尔欲自知趋避者，必然卦不乱占，心无杂念，每遇一事，即刻卜之，神不欺人。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.52","text":"如若间有卦之恍惚，次早洁诚再卜，再遇恍惚，还可再卜，自然响应，只不可心怀两事而占，一念至诚则应，若占两三事者，则不灵也。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.53","text":"又如占疾病更容易耳，一人有病，一家俱可代占，但有一卦爻逢六冲或卦变六冲，或用神值旬空或用神动而化空者即愈，久病逢此者难治。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.54","text":"又如防灾虑患，但得子孙持世，便与霹雳同居，管许安然无恙，有何难耶？","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.55","text":"客曰：再占有渎之，不敢再三，何敢连占几日？","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.56","text":"予曰：因此一语，误尽卜卦之人，岂不闻三人占听二人之言，一事既可三处而占，何妨再占？","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.57","text":"然亦有不可再渎者，以此一事一刻而再占也，须于次日再卜可也。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.58","text":"又有连日亦不可再渎者，如占功名，已得子孙持世，我心不悦，必欲求其官鬼持世而后已，此则谓之再三渎也。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.59","text":"然予亦有见其再三渎者，未见神之不应也，予因少年复功名占过七次，竟有六次而得子孙持世，此乃神不厌我多问而屡报也。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.60","text":"又有厌予多问者，如我问求财卦已明，现有财我心知矣，我再问之神不告矣，而又以我未占之事告我也。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.61","text":"如一日占求财，旺财持世，是我明知辰日得财，次日再占一卦，果于辰日得财否？","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.62","text":"卦得申金兄动而不得，是何说耶？","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.63","text":"及到辰日得财，至申日因他事而破财。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.64","text":"而悟辰日之得财，次日而再问之，神不告矣，报我申日而破财也。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.65","text":"故知再三渎者，神亦不见责而又报我未问之事也，此事极多。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.66","text":"予著此书传后贤之秘法者，无他法也，教学者凡遇卦之恍惚，心若未明，多占无碍，倘卦中已明现，不可再渎。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.67","text":"至于占病者，一人有病，一家俱可代占，自有显然之卦，再者遇事即占，乘此心而未乱，不可多积事情于心，事多心乱即非一念之诚也。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.68","text":"教其深学卜者，后有分占之法及予所辟诸书之谬，宜细味之，此皆予四十余年须臾不离以得之也，实先贤之所未传。","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.69","text":"须宜通前彻尾，细心详悟，自然巧夺天工，参天地之化育，测鬼神之隐微而不难矣！","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c1.70","text":"目录八卦章第—卦象图第二","chapter":"卷首·增删卜易序","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c2.1","text":"元神、忌神、衰旺章第十—五行相生章第十—五行相克章第十二—","chapter":"卷之一·用神、元神、忌神、仇神章第九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c3.1","text":"开行、开店及各色铺面章第七十—","chapter":"卷之四·为贵人奔走，效力求财章第七十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c4.1","text":"病源章第一百零—鬼神章第一百零二延医章第一百零三医卜往治章第一百零四家宅章第一百零五盖造买宅章第一百零六创造宫室章第一百零七修方动土章第一百零八迁居过火章第一百零九","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c5.1","text":"入宅六亲吉凶章第一百一十—","chapter":"卷之四·归宅入火章第一百一十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c6.1","text":"卜得地于何时章第一百二十—","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.1","text":"乾为父、震为长男、坎为中男、艮为少男坤为母、巽为长女、离为中女、兑为少女卦象图第二乾三连“三”连得三爻俱是单，为乾卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.2","text":"(一点为单)坤三断“三三”连得三爻俱是拆，为坤卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.3","text":"(两点为拆)震仰孟“＝：”初爻单，二爻、三爻俱是拆，为震卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.4","text":"艮覆碗“＝：”初爻、二爻俱是拆，三爻单，为艮卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.5","text":"离中虚“一一”初爻单、二爻拆、三爻单，为离卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.6","text":"坎中满“一”初爻拆、二爻单、三爻拆，为坎卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.7","text":"兑上缺“二”初爻、二爻俱是单．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.8","text":"三爻拆，为兑卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.9","text":"巽下断“一一”初爻拆，二爻、三爻俱是单，为巽卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.10","text":"占卦法：占卦时．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.11","text":"首先将三个铜钱平入于手心，两手合扣，问事之人要集中意念，脑子只准专想所要预测之事，反覆摇动手中铜钱，然后将铜钱掷于盘中，看铜钱的背和字的情况。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.12","text":"一个背，两个字，称作“单”．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.13","text":"画乍“′”为少阳。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.14","text":"两个背，一个字，称作“拆”，画作“″”为少阴。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.15","text":"三个背，没有字，称阼“重”，画作“O”为老阳，是变爻。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.16","text":"三个字，没有背，称作“交”，画作“X”为老阴，是变爻。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.17","text":"共摇六次，第一次为初爻，画在卦的最下面，依次上升，第六次为第六爻，画在卦的最上边。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.18","text":"如遇有X、O，再画出变卦来。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.19","text":"现摇一卦为例：第一次摇得一背，画作′；","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.20","text":"二次得两背，画作″；","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.21","text":"三次得三背，画作“O”；","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.22","text":"四次得三字，画作“X”；","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.23","text":"五次得三背，画作“O”；","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.24","text":"六次得两背，画作″；","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.25","text":"六爻′上三爻为外卦五爻O四爻X坎为水三爻O下三爻为内卦二爻″初爻′离为火即得水火既济卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.26","text":"初学点卦时，见到一点，二点容易理解，见到O、X时，可能一时不明白符号的意义，须要细心、慢想。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.27","text":"现以上卦为例，把前卦第三爻“O’改为“′’，成为离中虚卦，为内卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.28","text":"把第四爻“X”改作“″”，第五爻‘O”又改作“′”，成为坎中满卦，为外卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.29","text":"因为离卦为火，坎卦为水，所以此卦成为水火既济。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.30","text":"因为点卦时，由下至上，排卦名时，是由上往下排，此卦上卦为坎，为水，下卦为离，为火，所以此卦卦名为水火既济卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.31","text":"第一次得两背为“拆”，画作“″”，二次得三背为“重”，画作“O”，三次得两背为“拆”，画作“″”，四次得一背为“单”，画作“′”，五次得三了为“交”，画作“X”，六次得—背为“单”，画作“′”。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.32","text":"′X′″O″上三爻外卦“爻”仍算两点，即是离中虚，离为火，下三爻内卦“O”仍第一点，既是坎中满。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.33","text":"坎为水，火在上水在下，卦名为火水未济。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.34","text":"八宫六十四卦卦名：乾宫八卦：(俱属金)乾为天、天风姤、天山遁、天地否、风地观、山地剥、火地晋、火天大有。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.35","text":"坎宫八卦：(俱属水)坎为水、水泽节、水雷屯、水火既济、泽火革、雷火丰、地火明夷、地水师。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.36","text":"艮宫八卦：(属土)艮为山、山火贲、山天大畜、山泽损、火泽睽、天泽履、风泽中孚，风山渐。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.37","text":"震宫八卦：(属木)震为雷、雷地豫、雷水解、雷风恒、地风升、水风井、泽风大过，泽雷随。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.38","text":"巽宫八卦：(属木)巽为风、风天小畜、风火家人、风雷益、天雷无妄，火雷噬嗑，山雷颐，山风蛊。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.39","text":"离宫八卦：(属火)离为火，火山旅，火风鼎，火水未济，山水蒙，风水涣，天水讼、天火同人。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.40","text":"坤官八卦：(属土)坤为地，地雷复，地泽临，地天泰，雷天大壮、泽天夬，水天需，水地比。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.41","text":"兑宫八卦：(属金)兑为泽，泽水困，泽地萃，泽地咸，水山蹇，地山谦，雷山小过，雷泽归妹。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.42","text":"八宫图第三八卦各宫全图：(初学点卦，不会装卦者，须装照此全图装拼、应五行)。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.43","text":"子孙申金、、子孙酉金、世兄弟丑土、、父母午火、世妻财亥水兄弟辰士、世兄弟辰土、兄弟辰土、官鬼寅木、官鬼寅木、官鬼寅木、应妻财子水、妻财子水、应妻财子水、水天需水地比妻财子水、、妻财子水、、应兄弟戌土、兄弟戌土、子孙申金、、世子孙申金、、兄弟辰土、官鬼卯木、、世官鬼寅木、父母巳火、、妻财子水、应兄弟未土、、当年有一朋友宦游之时，野鹤老人以此全图相送，友说：我不知五行焉能断卦？","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.44","text":"答曰：先学点卦，点出卦象看是何卦，即出全图内寻出此卦，照样装排“世”“应”“五行”“六亲”，不用念卦画，不知五行生克之理，亦能决断四宗大事，不管卦中动与不动即照此图内单看世爻。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.45","text":"如占防忧虑患者，若得子孙持世无忧，官鬼持世忧疑难解，须加意防之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.46","text":"占功名者若得官鬼持世即许成名，子孙持世且待时。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.47","text":"占求财妻财持世者必得，兄弟持世者难求。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.48","text":"占病者若得六冲卦近病不药而愈，久病妙药难调。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.49","text":"友问：何以谓之子孙持世?答：子孙与世字同在一爻者即是子孙持世．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.50","text":"倘得官鬼与世字同在一爻者即是官鬼持世，其余兄弟、妻财持世皆由此说。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.51","text":"或问：何谓六冲卦?答：六冲卦者乾为天、坎为水、艮为山、震为雷、巽为风、离为火、坤为地、兑为泽，此八宫第一卦皆是六冲卦，再者天雷无妄、雷天大壮也是六冲卦一共十卦，其余不是。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.52","text":"或问：求官者若得官鬼持世，求名必成，求财者得妻财持世，求财必得，倘若官鬼爻与妻财爻或值旬空月破或被卦中子孙发动以伤官，兄弟发动以伤财，虽遇官鬼持世、妻财持世有何益也。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.53","text":"答：你知五行之理，神早知之，所得之卦，若非凶中藏吉，定是吉中藏凶．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.54","text":"此乃神圣引人以知其奥，自然要看旬空、月破，生克、冲刑，今吾友不知五行之理，神亦早知，如若求名，祷於神曰：功名若成，赐我于官鬼持世。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.55","text":"倘若无望，赐我子孙持世。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.56","text":"如占防忧患，祷於神曰：目下若有祸者，卦得官鬼持世，若能免祸逃灾者，赐我于子孙持世．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.57","text":"所得之卦自然显而易见，若有隐微者即是神变欺人，何以为神？","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.58","text":"况我作此一段简易之法，单欲教其全不知五行之理者学会点卦，即照全图装排就知决断四宗大事。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.59","text":"倘若稍知五行之理者，不可以此为法，务必细读此书卷后何谓空而不空，破而不破，何为墓而不墓，绝而不绝。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.60","text":"何为真反吟假反吟，何谓进不进．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.61","text":"退不退，何为回头克者生，何为回头克者死。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.62","text":"何处可看用神，何处不看用神，何为占此而应彼，何为占远而应近，何为得其法者百占百灵，何为不得其法者百占不验．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.63","text":"伺为元神不生用神，何为忌神无力能害用神．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.64","text":"何处辟诸占者之谬，何处增巧验之奇。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.65","text":"细观种种秘法，方能决事如神。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.66","text":"又问：假令占防灾、虑、患，若得子孙持世自是无忧，若得官鬼持世惊恐必见，若卦中并不现者何以决之?答：一卦不见再占一卦，再若不见他日又占，昔人泥其不敢再占，所以无法。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.67","text":"我见易经有：“三人占听二人之言。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.68","text":"”古人一事既可决于三处，今人何妨再占，余生平以来稍得其奥者全赖多占之力也，事之缓者，迟迟再占，事急者歇歇又占。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.69","text":"不管早晚，不必焚香。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.70","text":"深更半夜亦可占之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.71","text":"只要单为此事而占，不可又占他事，但有心怀两三事而占卦者，非一念之诚，决无灵验。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.72","text":"假令占功名或是官鬼持世，或是子孙持世，得其一者得失已知．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.73","text":"不必占矣，不必厌其子孙持世，务求其官鬼持世而后已，此非理也。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.74","text":"如占求财或是妻财持世或是兄弟持世，得其一者则止，不必再占。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.75","text":"倘一事而与众人同其祸福者，各占一卦决之更易。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.76","text":"即如行舟遇暴风，家中防火烛，人人俱可占之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.77","text":"但有一卦若得子孙持世皆同无患。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.78","text":"又如占疾病，病人自占，若不得六冲卦者一家俱可代占，但有一人得六冲之卦，或系近病或系久病吉凶合了然矣?世人凡有疑难，开口则说求神问卜。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.79","text":"可见欲知未来之吉凶，除卜之外，无他矣。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.80","text":"我习周易有年，所卜之事，感应之理，就如神圣开口说话。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.81","text":"真令人毛骨悚然。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.82","text":"因而不知周易之妙，不念卦书，不得不送此秘诀，试去行之，觅见其灵，从此自肯念书学卜，此法甚善。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.83","text":"你亦可以传人缙绅、士民、行商、坐贾，无人不可。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.84","text":"不用须要全不知五行生克之人方用此法，倘若稍知五行者，神必现隐微之卦，须要先念浑天甲子、六亲歌，占出卦来会装五行六采。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.85","text":"再学变动，卦中必有动爻，动则必变。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.86","text":"即知动变然后再看用神、元神、忌神，知此者即如入周易之门也。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.87","text":"再看四时旺相章、五行相生相克章、五行相冲相合章、旬空月破生旺墓绝章，又如进周易之堂也。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.88","text":"再看后卷各门各类占何事以何法断之，渐渐由浅入深，以得其奥，不须半载工夫，得余数十年之真学也。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.89","text":"今余先点一卦，教尔学看用神及五行生克旺衰之理。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.90","text":"凡问事先写年月日辰，再照六神章中写出六神然后占卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.91","text":"即如占得乾为天卦父母戌土′世兄弟申金′官鬼午火′父母辰土′应妻财寅木′子孙子水′自占吉凶者以世爻为用神，此卦世临戌土，即以此戌土自己之身。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.92","text":"宜于旺相，最怕休囚。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.93","text":"宜逢巳午之火相生，忌寅卯之木而相克，又不宜世爻落空，更不宜世爻临月破。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.94","text":"此世爻戌土有四处生克冲合。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.95","text":"、月建能生克冲合：此卦世爻戌土如在寅卯月占卦，被寅卯之木伤克，即为世爻受伤。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.96","text":"自占吉凶者谓之休囚不利。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.97","text":"若在辰月占卦，辰冲戌土，戌为月破，此谓之世爻逢月破，即如自己身子如破格也，百无所为。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.98","text":"若在巳午月占卦，巳午之火乃是官鬼，能生戌土，谓之火旺土相，世爻逢旺相，诸事可为。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.99","text":"若在未丑月占卦，此两月土旺之时亦能帮扶戌土，此世爻戌土亦谓之旺相，亦以为吉。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.100","text":"若在戌月占卦，世爻戌土而为月建，此旺相以当时也，自占吉凶，诸事享通。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.101","text":"若在申、酉，亥、子月占卦此戌土皆为泄气之时，谓之世爻休囚无力。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.102","text":"此谓之月建能生克、冲合世爻戌土之用神也。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.103","text":"要知何以谓之用神者，自占吉凶用此世爻为主，不说世爻而曰用神，占父母以父母爻为用神。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.104","text":"、日辰能生克冲合此卦世爻戌土，若在寅卯日占卦，寅卯之木能克戌土，此世爻受日辰伤克不利之象。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.105","text":"若在辰日占卦，辰冲戌土，谓之世爻暗动。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.106","text":"若在巳午日占卦，巳午之火即是官鬼能生戌土。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.107","text":"此谓之世爻逢官鬼而生旺，诸事皆吉。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.108","text":"若在未丑日占卦，土遇土而帮扶，此戌土亦为得助。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.109","text":"若在戌日占卦，谓之世爻临日建当令得权。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.110","text":"若在申酉亥子日占卦，此戌土无克无生。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.111","text":"此谓之日建能生克冲合用神也。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.112","text":"、卦中之动爻能生克冲合。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.113","text":"此卦世爻戌土，倘卦中第二爻寅木发动能克戌土，第四爻午火官鬼发动能生戌土第三爻辰土发动能冲戌土，此谓之卦中之动爻能生、克、冲、合用神。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.114","text":"、世爻发动变出之爻能回头生、克、冲、合．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.115","text":"世爻发动，动而必变，变出巳午之火谓之回头生世。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.116","text":"变出寅卯之木谓之回头克世，变出辰土谓之回头冲世，变出卯木谓之合世。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.117","text":"此谓之用神自动变出之爻能生克冲合用神也。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.118","text":"以上四处若得全来生合用神者，诸占全吉。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.119","text":"倘有三处相生一处相克，也以吉断。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.120","text":"若有两处克两处生者，须看旺衰。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.121","text":"生用神之神旺相者则以吉断，克用神之神旺相者可以凶推。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.122","text":"尚遇三处相克一处相生，若得相生之爻旺相者也可断为克处逢凶中得解。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.123","text":"若值休囚者有生之名无生之实，与四处俱来克者同断，诸占大凶。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.124","text":"或问：此卦世爻戌土并无变出寅卯巳午之理?答：他爻多有变出回头生克，借此以为法也。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.125","text":"又问：卯木能克戌土又与戌合，还是以之为合还是以之为克?答：五行相合章注解极明。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.126","text":"又问：此卦乾为天，卦中午火作官星，如何午月午日占卦也以午火作官星何也?答：不拘占得何卦，卦内若以巳午火作官星者，如遇巳午月日占卦，此巳午日也作官星，卦中若以巳午之火作财星者，而巳午月日也作财星，余仿此。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.127","text":"旺相休囚者，四时旺相查之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.128","text":"空破者旬空月破章查之．","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.129","text":"冲合者五行相合章查之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.130","text":"暗动者在暗动查之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.131","text":"回头生回头克者在动变生克章查之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.132","text":"日辰月建者在日辰月建章查之，生克者五行相生，五行相克章查之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.133","text":"生克者五行相生、五行相克章查之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.134","text":"元神者元神章查之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.135","text":"用神、官星者在用神章查之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.136","text":"占父母者以卦中父母爻为用神。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.137","text":"此卦辰、戌两爻俱是父母，若两爻俱动或都不发动，择其旺者为用神。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.138","text":"如一爻动者择其动者为用神。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.139","text":"父母即临辰戌两爻二土，即以土为父母，宜火相生，怕木相克、忌临旬空、月破亦有四处生克冲合，但宜生多克少为吉。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.140","text":"与前世爻相参看。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.141","text":"占室舍、车舟、文章、章奏、都以父母爻为用神，须在用神章细看。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.142","text":"占他人者以应爻为用神，此卦用临辰土，欲其吉者宜四处相生，欲其衰者宜四处冲克。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.143","text":"占兄弟者以兄弟爻为用神。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.144","text":"此卦申金兄弟即为此爻，宜土相生，怕火相克，忌临月破、旬空，也有四处生克，都是多生少克为吉，克多生少为凶。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.145","text":"又云：兄弟爻乃劫财之神。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.146","text":"如占弟兄姐妹之否泰者，宜其生旺不宜临月破旬空。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.147","text":"如占妻、妾、婢、仆及财物者宜克多生少。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.148","text":"更喜逢空逢破，使其不能劫我之财，克我之妻妾、婢、仆。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.149","text":"占妻、妾、婢、仆及占财物都以妻财爻为用神，此卦寅木妻财就是用神。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.150","text":"忌临旬空月破，宜水相生，怕金相克，也有四处生克，多生少克为吉与前同看。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.151","text":"凡占金银、买卖都以妻财为用神，须在用神章中细看。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.152","text":"占子孙者以子孙爻为用神，此卦子水就是用神。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.153","text":"忌临月破、自空，喜金相生、怕土相克。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.154","text":"也有四处生克冲合，宜其克少生多，与前同看。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.155","text":"占他事者以子孙爻为用神者，也从用神章查之。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.156","text":"占功名者以官鬼爻为用神，此卦午火官星即为用神。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.157","text":"此爻最忌逢空、逢破，怕水相克，宜木相生。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.158","text":"也有四处生克与前同看。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.159","text":"占鬼崇、妖蘖、乱臣、贼盗都以官鬼爻为用神，须在用神章细看。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.160","text":"以上所论诸事，后卷都有细法。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.161","text":"恐尔不得其门而入，写此以为纲领，引尔入门也。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.162","text":"知此纲领再细详后卷，各章由浅入深，自入佳境。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.163","text":"前八宫全图都是静爻，然而卦必有动，动则必变，后篇虽有动变章，恐尔不明，再排一变卦为例，尔宜细详。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.164","text":"卦有“O”变出，“O”为重重为阳，阳动变阴。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.165","text":"卦有“X”变出，“X”为交交为阴，阴动变阳。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.166","text":"如得：“泽天夬”变出“天风姤”卦兄弟未土″动兄弟戌土′子孙酉金′世子孙申金′妻财亥水′父母午火′应兄弟辰土′子孙酉金′官鬼寅木′应妻财亥水′妻财子水′动兄弟丑土″世泽天夬，上三爻外卦乃是兑卦，兑为泽，下三爻内卦乃是乾卦，乾为天，泽在上，天在下，即是泽天夬卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.167","text":"从全图内找出泽天夬卦，照样装出世应、五行、六亲然后再看动爻。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.168","text":"上三爻兑卦，第六爻“交”动变出“一”爻，即是兑卦变乾卦为乾为天。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.169","text":"下三爻乾卦初爻动“O”变为“一一”爻，即是乾卦变巽卦为巽为风。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.170","text":"天在上，风在下即为天风姤卦。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.171","text":"在全图内找出天风姤卦，以姤卦初爻之丑土，写在前卦初爻发动子水之旁谓之子孙变出丑土。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.172","text":"以姤卦第六爻之戌土写在前卦六爻发动之旁，即是未土变出戌土。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.173","text":"余爻不动不变不必写出。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c7.174","text":"按六亲者姤卦之丑土、戌土原是父母，今俱写兄弟何也?六亲须照前卦而按前卦泽天夬土为兄弟，所以变卦之丑、戌二土也写兄弟。","chapter":"卷之四·八卦章第一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.1","text":"乾在内：子水、寅木，辰土，乾在外：午火、申金，戌土。","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.2","text":"坎在内，寅木、辰土、午火，坎在外，申金、戌土、子水。","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.3","text":"辰在内：辰土、午火，申金，辰在外：戌土、子水、寅木。","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.4","text":"震在内：于水、寅木、辰土，震在外；","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.5","text":"午火、申金、戌土。","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.6","text":"巽在内：丑土、亥水、酉金，巽在外：未土、巳火、卯木。","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.7","text":"高在内：卯木、丑土、亥水，离在外：酉金、未土、巳火。","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.8","text":"坤在内：未土、巳火，卯木，坤在外：丑土、亥水、酉金。","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.9","text":"兑在内，巳火、卯木、丑土，兑在外：亥水、酉金、未土。","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.10","text":"如得天风姤卦，上三爻是乾卦即乾在外午火申金、戌土戌土一申金一午火一酉金一亥水一丑土下三爻是巽卦即巽在．","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.11","text":"内丑土、亥水、酉金。","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c8.12","text":"点卦由下而上，故装五行也由下而上，余仿此。","chapter":"卷之四·浑天甲子章第四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c9.1","text":"乾兑宫金兄、土父、木财、火鬼、水子。","chapter":"卷之四·六亲歌章第五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c9.2","text":"乾兑宫八卦都属金坎宫水兄、火财、土鬼、金父、木子。","chapter":"卷之四·六亲歌章第五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c9.3","text":"坎宫八卦都属水。","chapter":"卷之四·六亲歌章第五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c9.4","text":"坤艮宫土兄、火父、木鬼、水财、金子。","chapter":"卷之四·六亲歌章第五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c9.5","text":"坤艮宫八卦都属土。","chapter":"卷之四·六亲歌章第五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c9.6","text":"离宫火兄、水鬼、土子、木父，金财。","chapter":"卷之四·六亲歌章第五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c9.7","text":"离宫八卦都属火。","chapter":"卷之四·六亲歌章第五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c9.8","text":"震巽木兄、水父、金鬼、火子、土财。","chapter":"卷之四·六亲歌章第五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c9.9","text":"震巽宫八卦都属木。","chapter":"卷之四·六亲歌章第五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c9.10","text":"如占得乾为天父母戌土、世兄弟申金、官鬼午火、父母辰土、应妻财寅木、子孙一子水、照乾宫金兄、土父、木财、火鬼、水子、装之，所以辰、戌土为父母，申金为兄弟，火为官鬼，木是妻财，水是子孙，余卦仿此。","chapter":"卷之四·六亲歌章第五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c10.1","text":"乾为天“世”在六，天风姤“世”在初，天山遁“世”在二，天地否“世”在三，天地观“世”在四，山地剥“世”在五，火地晋“世”在四，火天大有“世”退在三。","chapter":"卷之四·世应章第六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c10.2","text":"隔世爻两位即是应爻，余卦仿此。","chapter":"卷之四·世应章第六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c11.1","text":"六爻不动则不变，动则必变，“O”为阳动则变“″”，“X’’为阴动则变“′”。","chapter":"卷之四·动变章第七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c11.2","text":"如乾卦初爻动则变为巽卦。","chapter":"卷之四·动变章第七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c11.3","text":"′′′′O″乾卦上下爻动则变为坎卦O″′′O″坤卦中爻动，变为坎卦″″X′″″坤卦中三爻都动变作乾卦如占得水天需卦变天水讼妻财子水″动兄弟戌土′兄弟戌土′子孙申金′子孙申金″世动父母午火′世兄弟辰土′动父母午火″官鬼寅木′兄弟辰土′妻财子水′应动官鬼寅木″应上三爻坎卦即是坎在外卦申金、戌土、子水，所以四爻申金、五爻戌土、六爻子水。","chapter":"卷之四·动变章第七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c11.4","text":"变为乾卦即是乾在外卦午火、申金、戌土所以申金变出午火，子水变出戌土，申爻不动则不变。","chapter":"卷之四·动变章第七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c11.5","text":"变出之爻按六亲者仍照正卦而推，余卦仿此。","chapter":"卷之四·动变章第七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.1","text":"父母爻：占父母即以卦中之父母爻为神。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.2","text":"祖父母伯、叔、姑、姨、父母，凡在我父母之上，或与我父母同辈之亲及师长、妻父母、乳释之父母，三父、人母或仆占主人皆以父母爻为用神。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.3","text":"占天地、城池、墙垣，宅舍、屋宇，舟车、衣服、雨具、绸缎，布匹、章奏、文书及书馆文契也以父母爻为用神，物类亦多在变通，一切庇护我身者是也。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.4","text":"官鬼爻：占功名、官府、雷霆鬼神、妻占夫皆以官鬼爻为用神。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.5","text":"占乱臣贼盗、邪崇也以官鬼爻为用神，物类亦多，一切拘束我身者是也兄弟爻：占兄弟、姐妹、族中兄弟、姑姨、妹夫及结拜兄弟都以兄弟爻为用神。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.6","text":"兄弟乃同类之人，彼得志则欺凌，见财则夺，所以占财物以此为劫神，占谋事以此为阻神、占妻妾、婢仆以此为刑伤克害之神。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.7","text":"占姊丈妹夫以世爻为用神子屡得验。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.8","text":"占妻妾、婢、仆、役，我驱使之人皆以要财爻为用神。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.9","text":"占货财、珠宝、仓库一切使用之财物亦以妻财爻为用神子孙爻；","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.10","text":"占子孙、占女、女婿、侄、甥、门生凡在我子孙辈中皆以子孙爻为用神。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.11","text":"占忠臣、良将、医药、僧、道、兵卒皆以子孙爻为用神。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.12","text":"占六畜、禽兽亦以子孙爻为用神。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c12.13","text":"为制鬼之神、为解忧之神、为剥官之神，诸事见之为喜，独占功名者忌之。","chapter":"卷之四·用神章第八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c13.1","text":"用神，即前各类之用神也。","chapter":"卷之四·用神元神、忌神、仇神章第九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c13.2","text":"元神，生用神之神即为元神。","chapter":"卷之四·用神元神、忌神、仇神章第九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c13.3","text":"忌神克用神之爻也。","chapter":"卷之四·用神元神、忌神、仇神章第九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c13.4","text":"仇神者克元神而生忌神也。","chapter":"卷之四·用神元神、忌神、仇神章第九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c13.5","text":"例：辰月戊申日占父近病，得乾为天变天小畜。","chapter":"卷之四·用神元神、忌神、仇神章第九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c13.6","text":"父母戌土′世妻财卯木′兄弟申金′官鬼巳火′官鬼午火′动父母未土″应父母辰土′应父母辰土′妻财寅木′妻财寅木′子孙子水′子孙子水′世一人持此卦而问余曰：近病逢冲即愈。","chapter":"卷之四·用神元神、忌神、仇神章第九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c13.7","text":"此卦乃系六冲，但父病之甚，再尔看愈于何日?余说此卦辰土、未土、戌土、三重父母爻，当择其旺者而用之，今辰土父母临月建，即用辰土为用神，目下病重者，乃因申日冲寅木而暗动，木动以克辰土。","chapter":"卷之四·用神元神、忌神、仇神章第九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c13.8","text":"彼问：卦中午火发动，寅木虽动，不克辰土。","chapter":"卷之四·用神元神、忌神、仇神章第九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c13.9","text":"余曰：午火虽动化出未土，午与未合，午未相合不生辰土，所以此辰土单受寅木之克，不得午火之生，故此病体沉重，须待丑日冲去未土而午火无合，其土灾退。","chapter":"卷之四·用神元神、忌神、仇神章第九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.1","text":"元神虽生用神，须要旺相，方可生得用神。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.2","text":"元神能生用神者有五：元神旺相或临日月或日月动爻生扶者一也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.3","text":"元神动化回头生及化进神者二也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.4","text":"元神长生帝旺于日辰三也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.5","text":"元神与忌神同动四也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.6","text":"元神旺动临空化空五也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.7","text":"占以临空化空为无用，非也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.8","text":"殊不知动不为空，皆应冲空实空之日而有用也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.9","text":"故以为吉能生用神，此五者乃有力之用神也，诸占皆吉。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.10","text":"例：酉月辛亥日占求财得兑为泽卦变雷水解卦父母未土″世父母戌土″兄弟酉金′动兄弟申金″应子孙亥水′官鬼午火′父母丑土″应官鬼午火″妻财卯木′父母辰土′世官鬼巳火′动妻财寅木″断曰：寅日得见财，亦如心。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.11","text":"彼曰：卯木妻财爻空而月破，又被金克，初爻巳火官虽生世，亥日冲散又化旬空何以为吉。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.12","text":"余曰：神兆机于动，余从来不言散，正因巳火化空，所以目下不见，待甲寅日出空而相见。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.13","text":"寅木之财以生官，官来生世，果于寅日早见木日得财。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.14","text":"元神虽现又有不能生用神者有六：元神休囚，不动或动而休囚又被伤克者一也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.15","text":"元神休囚又逢自空、月破二也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.16","text":"元神休囚动化退神三也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.17","text":"元神衰而又绝四也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.18","text":"元神入三墓五也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.19","text":"元神休囚动而化绝、化克、化破、化散六也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.20","text":"以上元神无力生用神，无用之元神也，虽有如无。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.21","text":"忌神动而克害用神者有五：忌神旺相或遇日月动爻生扶或临日月者一也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.22","text":"忌神动化回头生扶退神者二也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.23","text":"忌神旺动动临空化空三也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.24","text":"忌神长生帝旺与日辰四也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.25","text":"忌神与仇神同动五也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.26","text":"以上之忌神者如斧戟之忌神，诸占大凶。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.27","text":"忌神虽动，不能克用神者有七：忌神休囚不动，而动休囚被日、月动爻克者一也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.28","text":"忌神静临空破二也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.29","text":"忌神入三墓三也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.30","text":"忌神衰动化退神四也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.31","text":"忌神衰而又绝五也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.32","text":"忌神动化绝化破、化克、化散六也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.33","text":"忌神与元神同动七也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.34","text":"此忌神者乃无力之忌神也，诸占化凶为吉。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.35","text":"以上论元神、忌神之有力、无力者，亦要用神有气，倘若用神无根谓之元神有力亦难生，忌神无力何足喜。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.36","text":"例：巳月乙未日自占病得泽风大过变火风鼎卦妻财未土″动子孙巳火′官鬼酉金′动妻财未土″应父母亥水′世官鬼酉金′官鬼酉金′官鬼酉金′父母亥水′父母亥水′世妻财丑土″应妻财丑土″自占病世爻亥水为用神，被未土忌神动而克水，幸得酉金元神亦动，忌神未土反生元神之酉金，金生亥水，接续相生，化凶而为吉。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.37","text":"其如亥水月冲日克，值月破而被克，虽有生扶生之不起，如树无根，寒谷不回春也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.38","text":"果卒于癸卯日，应卯日者冲去元神之日也。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c14.39","text":"此谓之用神无根，元神有力亦难生。","chapter":"卷之四·元神忌神衰旺章第十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c15.1","text":"金生水、水生木、木生火、火生土、土生金。","chapter":"卷之四·五行相生章第十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c15.2","text":"凡用神、元神宜于逢生，月建生、日建生，动爻生、动化回头生。","chapter":"卷之四·五行相生章第十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c15.3","text":"如卯月己卯日弟占兄已得重罪，叩问能救否。","chapter":"卷之四·五行相生章第十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c15.4","text":"得复之震子孙酉金″兄弟戌土″世妻财亥水″子孙申金″兄弟丑土″应动父母午火′兄弟辰土″兄弟辰土″应官鬼寅木″官鬼寅木″妻财子水′世妻财子水′兄弟爻为用神，丑土兄动日月克之，，明现大罪难脱，幸得兄爻丑土化午火父母回头相生，断曰：速速行之。","chapter":"卷之四·五行相生章第十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c15.5","text":"父母化兄爻相生为吉，后蒙恩免死。","chapter":"卷之四·五行相生章第十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c16.1","text":"金克木木克土土克水水克火火克金凡忌神、仇宜于逢克，月克、日克、动爻克用神、化回头克，此四者用神、元神俱逢一克，他处不见生扶者，则为凶兆。","chapter":"卷之四·五行相克章第十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c16.2","text":"占吉事乐极生悲，占凶事须宜急急回避。","chapter":"卷之四·五行相克章第十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c16.3","text":"如卯月戊寅日占父官事已拟重罪得泽地萃卦变天火同人父母未土″动父母戌土′应兄弟酉金′应兄弟申金′子孙亥水′官鬼午火′妻财卯木″动子孙亥水′世官鬼巳火″世父母丑土″父母未土″动妻财卯木′外卦未土父母，卯月克之，内卦亥卯未合成木局又相克制，月克日刑全无助，果至重刑。","chapter":"卷之四·五行相克章第十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c16.4","text":"同日妹占兄官事同此一案亦拟重罪得天地否变天水讼父母戌土′应父母戌土′兄弟申金′兄弟申金′官鬼午火′官鬼午火′世妻财卯木″世官鬼午火″官鬼巳火″动父母辰土′父母未土″妻财寅木″应申金兄爻为用神，巳火鬼动，刑克申金，重罪定矣。","chapter":"卷之四·五行相克章第十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c16.5","text":"幸喜辰日冲动戌土父母暗动生申，克处逢生，若有父母可以救之，后因父年八十，援例恩留免死。","chapter":"卷之四·五行相克章第十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c16.6","text":"圣人作易，令人趋吉避凶，未卜而不知者，是大数也，卜之而神不告，亦大数也，既已卜之，神己先之，明知故犯者，亦不可尽委之于数也、命也。","chapter":"卷之四·五行相克章第十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c17.1","text":"受此处之克，得他处之生，即为克处逢生。","chapter":"卷之四·克处逢生章第十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c17.2","text":"大凡用神、元神克少生多为吉。","chapter":"卷之四·克处逢生章第十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c17.3","text":"忌神者以克少生多为凶，所以忌神宜克不宜生也。","chapter":"卷之四·克处逢生章第十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c17.4","text":"如辰月丙申日占弟癌症业已临危得既济卦变革卦兄弟子水″应官鬼未土″官鬼戌土′父母酉金′父母申金″动兄弟亥水′世兄弟亥水′世兄弟亥水′官鬼丑土″官鬼丑土″子孙卯木′子孙卯木′应断日：月建辰土虽克亥水，兄弟赖申日以生之，又得动爻相生，临危有救，果于本日酉时遇名医救活也，至巳亥日以全生。","chapter":"卷之四·克处逢生章第十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c18.1","text":"六爻安静旺相之爻，可以生得休囚之爻，亦可以克得休囚之爻，盖旺相者有力之人也。","chapter":"卷之四·动静生克章第十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c18.2","text":"例：令春天寅卯月占得坤卦。","chapter":"卷之四·动静生克章第十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c18.3","text":"子孙酉金″世妻财亥水″兄弟丑土″官鬼卯木″应父母巳火″兄弟未土″如占父母巳火为父母，三爻之卯木当春旺相能生巳火，父母既逢春，木相生，父旺能克子孙。","chapter":"卷之四·动静生克章第十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c18.4","text":"如占子孙，子孙衰矣。","chapter":"卷之四·动静生克章第十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c18.5","text":"春木当令能克丑未，二土临兄弟，如占兄弟谓之休囚无气，余仿此。","chapter":"卷之四·动静生克章第十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c18.6","text":"例：令春占得兑卦变归妹卦父母未土″世父母戌土″应兄弟酉金′动兄弟申金″子孙亥水′官鬼午火′父母丑土″应父母丑土″世妻财卯木′妻财卯木′官鬼巳火′官鬼巳火′酉金发动虽则休囚，动而能克旺相之卯木，卯木当令能克丑未二土，今既木被金伤，亦难克土，余仿此。","chapter":"卷之四·动静生克章第十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c19.1","text":"卦有动爻，动而必变，夫变出之爻能生克冲合本位之动爻，不能生克他爻，而他爻与本位之动爻，亦不能生克变爻。","chapter":"卷之四·动变生克冲合章第十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c19.2","text":"例：令子月卯日占得坤卦变火地晋子孙酉金″世动父母巳火′妻财亥水″兄弟未土″兄弟丑土″动子孙酉金′世官鬼卯木″应官鬼卯木″父母巳火″父母巳火″兄弟未土″兄弟未土″应酉金发动，酉为动爻，变出巳火，巳为变爻，变爻之巳火能回头克本位之酉金，并不能克生他爻。","chapter":"卷之四·动变生克冲合章第十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c19.3","text":"四爻之丑土能动而生世爻之酉金，不能生变出之酉金，而变出之酉金亦不能生克他爻。","chapter":"卷之四·动变生克冲合章第十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c19.4","text":"然则变爻谁能制之?惟日月能生之、克之、冲之、令之何也?日月如天，能生克动爻、静爻、变爻、飞爻、伏爻、而诸爻不能伤日月。","chapter":"卷之四·动变生克冲合章第十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c19.5","text":"黄金策曰：爻伤日月，徒受其名。","chapter":"卷之四·动变生克冲合章第十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c19.6","text":"既如此卦子水月建能克世爻变出之巳火。","chapter":"卷之四·动变生克冲合章第十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c19.7","text":"卯为日建能冲变出之酉金是也，余仿此。","chapter":"卷之四·动变生克冲合章第十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.1","text":"正月寅为月建，寅木旺，卯木次之。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.2","text":"二月卯当月建，卯木旺，寅木次之。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.3","text":"正二月木为旺、火为相，其余金火土作休囚。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.4","text":"三月辰为月建辰土旺，丑未之土次之，土生金，金为相，相虽不旺，还有余气。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.5","text":"其余俱作休囚，四月巳为月建，巳火旺、午火次之。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.6","text":"五月午为月建，午火旺，巳火次之，四五月火为旺，土相其余俱作休囚。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.7","text":"六月未为月建，未土旺，辰戌次之，土生金，金为相，火虽衰，但有余气，其余俱作休囚。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.8","text":"七月申为月建，申金旺，酉金次之。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.9","text":"八月酉为月建，酉金旺，申金次之。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.10","text":"七八月金旺，金生水、水为相，其余俱作休囚，九月戌为月建，戌土旺，丑未次之，土生金，金为相，其余俱作休囚。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.11","text":"十月亥为月建，亥水旺、子水次之。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.12","text":"十一月为月建子水旺、亥水次之。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.13","text":"十月十一月水旺，水生木，木为相，其余俱作休囚。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c20.14","text":"十二月丑为月建，丑土旺，辰戌之土次之，土生金，金为相，水虽衰，还有余气，其余俱作休囚。","chapter":"卷之四·四时旺相章第又十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.1","text":"月将即是月建又为月令。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.2","text":"掌一月之权，司三旬之令。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.3","text":"一月三十日内当权得令。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.4","text":"操持万人之提纲，巡察六爻之善恶，能助卦爻之衰弱，能挫爻象之旺强，制服动变之爻，扶起飞伏之用。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.5","text":"月将乃当权之帅，万卜以之为纲领。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.6","text":"爻之衰弱者能生之合之、比之、拱之、扶之，衰而亦旺。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.7","text":"爻之强旺者能冲之克之、刑之、破之，旺而亦衰。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.8","text":"卦有变爻克制动爻者，月建能制变爻。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.9","text":"卦有动爻克制静爻者，月建亦能制服动爻。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.10","text":"用神伏藏被飞神压住者，月建能冲克飞神，生助伏神而为用也，爻逢月合而有用，爻逢月破而无功。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.11","text":"月建合爻为月合，乃有用之爻也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.12","text":"月建冲爻即为月破，乃无用之爻也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.13","text":"月建不入爻亦为有用，月建一入卦愈见刚强。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.14","text":"卦无用神即以月建为用神，不必寻伏神也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.15","text":"月建入卦动而作元神者为福更大，动而作忌神者为祸更深，不入卦者缓之。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.16","text":"爻值月建旺相，当谓逢空不空，逢伤无害。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.17","text":"古有此说，余试不然，在旬内者毕竟为空。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.18","text":"如寅月庚戌日占求财得火天大有官鬼巳火′应父母未土″兄弟酉金′父母辰土′世妻财寅木′子孙子水′断曰：寅木财爻为用神，财爻克世，此财必得，但目下尚空，要到甲寅日出空可得。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.19","text":"若以逢空不空非也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.20","text":"若在旬内还作空亡，待出旬不为空也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.21","text":"逢空不空终非落底之空，逢伤亦伤却有待时之用。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.22","text":"所以用神逢空，勿即指为空，毕竟为空。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.23","text":"但此空者乃目下旬内之空也，待至出空之日则不空也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.24","text":"作忌神者出而为祸，作元神者出而不为福，非比休囚之真空到底而为空也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.25","text":"爻值月建乃为旺矣，或被他爻所克，即谓之逢伤，占病者目下不愈，占事者目下不成，待至冲去伤爻之日则不受其伤矣，病者必愈、事必成。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.26","text":"故曰：逢伤亦伤却有待时之用。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.27","text":"如酉月丙寅日占谒贵得山风蛊变山水蒙兄弟寅木′应兄弟寅木′父母子水″父母子水″妻财戌土″妻财戌土″世官鬼酉金′世动子孙午火″父母亥水′妻财辰土′妻财丑土″兄弟寅木″应世临月建之官，定得面见，但被午火回头之克，须待子日冲去午火方得拜谒，果得见于丙子日，故曰逢伤亦伤却有待时之用。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.28","text":"日绝、日冲、日克，须察别位有生扶。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.29","text":"化绝、化墓、化克，又怕他爻增制克。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.30","text":"爻值月建，墓于日或日建冲克者可以敌之，无吉无凶之象，倘得他爻又动相扶者为吉兆。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.31","text":"恐他爻又来克制用神，虽临月建，亦难敌也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.32","text":"如：寅月丙申日占官之升迁得艮卦变山雷颐官鬼寅木′世官鬼寅木′妻财子水″妻财子水″兄弟戌土″兄弟戌土″世子孙申金′应动兄弟辰土″父母午火″官鬼寅木″兄弟辰土″动妻财子水′应寅木官星持世临月建而旺相，虽被申日冲克，喜申子辰合成水局，以生官，不独无害，定然三月高迁，果于三月升任云南太守，即升者乃因爻得水局生扶，应三月者辰土出空之月也，应云南者，世与官星皆在六爻之故耳。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.33","text":"又如：午月丁未日占弟被讼吉凶得困卦变雷风恒卦。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.34","text":"父母未土″父母戌土″应兄弟酉金′动兄弟申金″子孙亥水′应官鬼午火′官鬼午火″动兄弟酉金′世父母辰土′子孙亥水′妻财寅木″世父母丑土″酉金兄爻为用神，午月克之，未日生之，可以相敌，但不宜又动出午火相克，正所谓最怕他爻增克制。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.35","text":"余曰：午火为月建动于卦中，谓之入卦者更见刚强，又谓之月建作忌神，为祸不浅，大凶之象，又问凶在何时？","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.36","text":"余曰：酉金兄爻化退神，今岁辰年太岁相合，自是无妨恐，退至申年而无路矣，果于本年下狱至申年而重刑。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.37","text":"天象吉者从斯而泰，天象凶者出月遭殃。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.38","text":"克少生多者天象吉也，克多生少者天象凶也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.39","text":"天象虽凶，在月内还许不碍，出此月而受其殃。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.40","text":"用神遇之得福不轻，忌神逢之得祸不浅，此言用神临月建而用神休囚无救者诸占皆凶。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.41","text":"生扶忌神乃助恶而为虐，克制用神乃邀路而截粮。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.42","text":"忌神克害用神得月建克制忌神者名为有救。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.43","text":"若月建反生忌神者助恶为虐也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.44","text":"如用神得元神之生，月建又生元神吉而又吉，倘月建克制元神者如劫神强夺食也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.45","text":"物穷则变，器满则倾。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.46","text":"用神衰遇时则发，即如用神临火，冬占不旺，等到春来则旺矣，谓之物穷则变，又如正月占卦，用神临寅木月建谓之大旺，若到秋季遇金冲克不无破败，故谓之器满则倾。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.47","text":"如：寅月丁酉日占开铺面得艮卦变明夷卦。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.48","text":"官鬼寅木′世动子孙酉金″妻财子水″妻财亥水″兄弟戌土″兄弟丑土″世子孙申金′应妻财亥水′父母午火″兄弟丑土″兄弟辰土″动官鬼卯木′应世临寅木得令，当时目下开张，即许热闹，独嫌日辰克世，世化回头之克，生少克多，又是六冲卦，不吉。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.49","text":"彼曰：我是伙计不同心？","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.50","text":"余曰：鬼在身边须防疾病，伙伴从此变心，受其累，果于六月疾至，八月伙计盗尽。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.51","text":"鸣之于官，分文不复。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.52","text":"此谓之当时旺相无伤，过时有害。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.53","text":"应六月者，木墓于未，伙计变心者，应爻申金秋天当令，而冲克世爻，财被盗尽者，四爻子财落空亡。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.54","text":"逢绝不绝，逢冲不散，日生月克，兼看生扶，日克月生，兼查冲克。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.55","text":"月将当权，其能衰绝？","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.56","text":"旺相如刚，其能冲散？","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.57","text":"月克日生遇帮而愈旺，月生日克逢他削而亦衰。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.58","text":"如午月戊辰日占妹临产吉凶得火地晋官鬼巳火′父母未土″兄弟酉金′世妻财卯木″官鬼巳火″父母未土″应酉金兄爻为用神，月令克之，日建生之，许之无碍，卯日卯时必生，果于次日卯时生，母子平安，应卯时者，酉金与辰日相合。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c21.59","text":"黄金策曰：若逢合住，必待冲开，此月克而日生，无增克制或帮扶也。","chapter":"卷之四·月将章第十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.1","text":"子水、丑土、寅木、卯木、辰土、巳火，午火、未土，申金、酉金、戌土、亥水。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.2","text":"日辰为六爻之主宰，司四时之旺相。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.3","text":"前章言：月令司三旬之令，令于春则生，令于秋则杀，春夏秋冬各令其时，独日辰不然，四时俱旺，操生杀大权与月建同功。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.4","text":"冲旺相之静爻，既为暗动，冲衰弱之静爻为日破，爻之旺而静者冲之则为暗动，愈得其力，爻之衰而静者，冲之则为日破，愈加无用。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.5","text":"冲空即起，冲合即开，爻之衰弱，能生扶合拱，如时雨以滋苗，爻之强旺，能克害刑冲，似秋霜杀草。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.6","text":"爻遇旬空，日辰冲起而有用，谓之冲空则实。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.7","text":"逢合住遇日建以冲开，谓之冲合则散。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.8","text":"他书有云，爻逢月建日冲而不散，是明知当令，不畏日冲，及至讲论祸福不拘旺相休囚，一概俱以散论，最重要者散，独余屡试不验，偏不应乎散，“神兆机于动，动则必验”，不见其散也，旺相者冲之愈强，休囚无气者，间乎有散，亦百中仅一二也。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.9","text":"逢月破而不破，遇冲克而无伤，似与月建同权，中天日丽，旺相之机。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.10","text":"生多克少锦上添花，生少克多，寡不敌众。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.11","text":"既如酉月卯日占卦，爻临卯木谓之逢破不破，假使爻中有动出申酉之金或卯爻动化申酉，此谓之寡不敌众，破亦为破，伤亦为伤．","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.12","text":"如申月戊午日占病得天山遁变天风姤父母戌土′父母戌土′兄弟申金′应兄弟申金′官鬼午火′官鬼午火′应兄弟申金′兄弟酉金′官鬼午火″世动子孙亥水′父母辰土″父母丑土″世世爻午火临日辰，本主旺相，不宜申金月建生亥水回头克世，卒于亥月。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.13","text":"又如：巳月亥日占仆何日回得夬卦变履卦兄弟未土″动兄弟戌土′子孙酉金′世子孙申金′世妻财亥水′父母午火′兄弟辰土′动兄弟丑土″官鬼寅木′应官鬼卯木′应妻财子水′父母巳火′亥水财爻为用神，亥为月破，临日建而不破，不宜重叠四重土动以伤之，谚云：双拳不敌四手，不独难望归期，预防不测，果于午月卯日得信中途已遭害矣。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.14","text":"此章当与月建章参看。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.15","text":"总注：旺之者，爻之帝旺于日月也；","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.16","text":"比之者，爻与日月同也；","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.17","text":"扶之、拱之者爻与日、月同类也；","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.18","text":"墓之、绝之者爻墓绝于日月也。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.19","text":"李我平日：易以爻临日辰莫能散之、莫能空之，谓逢空而不空也，然动逢日冲谓散，既作日辰又有日辰来冲乎？","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.20","text":"旬空者乃旬内之所无也，既是旬空其又有临日辰之事？","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c22.21","text":"故知读书之不足如此。","chapter":"卷之四·日辰章第十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c23.1","text":"甲乙日丙丁日戊日己日庚辛日壬癸日元武青龙朱雀勾陈滕蛇白虎白虎元武青龙朱雀勾陈滕蛇滕蛇白虎元武青龙朱雀勾陈勾陈滕蛇白虎元武青龙朱雀朱雀勾陈滕蛇白虎元武青龙青龙朱雀勾陈滕蛇白虎元武诸书无不以青龙为吉，白虎为凶。","chapter":"卷之四·六神章第十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c23.2","text":"天元赋曰：身旺龙持多吉处。","chapter":"卷之四·六神章第十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c23.3","text":"碎金赋曰：龙动家有喜，虎动家有丧。","chapter":"卷之四·六神章第十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c23.4","text":"卜筮元龟曰：滕蛇白虎忧尊长。","chapter":"卷之四·六神章第十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c23.5","text":"卜筮大全曰：畏口御刀之白虎，喜赴水之青龙。","chapter":"卷之四·六神章第十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c23.6","text":"阅奥章占疾痛滕蛇主死，白虎主丧。","chapter":"卷之四·六神章第十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c23.7","text":"此皆不以五行，竟以六神而断生死。","chapter":"卷之四·六神章第十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c23.8","text":"惟千金赋曰：虎兴而遇吉神不害其吉，龙动而逢凶曜难掩其凶。","chapter":"卷之四·六神章第十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c23.9","text":"此正理也，然则六神而不验耶乎，乃附合之神也，卦之吉者逢龙而更吉，卦之凶者逢白虎而更凶，且元武主盗赋，朱雀主口舌，无不验也，至于家宅坟茔不可少也。","chapter":"卷之四·六神章第十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c23.10","text":"如戊子日占生产，得山地剥变风地观卦朱雀妻财寅木′妻财卯木′青龙子孙子水″世动官鬼巳火′元武父母戌土″父母未土″世白虎妻财卯木″妻财卯木″勾陈官鬼巳火″应官鬼巳火″滕蛇父母未土″父母未土″应子水子孙化绝变鬼，本日落草而亡，却是青龙临子孙，亦可谓之喜耶？","chapter":"卷之四·六神章第十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c23.11","text":"又如申月甲辰日占兄病得屯之震元武兄弟子水″官鬼戌土″世白虎官鬼戌土′应动父母申金″勾陈父母申金″动妻财午火′媵蛇官鬼辰土″官鬼辰土″应朱雀子孙寅木″世子孙寅木″青龙兄弟子水′兄弟子水′子水兄爻为用神，卦中忌神、元神同动，土动生申，申金动而生子水，月建又生子水，至戊申日沉疴复起，其可谓之蛇动死，虎动主丧耶？","chapter":"卷之四·六神章第十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.1","text":"子与丑合、寅与亥合、卯与戌合、辰与酉合、巳与申合，午与未合。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.2","text":"相合法有六：日月合爻者一也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.3","text":"爻与爻合者二也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.4","text":"爻动化合者三也，卦逢六合四也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.5","text":"六冲卦变六合卦五也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.6","text":"六合卦变六合卦六也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.7","text":"日、月合爻者，假令丑月占得坎卦，世爻子水与月建作合是也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.8","text":"爻与爻合者，假令得天风姤卦、世爻丑动化出子水作合是也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.9","text":"卦逢六合者即如天地否卦内外六爻自相和合是也，不动亦是。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.10","text":"六冲卦变六和卦者，假令得乾为天乃是八纯六冲卦，若外卦三爻值动，乃是乾之泰卦，谓之六冲变六合是了。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.11","text":"六合卦变六合者即如占得旅卦变贲卦是也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.12","text":"爻之合者，静而逢合，谓之合起。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.13","text":"动而逢合，合谓之合绊。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.14","text":"爻与爻合谓之合好，爻动化合谓之化扶。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.15","text":"爻静或与日月动爻合者得合而起。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.16","text":"即使爻值休囚亦有旺相之意。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.17","text":"爻动或与日月动爻合者谓之动逢合而绊住，反不能动之意。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.18","text":"爻动与动爻相合，乃得他来合我，与我和好，相助之意。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.19","text":"爻动化出之爻回头相合者，谓之化扶，得他扶助之意。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.20","text":"凡得诸合，诸占皆以为吉，占名成，占利利就，占婚必成，占身发福，占宅兴旺，占风水聚气藏风、占求谋遂心合意，然必用神有气相宜，用若失陷无益。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.21","text":"卜书曰：万事若得三六合，诸事必得久远，有始有终。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.22","text":"但宜吉事逢之，事必就，不宜凶事逢之，事之难结。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.23","text":"如申月丙子日占出门，得明夷小过。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.24","text":"父母酉金″官鬼戌土″兄弟亥水″父母申金″官鬼丑土″世动妻财午火′世兄弟亥水′父母申金′官鬼丑土″妻财午火″子孙卯木′应动官鬼辰土″应世动破，余曰：合住必有事绊，不能动身。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.25","text":"伊曰：因何而阻？","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.26","text":"余曰：卦中子动变鬼，防儿女不安。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.27","text":"彼曰：因小女多病，男家催促成婚，今欲往外求取财物以备妆奁。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.28","text":"余曰：所得何病？","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.29","text":"彼曰：血枯成劳。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.30","text":"余曰：卯木子孙申月绝之，子日刑之，且动而变鬼，恐嫁之不及矣。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.31","text":"后因病重，此人未去，女死辰日，夫应不去者，世动而逢合也，女死辰日者，卯木子孙变辰土之故也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.32","text":"此乃爻之遇合、卦逢六合之验也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.33","text":"余又验其六冲卦变六合者。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.34","text":"如未月丁巳日占已悔婚还可成否得离卦变火山旅兄弟巳火′世兄弟巳火′子孙未土″子孙未土″妻财酉金′妻财酉金′应官鬼亥水′应妻财申金′子孙丑土″兄弟午火″父母卯木′动子孙辰土″世断曰：此卦从来难以吉断，因得屡验六冲变合，散而复聚，离而必合，此婚一定还成，果于次年三月仍成婚。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.35","text":"诸合皆以用神旺者为吉，独此六冲卦变六合得不看用神，竟以吉断。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.36","text":"占婚姻先吴越而后朱陈，占夫妻先参商后必合好，占功名始则艰驻，终顷荣显。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.37","text":"占求谋先难后易，占身命先困后显，占风水巧处奇逢，占家宅先衰后盛。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.38","text":"爻逢六合已为吉兆，动而变六合谓始终而作合也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.39","text":"占风水百代显荣。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.40","text":"占宅舍千秋基业、占婚姻白头相守，占功名仕路亨通，占财帛聚积如山，占兄弟累世同居，宜合吉，不宜合凶，诸占用神临日月者，吉之又吉也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.41","text":"惟占讼狱不利，冤仇难解，及占忧疑怪事，终不开心，占孕胎安，占产难生，若再用神受克，更为凶兆。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.42","text":"如卯月甲寅日占风水得困之节。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.43","text":"父母未土″子孙子水″兄弟酉金′父母戌土′子孙亥水′应动兄弟申金″应官鬼午火″父母丑土″父母辰土′妻财卯木′妻财寅木″世动官鬼巳火′世余曰：占祖茔必有其故，自葬后何事不亨？","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.44","text":"今日之念因何而起？","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.45","text":"明以告我，方敢决断。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.46","text":"彼曰：自葬之后功名屡困，年近五旬，尚无子息，是以问之曰：此茔之有疑否？","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.47","text":"余曰：龙自右脉来，水亦从左而还源，流水不归漕之故耳。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.48","text":"彼曰：何以知之，余曰：亥水子孙化申金生之，申为源流，寅日冲之，若能使水归漕，不至傍流者，明年起用，再拜丹墀，申年定生鳞种，彼曰：长久安泰否？","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.49","text":"申子辰合成水局、巳酉丑合成金局、寅午戌合成火局、亥卯未合成木局。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.50","text":"一卦之内有一爻动而合局者一也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.51","text":"若两爻动一爻不动亦成合局者二也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.52","text":"有内卦初爻、三爻、动而变出爻成三合者三也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.53","text":"又有外四多爻、六爻动、动而变出之爻成三合者四也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.54","text":"然此三合者有凶有吉。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.55","text":"如占功名合成官局谓之官旺,合成财局财旺生官，倘若合成子孙局者乃伤煞之神也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.56","text":"如占求财合成财局者谓之财库；","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.57","text":"合成子孙局者谓之子局生财；","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.58","text":"倘若合成兄弟局者乃破财、耗财、阻隔之神也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.59","text":"如占祖茔、家宅宜父母爻而合局也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.60","text":"如占婚姻、夫妇、宜财官旺而合局。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.61","text":"凡占求谋喜庆之事宜于成局，永远坚牢。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.62","text":"若占官讼、忧疑而合局者，终身团结，其心难于消释，但三合其局者必要世爻在局者为美，若世爻不在于局内，须要局生世爻为吉，局克世爻为凶，三爻若有两爻动，不成局，须待后之补凑合成其局，谓之虚三待用。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.63","text":"一爻明动一爻暗动亦作两爻动。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.64","text":"三合局中若有一空破者，待填满之日月成之。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.65","text":"有一爻入墓者待冲开之日成之。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.66","text":"凡得三合名利婚姻、家宅、风水、用神旺者无不为吉，必要世爻在局为美、若不在于局内须要局生世爻为吉，局克世爻为凶。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.67","text":"如占财，财局生世利于我财，局生应利于他。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.68","text":"占出行用神在三合内被合而留。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.69","text":"占行人用神在三合之内被合不回。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.70","text":"又有内卦外卦而成三合者须分内外。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.71","text":"如占家宅若属外宅不宜外卦克内，若居内宅须宜内卦生外卦，又如占彼此之形者，内卦为我，外卦为他．","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.72","text":"外卦合局而内卦者为吉，克内卦者为凶。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.73","text":"如卯月丁巳日上下两村因田水撕打得离之坤卦。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.74","text":"兄弟巳火′世动妻财酉金″世子孙未土″官鬼亥水″妻财酉金′动子孙丑土″官鬼亥水′应动父母卯木″应子孙丑土″兄弟巳火″父母卯木′动子孙未土″断曰：内卦为我村，亥卯未合成木局，外卦为人村，巳酉丑合金局来克木，幸衰金不克旺木，不足畏也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.75","text":"况系六冲卦变六冲，有人解散必不成讼，后果劝散。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.76","text":"或问：彼此之形，必以世应为主，如何不言世应？","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c24.77","text":"余曰：若无内外合局者，须看世应，今彼此两村即内外两卦人众同心，彼此合局，神之如用灵验显然，故舍世应而不用也，若非卦化六冲，未有不成非也。","chapter":"卷之四·六合章第十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.1","text":"子午相冲、丑未相冲、寅申相冲、卯酉相冲、辰戌相冲、巳亥相冲。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.2","text":"日月冲爻者一也，卦逢六冲二也，六合卦变六冲三也，冲变六冲四也。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.3","text":"动爻变冲五也、爻与爻冲六也。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.4","text":"冲者散也，凡占凶事宜于冲散、占吉事而不宜，必兼用神而言，用神旺虽冲不破，用神失陷凶而又凶，六合卦变六冲卦者，用神旺者始吉终凶，图事难成，有始无终也。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.5","text":"爻冲有五：爻与月冲谓月破。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.6","text":"爻遇日冲为暗动。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.7","text":"休囚而遇日冲谓之日破。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.8","text":"爻遇爻冲谓之相杀也。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.9","text":"如巳月戊戌日占财得风雷益兄弟卯木′应兄弟卯木′应子孙巳火′子孙巳火′妻财未土″妻财未土″妻财辰土″世妻财辰土″世兄弟寅木″兄弟寅木″父母子水′父母子水′辰土财爻持世，因值旬空，戌日冲空填实，本日辰得财。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.10","text":"又如午月丙辰日占出外经商贸易财如何得恒之豫卦妻财戌土″应妻财戌土″官鬼申金″官鬼申金″子孙午火′子孙午火′应官鬼酉金′世动兄弟卯木″父母亥水′动子孙巳火″妻财丑土″妻财未土″世世爻酉金化卯相冲及反复之卦，幸辰日合之，冲中逢合，又得戌土为财，暗动生世，虽则反复不常，却有财利。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.11","text":"果此人去而复反者三次，中途发财。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.12","text":"前曰：爻动化冲，如逢他敌，乃是化回头之克也。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.13","text":"此卦世爻酉金化卯冲世而不克世，又得辰日冲动戌财生世所以为吉。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.14","text":"又如酉月乙未日占子久出不归生死如何得坤卦子孙酉金″世妻财亥水″兄弟丑土″官鬼卯木″应父母巳火″兄弟未土″世持子孙以临月建，未日生之，虽是六冲之卦，此子必归。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.15","text":"果于子年建功卯年得意而归，此应静而逢冲之验也。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.16","text":"又有巳月甲寅日占严师训子得天地否卦变乾卦父母戌土′应父母戌土′世兄弟申金′兄弟申金′官鬼午火′官鬼午火′妻财卯木″世动父母辰土′应官鬼巳火″动妻财寅木′父母未土″动子孙子水′以应为用神，世应相合，应临戌父，巳月生之，乃饱学之士，独嫌卦变六冲，合而变冲，不久之兆，彼问曰：因何事而不久？","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.17","text":"余日：子水子孙值旬空，卦中未土父动，防子孙灾变，后果两月，其子得病，辞师未久而子死矣。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.18","text":"凡得六合变六冲者，诸占先合后离、先亲后疏、先浓后淡，始荣终悴，得而复失成而后败、惟占官非，盗贼事者宜之。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.19","text":"如申月已卯日父子七人俱蒙拿问。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.20","text":"得巽卦变坤卦兄弟卯木′世动官鬼酉金″世子孙巳火′动父母亥水″妻财未土″妻财丑土″官鬼酉金′应动兄弟卯木″应父母亥水′动子孙巳火″妻财丑土″妻财未土″此系卦变巽木化坤土，名为化去不克，当主无妨，只因世爻变鬼，卯木化酉金，木破金克，巳火子孙又化亥水，父子两爻皆被其伤，六冲乱室，一家俱受刑。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c25.21","text":"占法皆以六冲卦宜于官事，喜其冲散，然必看木之大小，又宜兼用神而言，此卦六冲变冲，亦可谓之官事逢冲而散。","chapter":"卷之四·六冲章第二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c26.1","text":"寅刑巳、巳刑申、子刑卯、卯刑午、丑戌相刑、未辰相刑。","chapter":"卷之四·三刑章第二十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c26.2","text":"又云：辰午酉亥谓之自刑，夫三刑者，余屡试之，或因用神休囚又兼他爻犯之，刑者则见凶，而独犯三刑得验者少，占过数十年只验得一卦。","chapter":"卷之四·三刑章第二十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c26.3","text":"如寅月庚申日占子痘症，得风火家人变离卦。","chapter":"卷之四·三刑章第二十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c26.4","text":"兄弟卯木′子孙巳火′世子孙巳火′应动妻财未土″妻财未土″动官鬼酉金′父母亥水′父母亥水′应妻财丑土″世妻财丑土″兄弟卯木′兄弟卯木′断曰：巳火子孙既当春令，子孙旺相许之可治，后死于寅日寅时。","chapter":"卷之四·三刑章第二十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c26.5","text":"后悟月建在寅，日建在申，与巳爻子孙共作三刑，独此一卦，无他爻之伤也，至于子卯、辰戌丑未亦有验者皆附和而为凶也。","chapter":"卷之四·三刑章第二十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c27.1","text":"静爻旺相日辰冲之为暗动，静爻休囚日辰冲之为破，暗动者有喜有忌。","chapter":"卷之四·暗动章第二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c27.2","text":"用神休囚得元神暗动以相生；","chapter":"卷之四·暗动章第二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c27.3","text":"忌神明动于卦中，得元神暗动而生用神，此皆谓之喜也。","chapter":"卷之四·暗动章第二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c27.4","text":"用神休囚无助，若遇忌神克害用神，此皆谓之忌也。","chapter":"卷之四·暗动章第二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c27.5","text":"占以暗动福来而不知，祸来而不觉。","chapter":"卷之四·暗动章第二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c27.6","text":"又曰：吉凶之应于动，有急缓之应，则缓非此论，何当不知不觉，报应亦非缓也。","chapter":"卷之四·暗动章第二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c27.7","text":"即如寅月已未日占女痘得坤之师卦子孙酉金″世子孙酉金″应妻财亥水″妻财亥水″兄弟丑土″兄弟丑土″官鬼卯木″应父母午火″世父母巳火″动兄弟辰土′兄弟未土″官鬼寅木″酉金子孙，虽则春令休囚，得日辰生之，二爻巳火动而克金，得未日冲动丑土，土动生金，花虽密以全生。","chapter":"卷之四·暗动章第二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c27.8","text":"彼曰：目下甚危。","chapter":"卷之四·暗动章第二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c27.9","text":"余曰：不妨，今日未申时有救，果于申时遇明医救治，何当缓也？","chapter":"卷之四·暗动章第二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c28.1","text":"占以日辰而冲动爻，谓之冲散，又以爻动冲爻，亦能冲散，予屡试之，旺相者冲之不散，有气者冲之不散，休囚者间有冲散，亦千百中之一二也，其故何也？","chapter":"卷之四·动散章第二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c28.2","text":"神兆机于动，动必有因。","chapter":"卷之四·动散章第二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c28.3","text":"虽则今日受制，后逢值日而不散也。","chapter":"卷之四·动散章第二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c28.4","text":"如丑月丁酉日占父出外一载无音得风水涣变坎卦。","chapter":"卷之四·动散章第二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c28.5","text":"父母卯木′动官鬼子水″世兄弟巳火′世子孙戌土′子孙未土″妻财申金″兄弟午火″兄弟午火″应子孙辰土′应子孙辰土′父母寅木″父母寅木″卯木父爻发动而生世，又化子水回头生许之，在外平安。","chapter":"卷之四·动散章第二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c28.6","text":"世空者还至交春即归，果于二月得意而回。","chapter":"卷之四·动散章第二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c28.7","text":"此非卯动酉日冲之？","chapter":"卷之四·动散章第二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c28.8","text":"李我平日：黄金策以空亡为重，冲散为轻。","chapter":"卷之四·动散章第二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c28.9","text":"易冒最重冲散，细阅占验多因错课。","chapter":"卷之四·动散章第二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.1","text":"卦变者：变生、变克、变墓、变绝、比和。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.2","text":"予得验者，凡遇卦化克者，不论用神之衰旺皆以凶推。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.3","text":"此乃巽卦变坎卦，巽木变坎水谓之化生，水回头以生木，也即以吉断。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.4","text":"此乃震卦化乾卦，震木变乾金谓之化克，金回头以克木，也即以凶推。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.5","text":"卯月辛巳日来人不言所事。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.6","text":"占得巽卦变乾卦。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.7","text":"伊曰：代卜长辈功名。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.8","text":"余曰：功名须要亲占，代占难取用神，从不敢断，幸此卦而易见，巽木化乾金，即为化回头克，为绝卦也，不必问名，寿命不长，果于削职后七月而终。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.9","text":"又如午月丙寅日占主病，得离卦变坎卦，离火变坎水，回头来克，但因午月火旺，许之冬令必危。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.10","text":"果卒于九月丁亥日。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.11","text":"此皆不看用神之衰旺也。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.12","text":"李我平曰：易冒墓绝章云，日月当令非真，却不知凶事将来，神机早兆，日月当时虽旺，过时则有消，即如此篇，占主病午月得离变坎，目今夏火虽旺，冬来火衰命绝。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.13","text":"易冒反伏章云：（日月非空破，徒往则重。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.14","text":"又曰：半徒往徒未半凶吉），种种疑论，皆非经验。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.15","text":"卦体如人之根本，卦变刑克绝，如树连根出土，目前枝叶虽青，能保长不朽乎？","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.16","text":"当时旺，过时而衰，空破虽虚，填实则应，且半凶半吉之论，难作后人法，此书只以回头克者为凶，见易胃反伏章中之占验，明是回头之克，误作反复休囚。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.17","text":"如寅月癸酉日占长子病。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.18","text":"得震之兑，此非震木化兑金回头之克耶？","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.19","text":"此二卦竟未看出，土遭木克，木被金伤，以震为长男，占长子所以不吉。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c29.20","text":"殊不知卦变回头之克，少女亦难保也，今以彼之占验而谓彼之错误，无他说也。","chapter":"卷之四·卦变生克墓绝章第二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.1","text":"卦有卦变，爻有爻变。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.2","text":"卦变者内外动而反伏者同一卦也。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.3","text":"爻变者内外爻动而反伏者，非同一卦也。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.4","text":"又有外卦反伏而内卦不动者，如观之坤是也。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.5","text":"又有内卦反伏而外卦不动者如巽之观是也内卦反伏，内则不安。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.6","text":"外卦反伏，外则不宁。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.7","text":"内外反伏者，内外不宁之象也。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.8","text":"皆主成而败，败而成，有而即无，无而即有，得而失，失而得，来而去，去而来，散而聚，聚而散，动而思静，静而思动。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.9","text":"占功名者，用爻旺相，迁而又行往他处，去而仍复来。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.10","text":"用神失陷有或降或升，或得或失矣。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.11","text":"占财物聚散不常，买卖经营兴衰往来不定。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.12","text":"占坟墓宅舍，欲迁不迁，或迁之而再迁，或目下就有迁移之事，占以久远之事者目前就有变动。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.13","text":"占天时晴而即雨，雨而又睛。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.14","text":"占婚姻反复难成。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.15","text":"占疾病愈而有病。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.16","text":"占盗贼官非，见而又见。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.17","text":"占出行，行至中途变反，即使到彼，一事无成。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.18","text":"占行人外卦反伏者，用神旺相必归，不然变他处。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.19","text":"在外之人而占家宅者，内卦反伏，家庭人口不安。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.20","text":"占彼此之形势者，内卦反伏，我乱他定，外卦反伏，他乱我定。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.21","text":"反伏卦用神旺相不变冲克者虽则反复，事之必成，第恐用神而化回头之冲克者，即是卦变大凶之象，如卯月壬申日占随官府上任。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.22","text":"得比之井妻财子水″应妻财子水″兄弟戌土′兄弟戌土′世子孙申金″子孙申金″官鬼卯木″世动子孙酉金′父母巳火″动妻财亥水′应兄弟未土″兄弟丑土″断曰：世临官鬼值月建而旺，随去必成，因内卦反伏，事有反复，不宜世爻绝于申日又化回头冲克，此行不吉，不去者为上，后有官府直接得缺，近於贼营，辞而不去，及至官府去后，忽又因他故而随去矣，至七月城破与官府一同被害。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.23","text":"与官府同害者，世爻与官鬼同受酉金之冲克也，不去而又去者，卦得反伏之故也。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.24","text":"又如卯月已亥日占升迁，得临变中孚。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.25","text":"子孙酉金″动官鬼卯木′妻财亥水″应动父母巳火′兄弟丑土″兄弟未土″世兄弟丑土″兄弟丑土″官鬼卯木′世官鬼卯木′父母巳火′父母巳火′应断曰：世临卯木月建之官，又长生于亥日，世与官星同临旺地，许之即升，果于本月闻报，由江西升任山东，未及一载复任江西，应本月升者卯官而值月令升山东者，官临卯木，复任江西者，外卦反伏，去之而复反也。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.26","text":"反伏者有内外伏呤者，内外忧郁呻吟之象。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.27","text":"内卦动变伏吟，内则呻吟，外卦动变伏吟，外则忧郁。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.28","text":"占名者久困官途，淹留任路。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.29","text":"占利者财源耗散，无利可图。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.30","text":"占坟茔宅舍，欲迁而不能，守之而不利。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.31","text":"占口舌官非，事非难解。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.32","text":"占出行总於动移。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.33","text":"占行人在外忧郁．","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.34","text":"占彼此之形势者，内卦为我，外卦为他，内伏吟我心不遂，外伏吟他忌不安。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.35","text":"然伏吟而较反吟者，反吟有冲有克，爻若受克，得祸不轻。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.36","text":"伏吟之卦，用神旺相，冲开之年月，其志则伸，用神休囚，冲开之年月，忧郁不吉。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.37","text":"如申月癸巳占父外任平安。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.38","text":"得到姤之恒卦：父母戌土′动父母戌土″应兄弟申金′动兄弟申金″官鬼午火′应官鬼午火′兄弟酉金′兄弟酉金′世子孙亥水′子孙亥水′父母丑土″世父母丑土″断曰：巳火日辰生父母，当许在任平安，独忧卦得伏吟，乃是不祥之象，任上必有事故，不得意以呻吟也。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.39","text":"彼曰：开地方苗独之变，可有妨碍否？","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.40","text":"余曰：日建生父，他事无碍。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.41","text":"有问：何时归来？","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.42","text":"余曰：伏吟欲归而不能，辰年可归，后知苗独作乱，地方不祥，惊险异常，寅年占卦，辰年缺归，午年又官者，占时遇巳日扶起午火之官，当日亥水克之而不尽，今午火官星值年依然旺矣。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.43","text":"李我平曰：易林补遗有曰，爻有伏吟不吉，术者未闻卦有反吟最凶，占卜家谁觉？","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.44","text":"不看用神之衰旺竟以反吟为畏途，今野鹤此论法，比之井卦，世途冲，事反伏，身受其殃。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c30.45","text":"临之中孚，世官得地，虽反伏，官连迁转，教人之法，何等透澈。","chapter":"卷之四·反伏章第二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.1","text":"甲子旬中戌亥空甲戌旬中申酉空甲申旬中午未空甲午旬中辰巳空甲辰旬中寅卯空甲寅旬中子丑空何谓旬空？","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.2","text":"如甲子至癸酉日为一旬，此十日之内，并无戌亥，以爻逢戌亥为空亡，又名旬空，馀仿此。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.3","text":"旬空之法，诸书论太烦，有真空、假空、动空、冲空、填空、无故自空、有散而空、墓空、绝空、害空、安空、破空。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.4","text":"野鹤曰：旺不为空，动不为空，有日建动爻生扶者不为空，动而化空、伏而旺相皆不为空。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.5","text":"有卦不动为空，爻反伏而被克为空，真空为空，真空即春土、夏金、秋木、三冬逢火是真空。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.6","text":"夫余初学卜，凡遇旬空，无法而断，欲以之为到底全空，却又应乎填实之日，而不空以之为不空，却有到底全空。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.7","text":"后得多占之法，凡遇旬空，命之再占，卦吉者许之出旬而不空，卦得凶者许之空矣。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.8","text":"如辰月乙卯日占求财得家人之贲。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.9","text":"兄弟卯木′兄弟寅木′子孙巳火′应动父母子水″妻财未土″妻财戌土″应父母亥水′父母亥水′妻财丑土″世妻财丑土″兄弟卯木′兄弟卯木′世断曰：丑财持世遇旬空，虽有巳火之生，巳火又化回头之克，不能生丑土之财，此财既无生扶当主难求。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.10","text":"或又因三月之丑土财爻有气，古法有气不为空，不敢竟断，命之再占。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.11","text":"又得暌之损父母巳火′官鬼寅木′应兄弟未土″妻财子水″子孙酉金′世动兄弟戌土″兄弟丑土″兄弟丑土″世官鬼卯木′官鬼卯木′父母巳火′应父母巳火′因得此卦合前卦而决之，竟断曰：财无气矣，不必劳心。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.12","text":"余曰：前卦丑则虽则空而有气，后卦子水财空伏于五爻未土之下，伏而又空，空而被克，知其无财而无疑也，后果全无。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.13","text":"又如子月辛亥日占远行求财得大畜。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.14","text":"官鬼寅木′官鬼寅木′妻财子水″应妻财子水″应兄弟戌土″兄弟戌土″兄弟辰土′兄弟辰土′官鬼寅木′世官鬼寅木′世妻财子水′妻财子水′断曰：世逢寅木，子月亥日俱作财神而生世，有喜。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.15","text":"应爻为地头，世应相生，乃全美之卦，独因世值旬空，若依古法断者，无故自空大凶之兆，故许之而远去始能求财耶，命之再占。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.16","text":"又得明夷之丰父母酉金″官鬼戌土″兄弟亥水″父母申金″世官鬼丑土″世动妻财午火′兄弟亥水′兄弟亥水′官鬼丑土″官鬼丑土″应子孙卯木′应子孙卯木′断曰：此卦与前卦相同，此行大有财发。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.17","text":"断得世爻丑土化午火回头相生，目下月破，行到此头已出月矣，出月而不为破，开春寅卯月，以前卦决者乃世爻出空之月也，逢子亥财生，满心如愿。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.18","text":"彼曰：去得成否？","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.19","text":"余曰：甲寅日世爻出空之日，准行无疑，果于乙卯日起程，后到彼地，寅卯月间，诸事顺心，满载而归。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.20","text":"野鹤曰：多占之法，能消许多疑惑，不然只以前卦决断者，无故自空，如入深渊大凶。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.21","text":"实则旺财生世，腰缠万贯之征。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.22","text":"李我平曰：空亡之说，鬼神不测之妙，似有又无，似无又有，实有到底全空，又有填实不空，此以多占两卦合而决之。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.23","text":"真为泄尽鬼神之机也，天地这理论，皆从空而生。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.24","text":"谓之悬空以待用，凡占遇空，不可即以为空也，然又有中空之日，实空之时，事在一旬之外，许其出空之日而应之，若占远之大事，尚无定期，非旬可以定者，大象不吉，乃可谓到底空也。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c31.25","text":"大象若吉，太岁月建又可填之，然又不如多占两卦，实为妙法。","chapter":"卷之四·旬空章第二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.1","text":"长生、沐浴、冠带、临官、帝旺、衰、病、死、墓、绝、胎、养余得验者，只验生旺墓绝，其馀不验，不必用之。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.2","text":"金长生在巳旺在酉墓在丑绝在寅木长生在亥旺在卯墓在来绝在申土水长生在申旺在子墓在辰绝在巳且如主事爻属木，若在亥日占卦即主事爻长生于亥日。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.3","text":"若在卯日占卦，木旺于卯。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.4","text":"若在未日占卦，木墓于未。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.5","text":"若在申日占卦，木绝于申，其馀仿此。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.6","text":"又如主事爻属木，动而变出亥水者，谓之化长生，动而变出卯木者谓之化旺，动而变出未土者谓之化墓，动而变出申金者谓之化绝，馀仿此。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.7","text":"觉子曰：金虽长生在巳，且宜金爻旺相，或日月动爻生扶，再遇巳日占卦，或是卦中动出巳爻，或是金爻动而化出巳火，皆谓长生。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.8","text":"倘若金爻休囚无气，再遇巳午火多者，烈火煎金，论克不论生也。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.9","text":"金爻虽墓于丑土，若得未土冲动，或卦中土多生金，论生不论墓也。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.10","text":"土爻虽绝於巳，必须休囚无气，又逢巳爻谓之绝。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.11","text":"若土爻旺相，或得日月动爻生扶，再遇巳爻，巳火反能生土，论生不论绝也。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.12","text":"巳爻虽长生於寅，倘日月动爻及变出之爻又逢申金者，谓之三刑，论刑不论生也。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.13","text":"古以土爻长生在申，又曰土长生在寅，无处考证，余以天时考之，常见土临父母。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.14","text":"有申日雨者，亦有子日雨者；","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.15","text":"又见土临子孙，有申日晴者，亦有子日晴者。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.16","text":"故知土长生於申，旺于子，实知土寄生于申而无疑也。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.17","text":"曾於午月已卯日占妻病得震之丰妻财戌土″世动子孙巳火′官鬼申金″妻财未土″世子孙午火′官鬼酉金′妻财辰土″应妻财辰土″兄弟寅木″兄弟寅木″应父母子水′父母子水′辰土财爻为用神，近病逢冲即愈，许之当愈於辰日，不然酉日必愈，后因连日昏沉，竟於子日起床，许辰日愈者，辰土逢值之日也。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.18","text":"许酉日者，辰与酉合动而逢合之日也，今愈子日辰土财爻旺於子也。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.19","text":"李我平曰：生旺墓绝之论，金生在巳，木生在亥，水生在申，火生在寅，四大长生，理之正也。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.20","text":"惟土寄生，未得关入。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.21","text":"法云：火土长生在寅。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.22","text":"知子上是胞胎，此即土寄生於寅。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.23","text":"今五行家戌土生寅己土生酉。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.24","text":"易冒虽曰：唯土之长生不一，山中有坤土生于申，若分阴阳，则戌土生寅已土生寅，实未得其据。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c32.25","text":"此专以天时考证者土长生于申，万古之不易也。","chapter":"卷之四·生旺墓绝章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.1","text":"后值分门各类当用字眼，恐其烦絮，不便全写，只用题头即如后有用神宜旺，不可指定旺于四时，但得用神临日月、或遇日月动爻变爻生扶、或用爻遇长生逢帝旺，皆谓之旺。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.2","text":"用神化吉：凡用神元神动化回头生、化长生、化帝旺、化扶助、化日月皆为化吉。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.3","text":"用神化凶：凡用神原神动化回头克、化绝、化墓、化空、化鬼、化退神皆为化凶。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.4","text":"岁君：即当年太岁。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.5","text":"岁五即卦中第五爻为太岁。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.6","text":"五位：卦中第五位为君位。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.7","text":"易经曰：九五之尊。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.8","text":"古以身为卦身、身世，余试之不验，后遇身者，即以之为世，非卦身，世身。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.9","text":"三墓即用爻入日墓、入动墓、动而化墓，非古法之世墓、身墓、命墓。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.10","text":"主象即定事吉凶之爻。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.11","text":"古法以卦中世爻为主象，又名主事爻。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.12","text":"即如占父母兄弟则卦中父母爻兄弟爻为主事爻，余仿此。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.13","text":"老阴而成少阳谓之变，老阳而成少阴谓之化。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.14","text":"古以变如物消亡而后长出，退而又进。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.15","text":"化如物之生成而后败，进而又退。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.16","text":"化进神、化生旺，虽化亦为吉。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.17","text":"变鬼、变克，虽变亦为凶。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c33.18","text":"各章所言变即是化，化即是变。","chapter":"卷之四·各门类题头总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.1","text":"静而逢值逢冲：如主事爻临子水不动，后逢子日午日而应之，余仿此。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.2","text":"动而逢合逢值：如主事爻临子水发动，后遇丑日子日而应之，余仿此。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.3","text":"太旺者逢墓逢冲：如主事爻临午火，又遇巳火午月日占卦，或卦中巳午爻太多，后逢亥子日应之，又有戌日应之乃火入墓也，余仿此。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.4","text":"衰绝者，遇生遇旺：如主事爻属金，占卦于巳午月日，即是休囚无气，后逢土月日或至秋令当时，则旺矣！","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.5","text":"入三墓俱喜冲开：如主事爻临午火，假使火墓于戌，后逢辰日则应之，余仿此。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.6","text":"遇六合亦宜相击：如主事爻与月作合，或动而化合，吉凶必待冲开之月日应之。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.7","text":"即如主象临子，与丑作合，后逢午未日应之是也，余仿此，月破喜填：如子月占，主事爻临午火，乃为月破。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.8","text":"后逢未日应之，谓之破而逢合。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.9","text":"又有逢午月应之，填实之月，则不破矣！","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.10","text":"旬空最爱填冲：详空亡论章。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.11","text":"大象吉而受克，须待克神受克：如用神临辰土，得日月动爻生扶，乃为大象吉也。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.12","text":"倘被寅卯克害，后逢申酉日冲克克神则吉，余仿此。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.13","text":"大象凶而受克，须防克者逢生：即如前说，用神临辰土，既无日月动爻生扶，乃为大象凶也。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.14","text":"再逢寅卯克制者，后逢寅卯亥日，则凶。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.15","text":"元神来助来扶，贵看用神衰旺，忌神来冲克，须观元气兴衰。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.16","text":"化进神、逢值逢合：如申动酉，乃为进神，为福为祸，有应申月日者，有应巳月日者，余仿此。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.17","text":"化退神、忌值忌冲：如酉化申，乃为退神，为凶为吉，有应申月日者，有应寅日月者，余仿此。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.18","text":"问有应于独发独静：详独发章。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.19","text":"问有应于变爻动爻：如爻临戌土，变出酉金，其吉凶有戌日应者，有酉日应者，余仿此。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.20","text":"勿谓爻之不验，远近当分：远事定之以年月，近事应之于日时。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.21","text":"再问有占远应近，占近应远，占月应年，占日应时，亦所当知。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.22","text":"倘遇卦之不明，再占是一法。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.23","text":"卦有恍惚者，再占一卦，不可妄断。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.24","text":"世空元动，须待元神逢值。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.25","text":"如甲辰旬，占求财，得困之坎，主亥日得财，余仿此。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.26","text":"世衰元静，必然是元气逢冲。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c34.27","text":"如秋占图谋，得困卦后逢巳日成事，余仿此。","chapter":"卷之四·各门类应期总注章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c35.1","text":"游魂卦为各宫之第七卦，如乾宫中之火地晋，坤宫中之水天需。","chapter":"卷之四·归魂游魂章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c35.2","text":"归魂卦为各宫之第八卦，如乾宫中之火天大有，坤宫中之水地比。","chapter":"卷之四·归魂游魂章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c35.3","text":"古以游魂行千里，我行此事而欲久者，游魂而不能久，心无定向，迁改不常。","chapter":"卷之四·归魂游魂章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c35.4","text":"占身命无安家乐业之所，占行人游遍他乡。","chapter":"卷之四·归魂游魂章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c35.5","text":"占出行，行无定止。","chapter":"卷之四·归魂游魂章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c35.6","text":"占家宅，迁变不常，占坟茔，亡灵不能安妥。","chapter":"卷之四·归魂游魂章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c35.7","text":"野鹤曰：须以用神为主，然后以此参之，若舍用神执此而断者，谬也。","chapter":"卷之四·归魂游魂章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c35.8","text":"古以归魂不出疆，诸事拘泥不行，与游魂卦相反而断之，可也。","chapter":"卷之四·归魂游魂章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c35.9","text":"野鹤曰：亦须以用神为主。","chapter":"卷之四·归魂游魂章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c35.10","text":"增删卜易卷之二野鹤老人著楚江李坦我平鉴定湖南李文辉觉子增删男婿陈文吉茂生茹芝山秀仝校","chapter":"卷之四·归魂游魂章第又二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.1","text":"正申、二酉、三戌，四亥、五子、六丑、七寅、八卯、九辰，十巳、十一午、十二未，月建冲之为月破，逐月之破日是也。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.2","text":"诸书皆以用神临月破如悖时也，即是枯根木，逢生生之不起，逢伤更伤者重，虽现于卦，有迹如无，伏于卦中，终莫透露，虽有日辰之生，亦不能生，动而作忌神者不能为害，作变爻者不能伤克动爻。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.3","text":"野鹤曰：余得其验，动则能伤于爻，变则能伤于动，何也？","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.4","text":"事之无吉无凶则不动矣，既动则有祸福之基，目下虽破，出月则不破，今日虽破，实破之日则不破，合之日则不破，近应日远应年月。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.5","text":"惟而不动又无日辰动爻生助者则到底而破矣。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.6","text":"如亥月已丑日占将来有官否。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.7","text":"得兑化讼卦父母未土″世动父母戌土′兄弟酉金′兄弟申金′子孙亥水′官鬼午火′世父母丑土″应官鬼午火″妻财卯木′父母辰土′官鬼巳火′动妻财寅木″应此卦官动而生世，世动化进神，虽然有官之象，但官逢月破，世遇旬空，然空者犹月日辰相冲，冲空则实不为空矣，而破者又无日辰动爻之生，占以日建亦生不起，况无日建动爻以生乎？","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.8","text":"余疑之即无所用，何故动而生世？","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.9","text":"命之再占，又得出水地比卦。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.10","text":"妻财子水″应妻财子水″应兄弟戌土′兄弟戌土′子孙申金″子孙申金″官鬼卯木″世官鬼卯木″世父母巳火″父母巳火″兄弟未土″兄弟未土″断曰：命若无官，官不得生世持世，今即前卦动官相生，后得官临世位，食禄王家终须有日。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.11","text":"彼问：应在何年？","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.12","text":"余曰：前卦官临月破，定于实破之年，果于巳年承袭长房世职，若以月破，百无所用，霄壤之隔也。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.13","text":"又如辰月戊子日占父何日归得乾之夬父母戌土′世动父母未土″兄弟申金′兄弟酉金′世官鬼午火′子孙亥水′父母辰土′应父母辰土′妻财寅木′妻财寅木′应子孙子水′子孙子水′父母持世，破而化空，既无日生，又无动助，以古法断者，作用神而无气，其父不能归也。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.14","text":"余不以此论之，竟断朱雀临父动而持世，卯日有信，午未日必归，果于卯日得信，乙未日到家，应卯日得信者，破而逢合之日也。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.15","text":"应未日归者，父化未土旬空出空之日到也。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.16","text":"古诀用神之论谓之动逢月破，我位既失，化月建，为退之不及。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.17","text":"此卦父爻破而动而化空，竞退以归家。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.18","text":"又如午月癸卯日占后遇功名官鬼寅木′世官鬼卯木′妻财子水″动父母巳火′兄弟戌土″兄弟未土″世子孙申金′应动官鬼卯木″父母午火″父母巳火″兄弟辰土″兄弟未土″应断曰：寅木官星持世被申金动爻克，今年七月必有凶。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.19","text":"彼曰：看因何事。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.20","text":"余曰：应动而克世，必有仇家。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.21","text":"又问：碍于功名否。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.22","text":"余曰：若非子水动爻，去位必矣，幸有子孙接续相生，降级离任而不免耳。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.23","text":"次日，有幕客知易理而问曰：既知子水，接续相生，卜书有云，忌神与原神同动，官与世爻得两生也，今冬高升之兆，如何反说离任。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.24","text":"余曰：子水破而化空，卜书有曰：虽有如无，作原神而无用，余因不依古法，而断神兆机于动，动必有因，所以断之降级而已。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.25","text":"若在冬至月，始有此验，倘在他月，子水而未实破，还不可知。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.26","text":"果于七月，成大非，冬至月事结降级调用。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.27","text":"余彼时，已往他省，复来呼唤，至彼而又卜之。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.28","text":"寅月丙辰日占得地泽临子孙酉金″子孙酉金″妻财亥水″应妻财亥水″应兄弟丑土″兄弟丑土″兄弟丑土″兄弟丑土″官鬼卯木′世官鬼卯木′世父母巳火′父母巳火′余曰：闻得士民保留，巩蒙不必，待子年仍以原品起用，知易理幕客在坐，问曰：九五亥水生官，如何不允。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.29","text":"余曰：被日克，将来子年亥水旺也，又合前卦，五爻子水值太岁而不破，起用无疑。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.30","text":"果于甲子年巳月仍以原品起用专补两任，卯年而开督府。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.31","text":"余劝离荣，公曰：何也？","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.32","text":"余曰：仍以前卦决。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.33","text":"因申金克世，子虽动临破化空，不能生世生官，所以成非构怨。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.34","text":"及子月虽则实破，其力尚轻，虽不至于削职，犹有降级之事。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.35","text":"值子年乃实破之年也，值太岁是以当权起用。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.36","text":"明年辰戌是子水入墓之年，太岁克去子水，申金仍复克世。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.37","text":"有克无生，较昔年之祸更甚，不听，果于辰年三月，条陈虽留万世芳名，而得罪解往矣。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.38","text":"士之辨日破者乃因破而动，勿以此断。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.39","text":"李我平曰：易冒之论，月破动作忌神而无害，动作元神而无用，动逢日辰生之而不起，曰百无所用之卦也。","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c36.40","text":"易林补遗亦曰：如临月破之爻，不拘衰旺，更作凶推，逢生不受，遇克能招，亦谓虽有而如无也，观此艮之观卦，占时而值月破，不能接续相生，勾讼士庭，值月建以填宫，其力尚轻，犹有降罚之事，值太岁而当权仍以原品而起用，至辰而入墓祸匪轻，平生凶吉，关乎一爻月破，岂可谓之有亦如无，毫无所用耶？","chapter":"卷之四·月破章第二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.1","text":"若用神不现，即以日月为用神，倘日月非用神者，则于宫首卦寻之，因本宫首卦，父子财官六亲俱全之故耳，假令占得天风姤卦父母戌土′兄弟申金′官鬼午火′应兄弟酉金′子孙亥水′父母丑土″世若占妻财，取财爻为神，用此姤卦以寅卯木爻为妻财，今六爻无寅卯，即是用神不上卦，如于寅卯月占者，则以日月为用神，倘非寅卯月，须在宫首卦，乾为天卦内寻之。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.2","text":"乾宫首卦乾为天。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.3","text":"父母戌土′世兄弟申金′官鬼午火′父母辰土′应妻财寅木′子孙子水′此卦寅木妻财在二爻，即以此寅木伏于姤卦亥水之下，姤卦二爻之亥水即为飞神，寅木妻财即为伏神，亥水而生寅木，谓之飞来生伏得长生，此用神不现，寻得伏神而遇生扶有用，亦为用神，便作吉断，余仿此。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.4","text":"又如占得天山遁父母戌土′父母戌土′兄弟申金′应兄弟申金′应官鬼午火′官鬼午火′兄弟申金′兄弟申金′官鬼午火″世官鬼午火″世父母辰土″父母辰土″如占子孙，取子孙为用神，此系乾宫卦，水为子孙，今六爻并无亥水，亦是子孙不现，倘在亥子月日占者，即以月日为用神，若非亥子月日亦在乾为天卦内寻之，乾为天初爻之子水子孙以伏于遁卦初爻辰土之下，辰土即是飞神，子水便是伏神，此乃飞来克伏，谓之飞克，伏神遭克害，名为伏神受制，有用亦无用矣，即作凶推，余仿此。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.5","text":"伏神有用者有六：伏神得日月生者一也；","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.6","text":"伏神旺相者二也；","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.7","text":"伏神得飞神生者三也；","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.8","text":"伏神得动爻生者四；","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.9","text":"伏神得遇日月动爻冲克飞神者五也；","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.10","text":"伏神得遇飞神空破休囚墓绝者六也。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.11","text":"黄金策曰：空下伏神，易于引拨，此论近理，但有不独飞神空亡而伏神得出，但得飞神临破休囚入墓而伏神皆易出也，何也？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.12","text":"飞神逢破墓衰空，虽有若无，所以伏神易于出现。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.13","text":"此六皆有用之伏神也，虽曰不现亦如现矣。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.14","text":"又伏神终不得出者有五。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.15","text":"伏神休囚无气者一也；","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.16","text":"伏神被日月冲克者二也；","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.17","text":"伏神被旺相之飞神克者三也；","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.18","text":"伏神墓绝于日月飞爻者四也；","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.19","text":"伏神伏囚值空月破者五也。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.20","text":"此五者乃无用之伏神也，虽有如无，终不能出。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.21","text":"黄金策曰：伏居空地，事于心违。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.22","text":"余得验者，非此论也。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.23","text":"凡用神旺相而遇旬空，出空之日则出矣。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.24","text":"如卯月壬辰日占候文书何日得领，得山火贲卦官鬼寅木′妻财子水″兄弟戌土″应妻财亥水′父母午火/兄弟丑土″官鬼卯木′世午火父母为用神，空而伏于二爻丑土之下，压住难出，许甲午日出空必得，果得于甲午日。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.25","text":"又酉月丙辰日占子病。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.26","text":"得地风升官鬼酉金″父母亥水″子孙午火/妻财丑土″世官鬼酉金′父母亥水′妻财丑土″应黄金策曰：空下伏神，易于引拨，此卦午火子孙伏于丑土之下，丑土旬空伏易出，许午日子孙出现必愈，果于午日起床。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.27","text":"以上用神不现，皆在本宫首卦寻之，古法又有凡得八纯首卦用神若值空破，又在他宫寻之，比如占得乾为天内有用神空破衰绝者，往坤宫寻之，谓之乾坤来往互换，易林补遗又以归魂卦取离宫第四卦也。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.28","text":"野鹤曰：何必如此？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.29","text":"用神衰败则祸福已知矣，为何不再占一卦合断？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.30","text":"余于用神不现，即有伏神亦不用之，再占两卦用神必现。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.31","text":"一日到一宅上见医者满座。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.32","text":"余连见此卦，毛骨松然，有神乎？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.33","text":"占父亥水回头克父，自占病亥水克世，妻占夫亥水克夫，三卦雷同，同如一手推出，今冬之危，扁鹊亦难为矣，余且不言，只以前卦断目前之愈，问请医曰：卦中不得见，列位各见何如？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.34","text":"曰：病势甚险，遂公议一方，对症便好，不然只看阴功德行耳，内有一位冷笑不言，余请问姓，答曰，姓寿，因私问曰：此公之祥，何如？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.35","text":"彼曰：我可治之，不服我药，奈何。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.36","text":"余暗嘱其子曰：太翁之病，须用姓寿者治之。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.37","text":"次早寿姓来谢，余问将来何如？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.38","text":"寿曰：目下不妨，今冬难保。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.39","text":"余曰：公言与数相合，真神医也。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.40","text":"果绝于亥月，余之不取伏神，多占几卦以决祸福而更稳。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.41","text":"即知目前之生，又知将来之死，非多占之力耶？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.42","text":"李我平曰：古法用伏神虽有验，然伏神之衰旺休囚刑冲克害月破旬空亦有难于把握者，此谓多占两卦又有用神，真秘法也，以此之秘，急欲传世，真婆心也。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.43","text":"或曰：多占两卦，虽有诗言，不敢再三，然亦有再占者，何为秘诀？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.44","text":"余曰：既知再占，何故用神不现而寻伏神，伏神无用又寻互卦，互之不得又寻于化，况易冒变互章中所存占验，非惟牵强且错误颇多。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.45","text":"有子月戊寅日占官得困之兑卦父母未土″父母未土″世兄弟酉金′兄弟酉金′子孙亥水′应子孙亥水′官鬼午火″父母丑土″应父母辰土′妻财卯木′妻财寅木″世动官鬼巳火′彼断曰：飞爻午之官已临破矣，巳官伏神长生于寅，至孟春必得升迁。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.46","text":"余断之：黄金策曰，飞爻变爻俱无用神者，始寻伏神。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.47","text":"此卦初爻寅木变出巳火官星，孟春官遇长生，且财爻独发亦生官矣。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.48","text":"不曰变出之官而曰伏神者，何也？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.49","text":"幸次卦伏神变爻皆巳火也。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.50","text":"倘后人遇他卦，亦执此为法，用变爻乎？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.51","text":"非传世教人之法而不取也。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.52","text":"观于化章中之占验更为可笑，有辛卯年丙申子日占存亡妻财卯木′动父母未土″官鬼巳火′兄弟酉金′应父母未土″世动子孙亥水′妻财卯木″妻财卯木″官鬼巳火″官鬼巳火″世父母未土″应父母未土″彼断曰：水为子孙不现，却得丙月辛年，丙辛化水，后至亥月甲辰日申子辰合成水局，亥月而归。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.53","text":"余断曰：世爻未土发动化出亥水子孙，是亥月即见子也，世与子孙亥卯未三合成局，明明父子相逢，何故而取于化？","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c37.54","text":"即使卦中亥水不现，子水日建亦作用神，叠叠用神而不取，左支右吾，以取于化，是误后人，非教后人也。","chapter":"卷之四·飞伏神章第二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.1","text":"进神退神者，爻之动而化也，化进化退，吉凶祸福有喜忌之分，所喜者宜于化进，所忌者宜化退神。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.2","text":"进神亥化子寅化卯巳化午申化酉丑化辰辰化未未化戌退神子化亥卯化寅午化巳酉化申辰化丑未化辰戌化未进神由此而进也，如春天花木枝繁叶茂。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.3","text":"退神由此而退也，如秋天花木渐渐凋零。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.4","text":"申月癸卯日占乡试得恒变大过妻财戌土″应妻财未土″官鬼申金″动官鬼酉金′子孙午火′父母亥水′世官鬼酉金′世官鬼酉金′父母亥水′父母亥水′妻财丑土″妻财丑土″应断曰：酉金官星持世旺相，当时卯日冲之而暗动，又得九五爻上官进神财助生扶，不独今秋折桂，来春占鳌头，果得联捷。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.5","text":"卯月乙丑日占求婚成否子孙巳火′动父母子水″应妻财未土″世动妻财戌土′官鬼酉金′动官鬼申金″妻财辰土″兄弟卯木″世兄弟寅木″应子孙巳火″父母子水′动妻财未土″断曰：财爻持世化进神，巳火子动而生世，但因巳火化子水回头之克，必待午日冲去子水，午火又合世爻，其婚必成，果于午日允婚。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.6","text":"或曰：间爻酉金鬼动，岂无阻耶？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.7","text":"余曰：鬼化退神虽有被阻而无力也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.8","text":"此卦世爻未土财化旬空，古以财化旬空，谓之动日月而空且不能进，此处未土无力，动散而化空，亦能进矣。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.9","text":"酉月甲辰日占自陈何如父母酉金″应父母酉金″兄弟亥水″兄弟亥水″官鬼丑土″官鬼丑土″世妻财午火″世动兄弟亥水′官鬼辰土′动官鬼丑土″子孙寅木″动子孙卯木′应断曰：世化回头之克，官化退神，子孙化进神，三爻皆非吉象，大凶之兆，果于次年革职拿问。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.10","text":"古以动日月化空破谓之不退，此卦官子孙动休囚而化空破，进者进而退者竟退。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.11","text":"丑月丙戌日占父有信至已起程我去迎之可能遇否.子孙子水″动官鬼巳火′父母戌土′动父母未土″兄弟申金″世动兄弟酉金′应兄弟申金′兄弟申金′官鬼午火″官鬼午火″父母辰土″应父母辰土″世父化退神，父已归矣，世化进神而欲去，父爻生世一定相逢，必相会于未日，果得遇未日，应未日，戌父化未，又破又空至未日乃实空实破之日也，若执古法动日月而化空破，谓之退其爻，岂有归来之日也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.12","text":"戌月癸亥日占本年冬今得关差否水泽节变需卦兄弟子水″兄弟子水″官鬼戌土′官鬼戌土′父母申金″应父母申金″世官鬼丑土″动官鬼辰土′子孙卯木′子孙寅木′妻财巳火′世兄弟子水′应丑土官动化进神许丑日必得，果得于丑日。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.13","text":"古以动日月化空破，谓之不进，此卦动非日月而化空破，亦能进也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.14","text":"又如未月丁卯日占功名始得出仕否得火天同人变革卦子孙戌土′应动子孙未土″妻财申金′妻财酉金′兄弟午火′官鬼亥水′世官鬼亥水′世官鬼亥水′子孙丑土″子孙丑土″父母卯木′父母卯木′应余曰：若以古法断者，子孙动克财官，终身而无官也，余许辰年出仕，何也？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.15","text":"戌土子孙孙虽动幸化退神，不克官也，辰年冲去戌土，是以许之，果于辰年得选岂可谓之动空化日月而不退也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.16","text":"又如申月辛卯日占病得泽天夬卦变大壮兄弟未土″兄弟戌土″子孙酉金′世动子孙申金″妻财亥水′父母午火′世兄弟辰土′兄弟辰土′官鬼寅木′应官鬼寅木′妻财子水′妻财子水′应此公因抱危症。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.17","text":"余曰：子孙持世，明日辰日必遇良医，果于次日用针而愈。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.18","text":"或曰：子孙化退神，何其用药亦效？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.19","text":"余曰：动变皆属秋金，当相得令，占近事岂可曰退？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.20","text":"若占久远之事，待休囚之时而退者得也，古以动破散而化日月无阶无路，谬也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.21","text":"又如丑月癸卯日占妻病服药可愈否？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.22","text":"得临之泰子孙酉金″子孙酉金″应妻财亥水″应妻财亥水″兄弟丑土″兄弟丑土″兄弟丑土″动兄弟辰土′世官鬼卯木′世官鬼寅木′父母巳火′妻财子水′断曰：兄动化进，神灵莫拘，其妻死于辰日，此乃兄动临月建而化旬空，亦可谓之不进耶？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.23","text":"又如戌月癸未日占病得乾之夬父母戌土′世动父母未土″兄弟申金′兄弟酉金′世官鬼午火′子孙亥水′父母辰土′应父母辰土′妻财寅木′妻财寅木′应子孙子水′子孙子水′断曰：久病逢冲莫治，又是父爻持世，妙药难医，虽化退神，非病退也，乃精神命脉渐渐消枯之象也，防日月冲破未土而无路矣，果卒于丑月。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.24","text":"又如戌月已卯日占母血崩一年有余得同人变解子孙戌土′应动子孙戌土″妻财申金′动妻财申金″应兄弟午火′兄弟午火′官鬼亥水′世动兄弟午火″子孙丑土″动子孙辰土′世父母卯木′动父母寅木″断曰：卯木父母值临日建，世爻戌土以生申金，金生亥水，丑土化破，非丑土化进神以塞亥水，此父母爻得旺相水生，精血太旺，至丑月土旺，令父母爻既无水养且化退神，正以绝其源，源绝危险，果卒于丑月，此乃父临日建不化空破，亦能退也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.25","text":"又如卯月癸酉日占父母近病得萃之否父母未土″动父母戌土′应兄弟酉金′应兄弟申金′子孙亥水′官鬼午火′妻财卯木″妻财卯木″世官鬼巳火″世官鬼巳火″父母未土″父母未土″断曰：未土父母动化进神，戌值旬空，近病逢空即愈，许次日退灾，果于甲戌出空即愈，此乃父爻休囚而化空也，若以古法动日月化空破尚且不进，今休囚而化空，可得愈耶？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.26","text":"又如辰月癸丑日占病得困变解父母未土″父母戌土″兄弟酉金′动兄弟申金″应子孙亥水′应官鬼午火′官鬼午火″官鬼午火″父母辰土′父母辰土′世妻财寅木″世妻财寅木″断曰：世爻寅木而值旬空，酉金忌神摇于五位，古法谓之避空，余以为谬也，此时逢空，出空一定遭伤，后卒于六月。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.27","text":"应未月者，土爻未土乃世爻之墓，已破，丑日冲开，谓之开墓，以待彼克，而入墓不死也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.28","text":"或问：酉金化退神，如何克木？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.29","text":"余曰：丑土生酉金，旺而不退。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.30","text":"又如辰月乙丑日占妻母病得随之否妻财未土″应动妻财戌土′应官鬼酉金′官鬼申金′父母亥水′子孙午火′妻财辰土″世兄弟卯木″世兄弟寅木″子孙巳火″父母子水′动妻财未土″断曰：子水父爻动化未土回头克父母，上爻未土又化进神以克父，须防戌日，果卒于甲戌日，乃戌土出空之日也，古法散如无也，此卦未土发动，丑日冲之，又化旬空月破，竟不见其散也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.31","text":"又如申月乙卯日占出得屯之节兄弟子水″兄弟子水″官鬼戌土′应官鬼戌土′父母申金″父母申金″应官鬼辰土″官鬼丑土″子孙寅木″世动子孙卯木′兄弟子水′妻财巳火′世断曰：世临寅木动而化进神，合当就行，因系月破，目下未必能行，出月方可，后至亥月方行由燕至粤，次八月归来。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.32","text":"余曰：途中安否？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.33","text":"彼曰：往来托庇平安。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.34","text":"余以子孙化进神知其平安，故问之耳。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.35","text":"夫应亥月行者，破而逢合之月也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.36","text":"此乃动破化日辰，岂可谓之不能进耶?又如辰月已未日占兄何日归来得履之兑兄弟戌土′动兄弟未土″世子孙申金′世子孙酉金′父母午火′妻财亥水′兄弟丑土″兄弟丑土″应官鬼卯木′应官鬼卯木′父母巳火′父母巳火′断曰：兄动化退，已有归志，但因戌逢月破，在外诸事未遂，六月可望，后至戌月方回，乃应实破之月也，此乃动破而变日月，岂可谓之退不及也？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.37","text":"又如辰月乙未日占子病得大有变睽，同时祖又占子孙亦得此卦官鬼巳火′应官鬼巳火′父母未土″父母未土″兄弟酉金′兄弟酉金′世父母辰土′世动父母丑土″妻财寅木′妻财卯木′子孙子水′官鬼巳火′应断曰：父母临月建化退神，此子死于次日。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.38","text":"又如卯月丙寅日衙役占官府升否得解之困妻财戌土″妻财未土″官鬼申金″应动官鬼酉金′子孙午火′父母亥水′应子孙午火″子孙午火″妻财辰土′世妻财辰土′兄弟寅木″兄弟寅木″世断曰：官动化进神，秋来得令必迁，后报升于巳月，应巳月者，动而逢合之月，申金又长生于巳，此乃动日月而化空破，岂可谓之不进耶？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.39","text":"又如巳月乙丑日占试中否得兑之讼父母未土″世动父母戌土′兄弟酉金′兄弟申金′子孙亥水′官鬼午火′世父母丑土″应官鬼午火″妻财卯木′父母辰土′官鬼巳火′动妻财寅木″应断曰：未父化进神，巳火官动而生世，吉兆显然，坐以待报，果于寅日揭榜，中第八名，古法动破散化日月尚不能进，此卦动散化空亦能中矣。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.40","text":"又如未月丁丑日占母路隔千里何时来得火天大有变井官鬼巳火′应动子孙子水″父母未土″动父母戌土′世兄弟酉金′动兄弟申金″父母辰土′世兄弟酉金′妻财寅木′子孙亥水′应子孙子水′动父母丑土″断曰：卦初爻子水化出丑父，子与丑合，被合不来，未父化进神，亦应不来，幸得未土生起酉金兄爻，兄化退神而合世，父母必不来，兄弟必来。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.41","text":"彼曰：有妹无弟。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.42","text":"果于次年三月妹至，此乃兄弟化空，爻空亦能退也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.43","text":"又如未月辛丑日占开金银器皿店得火雷噬嗑化屯卦子孙巳火′动父母子水″妻财未土″世动妻财戌土′应官鬼酉金′动官鬼申金″妻财辰土″妻财辰土″兄弟寅木″应兄弟寅木″世父母子水′父母子水′财爻妻财持世化进，生意兴隆，甲戌日开张，财源茂盛，妻财持世化进神乃久远丰隆之象。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.44","text":"余曰：代尔择甲戌日开张，管许大发，果开市于戌日，至今此店兴盛丰隆，此乃动日月而空，岂可谓之不进耶？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.45","text":"野鹤曰：夫进神之有四：动旺相而化旺，乘势而进，一也；","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.46","text":"动休囚而化休囚，待时而进，二也；","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.47","text":"动爻变爻有一而值衰，待旺相之日而进者，三也；","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.48","text":"动爻变爻有一而空破，待填实之日而进者，四也；","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.49","text":"退神之法有四：动旺相而化旺相或有日月动爻生扶，占近事得时而不退者一也；","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.50","text":"动休囚而化休囚及时而退者二也；","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.51","text":"动爻变爻有一而旺相待休囚之时而退者三也；","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.52","text":"动爻变爻有一而逢空破待填实之日而退者四也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.53","text":"李我平曰：初看易冒，有大进不进不能进祗近理，后见动日月而化空破，无阶无路，谓之不进，故知谬也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.54","text":"动爻既临日月，逢空不空，逢破不破，况化空破？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.55","text":"即日月如天，虽化空破，知浮云之掩日，实空实破之期即是云开雾散，司令当权，何以谓之不进？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.56","text":"又曰：动值破散而变日月谓我位既失，何以得前？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.57","text":"殊不知既动而破，自有实破之期，既动而散，自有填实之日，况化日月，名为化旺，后日填实愈旺强，何以谓之不前？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.58","text":"伊存格式：申月卯日占兄弟得兑之丰父母未土″世父母戌土″兄弟酉金′动兄弟申金″世子孙亥水′官鬼午火′父母丑土″应动子孙亥水′妻财卯木′动父母丑土″应官鬼巳火′妻财卯木′酉爻兄弟被卯日冲，虽化申为月建，亦不及退，不退者，建也，不及退者，谬也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.59","text":"彼日月将章云：爻临月将，逢散不散，七月之酉金，虽非月将，奈日不旺，况化月建，动变尽属坚金，帮助共扶，如山如冈。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.60","text":"知曰：焉能冲散？","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c38.61","text":"他章俱存占验，独此章只存数式，余故知其乃揣摩之说，非经验而得也。","chapter":"卷之四·进神退神章第二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.1","text":"古有日墓、动墓、化墓之三墓。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.2","text":"世爻随鬼入墓、本命随鬼入墓、卦身随鬼入墓、世身随鬼入墓。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.3","text":"觉子曰：执此数论，若逢辰戌丑未之日，竟不敢占卦，非世临鬼、即卦身临鬼、即本命临鬼，然又不独辰戌丑未日而他日亦不敢占，何也？","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.4","text":"卜卦之中不免有二三墓爻发动，非世命而入、即二身而入、及动而化墓、非世爻动化、即二身动化，再不然难保其本命不化墓也，一卦之中不必看刑冲克害破散绝空，凡占疾病凶危之事，只以随鬼入墓即知凶吉也，余屡于疾病之占卦，卦卦留神，见世爻旺者二身随鬼入墓而不死也。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.5","text":"本命随鬼入墓而不死也，存留验，不验又试，试之不验，而再试之，一而十，十而百，全不验者，始尽删之，便是世爻用爻随鬼入日墓入动墓或动而化墓，亦是休囚无气始见危，若旺而有扶亦有求解。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.6","text":"如申月戊辰日占夫病癸亥命子孙戌土′应兄弟巳火′世妻财申金′动子孙未土″兄弟午火′妻财酉金′官鬼亥水′世官鬼亥水′应子孙丑土″子孙丑土″父母卯木′父母卯木′断曰：妻占夫，亥水官星为用神，墓于辰日，乃夫星夫命皆入墓于辰日，古法断之必死，余曰：不独不死，明日愈。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.7","text":"辰日冲动戌土以生申金，因世爻亥水空亡不受其生，明日己巳冲起亥水，得遇金生，其病如失，果于次日大愈。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.8","text":"又如戌月甲寅日会试能联捷否？","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.9","text":"父母戌土″动妻财寅木′世兄弟申金″子孙子水″官鬼午火′世动父母戌土″兄弟申金′兄弟申金′应官鬼午火″官鬼午火″父母辰土″应父母辰土″断曰：世爻随官入三墓，动墓，化墓，又入月德之墓，明岁辰年冲开墓库，发榜之期，又遇辰月冲开三墓，不独连登，定中状元。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.10","text":"日月合成官局旺相当时，卦之全美，如玉无暇，果然如是。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.11","text":"又如申月己丑日占病壬申命得雷风恒妻财戌土″应妻财戌土″应官鬼申金″官鬼申金″子孙午火′子孙午火′官鬼酉金′世官鬼酉金′世父母亥水′父母亥水′妻财丑土″妻财丑土″此卦日命随鬼入墓，世爻随鬼入墓，世身又落旬空，卦身又临月破，若执古法断之，百无一生，因世爻旺相，许未日愈，果起床于未日者，冲开丑墓之日而出也。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.12","text":"古法以墓为沉滞昏迷之象，此说近理，此人病中不思汤药，昏昏沉沉，至未日忽然更醒，不药而愈，岂可一概谓之随鬼入墓也。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.13","text":"又如未月戊辰日占已定重罪可蒙赦免否兄弟寅木′应兄弟寅木′应父母子水″父母子水″妻财戌土″妻财戌土″官鬼酉金′世动妻财丑土″世父母亥水′兄弟卯木′妻财丑土″动子孙巳火′世爻随鬼入动墓，又动而化墓，古以为凶，余以为吉。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.14","text":"断日月生世，丑墓月破，破罗破网，容易而出。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.15","text":"明岁酉年定蒙赦免。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.16","text":"果于次年辰月蒙赦而出。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.17","text":"余因屡试而得验者，只验世爻入墓有三：世爻随鬼入日墓，入动墓，动而化墓。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.18","text":"此三墓者，自占看世爻，旺相者非真，代占看用神，用神旺相者非真，惟世爻休囚被克，而又入墓者，是也。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.19","text":"墓神破，日月动爻冲破，亦非真也。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.20","text":"墓破如破网，容易而出矣。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.21","text":"占功名，世旺得地，冲开墓库之年月成名，世若空破休囚，始终难成之象；","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.22","text":"占身命，世旺得地，冲开墓库之年月发迹。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.23","text":"世爻空破休囚，终身寂寞，如日月之无光也；","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.24","text":"占出仕，出行得世旺得地冲开墓库之日月遂心。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.25","text":"世若空破休囚，多见去而不返。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.26","text":"占求财图利，世旺者，冲墓之日月而成，若空破休囚，终无成日；","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.27","text":"占婚姻，世旺得地及财爻有气而生世者，冲墓之日月而成，若空破休囚，非病于他乡即流落也；","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.28","text":"占胎产，子孙入动墓化墓者，旺则冲墓之日月即生。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.29","text":"财爻空破休囚，妻遭产厄，子孙空破，子必危亡；","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.30","text":"占入公门，世旺得地，冲墓之年月如心，空破休囚，常遭枷锁刑狱；","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.31","text":"占家宅，世旺者，或得财爻生世，冲开之年月兴家。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.32","text":"空破休囚，身衰家破。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.33","text":"占祖茔者与家宅同；","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.34","text":"惟占新茔未葬者，旺相休囚皆不宜也；","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.35","text":"占偷关偷险，世爻旺相，又得生扶，难而无危，忧心难释，鬼在身边故耳；","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.36","text":"占讼事，世旺者得理，空破休囚被克者，必遭刑狱。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.37","text":"诸占世爻若旺，墓爻而值空破，待墓爻填实之日月而吉；","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.38","text":"世爻空破休囚者，又在墓爻填实这日月而凶。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.39","text":"古以世临破鬼，如占防患，祸患潜消，余以为非。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.40","text":"月破既为白虎鬼，目下虽无妨，实破之年月非吉。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.41","text":"如申月己未日占贼来否得大畜之泰卦官鬼寅木′动子孙酉金″应妻财子水″应妻财亥水″兄弟戌土″兄弟丑土″兄弟辰土′兄弟辰土′世官鬼寅木′世官鬼寅木′妻财子水′妻财子水′彼时土贼兴发常来，乡人了无宁日。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.42","text":"一日忽报贼来，此人携妻而避，因小女未随，复去抱女，同遭贼害，夫应自身之死者，世临破鬼而入日墓，女之死者，上爻鬼变子孙之故耳。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.43","text":"岂可谓世临破鬼，祸患消耶。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.44","text":"（鬼临月破，不动者不验。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c39.45","text":"）李我平曰：此论虽随墓令人刮目，每卦之动墓多见，倘再遇辰戌丑未之日，叠叠墓爻，若兼世命二身，非此即彼，以入墓也，真无暇他论，况诸书章不言及旺衰，概以随墓不吉，如占功名旺官临身，岂可曰履仕途而不返，占防灾世临月破又随鬼入墓，岂可竟曰无忧，颠倒凶吉，不得不为正之。","chapter":"卷之四·随鬼入墓章第三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.1","text":"五爻俱动，一爻不动，谓之独静；","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.2","text":"五爻不动，一爻独动，谓之独发。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.3","text":"事之成败，由乎用神；","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.4","text":"应期迟速，亦由乎用神；","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.5","text":"独发独静，古有验之，余试亦有验也，皆在验事应之后，如会神机，非初敢执之而断祸福与应期也。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.6","text":"况卦得独静虽少，而独发者多，如舍其用神，执之而决事者，谬也，过也。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.7","text":"曾于辰月甲戌日占迎请父王灵柩允否？","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.8","text":"官鬼巳火′应官鬼巳火′世父母未土″父母未土″兄弟酉金′兄弟酉金′父母辰土′世子孙亥水′应妻财寅木′动父母丑土″子孙子水′妻财卯木′彼有门客知易，谓寅木一爻独发，化出丑父，乃应正月得见父灵。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.9","text":"余曰，此隔靴搔痒也。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.10","text":"卦中父爻持世，据被寅木克制，乃身不能动，灵亦不能动也。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.11","text":"欲身动而灵动，必待冲开寅木之年月也，再请一卦，合而决之。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.12","text":"又得泽火革变既济官鬼未土″兄弟子水″应父母酉金′官鬼戌土′兄弟亥水′世动父母申金″兄弟亥水′兄弟亥水′世官鬼丑土″官鬼丑土″子孙卯木′应子孙卯木′余曰：此正前卦相合，前卦应冲开寅木者，申也。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.13","text":"此世化申金回头生，亦应申月。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.14","text":"世临虎动因丧事，而卯木冲动九五，又来生世，今年申酉月必蒙恩。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.15","text":"眼下月破，万万不能。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.16","text":"后应申月所请准，酉岁迎灵而归，两卦皆是独发，可执之耶。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.17","text":"又如午月甲申日防涨水冲去麦子子孙戌土′应动子孙未土″妻财申金′妻财酉金′兄弟午火′官鬼亥水′世官鬼亥水′世官鬼亥水′子孙丑土″子孙丑土″父母卯木′父母卯木′应友人执此而问。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.18","text":"余曰：戌土子孙一爻独发，昨日丙戌，定皆大晴，如何还雨，余曰：尔忧麦被水冲，神以子孙发动克去身边之鬼示尔忧非，应晴也。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.19","text":"虽则目下晴，决不涨水，即以此卦而决阴晴，卯日必大晴也，彼曰：何也？","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.20","text":"余曰：动而逢合之日晴，则尔无忧也。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.21","text":"又如辰月甲午日开煤得家人变益卦兄弟卯木′兄弟卯木′应子孙巳火′应子孙巳火′妻财未土″妻财未土″父母亥水′动妻财辰土″世妻财丑土″世兄弟寅木″兄弟卯木′父母子水′丑土财爻持世，日生之，许其可开。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.22","text":"余曰：财静未月冲开，应在六月。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.23","text":"及至六月，竟不见煤，歇而开，开而歇，未年占卦，至亥年辰月始得见煤，此乃应于独发亥水化辰土，年月俱应，断卦之时，谁以亥年辰月而断耶？","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.24","text":"又如寅月庚戌日占女病兄弟巳火′应动官鬼子水″子孙未土″动子孙戌土′妻财酉金′动妻财申金″世兄弟午火″世动妻财申金′子孙辰土′动兄弟午火″父母寅木″子孙辰土″应古有以独静之爻而断应期，譬如此卦，寅木独静，若不看用神，断寅日生也？","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.25","text":"余以卦土为子孙，虽则休囚，得巳午火动而生之，未土子孙化进神，辰土子孙化回头生，许之寅日当愈，然亦不敢竟断，命伊母再占一卦父母戌土′父母戌土′兄弟申金′兄弟申金′官鬼午火′应官鬼午火′世兄弟酉金′动父母辰土″子孙亥水′动妻财寅木″父母丑土″世动子孙子水′应亥水子孙化寅木空亡，近病逢空即愈，出空之日也。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.26","text":"余曰：寅日大愈，目下病体虽重，管许无虞。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.27","text":"此虽应前卦一爻独静，必应用神之旺也，又得后卦显然，方敢以寅日决之。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.28","text":"李我平曰：易冒以吉凶之生由乎动，所以重于动而轻于用。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.29","text":"事应之来不验于用神于卦象，此教人重于独静，独静不用用神者明矣。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.30","text":"又云：虽不离用而亦不执用爻也，此又教人用用神、不用用神也。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.31","text":"又曰：独发静可用，时日吉凶须审用卦，又教人重于用卦也。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c40.32","text":"留书传世，须一字开后人之茅塞，一言破千古之疑患，即曰用用神之，又曰不用用神主，既无定，何以为法，得此可以醒世。","chapter":"卷之四·独发章第三十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.1","text":"用神两现，如占父母卦中两爻父母者是也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.2","text":"舍其休囚，用其旺相，舍其静爻，而用动爻，舍其月破，而用不破，舍其旬空，用其不空，舍其被伤，用其不伤。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.3","text":"得其验者，应乎旬空月破，舍其不空，而用旬空，舍其不破，而用月破。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.4","text":"如未月庚子日占求财得风天小畜兄弟卯木′兄弟卯木′子孙巳火′子孙巳火′妻财未土″应妻财未土″应妻财辰土′妻财辰土′兄弟寅木′兄弟寅木′父母子水′世父母子水′世应临月建之财以克世，许之必得，彼问何时到手，余以次日辛丑冲动未财日得，却得于辰土出空之日，此乃舍其不空而用旬空。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.5","text":"未月甲午日占升迁得师之涣卦父母酉金″应动子孙卯木′兄弟亥水″动妻财巳火′世官鬼丑土″官鬼未土″妻财午火″世妻财午火″官鬼辰土′官鬼辰土′应子孙寅木″子孙寅木″断曰：世爻极旺，既临日建又得月令作官星而合世，但卦中官星两现，一空一破，至辰年官而出空一定高升，然反吟于外卦，当得验者，去而复来，果于辰年，调于河南，五月因他故，又调回楚，十月而升督府，十年两调一升，皆应实空之年也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.6","text":"又如亥月丙午日母占子何日脱厄，得豫之归妹妻财戌土″妻财戌土″应官鬼申金″官鬼申金″子孙午火′应子孙午火′兄弟卯木″妻财丑土″世子孙巳火″动兄弟卯木′妻财未土″世动子孙巳火′余见卦中三现子孙，俱生世爻，午逢日建而静，两爻巳火逢月破许巳年脱厄，乃实破之年也，果脱厄于巳年。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.7","text":"此乃卦中用神三现，而用逢破之爻也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.8","text":"野鹤曰：余竟以月破而断年者，非只此一卦也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.9","text":"因此位老夫人之长公弃封疆而归，本人自身占过，申金子孙发动，动逢合乃应巳年；","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.10","text":"弟又占兄，申金兄动亦应巳年，此卦巳火子孙回头生世，虽逢月破，合前二卦故敢许以巳年，以卜易者一则全其灵机达变，二则卦要留神记之，若不留心记得前卦，此卦午火日建生世，何不许其午年，况午岁又是合世之年，何敢许其巳年，许巳年者，因合前卦而断也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.11","text":"《星煞章》第三十三太乙贵人甲戊兼牛羊乙巳鼠猴乡丙丁猪鸡位壬癸兔蛇藏庚辛逢马虎此是贵人方假令甲戊庚日占卦又中见丑未者即是贵人禄神甲日到寅乙初到卯丙戌禄在巳丁己禄居午庚禄居申辛禄在酉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.12","text":"假令甲日占卦爻中见寅为禄乙日占卦爻中卯为禄余仿此驿马申子辰马到寅巳酉丑马在亥寅午戌马居申亥卯未马在巳假令子日申日辰日占卦爻中见寅即为马余仿此天喜春戌夏丑秋畏冬未假令春天正月占卦爻中见戌即为天喜，三月虽以戌为天喜，又为月破，若发动于卦中扶助旺相之用神者，以之为喜，不以为破，余仿此。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.13","text":"诸书星煞最多，余留心四十余载独验贵人禄神驿马天喜，然不能独操祸福之权，用神旺者见之愈吉，用神失陷虽有如无。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.14","text":"李我平曰：伏羲观奇偶以判阴阳，文王以爻辞而断凶吉，周公之后，决祸福于五行，易道穷矣，今兼吉凶煞星，不知起自何人。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.15","text":"丧门拓墓大杀飞鹰，加此验语惊人，往往全无应验，易冒疾病章云：卜卦不死星煞不死用神煞（此处缺），出尔反尔，后学何从，即如此书得验贵人禄神驿马亦必附和用神之旺相，即不能独操祸福之权。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.16","text":"予以为诚意先生千金赋曰：吉凶神煞之多端，何如生克制化之理，一言以敝之矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.17","text":"增删《黄金策千金赋》第三十四动静阴阳，反复变迁。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.18","text":"前动变章注解明白。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.19","text":"太过者损之斯成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.20","text":"旧注主事爻重复太多，事不专一，故宜损之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.21","text":"且如土为主事爻多，卦中多逢丑戌辰未，谓之大过，须待寅卯月日克制土爻，然彼成事，或占时得遇寅卯日月亦好。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.22","text":"野鹤曰：不独后逢寅卯月日，得逢辰月辰日者，或许成事，何也？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.23","text":"辰乃土之墓库，谓之用爻重叠，须墓库以收藏是也，余仿此。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.24","text":"不及者益之则利。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.25","text":"若主事爻只有一位，又不旺，谓之不及，其事难成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.26","text":"且如金为主事爻，若在夏天占得休囚死煞，若得日辰动爻生之，或得后来逢生助之日月，皆有利益，其事亦成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.27","text":"但要主事爻原有根蒂，衰而逢生者，如旱苗得雨也，勃然而兴，故谓之有扶有助，衰弱休囚亦吉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.28","text":"只恐衰弱无助，休囚失陷，虽逢生合，亦难生矣，岂不闻制中弱主，难以为持。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.29","text":"生扶拱合，时雨滋苗。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.30","text":"克害刑冲，秋霜杀草。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.31","text":"前五行生克、三合六合章、月将日辰章，三刑六害章，注解极明。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.32","text":"长生帝旺，争如金谷之园。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.33","text":"死墓绝空，乃是泥犁之地。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.34","text":"前《生旺墓绝章》、《空亡章》详之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.35","text":"日辰为六爻之主宰，月将是万卜之提纲。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.36","text":"前《日辰月将章》详之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.37","text":"最恶者岁君，宜静不宜动。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.38","text":"岁君乃当年之太岁是也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.39","text":"或旺动暗冲克世爻，占年运者，必须是一年中的大事。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.40","text":"占官事的，一定得是朝廷的大事，占卜升迁官运以及占卜面圣朝君，或者占卜向圣上请功的，皆宜太岁生合世爻，动而生世更吉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.41","text":"除此数占之外，皆与他要等也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.42","text":"太岁虽司一年之令，尊而不亲，难仰吉凶，皆不及日月。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.43","text":"古以太岁不理家庭琐事，此理是也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.44","text":"所以太岁冲爻为岁破不以为凶，合爻为岁合不以为吉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.45","text":"爻之衰者，太岁不能生之，爻旺者太岁不能制之，遇月破者即破，逢旬空者旬空，此非月建日建力也？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.46","text":"野鹤曰：作当年祸福，不以为重，作后世之吉凶，其实不轻。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.47","text":"且如主事爻属木爻，卦中申酉金动，谓之木被金伤，纵使木旺金衰，目下可保无事，后遇申酉岁难免其殃。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.48","text":"如巳月壬子日占乡试得水地比妻财子水″应妻财子水″应兄弟戌土′兄弟戌土′子孙申金″子孙申金″官鬼卯木″世官鬼卯木″世父母巳火″父母巳火″兄弟未土″兄弟未土″巳月父爻当月建文星旺矣，独嫌官星持世，卯木旬空，许之卯科方得遂意。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.49","text":"子年占，果于卯年登科。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.50","text":"卯年者，太岁填实不空也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.51","text":"不验者身位，宜删而不宜存。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.52","text":"旧系最要者身位，喜扶而不喜伤。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.53","text":"原注有云，古用身世而不验，故用卦身。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.54","text":"野鹤曰卦身亦不验，亦用世爻。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.55","text":"余用世爻，百发无不百中也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.56","text":"然间有之验，乃偶然凑合耳，何足为法。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.57","text":"世为己，应为人，大宜生合。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.58","text":"世为自己，应为他人，凡兼彼此之事，兼而用之，欲他扶助我者，喜应爻生合世爻。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.59","text":"我欲代他而谋事者，亦世爻而生应也，兼彼此而不应也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.60","text":"如卯月辛巳占自陈何如得恒之升妻财戌土″应官鬼酉金″官鬼申金″父母亥水″子孙午火′动妻财丑土″世官鬼酉金′世官鬼酉金′父母亥水′父母亥水′妻财丑土″妻财丑土″应余曰：酉官持世破而且空，又动出午火，相克，不独削职，须防五六月还见凶灾。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.61","text":"或曰，幸得世应相生，又变升卦，必相救解，余曰，自占自陈，与应何干，此迂腐之论也，果于五月下狱。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.62","text":"动为始，变为终，最怕交争。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.63","text":"动爻为事之始，变爻为事之终，不宜互相冲克。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.64","text":"应位遭伤，不利他人之事，世爻受制，岂宜自己之谋。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.65","text":"自占者，宜世爻旺相，或临日月，或日月动爻扶助，或动而化吉，诸占皆吉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.66","text":"占他人以应爻为用，喜他旺者，宜临旺相之地，又宜日月动爻以生扶；","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.67","text":"喜他衰者，宜临墓绝空之乡，及被日月动爻冲克。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.68","text":"世应俱空，人无准实。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.69","text":"世空自己不真，应空他人不实，世应俱空，彼此皆无准实。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.70","text":"内外竞发，事必翻腾。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.71","text":"卦中动爻少者，吉凶自有条理，容易剖断。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.72","text":"若内卦外卦纷纷乱动，则吉凶不定，必人情不常，事体反复，全无定论，须再占一卦，合而决之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.73","text":"世或交重，两目自顾瞻于马首。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.74","text":"应如发动，一心似托于猿攀。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.75","text":"旧注世应皆不动，动则反复不常，如马首，似猿攀，意以无宁。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.76","text":"野鹤曰：吾不敢以之为是，亦不敢以为非。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.77","text":"此乃用不旺，象不成之说也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.78","text":"若用爻得地，大象当成，世动不受克制，应动三合世爻，图事成之更速。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.79","text":"用爻有气无他故，所作皆成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.80","text":"主象徒存更被伤，凡谋不遂。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.81","text":"用爻及主象，即主事之爻也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.82","text":"或旺有生扶，或有气并无他爻克制，事之必成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.83","text":"倘衰弱无力又逢克制，虽则出现亦无用矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.84","text":"爻遇旬空，逢冲而有用。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.85","text":"旬空得遇日辰冲者，谓之冲空，实不为空，反为有用。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.86","text":"倘动爻空者，日辰冲之更实。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.87","text":"旧注爻相合，如两人同心，事必克济。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.88","text":"若日月动爻冲克者，则为合处逢冲。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.89","text":"须防小人挑唆，合好之中，以生疑忌。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.90","text":"只在自为之事者，亦被旁人挑阻，我事难成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.91","text":"余得验者，凡三合六合，虽不宜目下日月动爻冲克，又宜后来之月冲开。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.92","text":"正所谓如逢合住，冲破成功。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.93","text":"且如爻中寅与亥合，事若在申巳之日月方成其事，余仿此。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.94","text":"古之不动，宜为之合，非也，两爻皆动，始为合。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.95","text":"动空化空，皆成凶吉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.96","text":"余得验者，动不为空，动而化空，亦不为空，吉凶皆应冲空实空之日，予故更之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.97","text":"刑合克合，终见乖淫。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.98","text":"旧注合者，和合也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.99","text":"见之为吉，殊不知合中有刑有克，毕竟不合。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.100","text":"用午字为财爻，寅为福神，因午字带自刑，名为刑合，不以为合，而为刑也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.101","text":"野鹤曰：午既自刑，乃自有刑害之祸，得福神而作合，是救解其祸矣，反不为吉者，非也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.102","text":"余尝得验，世爻午火，化未相合，已定重刑，后竞得释放，免于灾祸。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.103","text":"旧注忌神动逢日月相合，则不成凶。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.104","text":"原神动逢日月合住则不济事。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.105","text":"此亦有理，余得验者，后逢冲开之日月，吉凶俱成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.106","text":"如未月庚寅日占官运。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.107","text":"官鬼未土″兄弟子水″应父母酉金′官鬼戌土′兄弟亥水′世动父母申金″兄弟亥水′兄弟亥水′世官鬼丑土″官鬼丑土″子孙卯木′应子孙卯木′断曰：世临亥水，今岁子年，太岁拱扶，九五酉金，虽不发动，亦有生意。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.108","text":"世爻又化回头生，又得日辰相合，六爻未土官星当权得令，仕途平坦，如顺水行舟也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.109","text":"惟疑权操两省，不为不当，如何兄爻持世，财伏被克，此美中不足也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.110","text":"公问，后日何如。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.111","text":"余曰：防巳年太岁冲害，刑申，不无蹭蹬荣归之日，只落得四海一空囊耳。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.112","text":"果于巳年被论，宦囊消索。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.113","text":"此乃世逢合而绊住，逢冲之年月则开。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.114","text":"暗动章注解极明。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.115","text":"旧注墓者，滞也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.116","text":"忌神入墓不克用神。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.117","text":"且如木为用神，金为忌神，若在丑日占者，金入墓矣，焉能克木。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.118","text":"卦中动出丑爻，亦向此推。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.119","text":"金爻动而化丑亦是，余仿此。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.120","text":"野鹤曰：是则是也，屡见后逢冲开墓库日，依然木被金伤。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.121","text":"旺者乃旺之爻而遇旬空不作空论，倘遇本日之日辰冲者，谓之空逢冲而有用，遇后日之日辰冲，谓之冲起，过此一旬而出空者，谓之填实，但不为之空也，倘若发动更不为空。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.122","text":"有助有扶，衰弱休囚亦吉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.123","text":"此指主事爻而言，且如主事爻无气本为不美，若得日辰与动爻生扶拱合，即为得助，与前不及者益之则利相同。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.124","text":"贪生贪合，刑冲克害皆忘。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.125","text":"此亦指主事爻而言，且如主象临卯木，遇申爻动而克之，卦中动出亥水，申金贪水之生，不来克木。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.126","text":"又如主事爻临子水欲卯木动而相刑，若得旁爻动出戌字，卯与戌合，不来刑子，此乃贪合忘刑。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.127","text":"又如用爻临巳字，卦中动出亥水，动克一火，若得卯木同动，亥卯未合成木局，反来生火，亦谓之贪合忘克忘冲，余皆仿此。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.128","text":"别衰旺以明克合，辨动静以定刑冲。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.129","text":"衰旺克合，前五行生克章及四时旺相章中已注明白。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.130","text":"动静刑冲，前动变章已注明。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.131","text":"并不并因多字眼，合非合因少支神。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.132","text":"旧注卦爻既成，未免有刑冲并合，然多一字不成其名，少一字亦不成刑冲并合之名也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.133","text":"且如子日卜卦，卦中有一子字而谓之并，若有二字则分开而太过也，名虽为并，其实不能并之，二午则不冲，二卯则不刑，二巳则不克，此多一字，不成刑冲克害之名。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.134","text":"野鹤曰：若爻中二子不合二丑，名为合，不成者，亦有理也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.135","text":"若以日辰不能并爻出之二子不能冲爻中之二午者非也，日月如天，无处不沾雨露，不然何以为之巡查六爻之善恶。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.136","text":"即如丑月壬子日占讼父母戌土′父母戌土′兄弟申金′应兄弟申金′应官鬼午火′官鬼午火′兄弟申金′兄弟申金′官鬼午火″世官鬼午火″世父母辰土″父母辰土″断：世临午火，子日冲之，休囚为日破，不为暗动，今日若审，必有责罚，果于本日见官责杖二十，此即卦见二午，岂可谓之一子不冲二午耶，又曰寅巳申为三刑，若有寅巳二字，而无申字，或有寅申二字，而无巳字，但少一字，不成三刑，又曰亥卯未为三合，卦有二，内少一字者，不成三合。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.137","text":"野鹤曰：此二者皆非其说，殊不知虚一待用，待后时之月日可以填之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.138","text":"如巳月未日占久病得困之兑卦父母未土″父母未土″世兄弟酉金′兄弟酉金′子孙亥水′应子孙亥水′官鬼午火″父母丑土″应父母辰土′妻财卯木′妻财寅木″世动官鬼巳火′断曰：世爻寅木化出巳爻，寅能刑巳，三刑少申字，防申日之危，果卒于申日，此乃少一字，得后来之申日补之，岂可谓少一字不成三刑耶。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.139","text":"如酉月乙巳日占升迁得泽地萃之天地否父母未土″动父母戌土′应兄弟酉金′应兄弟申金′子孙亥水′官鬼午火′妻财卯木″妻财卯木″世官鬼巳火″世官鬼巳火″父母未土″父母未土″断曰：巳火官星持世由临日建，卜书曰官临日月即升，且巳日冲动亥月与发动之未爻，欲成三合，因少卯字，明年卯月必升，此乃虚一待用，果升于卯月，岂可谓之少一字不成三合耶。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.140","text":"爻遇令星物难我害。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.141","text":"日辰月建章注解极明。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.142","text":"伏居空地事与心违。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.143","text":"伏也又空，诸事难成之象。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.144","text":"旧存占验丙申日占文书子孙酉金″应妻财亥水″兄弟丑土″兄弟辰土′世官鬼寅木′伏父母巳火妻财子水′断曰：以父母爻为用神，此卦六爻无父母巳火，父母伏于妻财寅木之下，又遇旬空，所以文书不成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.145","text":"野鹤曰：伏而又空，事之不成者是也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.146","text":"但此卦文书之不成者，非因空也，乃因飞神在寅，伏神在巳与申日作三刑之故耳，何也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.147","text":"申日冲动，寅木以生巳火谓之飞来生伏得长生，伏神既得长生，则为有气不空，不然何以谓之飞不冲开亦枉然，余故曰：非因空也，三刑也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.148","text":"伏无提携终徒耳，飞不冲开亦枉然。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.149","text":"凡用神不现，伏于卦中，须宜月建日辰，冲开飞神，生合扶起飞神，即为有用。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.150","text":"空下伏易于引拔。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.151","text":"伏神不空而飞神空，易于出现，何也，飞神即空，乃上无压住之爻也，而伏神再得月建日辰生扶拱合，脱然出矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.152","text":"制中弱主难以维持。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.153","text":"用爻休囚又被月建日辰制服，纵遇生扶，亦不济事也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.154","text":"如辰月丙辰日占地下忽然起五色之光疑有古窖。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.155","text":"父母巳火′官鬼寅木′应兄弟未土″妻财子水″子孙酉金′世动兄弟戌土″兄弟丑土″动子孙酉金′世官鬼卯木′妻财亥水′父母巳火′应动兄弟丑土″余曰：财伏而空，全无影响，伊曰：既是无财，何故有五色之光，余曰，乃妖气也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.156","text":"彼时人人望财，议论纷纷，有曰子动爻中，兄弟交重偏有望，此卦兄动生子，子动生财，又是内卦合成金局生水旺，何曰无财。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.157","text":"余曰，尔知其一，不知其二，子孙虽旺，不生无蒂之财。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.158","text":"子水伏而有空，又被日月飞神克制，财从何来，后竞掘之，掘破缸一口，尽是瓦屑泥土。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.159","text":"日伤爻真罹其祸，爻伤日徒受其名。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.160","text":"日月如天如君，六爻如臣如万物。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.161","text":"日辰能刑冲克害得卦爻，而卦爻不能刑冲克害日月。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.162","text":"墓中人不冲不发。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.163","text":"旧注大抵用爻入墓，则被阻滞，诸事费力难成，须得日辰动爻冲破或克破其墓，方有力也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.164","text":"如戊寅日占财得同人之乾卦子孙戌土′应子孙戌土′世妻财申金′妻财申金′兄弟午火′兄弟午火′官鬼亥水′世子孙辰土′应子孙丑土″动父母寅木′父母卯木′官鬼子水′用爻入墓，喜得日辰克破，后果得财。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.165","text":"以用空入墓许以无财者，非也，殊不知虽空而遇冲，冲空则实，虽墓而克破，破墓则开。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.166","text":"野鹤曰：此极有理，屡试屡验，但要用神有力，方可许之，倘若用神休囚无气，虽遇冲开之日，亦难发矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.167","text":"如未月戊辰日占年运。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.168","text":"子孙酉金″子孙酉金″妻财亥水″妻财亥水″世兄弟丑土″应兄弟丑土″兄弟辰土″动子孙申金′官鬼寅木″父母午火″应妻财子水′世动兄弟辰土″断曰：世爻子水是申子辰三合水局，不宜日月克世，世爻化回头克，动爻辰土又克，此乃世爻休囚无气也，卯年占，卒于午年，应午年者，世临岁破之年也，岂可谓之墓中人不冲不发耶。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.169","text":"身上鬼不去不安。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.170","text":"诸占最怕克世，独官鬼持世者，若非职役之人，最宜日月动爻相冲克，反为吉矣，何也，非克世爻，乃克去身边之鬼。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.171","text":"如午月癸丑日占妻病父母未土″子孙子水″应兄弟酉金′应父母戌土′子孙亥水′动兄弟申金″妻财卯木″妻财卯木″世官鬼巳火″世官鬼巳火″父母未土″父母未土″问来人病得几时，彼曰三月病起，余曰卯日财空，明日出空，必定退灾，彼曰，医空不药矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.172","text":"余曰，不妨，此卦亥水子孙独发，克去世爻之鬼，应在明日寅日，寅与亥合，合起子孙之日，尔无忧也，果于次日退灾，不药而愈，亦不独此，又因卯木财空，次日出空而退灾。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.173","text":"曾如辰月戊子日占小舟过关恐盘阻得水地比变泽山咸卦。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.174","text":"妻财子水″应兄弟未土″应兄弟戌土′子孙酉金′子孙申金″动妻财亥水′官鬼卯木″世动子孙申金′世父母巳火″父母午火″兄弟未土″兄弟辰土″世爻之鬼，乃满腹忧疑之象，申金克去身边之鬼则无忧也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.175","text":"果于卯日过关，并无阻滞。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.176","text":"德入卦无谋不遂。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.177","text":"旧注德者，得也，指与天地合其德。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.178","text":"主事爻，天干地支上下相合是也，存有占验。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.179","text":"戌月己酉日占文书得小畜之蛊兄弟卯木′兄弟寅木′应子孙巳火′动父母子水″妻财未土″应妻财戌土″妻财辰土′官鬼酉金′世兄弟寅木′父母亥水′父母子水′世动妻财丑土″谓五爻动出丙子，文书与世爻变出辛丑干支相合，应戊子日成其文书，余以此论为多事之论。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.180","text":"野鹤曰：鬼谷三才论含爻辞以五行以定祸福者乃用地支。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.181","text":"既用地支，不得不以天干为配，未闻以天干而定吉凶。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.182","text":"以天干配于地支者，欲全用周天甲子卦，又止于四十八爻。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.183","text":"所以乾内卦甲坤之内用乙，乃十干之首，乾之外卦用壬，坤之外卦用癸，皆十干之尾。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.184","text":"乾之内卦用子，与坤之外卦相合，坤之内卦用未，与乾之外卦相合。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.185","text":"二老上下相映，阴阳相配，中包六子，甲乙之次者丙丁，用之于少男少女，艮与兑也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.186","text":"戊己用之于中男中女，坎与离也，庚辛用之于长男长女，震与巽矣，以全上下干支，此乃配偶之法也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.187","text":"故谓之浑天甲子。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.188","text":"而祸福吉凶皆地支生克制化克合刑冲以判之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.189","text":"今又以天干而判休囚者，每卦皆宜用也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.190","text":"何独于此，况小畜变蛊五爻朱雀为文书，动临巳火变出子水文书，而世爻临子水父母，又为文书，酉日生之，化丑合之，叠叠文书旺动于卦中，便非干支相合，亦不能说无成，故曰多事之论。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.191","text":"忌临身而多阻无成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.192","text":"忌即忌神，占不宜持世。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.193","text":"如占官子孙为忌神，子孙持世求名不成，占财兄爻为忌神，兄爻持世，求财不获。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.194","text":"野鹤曰：此论极是。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.195","text":"然余得有验者，兄爻持世化出财爻而得财，世临财爻化出父母而见父。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.196","text":"如巳月丙申日占财得未济变鼎卦兄弟巳火′应兄弟巳火′子孙未土″子孙未土″应妻财酉金′妻财酉金′兄弟午火″世动妻财酉金′子孙辰土′官鬼亥水′世父母寅木″子孙丑土″此乃忌临世位化酉财，即于酉日得财。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.197","text":"又如申月戊午年占领文书得风雷益卦之家人兄弟卯木′应兄弟卯木′子孙巳火′子孙巳火′应妻财未土″妻财未土″妻财辰土″世动父母亥水′兄弟寅木″妻财丑土″世父母子水′兄弟卯木′此亦忌临世位，即于酉日而得文书，同日子占父亦得此卦，亥日见父，其故何也，疑是动爻不克变爻之故耳。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.198","text":"然亦无多见者，余既得验，不得不以告之，然非教后人之法也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.199","text":"诸占必以忌神持世多阻无成者为是。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.200","text":"卦遇凶星避之皆吉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.201","text":"旧注凡值用神空凶，遇日月动爻冲克者，谓之避空，反不遭其冲克之害，旧存有占验：六月壬子日占子病得姤之大过父母戌土′动父母未土″兄弟申金′兄弟酉金′官鬼午火′应子孙亥水′世兄弟酉金′兄弟酉金′子孙亥水′子孙亥水′父母丑土″世父母丑土″应谓父母旺动，用爻亥水子孙而无气，本为凶兆，喜得用爻值旬空而避之，至丙子日而愈，盖丙子者，则前面已过，又是亥水子孙值子日而临帝旺故耳。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.202","text":"野鹤曰：此论非理，诸占最恶者忌神，既动于卦中，祸已兆矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.203","text":"用神静者逢冲之日遭害；","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.204","text":"用神动者，逢合之日遭伤；","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.205","text":"用神破者，实破之日而遇；","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.206","text":"用神空者，出空之日相逢。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.207","text":"是乃未曾出一可以避之，出空必遇其害，岂曰出空则前面已过，反不受其祸，此说悖也，谬也，余得其验者，原神动于卦中，用神空者，出空之日而得。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.208","text":"忌神动于卦中，而用神空者，出空之日逢殃，屡占屡验，独近病逢空不论。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.209","text":"凡占近病，用神得遇旬空者，不拘日月动爻克害，用神出空之日即愈。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.210","text":"即独此一事，论空不论克也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.211","text":"此姤之大过，定是占于近病，不悟近病逢空，继而曰诸事皆可避之，此误后人也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.212","text":"爻逢忌杀敌之无伤。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.213","text":"旧注忌爻发动，心事不利，若得日月动爻帮助用爻，可以敌之，不伤于彼，事亦可成，余以此论是理。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.214","text":"申月乙未日占脱役得损之节官鬼寅木′应动妻财子水″妻财子水″动兄弟戌土′兄弟戌土″子孙申金″应兄弟丑土″世兄弟丑土″官鬼卯木′官鬼卯木′父母巳火′父母巳火′世谓世临丑土，而子水财动生助寅木之鬼，木之鬼动而克世，喜得日辰未土、五爻变出戌土扶助世爻，可以敌其寅木之鬼，不能伤身。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.215","text":"野鹤曰：以此作后人之法者，亦误人也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.216","text":"何也，一重未土扶世，岂可敌其寅鬼伤身之恶煞耶？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.217","text":"殊不知寅木鬼动，月建破之，未日墓之，此寅木之鬼破，保无事者也！","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.218","text":"此误作戌未二土帮扶者，错也！","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.219","text":"况变爻戌土从无帮助正卦之爻，作有一例，可以比之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.220","text":"辰月乙未日占月令得泰之丰子孙酉金″应兄弟戌土″妻财亥水″子孙申金″世兄弟丑土″动父母午火′兄弟辰土′世妻财亥水′官鬼寅木′动兄弟丑土″应妻财子水′官鬼卯木′世爻辰土，月建助之，丑土动而化回头之生，又来扶助。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.221","text":"虽则寅木鬼动而世爻旺相有助有扶可以相敌，然此后至辛丑日尚亦见其凶非，因一言触怒上司，几乎危殆，幸得解救。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.222","text":"应解救者，因得日月之土帮扶也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.223","text":"主象休囚怕见刑冲克害。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.224","text":"主象旺相，尚难敌乎刑冲克害之爻，况休囚耶？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.225","text":"用爻变动忌遭死墓绝空。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.226","text":"旧注死墓绝乃陷阱之地，若用爻动而化墓化绝化死化空者，不问公私大小之事，皆主不成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.227","text":"占病逢之，必死无疑。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.228","text":"予得验者，化墓化绝，若动爻旺相，或临日月帮助，亦无大害，化墓者，冲开之日月而成，化绝者逢生旺之日月而就。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.229","text":"至于化空之说，更得多验，占谋事，实空之日必成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.230","text":"占近病，出空之日即愈。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.231","text":"用化用有用无用。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.232","text":"旧主既有用爻，不可动而又化出来。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.233","text":"谓之化去，或旁发出，皆不济事。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.234","text":"故虽有用，即如无用。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.235","text":"野鹤曰：此论非理。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.236","text":"用爻若化进神，诸占皆吉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.237","text":"即使他爻动出者，再得此助帮扶，何谓无用。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.238","text":"岂不知太过者损之斯成，有曰用爻重叠，得墓库以收藏。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.239","text":"如果用爻太多，待至伤损之日，墓库之日，成之更稳，反曰无用。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.240","text":"空化空虽空不空。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.241","text":"余得验者，不独空化空则不为空，动亦不为空。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.242","text":"动不为空，为祸为福，冲空实空之月日必应。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.243","text":"养主狐疑，墓多暧昧。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.244","text":"此亦长生沐浴之中之二位星是也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.245","text":"余用生旺墓绝，其余不验。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.246","text":"今之验化出者亦验生旺墓绝。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.247","text":"用神动而化墓者，近病久病遇之，主昏迷之象。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.248","text":"用神旺者，冲开墓库之日则安。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.249","text":"用神休囚，又被刑冲克害者，难愈。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.250","text":"逢空者，近病者愈，久病者凶。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.251","text":"捕获遇之，深藏难保。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.252","text":"身命遇之，愚蒙不振。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.253","text":"失脱遇之，暗藏不见。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.254","text":"婚姻遇之，皆暗昧不明之象。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.255","text":"若动爻化墓，墓神回头克动爻，勿以暗昧论，乃凶兆也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.256","text":"忌回头克我者是也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.257","text":"如若墓神为鬼，回头克用，更凶。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.258","text":"化养化病化胎又化沐浴俱不验者删之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.259","text":"化生旺兮祸福有三。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.260","text":"生者动爻化长生也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.261","text":"如亥水动化出申金，即化长生又回头之生，化酉金者不曰化沐浴而曰化回头之生，此二者动爻有气化爻旺相，诸占皆吉，旺者，长生之第五位者是也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.262","text":"金木水火而化旺即是化进神，且如申金化酉金，亥水化子水，寅木化卯木，巳火化午火，主占无不亨吉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.263","text":"惟土寄生于申，旺于子水为进神，辰未土动而化出子爻者，乃为化旺，丑土化出子爻者，即为化旺，又为化合，诸占皆吉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.264","text":"化官鬼兮吉凶有二。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.265","text":"动爻变出官，吉凶有二，何也？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.266","text":"占功名者，世爻旺相，或临日月或日月生扶动而变出官星，又无破损，乃为得官之兆也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.267","text":"世若休囚，受克动而变出官星者乃为变鬼，不惟难于王家食禄，须忧梦沉黄梁。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.268","text":"果于八月，因子赌博送官，子受杖刑而死。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.269","text":"此应酉金子孙应变鬼，忌回头之克我。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.270","text":"爻动化克者，如金爻动变火克金，木爻动变金克木，谓之回头克也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.271","text":"觉子曰：余存占验，凡占回头之克，占病、占寿、占年运，得之十有九死，亦有占名利、及占家庭得之亦见危亡，何也？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.272","text":"其人大限至矣，自己无知犹有名利之求，如神戒曰：数之将尽，何用他求，警戒勿贪，庶几不罗乎罗网，即使难以回避，亦可保其正寝，疑神之告，乃此意耳。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.273","text":"古法相生须宜他生我，相克还宜我克他。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.274","text":"如占彼此两家之事者，宜应爻生世。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.275","text":"如占财者，宜财生世，如占官者，宜官生世。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.276","text":"如世去生助他爻，泄尽自己之气也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.277","text":"恶曜孤寒，怕日辰之并起。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.278","text":"刑冲克害之要即为恶曜，非诸星之凶煞。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.279","text":"凡见此爻动而冲克用神，若此星孤立无助，或休囚无力，虽则伤害用神，用神旺相可以敌之，必然无妨，得祸亦轻。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.280","text":"惟怕日辰动爻助他为害，彼必狐假虎威，仗势作恶，得祸不浅也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.281","text":"前月将日辰章内，最怕他爻增克制，同此意耳。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.282","text":"用爻重叠，喜墓库以收藏。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.283","text":"旧注用爻若无日辰动爻损之，必须得墓库收藏，然后可得。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.284","text":"丁丑日占财兄弟卯木′动妻财未土″子孙巳火′官鬼酉金′妻财未土″应动父母亥水′世妻财辰土′官鬼酉金′兄弟寅木′父母亥水′父母子水′世动妻财丑土″应彼断曰：卦有两财，初爻上爻又化出两财，日辰又是财，本为太过，喜得世爻上有辰字，乃为财库，谓之财有库以收藏，后主得财。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.285","text":"余以此论，极其得理，屡试屡验，但不必卦中有库，后来逢库之日月亦成其事。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.286","text":"如午月戊午日占何日雨得地风升变恒卦。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.287","text":"官鬼酉金″妻财戌土″应父母亥水″官鬼申金″妻财丑土″世动子孙午火′官鬼酉金′官鬼酉金′世父母亥水′父母亥水′妻财丑土″应妻财丑土″友人持此卦问余曰：今日占雨，父母不动，而丑土之财又化出午火回头生，竟是大旱之年也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.288","text":"余曰：壬戌日必雨。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.289","text":"友曰：父临月建，阴雨连旬，今子孙临月建，亦同此意，如何得雨？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.290","text":"余曰：午火子孙临日月旺之极矣，乃为用爻重叠，逢墓库以收藏，故知戌必雨。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.291","text":"果于戌日申时雨。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.292","text":"旧注世应中间两爻谓之间爻，动则事事阻隔。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.293","text":"谓之两爻在世应之中，动阻两家之事，使彼此不能相通。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.294","text":"又曰世应中间两爻发动所求多阻隔。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.295","text":"觉子曰：以此爻作为间爻试之果验，但看所占何事，须是彼此两家之事始可用之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.296","text":"婚姻以之为媒妁，词讼以之为证，买卖以之为牙行，借贷成文以之为中保，舟车以之为附载。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.297","text":"交游以之为帮开，胎产以之为收生保姆。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.298","text":"旧注自占世为主象，若无明动爻伤克而世爻无故自空者，必主心惰意懒，自不向前。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.299","text":"野鹤曰：此论为是。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.300","text":"前曰无故之空，如入深渊大壑，诸占大凶者，非也！","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.301","text":"易林补遗有曰世应皆空，故不向前，退悔，主宾皆动二边，日后更张。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.302","text":"所以不独世空不宜，应爻亦不宜也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.303","text":"谓之世应皆空，事无准实，凡动而空者，不以此论。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.304","text":"卦爻发动须看交重。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.305","text":"旧注交动主未来之事，重动主过去之事。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.306","text":"大凡爻象有一定不可移者，可以为法，间有验者，乃偶然之合耳。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.307","text":"动变比合当明进退。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.308","text":"杀生身莫将吉断，用克世勿作凶看。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.309","text":"盖生中有刑害之两妨，合处有克伤之二虑。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.310","text":"杀生世者，是日月动爻动临忌神而生世，非凶煞也，不以吉断者，何也？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.311","text":"谓忌神既旺，用衰矣，世虽逢生何益？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.312","text":"如戌月丙子日占父任云南何时得信？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.313","text":"得地泽临卦子孙酉金″子孙酉金″妻财亥水″应妻财亥水″应兄弟丑土″兄弟丑土″兄弟丑土″兄弟丑土″官鬼卯木′世官鬼卯木′世父母巳火′父母巳火′占信者，朱雀巳火父母为用神，日辰子水克巳火，忌神戌月乃巳火月墓，日克音信茫然之兆也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.314","text":"而世爻卯木虽遇日生月合，何益于事。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.315","text":"杀生身勿将吉断，此之谓也，后果无音讯，四年知父而遇害矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.316","text":"用克世勿作凶看者，乃用为克世也，旧注主事爻动来克世，乃是事来赶我，事必速成，我虽见克，亦何伤哉，故云克世者不以为凶。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.317","text":"觉子曰：此论未必全是，余之得验如占财财为用神，财爻克世者必得。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.318","text":"占行人用神克世者即至，占医药子孙为用，子孙克世者即愈，此外数占皆不宜用神克世也，若占功名，官鬼克世，非灾即祸，岂可曰勿作凶看。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.319","text":"如丑月庚子日占关差得否得泰之明夷子孙酉金″应子孙酉金″妻财亥水″妻财亥水″兄弟丑土″兄弟丑土″世兄弟辰土′世妻财亥水′官鬼寅木′动兄弟丑土″妻财子水′官鬼卯木′应占官差以官鬼为用，此卦辰土持世，寅木官鬼克世，世爻空，即于壬寅日得差，次年三月死于中途，岂可谓之用克世勿作凶看。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.320","text":"主事爻与日月动爻作三刑者，占事不成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.321","text":"用爻世爻绝于日辰，或化绝，有旧注诸事不利，余以休囚被克而又绝者，是也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.322","text":"旺相不妨，动逢冲而事散。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.323","text":"大凡世与用神或绝于日或化绝，若得日月动爻生者，谓之绝处逢生，且入寅日占卦酉为用神，酉绝于寅，若在辰戌丑月未月，或爻中动出辰戌丑未，以土生酉金，皆谓之绝处逢生。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.324","text":"如逢合住须冲破以成功，若遇休囚必旺相而成事。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.325","text":"速则动而克世爻，缓则静而生身。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.326","text":"此独占行人而用之，他占不用。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.327","text":"谓用神动而克世，行人回来之速也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.328","text":"用神静而生世，行人归来缓也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.329","text":"且如占父母何日归，父母动而克世者，许之归。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.330","text":"父亡而事无头绪，福隐而事不称情。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.331","text":"古法卦中无父母，事无头绪，卦无子孙无喜悦，余以此论为多事，凡占事者，用神原神忌神仇神克害刑冲破墓空绝日月飞伏许多事故尚无定论，不敢寻不当用之爻耶，余恐枝叶多生。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.332","text":"鬼虽祸灾，伏尤无气。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.333","text":"天元赋中无鬼论虽则有理，实亦多事，余生平以占官鬼疾病当用者则用，不当用者则不用也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.334","text":"子虽福德，多反无功。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.335","text":"觉子曰：以之为忌神者，实则不宜，以之为用神者，多则何害？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.336","text":"岂不闻损之斯成，逢墓库以收藏也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.337","text":"虎兴遇吉神不害其为吉，龙动而逢凶曜难掩其为凶。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.338","text":"元武为盗贼之事，亦必官爻。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.339","text":"朱雀为口舌之神，必须兄弟。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.340","text":"此论欠理，元武朱雀勾陈腾蛇动而不克世者，无碍。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.341","text":"动而克世者，皆以为凶，勿分兄弟官鬼。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.342","text":"吉凶神煞之多端，何如生克制化之一理。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.343","text":"此之言也，学者亦深味之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.344","text":"除恶未尽，须防死灰复燃。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.345","text":"克害刑冲之神，若得日月动爻克制者，须尽其根，若除而未尽，将来遇生扶之年月，仍复为祸。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.346","text":"如卯月甲申日占病得地山谦变水山蹇兄弟酉金″子孙子水″子孙亥水″世动父母戌土′父母丑土″兄弟申金″世兄弟申金′兄弟申金′官鬼午火″应官鬼午火″父母辰土″父母辰土″应断曰：亥水子孙长生于申日，世遇日建逢生，虽化戌土之克，春令土衰，卯月克制，有杀无妨。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.347","text":"果于丁亥日全愈。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.348","text":"岂知卯木虽克戌土，还有相合之意，亥水虽长生，戌土亦得长生于申，后至巳月亥逢月破，巳火生助戌土，谚语：斩草不除根，萌芽依旧生。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.349","text":"伤害不重，枯木犹有逢春。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.350","text":"世与动爻有气，若被日月动爻冲克者，目下虽克伤，他日逢生再发。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.351","text":"水要看源，木要寻根。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.352","text":"凡占身命、家宅、功名、坟墓、贸易等事，欲其久远者。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.353","text":"用神虽则为重，而元神必须兼看。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.354","text":"用神为事之体，元神为事之本。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.355","text":"用神虽旺，原神若被伤克者，即如水无泉源，木无根蒂，金火土者皆同。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.356","text":"如午月庚寅日占掣签何处。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.357","text":"得大畜变中孚卦。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.358","text":"官鬼寅木′官鬼卯木′妻财子水″应动父母巳火′兄弟戌土″兄弟未土″世兄弟辰土′动兄弟丑土″官鬼寅木′世官鬼卯木′妻财子水′父母巳火′应断曰世临寅木官星，必得东缺。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.359","text":"独嫌子水月破动而化绝，恐不能到任。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.360","text":"余曰：财为养命之源，又为朝廷之禄，今财临绝地，是无财无禄，世爻寅木无水滋生，乃为凶兆。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.361","text":"彼曰：改日洁诚再占。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.362","text":"甲午日又得临之节。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.363","text":"子孙酉金″妻财子水″妻财亥水″应动兄弟戌土′兄弟丑土″子孙申金″应兄弟丑土″兄弟丑土″官鬼卯木′世官鬼卯木′父母巳火′父母巳火′世余曰此与前卦，卦名虽殊，其理一也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.364","text":"又是亥水财爻被回头克，不独难以到任，还妨秋令危灾。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.365","text":"后果于七月，先得泻疾，略好后，因服补药太过，吃一次药，只能喝一两水，后竟渴死。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.366","text":"动爻空破又何妨。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.367","text":"如戌月己巳日余占南行得大有之大壮官鬼巳火′应动父母戌土″父母未土″兄弟申金″兄弟酉金′官鬼午火′世父母辰土′世父母辰土′妻财寅木′妻财寅木′子孙子水′子孙子水′应余以应爻为官星动而生世，官贵相生者，虽则可喜，但嫌巳火墓于戌月而又化墓，生我之官爻即又入墓耶，兼且又是六冲，疑为不吉。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.368","text":"又亥月甲辰日又占得大有变畜卦官鬼巳火′应妻财寅木′父母未土″子孙子水″应兄弟酉金′动父母戌土″父母辰土′世父母辰土′妻财寅木′妻财寅木′世子孙子水′子孙子水′余疑又得此卦，巳火虽则生世又为月破，破而不能生我，这何益。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.369","text":"况间爻酉金兄动乃阻隔耗财之神，疑之不行。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.370","text":"及至甲寅日又占又得大有之大壮官鬼巳火′应动父母戌土″父母未土″兄弟申金″兄弟酉金′官鬼午火′世父母辰土′世父母辰土′妻财寅木′妻财寅木′子孙子水′子孙子水′应连得三次，余始悟，曰：此行到明年三四月必定如心。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.371","text":"巳火之官动而生世，目下虽破入墓，明年三月冲开戌墓，巳火得出，至巳月得令，当时不破不空，旺相而生世矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.372","text":"即于巳日起程，行至中途遇旧识，母死又被回禄，同行，行不数日，又遇知己，道及某处有奇门一部，乃系抄本，命余同去买之，同道两日，余卜一卦，又得大有之大壮，余对友曰：此卦得之四次，非叫我买书，乃促我行也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.373","text":"竟行，后至地头，已二月矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.374","text":"一日于将军府中，将军问曰：江南其抚国，功名将来何如？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.375","text":"余曰：向于酉年占得艮之观卦，即许酉年离任，又许今年三月仍以原品起用。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.376","text":"卯月戊戌日占目下功名升否？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.377","text":"兄弟巳火′世动子孙戌土″世子孙未土″妻财申金″妻财酉金′兄弟午火′官鬼亥水′应动子孙辰土″应子孙丑土″父母寅木″父母卯木′官鬼子水′余曰：离变震卦，六冲而变六冲，世爻化墓入墓，亥水官星动化回头之克，大凶之兆，勿望升迁，且防刑狱。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.378","text":"将军曰：此吾侄也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.379","text":"曾在二十九岁于都门向尔占过，许之四十九岁有险。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.380","text":"今年四十九岁，有何险处？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.381","text":"余曰，既是卦之前后照应，目下诸事更宜慎之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.382","text":"一日于藩司署中藩台向余曰：此系余府尊，因得罪制台，已为辩护，看何如？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.383","text":"卯月庚子日占得风山渐。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.384","text":"官鬼卯木′应官鬼卯木′应父母巳火′父母巳火′兄弟未土″兄弟未土″子孙申金′世子孙申金′世父母午火″父母午火″兄弟辰土″兄弟辰土″断曰：子孙持世，官临应爻，禄位已属他人矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.385","text":"藩台曰：令尔报喜，如何此说？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.386","text":"余曰：有喜则报，此卦无喜可报也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.387","text":"府尊曰：今日不诚，明早请到敝处，诚意卜之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.388","text":"卯月辛丑日又占得火地晋卦官鬼巳火′官鬼巳火′父母未土″父母未土″兄弟酉金′世兄弟酉金′世妻财卯木″妻财卯木″官鬼巳火″官鬼巳火″父母未土″应父母未土″应余曰：今日卦与昨日相同，世爻破而入墓，官星两现，皆空破，彼之不服，余曰，再占一卦不妨。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.389","text":"又得恒之大过妻财戌土″应妻财未土″官鬼申金″动官鬼酉金′子孙午火′父母亥水′世官鬼酉金′世官鬼酉金′父母亥水′父母亥水′妻财丑土″妻财丑土″应余曰：恭喜，此地爵位虽已失矣！","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.390","text":"速速援刑例，再任西方。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.391","text":"彼曰：何以见之？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.392","text":"余曰：持世官星破而入墓，所以知其失之就矣！","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.393","text":"幸五爻官化进神乃再任之官也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.394","text":"余于彼地二月，占过数卦，尚无应验，及至三月将军之侄因昔年因陈不前，都中有人报出行文拿问；","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.395","text":"又见邸报，江南抚军果以原品起用；","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.396","text":"又本府府尊命下，不准复职，后援刑例果于巳年补陕庆阳府知府。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.397","text":"余于彼地三五月，了无宁日。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.398","text":"悟前火天大有连得四次，巳火之官而生世爻，应巳月官以相生，须知神报吉凶之月日不可照样而书符，全在人之变通也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.399","text":"大匠诲人，必以规矩。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.400","text":"卜者决断，全在灵机。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.401","text":"古圣先贤，教人占卜，先教人动静衰旺生扶拱合刑冲克害破墓绝空，种种关节不可放过，书宜熟看，自能触类旁通，随机应变，爻象一成，即知祸福。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.402","text":"用者重之，不用者去之，切不可谬柱而鼓瑟也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.403","text":"筮必诚心，子日不忌。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.404","text":"天下无事不由心生，心动求神，必须至诚。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.405","text":"故曰：诚则形，形则聚，聚则明。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.406","text":"心诚求之，卦必显而易见。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.407","text":"古有子不问卜，黄金策曰只在诚与不诚，不在子与不子。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.408","text":"占勿二念，早晚何妨。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.409","text":"一念之诚，可格天地。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.410","text":"一篮之用，可享鬼神。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.411","text":"若怀两三事而占者，念既不专心，何能一念多心？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.412","text":"故曰：遇事即占，不认早晚，慎勿两念，二念不验曾有先占求财后占丈人之病。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.413","text":"辰月乙丑日占求财得随之否妻财未土″应动妻财戌土′应官鬼酉金′官鬼申金′父母亥水′子孙午火′妻财辰土″世兄弟卯木″世兄弟寅木″子孙巳火″父母子水′动妻财未土″由占妻父病得水山骞子孙子水″子孙子水″父母戌土′父母戌土′兄弟申金″世兄弟申金″世兄弟申金′兄弟申金′官鬼午火″官鬼午火″父母辰土″应父母辰土″应若依本人之言告而断者先占求财，满盘俱足财星，其财彼得。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.414","text":"占丈人病者，父母临日月而不死，却不知二事从此人之念而出，神以前卦应丈人之病，财动克父，丈人病重辰日。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.415","text":"应辰日者，财爻属土，有辰乃土之墓耳。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.416","text":"后卦反应求财，兄爻持世，不得。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.417","text":"若非留神参悟，以前卦而断求财，以否卦断丈人之病者，令人喷饭。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.418","text":"余故曰：一念只占一事，不仿早占晚占，心怀两三事者，半夜求神，亦有错矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.419","text":"我有心事，不可叫他人代我去占，我之一念，他又一念，事二念也！","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.420","text":"曾有现任官府命家人代占防害，卯月戊戌日占主人目下灾悔否。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.421","text":"得比之咸妻财子水″应兄弟未土″应兄弟戌土′子孙酉金′子孙申金″动妻财亥水′官鬼卯木″世动子孙申金′世父母巳火″父母午火″兄弟未土″兄弟辰土″此卦若以本人念，占防害者，喜子孙克世，克去身边之鬼。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.422","text":"告以家人，占主以父母为用神，又以官爻而兼用，巳火父爻旬空而墓于戌日，卯官虽临月建，难挡叠叠之金，目下虽则无妨，秋来岂无险厄？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.423","text":"岂知此卦，竞应官府自己之念，世爻为用，子孙克世，以解其灾。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.424","text":"至申日闻信，有人往上司揭告，被人劝阻，讼之未成。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.425","text":"若以家人占主而决者，差别远矣；","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.426","text":"又有不应主人之念，而应家人之念者，故日我事必要亲占，命他人而代者，难取用神，必于不验。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.427","text":"他是诚心，持颂问神，让我先占，恐神不许。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.428","text":"我真诚问，早已举念，我让他占，神必应我。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.429","text":"曾于辰月癸未日欲占功名先代尊长而占于病。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.430","text":"得姤之涣卦父母戌土′妻财卯木′兄弟申金′官鬼巳火′世官鬼午火′应动父母未土″兄弟酉金′动官鬼午火″子孙亥水′父母辰土′应父母丑土″世妻财寅木″本人占功名得天泽覆兄弟戌土′兄弟戌土′子孙申金′世子孙申金′世父母午火′父母午火′兄弟丑土″兄弟丑土″官鬼卯木′应官鬼卯木′应父母巳火′父母巳火′若以前卦，断子病者，其子必死。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.431","text":"亥水子孙，日月伤克，世爻暗动，又伤子孙，兄申酉金，又被午火克坏，谓之忌神旺而元神衰，势之必死，岂知本人举念在前，前卦而应功名，午火官动而生世，世动官兴，五月高迁。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.432","text":"后卦竟应父占子病，申金子孙，日月生之，次日即愈。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.433","text":"他事由他动念，慎勿提他。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.434","text":"他之心事，未动念而占，我提醒他，叫他占，乃我之念也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.435","text":"曾有父叫子占功名午月辛酉日占功名得萃变遁。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.436","text":"父母未土″动父母戌土′兄弟酉金′应兄弟申金′应子孙亥水′官鬼午火′妻财卯木″动兄弟申金′官鬼巳火″世官鬼午火″世父母未土″父母辰土″此子十有五岁，父叫他占将来有功名否？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.437","text":"若于官星持世，夏火当令，未土父爻为文章，父化进神，功名有望，岂知父叫子占，乃父之念也，此卦乃是父占子也，父动克子只伤妻，此子未年而死。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.438","text":"未年死子者，未土父动，值未年以伤子也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.439","text":"夫应七月伤妻，卯木财爻绝于申也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.440","text":"余今亦曾叫人而占，另有一法，先向伊曰，尔之某事，须占一卦，目下我起之念，尔且莫占，待少刻忘怀，尔忽想起念而占之，即数之念，也屡验。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.441","text":"我占必以直告，却莫昧已，此等极多，难以枚举，有为婚姻故，占月令者。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.442","text":"因功名，故占流年。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.443","text":"有现任官府，欲望他人之缺，不便言之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.444","text":"故占在任之吉凶，有孝廉不明言卜会试，却问功名，有已生子，故问有子否？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.445","text":"如未月癸亥日占流年得艮卦。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.446","text":"官鬼寅木′世官鬼寅木′世妻财子水″妻财子水″兄弟戌土″兄弟戌土″子孙申金′应子孙申金′应父母午火″父母午火″兄弟辰土″兄弟辰土″此人已往军前援例，故占流年，只谓命有功名，流年必现，却不知占功名，以官为官，最喜官星持世。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.447","text":"占流年以官为鬼，不宜官鬼持世，余以此理告之，彼曰：烦人援例，如不知成否？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.448","text":"余曰：此卦官星持世，长生于亥日，业已成矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.449","text":"亥水为财，财旺生官。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.450","text":"果于申日文书实收俱到，应申日者，寅木官星持世，静而逢冲之日也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.451","text":"若以流年作鬼断者，如天远矣。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.452","text":"占远应近，务必留心。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.453","text":"天下之理生于动，有机则动，凡来占者，事在目前，心神迫情，两心相感，起课之人精神亦聚，吉凶立建；","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.454","text":"事尚无机，或占后运，或占不关切之事，甚有作戏谈而问占卦之人，不得已而应之，两心毫无相摄，卦亦茫然，卦之成者戏以远而报近事，或以近事而报远。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.455","text":"如未月丙辰日占财。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.456","text":"得咸之大过父母未土″应父母未土″兄弟酉金′兄弟酉金′子孙亥水′子孙亥水′世兄弟申金′世兄弟酉金′官鬼午火″动子孙亥水′父母辰土″父母丑土″应此人闲问，家中常见白人，必有古窖，何时得财？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.457","text":"余曰：卦中鬼变子孙，目下子女不利，彼小女出花，余曰：须防亥日，果死于亥日。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.458","text":"彼问：何所问得财，神报目下而死女？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.459","text":"应亥日者，午火鬼化亥水子也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.460","text":"又如酉月甲辰日占本月月令。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.461","text":"父母戌土′父母戌土′兄弟申金′应兄弟申金′官鬼午火′官鬼午火′应兄弟申金′兄弟酉金′官鬼午火″世动子孙亥水′父母辰土″父母丑土″世世爻午火动化亥水回头克，世辰年占卦，在午年子月而死。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.462","text":"占月令而现寿元，此占近而应远也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.463","text":"占此应彼，必须详察。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.464","text":"大凡占出卦象，必须细为详查，卦有不应所问之事，而反应所未问之事，其故何也？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.465","text":"神有舍小事而报大事，有舍小吉而报大凶，有舍此应彼，占我应他，占他应我，乃旦夕祸福将至，机之一动，卦必现，故曰：知机其神乎，此之谓也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.466","text":"如巳月已未日占小厮病妻财子水″应妻财子水″兄弟戌土′兄弟戌土′子孙申金″子孙申金″世官鬼卯木″世动子孙申金′父母巳火″父母午火″兄弟未土″兄弟辰土″应余曰：此卦不应小厮病，而应今秋功名有碍，彼曰：何也？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.467","text":"余曰：世临卯木之官化申金子孙回头克，是以知之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.468","text":"彼曰：我问小厮，如何应在功名？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.469","text":"余日：神之机常常如此，舍小事而报大凶，公之诸事须宜慎之，果于七月，被论革职，此占他而应我也！","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.470","text":"又如申月戊寅日占身病得坤之比子孙酉金″世妻财子水″应妻财亥水″动兄弟戌土′兄弟丑土″子孙申金″官鬼卯木″应官鬼卯木″世父母巳火″父母巳火″兄弟未土″兄弟未土″断曰：卦中世爻酉金绝于寅日，所幸秋天问卜，正值旺相，故自身无灾。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.471","text":"防九十月妻财有危。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.472","text":"因亥水财爻化戌土为回头克。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.473","text":"彼曰：吾病已重。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.474","text":"余曰：卦中子孙持世，不药而愈。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.475","text":"九月妻死，是占我应他。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.476","text":"又如未月丁亥日占母病得坤之剥。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.477","text":"子孙酉金″世动官鬼寅木′妻财亥水″妻财子水″世兄弟丑土″兄弟戌土″官鬼卯木″应官鬼卯木″父母巳火″父母巳火″应兄弟未土″兄弟未土″断曰：此卦不现母病，而现子女有灾。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.478","text":"余曰：令堂近病，卦得六冲即愈，只不宜爻中现出子孙变鬼，伊曰：小儿初生两月。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.479","text":"余日：八月防之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.480","text":"果于八月其子惊风，又来卜之。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.481","text":"酉月丁卯日又占子病得既济之革兄弟子水″应官鬼未土″官鬼戌土′父母酉金′父母申金″动兄弟亥水′世兄弟亥水′世兄弟亥水′官鬼丑土″官鬼丑土″子孙卯木′子孙卯木′应断曰：卯木子孙，临月破，又动出申金伤克，虽值日辰，难过酉月卯日。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.482","text":"余曰：向占母病，已应八月死子。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.483","text":"今又得此凶卦，何以救之？","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.484","text":"夫应于卯日者，乃实破之日也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.485","text":"李我平曰：黄金策千金赋，乃诚意先生所著，昔有人曰：有能易一宇者，予以千金，后因刻板错误，以讹传讹，致白玉生瑕，不意野鹤老人，前后增删，另作解注，以成全壁。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c41.486","text":"余不能遣以千金，从此名之万金赋可也。","chapter":"卷之四·两现章第三十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.1","text":"增删《黄金策》天道旱涝不定，易爻阴晴可测。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.2","text":"古以晴雨之占，不可以有试其行术而轻渎鬼神，如亢旱求雨，涝则求晴，始可卜之。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.3","text":"余曰：不然，正可以此试其术何也！","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.4","text":"卦之微妙，初学难知，以人事而卜，不易得验；","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.5","text":"以天时而卜，目下即可得验。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.6","text":"天时人事，皆不离五行。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.7","text":"天时得验，人事验矣，余初学卜，皆赖天时之巧应，得其微妙之处。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.8","text":"子孙为日月星斗，动则万里晴光。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.9","text":"黄金策以财动者，八方咸仰晴光，非也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.10","text":"子孙发动，万里无云，财以子孙为原神，财动虽晴，倘如子孙休囚空破，或现而不动，必不大晴，当有浮云薄雾。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.11","text":"如卯月甲午日占晴兄弟戌土″兄弟未土″子孙申金″动子孙酉金′世父母午火′世妻财亥水′兄弟辰土′兄弟辰土′官鬼寅木′官鬼寅木′应妻财子水′应妻财子水′申金子动化进神，酉日碧天如洗。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.12","text":"或曰：凡存占验，皆尚奇微巧验，此卦显而易见，何故录之？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.13","text":"余曰：令初学者易知，由浅以入深也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.14","text":"奇验于理，后卷有之。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.15","text":"父母为雨雪雾霜，发则八方润泽。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.16","text":"凡占，须以分看，或求晴、求雨、求雪、求霜，念专于一而神告矣。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.17","text":"宜分请求于何地？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.18","text":"神曰：域内晴否？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.19","text":"或占本乡、或占本省、不然天下何日不晴？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.20","text":"指其地而占之可也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.21","text":"法以父母为天地，天地闭塞，而日月塞，而日月掩藏，此亦近理。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.22","text":"余以父母为厚云重雾，父动伤子，掩其日月也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.23","text":"所以父爻发动，云雾迷天，日月掩藏而雨矣。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.24","text":"如巳月甲戌日占天何日雨得小过之旅父母戌土″动官鬼巳火′兄弟申金″父母未土″官鬼午火′世兄弟酉金′应兄弟申金′兄弟申金′官鬼午火″官鬼午火″父母辰土″应父母辰土″世因连日大晴，本日卯时占何时雨？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.25","text":"即于辰时起云，辰末巳初雷雨大作，应辰时者，戌日冲辰父而暗动，雷雨大作者，戌化巳火鬼也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.26","text":"财动克父而生子孙，所以主睛。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.27","text":"如酉月乙巳日占本日阴晴：得升之恒官鬼酉金″妻财戌土″应父母亥水″官鬼申金″妻财丑土″世动子孙午火′官鬼酉金′官鬼酉金′世父母亥水′父母亥水′妻财丑土″应妻财丑土″此卦丑土财动化出午火子孙，上半日虽晴常有浮云掩日，至午时之后满天红日无云，所以财爻虽主晴明，难免无云，至午时而见子孙，始大晴也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.28","text":"官鬼乃父母之原神，动则生父，故主雾霆雷电。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.29","text":"或应雷霆，不拘春复秋冬，方可执以为雷霆雾电看是也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.30","text":"如巳月丁卯日占天何日雨得恒之大过妻财戌土″应妻财未土″官鬼申金″动官鬼酉金′子孙午火′父母亥水′世官鬼酉金′世官鬼酉金′父母亥水′父母亥水′妻财丑土″妻财丑土″应世爻酉鬼暗动，申鬼明动化进神，本日申时，霹雹擎天，远方大雨，而本处洒来几点，或曰：因父爻月破。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.31","text":"予曰：非也，父爻若动，虽临月破，亦作大雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.32","text":"应乃太虚，逢空雨晴难定，世为大地，受克天变非常。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.33","text":"觉子曰：占雨用父爻，占晴用子孙爻、财爻，世应何干？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.34","text":"余曾占雨占晴，一卦不现，再占两卦。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.35","text":"六爻不动者，务必求其动而验之。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.36","text":"何故而曰雨晴难定？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.37","text":"假使人间趋避，亦可答曰我难定耶？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.38","text":"至于世爻受克而天变者，系偶然凑合一两卦耳，何得以之为法？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.39","text":"余常占得官父兄爻克世者不少，未见天变，此两句宜删之。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.40","text":"若论风云全凭兄弟。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.41","text":"兄弟发动，虽主风云乃云淡风轻之景，非晴非雨之天。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.42","text":"每见兄动而日月于云中穿走，怎隐乍出现。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.43","text":"如午月丁亥日占本日阴晴得逐之否父母戌土′父母戌土′应兄弟申金′应兄弟申金′官鬼午火′官鬼午火′兄弟申金′动妻财卯木″世官鬼午火″世官鬼巳火″父母辰土″父母未土″或曰：兄动为风云，今日还是阴天。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.44","text":"余曰：申金兄爻为云，化卯木财爻，是由云雾中变出日色之象，果一日阴云申时而见日色，次日卯时大晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.45","text":"更详四季推辞，须配五行参决。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.46","text":"黄金策曰：父母爻四时主雨，若临金水雨大而不止，若临火土雨小而不久。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.47","text":"觉子曰：此系不论衰旺四时，皆以父临水则雨大，临火则雨小。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.48","text":"既不论衰旺如何，后章又曰：父持月建必然阴雨连旬，假使巳午未月火土当令之时，正大雨施行之际，若值父临火土而动，如以旺衰而论，父旺当主阴雨连旬；","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.49","text":"若以五行来决，论火土者当断之雨小。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.50","text":"古法之错，何以不删？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.51","text":"更可笑者，旧注有云，冬天以子孙为霜雪，以子孙为霜雪，倘值冬令占晴，以何爻而用？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.52","text":"明昔贤悖理之廖，当时而不省悟者，何也？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.53","text":"如子月已亥日因连日雪占何日晴得观之比妻财卯木′动子孙子水″应官鬼巳火′父母戌土′父母未土″世兄弟申金″妻财卯木″妻财卯木″世官鬼巳火″官鬼巳火″父母未土″应父母未土″断曰：两爻火鬼暗动，今日还是阴天，卯木财爻化出子孙子水，明日卯时必晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.54","text":"果于次日卯时，云开日出，此子水者既临月建，又有亥月拱之，旺之无比。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.55","text":"若以之为霜雪，不独不晴，既当雪深十尺。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.56","text":"所以占天时，不论旺衰，亦未有以子孙为霜雪也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.57","text":"晴或逢官，为烟为雾。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.58","text":"旧注卦得时兆，爻中又有鬼动者，必须有浓云重雾，或恶风晦暗，冬或大寒，夏或大热，非风和日霞之天。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.59","text":"余以此论有理，但须分别时辰。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.60","text":"既如辰月已卯日占本日阴晴得屯之临兄弟子水″父母酉金″官鬼戌土′应动兄弟亥水″应父母申金″官鬼丑土″官鬼辰土″官鬼丑土″子孙寅木″世动子孙卯木′世兄弟子水′妻财巳火′断日寅木子孙化进神，今日大晴，五爻戌土鬼动，戌亥时必主黑云。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.61","text":"果于戌时，星辰无光。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.62","text":"若以一日之烟雾断者，错也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.63","text":"雨而遇福，为电为虹。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.64","text":"卦得有雨之象，子孙亦动者，非有闪电，则有彩虹，余以之为非。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.65","text":"三合成财问雨难堪八卦。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.66","text":"三合财局子孙局者，主晴．","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.67","text":"三合父局主雨，三合鬼局，黑雾迷天或雷电闪烁，三合木局主风。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.68","text":"五乡连父晴怪杀临空。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.69","text":"旧注谓父爻空而无雨，子孙及财爻空而不晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.70","text":"余常占雨，父母休囚不动，果是难望。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.71","text":"若值空者，勿谓无望，常得父爻动而逢空，不应冲空之日，则应填实之期。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.72","text":"百试百验，财与子孙空者，同此。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.73","text":"财化鬼阴晴不久。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.74","text":"旧注系财化鬼阴晴未定，非也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.75","text":"如巳月甲寅日因连日晴占何日雨，得既济变蹇兄弟子水″应兄弟子水″官鬼戌土′官鬼戌土′父母申金″父母申金″世兄弟亥水′世父母申金′官鬼丑土″妻财午火″子孙卯木′动官鬼辰土″应若以财化鬼阴晴未定，此卦卯木子孙化辰土鬼，岂可曰阴晴两来，殊不知卯木子卯日晴，辰土鬼日天变则不晴矣。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.76","text":"余断辰日天阴，巳日必雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.77","text":"何以知其巳日雨？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.78","text":"卦中申金父爻暗动，动而逢令之日，果于辰日天变，巳日大雨，故曰，子孙爻、财爻、化鬼，晴之不久，父爻动化子，乃雨之不久，非阴晴而难定。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.79","text":"父化兄风雨靡常。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.80","text":"父化兄，父化鬼或卦中父动兄动皆主风雨交作，若论前后，动者为先，变者为后，既如兄化父先风而后雨，鬼化父春夏占者先雷后雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.81","text":"觉子曰：鬼动虽为雷电，应雷者少，黑云者多，不可执之。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.82","text":"父化子雨后晴明，弟化孙云开日出。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.83","text":"旧注系母化子，长虹满带，非也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.84","text":"如午月乙卯日因连日雨本日亦雨，占何日晴父母酉金″动子孙寅木′世兄弟亥水″兄弟子水″官鬼丑土″世官鬼戌土″兄弟亥水′父母申金′应官鬼丑土″妻财午火″子孙卯木′应动官鬼辰土″余曰：今日酉时必见红轮西堕，明日还见阴天。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.85","text":"余曰：六爻酉父化子，今日酉时落日。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.86","text":"初爻卯木化辰鬼，明朝辰日必是阴云。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.87","text":"果于酉时忽然天开，见日色。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.88","text":"父持月建必然阴雨连旬。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.89","text":"父母临月建而动者雨必不止，野鹤曰：此以旺衰而言，余试不验。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.90","text":"如午月丙午日占何日雨得大壮之升兄弟戌土″子孙酉金″子孙申金″妻财亥水″父母午火′世动兄弟丑土″世兄弟辰土′子孙酉金′官鬼寅木′妻财亥水′妻财子水′应动兄弟丑土″应又如申月丙辰日占何日得坎之困兄弟子水″世官鬼未土″官鬼戌土′父母酉金′父母申金″动兄弟亥水′应妻财午火″应妻财午火″官鬼辰土′官鬼辰土′子孙寅木″子孙寅木″世前卦午火父动，未时一阵大雨而酉时既晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.91","text":"后卦申金爻动庚申日雨辛酉半阴晴亥时大晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.92","text":"前卦不惟父持月建，且临日辰，从卦父持月建，辰日生之，旺莫如此也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.93","text":"似此之旺且无风雨连旬，而况他乎？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.94","text":"余试天时，兄坐长生，才能定风累日，如辰月戊申日占本日阴晴得中孚之小畜卦官鬼卯木′官鬼卯木′父母巳火′父母巳火′兄弟未土″世兄弟未土″应兄弟丑土″动兄弟辰土′官鬼卯木′官鬼寅木′父母巳火′应妻财子水′世丑土兄动化进神临月令，父长生於申日，若论旺衰，旺之无比，并不见，狂风累日，只见一日阴云而已。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.95","text":"或曰：兄动化进神不见狂风者，以何爻而至狂风？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.96","text":"余曰：水动化进神乃狂风可。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.97","text":"父财无助旱涝有常。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.98","text":"旧注：官鬼空伏，父母无气，而财爻旺动者必旱；","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.99","text":"子孙空伏，妻财无气，而父爻旺者必涝，再遇日月动爻扶者，涝必至於浸没。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.100","text":"觉子曰：若重旺衰，此论何当无理？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.101","text":"余存四十余年之占验，天时无日不占，时当涝者鬼动亦雨，兄动亦雨，父鬼休囚无气者动亦有雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.102","text":"时当旱者，父持月建，亦不过浓云重雾而已。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.103","text":"故章有云，竟发父官，连朝风雨，凡卦中父鬼乱动而雨水连续而不止也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.104","text":"福德带刑日月必蚀。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.105","text":"此乃特占日月之论，不可以占阴晴之卦偶而凑合者而弃断也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.106","text":"雨嫌妻位以逢冲。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.107","text":"占雨倘父爻不动而妻财暗动者还主晴明。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.108","text":"占晴若子财不动而父母暗动者还主雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.109","text":"晴利父官而化退。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.110","text":"旧系晴利父爻之入墓成动而化墓，必主晴明，余以为非父爻入墓，冲开之时则雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.111","text":"惟父动化退神，势必晴也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.112","text":"如丑月戊辰日久雪占晴，得随之震。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.113","text":"妻财未土″应妻财戌土″世官鬼酉金′动官鬼申金″父母亥水′子孙午火′妻财辰土″世妻财辰土″应兄弟寅木″兄弟寅木″父母子水′父母子水′断曰：鬼化退神雨将止矣，果于酉时雾散天开。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.114","text":"凡得父化退神，雨亦将止。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.115","text":"兄动化退神，云将开。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.116","text":"于子孙财爻化退神者，晴不久矣。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.117","text":"子伏财飞淡云雾轻。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.118","text":"旧系子伏财飞曝夫犹抑，谓财动虽主晴明，若子孙休囚空伏乃阴晴之象。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.119","text":"余以此论是理，此章首句，原系“妻财发动，八方咸仰晴光。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.120","text":"”余故改曰：“子孙发动，万里晴光”。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.121","text":"父衰鬼旺少雨浓云。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.122","text":"占雨以父爻为主，若父爻不动且不暗动，而官鬼者动必主浓云厚雾而无雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.123","text":"倘爻变出父母者不拘旺衰皆主有雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.124","text":"卦传暗冲虽空有望。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.125","text":"父母官鬼静而逢空，日建冲之主雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.126","text":"子孙财爻静而逢空，日建冲之主晴，木临兄鬼静而逢空，日建冲之主风。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.127","text":"兄弟临空日建冲主轻风薄雾。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.128","text":"如巳月已卯日占何日晴得离卦兄弟巳火′世兄弟巳火′世子孙未土″子孙未土″妻财酉金′妻财酉金′官鬼亥水′应官鬼亥水′应子孙丑土″子孙丑土″父母卯木′父母卯木′酉财旬空，本日日建冲动，次日即晴，乃应动而逢冲之日。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.129","text":"福兴被克，冲则成功。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.130","text":"卦中子孙爻动化回头克，或被动爻克，须待冲去克神之日始晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.131","text":"父财动而被克亦同此断。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.132","text":"如丑月甲戌日占何日雨得震之豫卦。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.133","text":"妻财戌土″世妻财戌土″官鬼申金″官鬼申金″子孙午火′子孙午火′应妻财辰土″应兄弟卯木″兄弟寅木″子孙巳火″父母子水′动妻财未土″世断曰：父母子水动被未土回头克，丑日雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.134","text":"应丑日者，冲去未土合起父母，故雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.135","text":"“木动生风，风伯肆虐”（缺）“金空则响，电母施威”（缺）如辰月癸卯日因晴占何日雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.136","text":"得蹇卦子孙子水″子孙子水″父母戌土′父母戌土′兄弟申金″世兄弟申金″世兄弟申金′兄弟申金′官鬼午火″官鬼午火″父母辰土″应父母辰土″应或曰：卦中辰戌父爻，月建又是父爻，明日辰日冲动，戌父必然有雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.137","text":"余曰：戌临月破，如何有雨？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.138","text":"阴云而已，果于次日常见阴云。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.139","text":"冲则应，填则实，最喜动空。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.140","text":"人以为空则无功，殊不知动而空者，占晴占雨若非冲空之日，定应填实之朝。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.141","text":"如未月丙午日占何雨，得离之旅兄弟巳火′世兄弟巳火′子孙未土″子孙未土″妻财酉金′妻财酉金′应官鬼亥水′应妻财申金′子孙丑土″兄弟午火″父母卯木′动子孙辰土″世断曰：卯木父动临于旬空，己酉若不雨，卯日必雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.142","text":"或曰：如何定在两日？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.143","text":"余曰：不难，再占一卦。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.144","text":"余曰：此卦还以前卦相同。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.145","text":"再占一卦又得艮之谦卦官鬼寅木′世动子孙酉金″妻财子水″妻财亥水″世兄弟戌土″兄弟丑土″子孙申金′应子孙申金′父母午火″父母午火″应兄弟辰土″兄弟辰土″断曰：甲寅日阴云，乙卯日必雨，辰日而又晴矣。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.146","text":"彼曰：何余知止？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.147","text":"余曰：此卦又是寅木鬼动值旬空，出空之日，必定天变。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.148","text":"前卦卯木父变辰土子孙，故知卯日必雨辰日必晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.149","text":"果于寅日云卯日大雨辰日大晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.150","text":"所以动则不为空矣。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.151","text":"占雨遇财动，欲雨须得财墓绝。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.152","text":"雨须宜父动鬼动，倘父鬼不动，又见妻财子孙动者，须待财爻入墓或临绝之日有雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.153","text":"占晴须于财动，倘若父母发动，须得父爻临墓绝之日方能得晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.154","text":"如戌日丙午日占何日雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.155","text":"得坎之井卦兄弟子水″世兄弟子水″官鬼戌土′官鬼戌土′世父母申金″父母申金″妻财午火″应动父母酉金′官鬼辰土′兄弟亥水′应子孙寅木″官鬼丑土″或曰：今日占雨，如何有动财爻，想是大旱，而无雨也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.156","text":"余曰：非也，化出酉父，酉日就当有雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.157","text":"但因日建，又因午火，必待戌日午火入墓，方晓有雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.158","text":"果于酉日天变，戌日而雨，午火财爻墓于戌也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.159","text":"占晴逢子动，望晴只待子逢生。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.160","text":"占晴得子财动，占雨得父动，后逢长生之日应之。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.161","text":"如卯月丁巳日占何日雨：得涣之坎卦父母卯木′动官鬼子水″世兄弟巳火′世子孙戌土′子孙未土″妻财申金″兄弟午火″兄弟午火″应子孙辰土′应子孙辰土′父母寅木″父母寅木″卯木父动，当应在卯戌日，而雨却应长生亥日。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.162","text":"竟发父官，连朝猛雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.163","text":"卦中父鬼重叠或又鬼变父，父变鬼，父化兄，兄化父，或连日又占并不见子孙财爻发动者，一定连旬风雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.164","text":"如午月乙卯日占何日晴，得晋之归妹。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.165","text":"官鬼巳火′动父母戌土″应父母未土″兄弟申金″兄弟酉金′世官鬼午火′妻财卯木″父母丑土″世官鬼巳火″动妻财卯木′父母未土″应动官鬼巳火′断曰：父鬼叠见，乃连朝风雨之象。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.166","text":"次日又占，又是鬼父同动，果雨旬日。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.167","text":"多逢财子，累日明晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.168","text":"未月甲午日占何日雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.169","text":"得屯之中孚兄弟子水″动子孙卯木′官鬼戌土′应妻财巳火′父母申金″官鬼未土″世官鬼辰土″官鬼丑土″子孙寅木″世动子孙卯木′兄弟子水′妻财巳火′应大旱望云雷，卦中父爻不动，子孙重叠化进神，疑其木爻入墓之日必雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.170","text":"又令他日占之，又得财爻子不动，次日又占并无父动鬼动，知其旱矣，果然两月不雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.171","text":"卦得反吟晴雨终须反复。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.172","text":"如辰月庚寅日占何日晴得观之升妻财卯木′动兄弟酉金″官鬼巳火′动子孙亥水″父母未土″世父母丑土″世妻财卯木″动兄弟酉金′官鬼巳火″动子孙亥水′父母未土″应父母丑土″应断曰：卯木财现，明日必晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.173","text":"但卦得内外反吟，晴而还雨，果于次日晴还又雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.174","text":"爻逢伏象，旱涝必待冲开。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.175","text":"伏吟卦动如不动，子财动者，冲开之必晴，父爻动者，冲开之日必雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.176","text":"如辰月甲戌口占雨，得大壮变震卦。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.177","text":"兄弟戌土″兄弟戌土″世子孙申金″子孙申金″父母午火′世父母午火′兄弟辰土′动兄弟辰土″应官鬼寅木′动官鬼寅木″妻财子水′应妻财子水′占雨，父爻不动，兄鬼同动，木动生风，无雨而有风也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.178","text":"既于本日申时冲开寅木，扳木狂风。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.179","text":"合父鬼冲开有雷则雨，合财兄克破无风不晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.180","text":"父母合住本主不雨，若遇鬼冲动者，须待必雷震而后有雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.181","text":"卦中若无鬼爻动而他爻冲动者亦有雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.182","text":"他爻又无冲动者，须待冲开之日有雨，财子两爻被合亦同此推。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.183","text":"觉子曰：合父鬼冲开之日必雨，合财子冲开之日必晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.184","text":"必雷有风者仍然耳，不它执之。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.185","text":"半晴半雨卦中财父同兴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.186","text":"旧注：妻财父母同兴，或是子孙鬼爻同动，必然半晴半雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.187","text":"余以此论亦谬，殊不知各因其时。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.188","text":"如酉月癸未日占何晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.189","text":"子孙戌土′动子孙未土″应妻财申金′妻财酉金′兄弟午火′世官鬼亥水′兄弟午火″子孙辰土″世子孙辰土′动父母寅木″父母寅木″应动官鬼子水′此卦子孙父母同兴，寅木父化火兄，又是一日阴雨，至戌时，天开而见星斗，应戌时晴者，戌土子孙而值时也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.190","text":"又雨又晴爻上母子皆动。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.191","text":"如巳月丙申日占何日得临之蒙子孙酉金″动官鬼寅木′妻财亥水″应妻财子水″兄弟丑土″兄弟戌土″世兄弟丑土″父母午火″官鬼卯木′世兄弟辰土′父母巳火′动官鬼寅木″应卦中父母子孙皆动，因巳火父空，亥日冲空则雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.192","text":"亥日而雨，即于亥日酉时晴，应酉时者，上爻动出酉金子孙之故耳。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.193","text":"前卦父兴子孙同动，戌土子孙应本日戌时晴。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.194","text":"后卦父兴子孙同动应他日之雨晴之时也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.195","text":"觉之占远应近可积为神。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.196","text":"如酉月初五戊子日占中秋雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.197","text":"得小过之丰卦父母戌土″父母戌土″兄弟申金″兄弟申金″世官鬼午火′世官鬼午火′兄弟申金′子孙亥水′官鬼午火″父母丑土″应父母辰土″应动妻财卯木′卦中辰父发动，当许中秋有雨，殊不知应在初九辰日即雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.198","text":"即于壬辰日又占中秋晴否癸巳日又占，得屯之中孚兄弟子水″动子孙卯木′官鬼戌土′应妻财巳火′父母申金″官鬼未土″世官鬼辰土″官鬼丑土″子孙寅木″世动子孙卯木′兄弟子水′妻财巳火′应一卦财动，一卦子动，不见父鬼爻动，知其晴，果于中秋夜，月明星稀。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.199","text":"诚得卜日应时，方得其奥。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.200","text":"辰日癸巳日占甲午日，临造此日有雨否父母戌土′动父母未土″应兄弟申金′应兄弟酉金′官鬼午火′子孙亥水′兄弟申金′兄弟申金′世官鬼午火″世官鬼午火″父母辰土″父母辰土″彼以父动有雨，余曰：应时日看，今日申戌时而无雨者，明日必有雨也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.201","text":"果于本日申时雨。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.202","text":"彼：又是如何申时雨？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.203","text":"余曰：戌土是长生在申。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.204","text":"又问：雨至何时？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.205","text":"余曰：父化退神，雨不久。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.206","text":"果于次日大晴，野鹤曰：或向余曰：有动而逢合、逢值，可能只知其日也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.207","text":"余曰：昔人不知多占之法，亦不明其此理，错断有之，天机未必全泄，全在人之变通。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.208","text":"圣人立教设此天时，教人以验人事。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.209","text":"即如子孙持世发动，占天时者皓日当空，无云点缀。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.210","text":"乃至墓绝之日，黑暗无光。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.211","text":"若占身命，烈烈轰轰，扬扬得志，后逢墓衰之年，灾非同至。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.212","text":"余言：教人以天时而验人事，取效之速。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.213","text":"今欲久知一日者不难，曾因官长有事，命在旦夕，因占得子孙持世，劝之勿忧，必蒙赦免。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.214","text":"彼不肯信，意欲先寻自尽。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.215","text":"酉日丙子日占何日雨得蒙之临卦父母寅木′动妻财酉金″官鬼子水″官鬼亥水″应子孙戌土″世子孙丑土″兄弟午火″子孙丑土″子孙辰土′父母卯木′世父母寅木″应动兄弟巳火′上下寅木父动，明知寅日必雨，再叫人占何日雨，又得大壮之泰卦兄弟戌土″子孙酉金″应子孙申金″妻财亥水″父母午火′世动兄弟丑土″兄弟辰土′兄弟辰土′世官鬼寅木′官鬼寅木′妻财子水′应妻财子水′前卦寅木父动，当应寅日，此卦午火父爻长生于寅亦是。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.216","text":"又叫人再占，得随之屯。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.217","text":"妻财未土″应父母子水″官鬼酉金′妻财戌土′应父母亥水′动官鬼申金″妻财辰土″世妻财辰土″兄弟寅木″兄弟寅木″世父母子水′父母子水′又见亥水父动知寅日必雨也，何也？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.218","text":"亥水父动，动而逢合之日，亦应寅日。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.219","text":"又至寅日五更又占本日何时有雨得睽之履父母巳火′兄弟戌土′兄弟未土″动子孙申金′世子孙酉金′世父母午火′兄弟丑土″兄弟丑土″官鬼卯木′官鬼卯木′应父母巳火′应父母巳火′余以前三卦俱应寅日而雨此，卦未土动化出申金子孙，此应一爻独发，知其未时必雨申时大晴，清晨往彼安慰之曰：卜公之卦子孙持世无灾，公不肯信，试看今日未时雨，申时晴者，公知我卦之灵，从此不须忧也，彼留於家，见午末未初雨从西南而来，未时大雨，申时云散天开。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.220","text":"合家齐曰：真神卦也。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.221","text":"余曰：既知天时，何难知其人事？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.222","text":"公宜宽心，过半月，果蒙恩赦。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.223","text":"或日：未土兄动，如何指定未时必雨？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.224","text":"余曰：神已报定寅日雨，今日再问者，又报晴时，不然目下已是晴天，如何又现申金子孙？","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.225","text":"全在灵机变通耳。","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c42.226","text":"增删卜易卷之三野鹤老人著楚江李坦我平鉴定湖南李文辉觉子增删男婿陈文吉茂生茹芝山秀仝校","chapter":"卷之四·天时章第三十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c43.1","text":"诸书占身命，谓妻财子禄一卦，能包寿夭穷通，六爻兼断。","chapter":"卷之四·身命章第三十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c43.2","text":"殊不知父子财官兄弟，各有相忌相伤，若以一卦而兼断者，即如父母旺相，变应之微，又曰父旺伤子，岂世之有父母者，皆无子嗣之人也？","chapter":"卷之四·身命章第三十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c43.3","text":"又曰见兄则财莫能得，又为克妻之神，又曰兄弟爻与紫荆并茂，倘值旺兄持世，克妻耶？","chapter":"卷之四·身命章第三十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c43.4","text":"易林补遗有曰兄动妻亡财相，故执此论者，世之贫人寒士，皆失偶之人耶？","chapter":"卷之四·身命章第三十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c43.5","text":"至于财官子孙皆同此论，不暇细辨。","chapter":"卷之四·身命章第三十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c43.6","text":"必兼而断者，即先医犹在，执此问之，知亦无从置喙。","chapter":"卷之四·身命章第三十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c43.7","text":"觉子曰余今得其法，乃分占之法也，占父母占兄弟，另占—卦终身财福何如？","chapter":"卷之四·身命章第三十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c43.8","text":"占终身功名有无？","chapter":"卷之四·身命章第三十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c43.9","text":"占终身夫妻偕老否？","chapter":"卷之四·身命章第三十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c43.10","text":"占终身子嗣及帮元俱宜分占。","chapter":"卷之四·身命章第三十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.1","text":"福财旺相，钟鸣鼎食之家。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.2","text":"世爻旺相无伤，既富且寿。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.3","text":"觉子曰：占财宜于财旺，占寿独重世爻，未闻财福不旺而世爻独旺，即许富与寿也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.4","text":"执此论者世之多寿者皆富贵之人也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.5","text":"凡占终身财福，世爻财爻子孙爻三者无一失陷，定是家殷户足、福禄绵长。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.6","text":"财世旺相而福神不旺者，乃先富后贫之人也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.7","text":"子孙者，财之源也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.8","text":"水无源流，终须枯涸，谓之财旺福空荣华不久。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.9","text":"世与福爻旺相而财爻不旺者，乃无财享福之人也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.10","text":"既曰无财，焉能享福？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.11","text":"此人心有现成之事业，祗知坐享，不知生发；","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.12","text":"或是财托他人掌管，祗知花费，不试艰难。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.13","text":"财与福爻旺相而世爻不旺者，乃富屋之贫人也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.14","text":"觉子曰：以上之论，不旺所句者，无气失陷谓之不旺，得地有气亦谓之不旺，空破墓绝亦谓之不旺。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.15","text":"财福旺而世爻不旺而有气者，从逢生之年复旺相。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.16","text":"故谓之财福司权，荣华有日。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.17","text":"财福两旺，世爻无气者，不为吉也，虽旺财丰衣足食，不免痴痖暗聋、或遭疾病官非、或系吝涩鄙俗。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.18","text":"财福两旺而世爻失陷者，更为凶也，虽有万斛金银，难买长生药丹。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.19","text":"前论财与福神，虽则不旺，亦宜有气，若失陷者，更为凶兆，财福失陷，立见倾家，唯动空及动而破者，不妨定(应实)破(实)空之年月也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.20","text":"财世休囚，龟釜生尘之宅。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.21","text":"世爻财爻福爻三者无气、或空破墓绝、或动而变凶，乃无衣乏食之人也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.22","text":"世爻得地、而财福失陷者，此人身强力健、或有小谋小技，亦可支撑度日。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.23","text":"世爻福爻有气、财爻无气者，虽则贫寒乐享清福。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.24","text":"世爻财爻有气、福爻而无气者，此人虽无积蓄，手头常过金银、或代人掌财，再得日月动爻生扶者，亦许小成。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.25","text":"如卯月申日占终身财福得复之颐子孙酉金″动官鬼寅木′妻财亥水″妻财子水″兄弟丑土″应兄弟戌土″世兄弟辰土″兄弟辰土″官鬼寅木″官鬼寅木″妻财子水′世妻财子水′应五爻亥水财、世爻子水财，皆长生于申日，虽不当令，却得日建之生，独嫌酉金福冲破而化绝，生平衣禄不少，难于积蓄成家。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.26","text":"果此人自三十七岁入典铺掌柜，财东更换者三，此人依然在柜，活至七旬之一，每年工食养家，此应财爻持世遇长生也，生四子二女。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.27","text":"若执古法而兼看，卦中子孙破化绝，乃无子也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.28","text":"黄金策曰：世位休囚，非贫即夭。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.29","text":"余以为非贫者，须观财福。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.30","text":"夭者，单用世爻。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.31","text":"非夭即贫，不是卜易之理。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.32","text":"世居空位，终身作事无成。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.33","text":"旧注大忌世空，一生百事无成。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.34","text":"余以此论近理，但未分出旺与动，世爻旺而空者，谓之带旺匪空。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.35","text":"动不为空，遇日建冲者，冲空则实空之年，勃然发福。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.36","text":"如戌月辛亥日占终身财福得比之观卦妻财子水″应动官鬼卯木′兄弟戌土′父母巳火′子孙申金″兄弟未土″世官鬼卯木″世官鬼卯木″父母巳火″父母巳火″兄弟未土″兄弟未土″应断曰：世爻虽空，月建合之，亥日生之，子水财爻动而生世，卯年一定成家，丑年占卦，果至卯年立业成家。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.37","text":"彼时定鼎之初，云贵才平，此人于川中带出附子黄莲桑材数担，勃然家蓄数千余金，从此立业成家，连年丰足，此岂可谓终身作事无成耶？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.38","text":"又如酉月辛未日占终身财福得颐卦兄弟寅木′兄弟寅木′父母子水″父母子水″妻财戌土″世妻财戌土″世妻财辰土″妻财辰土″兄弟寅木″兄弟寅木″父母子水′应父母子水′应断曰：财爻持世，虽有未日扶拱，不宜旬空。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.39","text":"卦中无火生助，占身命之最忌也，难许成家。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.40","text":"此人自二十五岁至五十多岁东奔西走，一事无成，后因贫困，从戒外出。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.41","text":"如此者谓之生平作事无成，可也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.42","text":"身入墓乡，到老求谋多泪。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.43","text":"世爻有墓，但有一墓者，若休囚无气，主其人如痴如醉、不伶不俐、动静行藏心不响快、凡为不遂。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.44","text":"觉子曰：世爻若得临于日月，或日月生扶、或动而化吉、不逢冲墓之年，果然颠倒昏迷，及逢墓库冲开，如苗逢雨。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.45","text":"谚云：福至心灵，爻中再有财福相生，或财福旺相者，陡然富足，故曰墓中人逢冲之年而发，岂可谓到老而多泪耶？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.46","text":"如午月丙戌日占终身财福得节卦兄弟子水″兄弟子水″官鬼戌土′官鬼戌土′父母申金″应父母申金″应官鬼丑土″官鬼丑土″子孙卯木′子孙卯木′妻财巳火′世妻财巳火′世此人旺财临世，平素手有余钱，亦因世入戌墓，酷好如痴赌，后至巳年因开铅矿，连开数穴，富冠一乡。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.47","text":"野鹤曰：古法当应冲开戌墓之年，此卦而应冲世之年。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.48","text":"卦宫衰弱根基浅，爻象丰隆命运高。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.49","text":"爻象丰隆，占身命最重。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.50","text":"世爻、财爻、福爻，得遇生扶，自然命运高强。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.51","text":"唯卦宫之衰弱者不验，常见根基浅薄之人，宫几旺，是不为法。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.52","text":"若问成家嫌六冲之为卦。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.53","text":"旧注：凡遇六冲，必主其人作事有始无终。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.54","text":"前卦六冲，前三十年生涯淡泊，后卦六冲，三十年后家业凋零。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.55","text":"余曰：非也，若之以两卦六冲断六十年之休咎，而世与财福置之于何地？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.56","text":"若世财福爻无气，再遇六冲卦者是也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.57","text":"如寅月乙巳日占财福兄弟戌土″兄弟戌土″子孙申金″子孙申金″父母午火′世父母午火′世兄弟辰土′兄弟辰土′官鬼寅木′官鬼寅木′妻财子水′应妻财子水′应余见此卦，世旺官父旺，见其人才品异常，问曰：近来所作何事？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.58","text":"彼曰：在庠，因家寒，意欲行医，不名财福如何？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.59","text":"余曰：卦中官父两旺，寅年必有际遇，午未年定登金榜。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.60","text":"伊曰：予知不能，竟无此念。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.61","text":"余曰：尔虽以财为问，而神告将来可成名。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.62","text":"后果于寅年医好富翁，厚赠读书。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.63","text":"午年一榜，富翁及亲友又赠，援例县令，未几丁艰，及至补缺未几，里误而归，囊筐消然。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.64","text":"应寅年者，寅年而实空。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.65","text":"应午年发者，世爻而值年月，功名反覆而不久者，六冲之卦也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.66","text":"宦囊消索者，子水财爻绝于日也；","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.67","text":"要知创业喜六合以成爻。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.68","text":"旧注：占身命得六合卦，主其人春风和气，交结善友，百事如心。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.69","text":"交游春风者有理，若以百事如心未必然，世必以用神兼之，爻象吉者，吉而又吉，爻象凶者，合亦无益。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.70","text":"动身自旺独力撑持。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.71","text":"旧注：世爻不遇日辰动爻生扶，而自强自旺，其人必白手成家，此屡验。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.72","text":"但须财爻持世，而自强自旺，多自成家。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.73","text":"若兄父官鬼持世，未必仅可撑持而已。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.74","text":"如申月壬子日占终身之财福子孙酉金″应子孙酉金″妻财亥水″妻财亥水″应兄弟丑土″兄弟丑土″兄弟辰土′世动兄弟丑土″官鬼寅木′官鬼卯木′世妻财子水′父母巳火′世临辰土，旺于子日，虽无刑伤冲克，亦无生扶，真可谓之自强自旺，此人原来稍有家业，因赌致贫，问将来还有发旺否？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.75","text":"余曰：兄爻持世，永无发福之秋，且世爻逢退，难许长年。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.76","text":"后从当夫头死于丑年。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.77","text":"衰世遇扶，因人创立。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.78","text":"世爻无气，得遇日月动爻有一而生扶者，必遇好人提拔，但亦要财爻持世，或日月动爻作财以生世，因人照管成家，若父兄持世仅可度日，屡见日月生世，贵人生世，常得官贵垂青。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.79","text":"如丑月丙辰日占终身财福得未济之睽兄弟巳火′应兄弟巳火′子孙未土″子孙未土″妻财酉金′妻财酉金′世兄弟午火″世子孙丑土″子孙辰土′父母卯木′父母寅木″动兄弟巳火′应断曰：兄爻持世，耗财之神，虽得寅木相生，而财不聚。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.80","text":"彼曰：作何事可以成家？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.81","text":"余曰：木生火旺，木火通明，胸中灵巧，况朱雀临父，笔砚可以营生。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.82","text":"后因叔父作衙门命之贴，写得上人之意，可度日而财不聚。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.83","text":"叔父提拔者，应寅木父爻生，又是笔墨营生。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.84","text":"日持合助一生偏得小人心，岁月克冲半世未沾君子德。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.85","text":"世爻不论旺衰但得岁月日建有一而生扶者，君恩宠爱、君子相亲、小人忠敬，平人者必得贵客扶持。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.86","text":"又曰：父来生得父辈之恩，兄来克受兄之累，此则问有验不可执之。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.87","text":"世爻有气或被日月有一而冲克者，仕者上位相陵、同僚不睦、小人毁谤，若太岁五爻冲克者，君恩失宠，世若休囚者更甚。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.88","text":"平人而得此者，官贵欺陵，新朋妒忌，下辈欺侮。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.89","text":"遇龙子而无气，纵清高亦是寒儒。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.90","text":"凡得青龙子孙持世，必然立志高远，不慕富贵。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.91","text":"即子孙无气，亦主绝俗超群，自甘寒薄。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.92","text":"如酉月癸丑日占终身除功名外何事可为？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.93","text":"得卦如下：父母戌土′父母戌土′兄弟申金′兄弟申金′应官鬼午火′应官鬼午火′兄弟酉金′兄弟申金′子孙亥水′动官鬼午火″世父母丑土″世父母辰土″断曰：财星伏于二爻，又值空亡，正所谓内外无财，伏又空，财莫能聚，且喜子孙独破遇青龙，虽不持世，亦主清高，生平非义不取，不以富贵关心。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.94","text":"彼曰：祖有恩荫，让与弟承袭，令欲挟会遍游，取乐山水，可能如愿否？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.95","text":"余曰：亥水子孙变鬼，财爻又空，子死妻空，绝俗离群之事，如有此志，此卦验之几矣。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.96","text":"彼曰：余年四十有三，自二十一岁妻亡之后，竟未续弦，子女皆无。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.97","text":"余曰：卦之相合，必如其愿。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.98","text":"后闻此人游川广填黔，及至十余载之后，致书于家。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.99","text":"竟入华山，不知所终。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.100","text":"觉子曰：余因父子兄财官鬼各有相忌，难以一卦决之，是以分占得理，然亦有不占财神卦中现出旺财，不问功名爻象现出旺官，目下刑妻克子不待另占，卦中先现刑伤，不可不详加细查。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.101","text":"或曰：既谓分占，何故又言兼断？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.102","text":"余曰：此理难同俗人而言，来人欲占事者其几动矣，人之至亲，莫过于骨肉，人之得志，莫过于利名，神不告已问之事者，以重大者而先告也，即如此卦福遇青龙清高之客，子孙变鬼绝后之人，兼之财伏而空，乃是离尘绝俗，以此数事，正合福遇青龙清高之客也，似显而见，何须另卜再卦？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.103","text":"不然，此财爻者以之为财帛空耶？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.104","text":"以之为妻妾空耶？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.105","text":"逢虎妻而旺强，虽鄙俗偏为富客。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.106","text":"旧注为白虎临财持世，虽其人不知礼义，然必家道殷实，果有验。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.107","text":"又曰：旺财若有制服，亦粗知文墨，此又非理，论旺财逢制，及应将来之破败也，岂以文墨言？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.108","text":"如午月丙子日占财福得明夷之丰父母酉金″官鬼戌土″兄弟亥水″父母申金″世官鬼丑土″世动妻财午火′兄弟亥水′兄弟亥水′官鬼丑土″官鬼丑土″应子孙卯木′应子孙卯木′世临白虎化出旺财生世，果此人目不识丁，鄙俗不堪，农生尽可度日，人丁六畜丰盛。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.109","text":"戌年占卦，值子年农生被蝗虫食尽，全家瘟疫，六畜亦瘟。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.110","text":"应子年者，占时原有子日冲其午火，因午火而值月建可以相敌，令遇子年，增其冲克，所以破败。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.111","text":"父母持身辛勤劳禄，鬼爻持世疫病缠绵，遇兄则莫能聚财，遇子则身不犯刑。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.112","text":"黄金策曰：父母官鬼持世皆可断为辛勤劳碌、疾病缠绵。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.113","text":"旧注曰：若是贵人勿以此断。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.114","text":"此说非理，实知不是贵人，焉知将来不贵？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.115","text":"曾有人占财福酉月壬辰日得恒卦妻财戌土″应妻财戌土″应官鬼申金″官鬼申金″子孙午火′子孙午火′官鬼酉金′世官鬼酉金′世父母亥水′父母亥水′妻财丑土″妻财丑土″问曰：尔过祷告曾问功名否？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.116","text":"彼曰：生意人问，何有功名之念？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.117","text":"余曰：此卦财生官旺，竟可问名。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.118","text":"彼曰：天有落下来之官，亦不到我头上。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.119","text":"命再占得噬嗑变否卦子孙巳火′妻财戌土′应妻财未土″世动官鬼申金′官鬼酉金′子孙午火′妻财辰土″兄弟卯木″世兄弟寅木″应子孙巳火″父母子水′动妻财未土″余曰：世爻未土之财变出申金之官，明明以财而变官。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.120","text":"前卦财旺生官者，因世临月建之官，辰日冲动戌土之财，暗动生世。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.121","text":"虽可许名，不敢指以年月，后卦世临未土而逢空，实空之年包出仕。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.122","text":"果于卯年援例入临，巳年初任兵马即加纳县令，未年再位江南。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.123","text":"旧注官鬼持世疾病缠绵，若是贵人。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.124","text":"岂谓之疾病缠绵耶？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.125","text":"又如巳月已丑日占终身财福得归妹之临卦父母戌土″应兄弟酉金″兄弟申金″子孙亥水″应官鬼午火′动父母丑土″父母丑土″世父母丑土″妻财卯木′妻财卯木′世官鬼巳火′官鬼巳火′余曰：卦中财福不旺，而官父两旺，如何不问功名？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.126","text":"彼曰功名之念已灭。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.127","text":"余曰：世临日建月建生身，必主显贵中举，巳午年富贵逼人来也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.128","text":"果于午年保举，虽非科甲，身为科里之官，此岂可谓父母持身辛勤劳碌耶？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.129","text":"父母临身劳碌贫寒之辈。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.130","text":"或曰：黄金策乃卜筮之宗，未有占身命而以父子财官兼断之理。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.131","text":"余曰：既不为信，即看父母持身之解注，其可知矣。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.132","text":"谓占身不可见父兄官鬼持世，爻遇父则克伤子女，一生劳碌，不得安逸。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.133","text":"岂非父为克子之神，又为一生劳碌之神？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.134","text":"即执论之，但遇父爻持世，不独一生劳碌辛勤，官不旺而父旺者，虽不见用于朝廷，名盛之传。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.135","text":"衰而又逢冲克，即欲寄食于公门，凶多吉少。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.136","text":"如子月乙未日占终身财福得兑卦父母未土″世父母未土″世兄弟酉金′兄弟酉金′子孙亥水′子孙亥水′父母丑土″应父母丑土″应妻财卯木′妻财卯木′官鬼巳火′官鬼巳火′断曰：卯木之财，而入未日之墓，巳火之官，休囚无气，名不能成，利不能就，惜乎旺父临身，才愈高而和愈寡，况得卦遇六冲，一事无成之象。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.137","text":"后屡见逢显贵聘之，才高气傲，皆不待瓜期辞矣。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.138","text":"目挚十余载，贫寒炎泊，后随表弟升任云南，不知所终。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.139","text":"兄父临世财耗贫寒O旧系遇兄则财莫能聚解。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.140","text":"注有云：世逢兄爻必克妻妾，一生必不聚财，既以之为克妻，又以之为破耗，执此而论，世之伤妻者，皆贫困之人也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.141","text":"假使贫者偕老，富者断弦，何以决之？","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.142","text":"故予以分占之法，实得理也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.143","text":"觉子曰：凡占财福，兄爻持世，虽不许之富足，亦看旺衰，旺则贫而好义，衰则多疾病官非，得日月生扶，贫而乐。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.144","text":"得日月作财而合世，富而骄。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.145","text":"旺临蛇虎元武，奸盗诈为之凶顽。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.146","text":"衰遇勾陈雀武，背负肩挑之躬汉，受克受制，下贱隶卒。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.147","text":"得合得扶，上人抬举。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.148","text":"全在人之通变，人观其轻重而言。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.149","text":"官衰无破公门异行资生O官鬼持世，休囚无气者，乃缠绵病疾残疾之人也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.150","text":"若有气者，或入公门或挟术行道，再遇日月动爻贵人扶助，皆得贵客相亲，从此成家立业，财若无气，空有虚名而已。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.151","text":"财弱有商贾百工事业O财爻福爻自来旺相者，或商或贾或守农生，成之富足，乐享丰饶，倘遇衰财持世，或得日月动爻生扶合助者，暴发兴家，守农庄年时丰稔，习工艺巧夺天工。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.152","text":"慕道修持皆为子孙持世O子孙乃恬淡之神，如若持世，孤立无助，又遇财爻陷者，若有高尚之志，许之为道为僧。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.153","text":"若无出家之志，不可妄断，殊不知见子，则身不犯刑，许之生平，不犯官刑可也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.154","text":"家倾名丧乃因官鬼伤身。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.155","text":"凡遇官鬼克世，世多旺者，生平多招刑宪，或招嫉妒、或小人暗害、或残疾缠绵。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.156","text":"若鬼旺身衰，乃身伤家倾之兆，动之不必以财福为问，速寻趋避之法可也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.157","text":"如世爻动而变鬼克世，及日月作官鬼而克世者，更凶。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.158","text":"如卯月癸未日占终身财福得革之家人官鬼未土″动子孙卯木′父母酉金′妻财巳火′应兄弟亥水′世动官鬼未土″兄弟亥水′兄弟亥水′官鬼丑土″官鬼丑土″世子孙卯木′应子孙卯木′应外卦世与日月同为三合，以为吉卦，不宜世爻变鬼，又化回头之克，上爻未土又克，目下虽则无妨，今年五月冲开其合，或是酉月冲开卯木，须防不测。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.159","text":"果至巳月而生恶疮，卒于酉月。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.160","text":"财化退兮不利于已O财爻持世化进神，或动而生世者，事业从此而进，家道自此丰亨，若化退神，家业自此渐退，日剥月削，渐生萧条，若世爻再被刑克冲害者，非渐退也，即见家覆财倾。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.161","text":"世逢合住受制于人。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.162","text":"世临财爻兄者，而得日月动爻合住，衣食仅可度日，难许丰足。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c44.163","text":"世爻无气而被合，财福无气，兄动卦中，乃奔走受制之下贱人也。","chapter":"卷之四·终身财福章第三十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.1","text":"官父兴隆，文章见用。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.2","text":"凡得旺父持世、官动生之，或官星持世、父爻旺动，或官星父爻旺动、生合世爻，或日月作官星、父母生合世，皆主成名之象。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.3","text":"学成文武艺，货与帝王家。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.4","text":"鬼财摇发，纳栗成名。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.5","text":"官星持世、财动相生，或世临官动化财，世临财动化官，或官星动而生合世爻，或日月作官星生合世爻，皆主纳栗以奏名。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.6","text":"如辰月乙未日占终身功名有无得地火明夷变丰卦父母酉金″官鬼戌土″兄弟亥水″父母申金″世官鬼丑土″世动妻财午火′兄弟亥水′兄弟亥水′官鬼丑土″官鬼丑土″应子孙卯木′应子孙卯木′此公原是武荫，巳任卑宫，因病告退，即无官矣。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.7","text":"问将来还有功名否？","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.8","text":"此卦丑土官星持世，化出午火，财旺生官，卯年占卦，巳年援例连连加纳，官至府佐，未年出仕，戌年升任。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.9","text":"黄堂古法以动而逢冲谓之散，此系未冲世爻之丑土，竟不见其散也。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.10","text":"独旺于官，立功建业。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.11","text":"凡卦中财爻父爻皆不得地，而官星独旺或日月作官星而生世，或虎临世动，或虎临金鬼动而生合世爻，皆主立功以成名也。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.12","text":"如戌月戊辰日占终身功名有无得蛊卦兄弟寅木′应兄弟寅木′应父母子水″父母子水″妻财戌土″妻财戌土″官鬼酉金′世官鬼酉金′世父母亥水′父母亥水′妻财丑土″妻财丑土″日月作财生世，白虎临金官持世，若入文途，必以援例，若入武途，可以立功。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.13","text":"彼曰：有功名否？","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.14","text":"余曰：官星持世日月生，岂曰无官？","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.15","text":"后此人亦未食粮，竟随营破寨，奋勇当先，主帅嘉之，即以官。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.16","text":"不出五载，建奇功，官至元戎将军。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.17","text":"岁五生世，平步登云。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.18","text":"凡得太岁及五爻动而生世皆旺，主庶民食禄，平步登云。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.19","text":"太岁入爻，又宜发动。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.20","text":"倘得五爻生世，亦要发动，而世与官星亦宜旺相，方可断之。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.21","text":"福德动摇，岂是朝廊之客。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.22","text":"凡得子孙持世发动，终非朝廊之贵客。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.23","text":"如戌月丁卯日占终身功名有无得需卦妻财子水″妻财子水″兄弟戌土′兄弟戌土′子孙申金″世子孙申金″世兄弟辰土′兄弟辰土′官鬼寅木′官鬼寅木′妻财子水′应妻财子水′应断曰：子孙持世，休问功名。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.24","text":"彼曰：作何事可以成名？","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.25","text":"余曰：任尔才能倚马，力能举鼎，终身不许成名。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.26","text":"但此人功名之念切甚，读书苦胜囊萤，文章当时竟未游泮，后从戌二十余载，或立军功，或援例纳栗，奔驰于名利之场，皓首无成，此子孙克官之征验也。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.27","text":"破空临世，终须白屋之人。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.28","text":"世静而临旬空月破，官逢月破自空，皆主不得成名。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.29","text":"惟世与官星空破而动者，勿以此断。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.30","text":"又如巳月乙卯日占终身功名得旅卦兄弟巳火′兄弟巳火′子孙未土″子孙未土″妻财酉金′应妻财酉金′应妻财申金′妻财申金′兄弟午火″兄弟午火″子孙辰土″世子孙辰土″世断曰：虽是爻逢六合，嫌其子孙持世，官逢月破，勿想成名，彼曰：业已援例。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.31","text":"余曰：费尽万金，终难食禄。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c45.32","text":"至子年得病，丑年得蛊病而终。","chapter":"卷之四·终身功名有无章第三十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.1","text":"世爻旺相，永享长年，身位休囚，须防夭折。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.2","text":"凡占寿元，独以世爻为根本，世爻或旺相、或临日月、或得日月生扶及动爻生扶、或动而化生化旺化回头生者，乃大寿之征也。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.3","text":"世爻休囚，防之于冲克之年，再有刑伤克害者，动而逢合逢值之年，静而逢值逢冲之年，皆在应期章内断之。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.4","text":"休囚随鬼入墓，衰逢助鬼之伤，皆为凶兆。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.5","text":"世动化退，化鬼又化回头之克，化绝、化墓、化破空，夕阳无限好，只恐不多时，皆于应期章内决之。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.6","text":"如辰月乙巳日占寿得中孚卦官鬼卯木′官鬼卯木′父母巳火′父母巳火′兄弟未土″世兄弟未土″世兄弟丑土″兄弟丑土″官鬼卯木′官鬼卯木′父母巳火′应父母巳火′应世临未土，巳日生之，月建扶之，遂鬼孙期颐之祝，必享长年。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.7","text":"彼曰：看在何时？","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.8","text":"余曰：占以初爻管五年，二爻管五年，共作三十年。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.9","text":"再占一卦，又作三十年，余试四十余载，并无应验，不以为法，止以世爻衰旺而断知长短，欺人之法，余不为之。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.10","text":"此卦象过二十年公再卜之。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.11","text":"此人占卦之时五十三矣，后至七旬之一相遇而曰：向年所占，寿元还可记否？","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.12","text":"余曰：占得中孚卦，原许二十年后再占。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.13","text":"申月已卯日占得山泽损之复卦官鬼寅木′应动子孙酉金″妻财子水″妻财亥水″兄弟戌土″兄弟丑土″应兄弟丑土″世兄弟辰土″官鬼卯木′动官鬼寅木″父母巳火′妻财子水′世余曰：若是父爻鬼动，公之寿则不久矣。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.14","text":"今见多鬼摇发，反为不碍，今年太岁在子，远享八年之福，至未年发是其时也。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.15","text":"余曰：未年鬼多入墓，又是世逢年破。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.16","text":"果终于未年七月。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.17","text":"占寿，世为根本，元神为滋生之物，宜旺而静不宜动摇，其故何也？","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.18","text":"占他事宜元神动者，动则而有力也，占寿元不宜发动，动则已有限期矣，非元神逢绝墓之年，即在元神被冲克之岁。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.19","text":"如辰月乙卯日占寿得中孚之暌官鬼卯木′父母巳火′父母巳火′动兄弟未土″兄弟未土″世动子孙酉金′世兄弟丑土″兄弟丑土″官鬼卯木′官鬼卯木′父母巳火′应父母巳火′应余曰：世爻未土，月拱日克，可以敌之，反不宜巳火动而生世，今岁太岁在申，余恐亥年不利，后卒于戌年。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.20","text":"应在巳火入墓之年。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.21","text":"忌神不动，自是平安，动则已有限期矣。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.22","text":"非应逢合之年，必应逢值之岁。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c46.23","text":"如寅月已酉日占寿得剥之无妄卦妻财寅木′父母戌土′子孙子水″世动兄弟申金′父母戌土″动官鬼午火′世妻财卯木″父母辰土″官鬼巳火″应妻财寅木″父母未土″动子孙子水′应断曰：世化申金回头之生，不宜寅月冲破，又嫌戌土未土动而克而无生也，须防卯岁，果卒于卯年，乃应戌土逢合之年而克世也。","chapter":"卷之四·寿元章第三十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.1","text":"圣人作易，原令人趋吉避凶，若使吉不可趋，凶不可避，圣人作之何益？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.2","text":"或曰：年炎月晦，可以避之，死生如何能避？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.3","text":"余曰：安于正寝者，虽有可避之方，亦不须避。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.4","text":"康节先生临终呼弟子沐浴更衣，群弟子哭曰：先生何不忌神避杀，以乐天年，先生曰不怕二程夫子笑，要作神仙不甚难。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.5","text":"若占得死于水者，莫近河旁，死于刑者，不可违条犯法，未有不化凶而为吉。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.6","text":"也曾于汉口卯月丙寅日占索债得否得益之中孚兄弟卯木′应兄弟卯木′子孙巳火′子孙巳火′妻财未土″妻财未土″世妻财辰土″世妻财丑土″兄弟寅木″动兄弟卯木′父母子水′子孙巳火′应此人欲渡江索债，因屡取不得，欲与之厮闹，问得财否？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.7","text":"余见此卦，本日日辰动化进神克世，因世爻落空，辰时出空，被日月动爻之克，必有危亡之祸，留之早膳，过此时辰去亦不迟，彼必欲去，余苦留之，饭后去到江傍，忽而跑回，向余拜谢活命之恩。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.8","text":"余曰：此其何故？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.9","text":"彼曰：今早四只大船横渡，行至江心，忽起暴风，尽覆没。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.10","text":"此时尸满长江，若不蒙君苦留，已在江中矣。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.11","text":"余曰：依数全无救星，定是兄之德行，我有何功，此非谓之避之则吉也？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.12","text":"凡占防患克世者，皆不为吉，独鬼爻克世更凶，火鬼须防火炎，木鬼须防木窖，水鬼克世沉溺之忧，土鬼伤身岩樯之厄，金鬼剑刀斧锹。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.13","text":"玄武戾充盗贼兵戈。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.14","text":"蛇雀官非兼防火厄，勾陈田土又系牢狱，青龙虽是吉神，克世亦为凶象，或因酒危亡身，间有喜中起祸。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.15","text":"既以五行六神而定，再以八卦参之，乾兑为寺，又属金形，坎兑以水为灾，离以火，震有舟车，巽防妇女之奸，坤艮郊野山林，又为老妇妖童之惑，诸类多门，在人通变。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.16","text":"如丑月戊子日占梦得益之中孚卦兄弟卯木′应兄弟卯木′子孙巳火′子孙巳火′妻财未土″妻财未土″世妻财辰土″世妻财丑土″兄弟寅木″动兄弟卯木′父母子水′子孙巳火′应此人因梦一身之血，入河洗之。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.17","text":"余曰：血乃财也，洗去者，破财之兆也。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.18","text":"今占得此卦，元武发动化进神，克世克财不独劫财，远防身遭木害，巽宫属木，又系木动克世，木害须防。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.19","text":"彼曰：何以避之？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.20","text":"余曰：世与木爻皆在内卦，出外可避，巽为少女，勿贪幼妇。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.21","text":"彼曰：应在何时？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.22","text":"余曰：交春可以避之。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.23","text":"彼曰：年岁逼如何远去？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.24","text":"不意果于正月亥日宿于妾房，被贼明火入室，席卷一空，身受木器所伤，若不宿于少妇之室，或者扒墙而出，未必受其伤。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.25","text":"占梦兆占漂洋过江占愈险偷关占防瘟疫占防病占误食毒物占远领火起占防伊害占避难占贼盗生发占孤身夜行占宿店朝占入山占仇人讹诈占已定大罪占入不毛大凡一切忧疑、惊恐、防灾、防患者，皆宜子孙持世，或福神动于卦中。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.26","text":"古法曰：但得子孙乘旺动，飞殃横祸化为尘。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.27","text":"如午月丁亥日占梦前夫叫去已随去矣兄弟子水″应父母酉金″官鬼戌土′动兄弟亥水″父母申金″官鬼丑土″应兄弟亥水′世动官鬼辰土″官鬼丑土″子孙寅木″子孙卯木′兄弟子水′世断曰：世爻亥水临日辰，岂当重重土克？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.28","text":"果于九月成痨，腊月而死。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.29","text":"如戌月戊申日占梦母叫去已随去矣得风山渐官鬼卯木′应官鬼卯木′应父母巳火′父母巳火′兄弟未土″兄弟未土″子孙申金′世子孙申金′世父母午火″父母午火″兄弟辰土″兄弟辰土″凶梦相同，生死各别，前卦世爻变鬼，死于腊月，后卦子孙持世，竟无凶灾。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.30","text":"觉子曰：虽然子孙持世，难为吉兆，如逢月破，出月无忧。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.31","text":"若临旬空，许之出旬无忧。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.32","text":"未至出旬之日，尽属虚疑空忧。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.33","text":"如巳月庚辰日占防患得夬卦兄弟未土″兄弟未土″子孙酉金′世子孙酉金′世妻财亥水′妻财亥水′兄弟辰土′兄弟辰土′官鬼寅木′应官鬼寅木′应妻财子水′妻财子水′世临子孙值旬空，事之不结，终日忧煎。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.34","text":"又于乙酉日占得无妄妻财戌土′妻财戌土′官鬼申金′官鬼申金′子孙午火′世子孙午火′世妻财辰土″妻财辰土″兄弟寅木″兄弟寅木″父母子水′应父母子水′应世临午火子孙又值旬空，事又反覆不结。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.35","text":"乙酉日又占得节之坎卦兄弟子水″兄弟子水″世官鬼戌土′官鬼戌土′父母申金″应父母申金″官鬼丑土″妻财午火″应子孙卯木′官鬼辰土′妻财巳火′世动子孙寅木″余日甲寅日则事结矣。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.36","text":"余曰：世下巳火变寅木子孙，又值旬空，幸得卦遇六冲，所以结矣。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.37","text":"克在内，世在外，宜于外避。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.38","text":"克神若在内卦，动而克世，宜出外避之，克神若在外卦，动而克世，宜在家避之。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.39","text":"如寅月丁卯日占流年得益之睽兄弟卯木′应子孙巳火′子孙巳火′动妻财未土″妻财未土″动官鬼酉金′世妻财辰土″世妻财丑土″兄弟寅木″动兄弟卯木′父母子水′子孙巳火′应余曰：今秋必有险厄，寅木动爻临月建化进神克世，此时大盛贪荣，不来克害，六七月衰墓之时，防土木之厄。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.40","text":"余曰：宜往外方可避。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.41","text":"余曰：目下去者宜往西方。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.42","text":"六七月去者，宜往东方，何也？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.43","text":"六七月木衰矣，所以反宜于东。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.44","text":"此人竟未出门，捱至七月初七，又得凶梦，初八即往东行二十八里，地震房塌，人口被伤，独伊得免。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.45","text":"世在外，克在外，宜于家居。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.46","text":"世爻与忌神皆在外卦者，不可出行，宜家居可避。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.47","text":"世与忌神在内卦者，不可家居，宜于外避。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.48","text":"出行章云：路上有官休出外，中有鬼莫居家。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.49","text":"如未月丙子日占仆人为祸否得解之震妻财戌土″妻财戌土″世官鬼申金″应官鬼申金″子孙午火′子孙午火′子孙午火″妻财辰土″应妻财辰土′世动兄弟寅木″兄弟寅木″动父母子水′此公知仆役变心，意欲处治，尚无实迹，故占之。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.50","text":"断卦者若执奴仆为财，则迁矣，彼既防患，只看忌神，此卦世临辰土，两重寅木伤之，余曰：不独此人，还有附从者。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.51","text":"彼日：何法处之？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.52","text":"余曰：彼实无实迹，如何处之？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.53","text":"但未月乃木之墓，七月乃木之绝，此两月乃露之月也。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.54","text":"公宜出外，自能免祸，果依语而行，往庄上住过半月，两仆矣一妇随去一妇未去，未去之妇而曰：彼二人原欲害主而逃，今因外出，不能相害，此非避凶之征耶？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.55","text":"避患于生世之方，趋吉于福神之地。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.56","text":"凡避兵、避盗、避瘟、养病、避是非、皆宜避于生世之方及子孙为吉。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.57","text":"子孙若发动于卦中，不拘克世持世，俱以为吉如巳月戊辰日占防流兵得临之暌卦子孙酉金″动父母巳火′妻财亥水″应兄弟未土″兄弟丑土″动子孙酉金′世兄弟丑土″兄弟丑土″官鬼卯木′世官鬼卯木′父母巳火′父母巳火′应彼时流兵为害，到处遭殃，此人知易占得此卦，终日焦忧，余问其故，彼曰：巳酉丑合成金局而克世，世爻又临腾蛇之鬼，数在结中，乃万莫能逃矣。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.58","text":"余笑而曰：尔与兵贼同居，保尔无事。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.59","text":"余曰：子孙合成金局，克去身边之鬼，夫复何忧？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.60","text":"彼曰：酉金子孙，旺于巳月，又化巳火，论克如何论生？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.61","text":"余曰：酉金得丑未二土以相生，如何为克？","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.62","text":"后此人屡次遇兵变，或避之，或有惊无险，自癸未占卦到地方安定。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.63","text":"彼曰：子孙福神，信乎有验，世之看书不到，论理不彻，以吉为凶者，不独我一人而已。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.64","text":"如巳月丙戌日占通乡避乱得乾之大有父母戌土′世官鬼巳火′应兄弟申金′动父母未土″官鬼午火′兄弟酉金′父母辰土′应父母辰土′世妻财寅木′妻财寅木′子孙子水′子孙子水′众以子孙属水，金动生之，北方为吉。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.65","text":"余曰：非此议论，兄动化进神乃破财之象，午火得令而生世，往南避之为吉。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.66","text":"信余之言，皆从南避，后果从北来，放火烧村而去，房屋稻毂尽成灰烬，乃申金兄动破财之故耳，所以生方为吉，子孙之方亦吉，又当以旺衰分别，火乃鬼方，生我何碍。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.67","text":"世遇生扶，百年正寝，身遭克害，分五类推O凡占终身结果如何，但得世爻旺相，或有功爻日月生扶，或动而化吉，皆许无疾而终。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.68","text":"如若世逢克制刑冲，须以五行兼六神而断，受五行之克，以疾病而言，如兼六神之凶，即以横亡而断。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.69","text":"火属金肺经之病；","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.70","text":"土来刑水，肾受其伤；","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.71","text":"水克火，以伤心；","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.72","text":"金克木，而肝疾；","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.73","text":"脾虚胃弱，皆因木旺刑冲。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.74","text":"肠损腰伤，乃谓仇神独发。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.75","text":"兼腾蛇以心惊，带青龙而酒色，勾陈肿胀，朱雀颠狂，虎必血灾，元因气恼。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.76","text":"虎元金鬼，难免盗贼兵戈；","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.77","text":"水鬼龙元，宜远江湖池井；","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.78","text":"蛇雀木鬼犯官刑，临火须防焚害，蛇木又言缢绞，勾陈土鬼牢狱。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.79","text":"谚云：一样之生，百样之死，卦如神见，理宜细详。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c47.80","text":"如未月癸亥日占定何罪得中孚变临卦官鬼卯木′动子孙酉金″父母巳火′动妻财亥水″应兄弟未土″世兄弟丑土″兄弟丑土″兄弟丑土″官鬼卯木′官鬼卯木′世父母巳火′应父母巳火′断曰：木鬼临白虎，绞罪定矣，但幸世临月建，木鬼虽动，又被酉金回头之克，外卦反覆，虽定绞罪，终有改刑，果议绞罪，后蒙驳番拨活罪。","chapter":"卷之四·趋避章第四十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.1","text":"凡占祖父祖母，占父母须宜分占。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.2","text":"父临日月椿庭晚放荣华，母值空破萱草残年憔悴。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.3","text":"古以阳爻为父，阴爻为母。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.4","text":"父母爻或旺相或临日月动爻生扶及动而化吉，长享遐龄。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.5","text":"父母爻休囚，不遇刑伤克害，晚年多病，远保无伤。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.6","text":"休囚又被刑冲，或日月动爻之克及动而变凶，承欢宜早。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.7","text":"如丑月庚子日先占父寿得姤卦父母戌土′父母戌土′兄弟申金′兄弟申金′官鬼午火′应官鬼午火′应兄弟酉金′兄弟酉金′子孙亥水′子孙亥水′父母丑土″世父母丑土″世又占占母寿得大壮之升兄弟戌土″子孙酉金″子孙申金″妻财亥水″父母午火′世动兄弟丑土″世兄弟辰土′子孙酉金′官鬼寅木′妻财亥水′妻财子水′应动兄弟丑土″应断曰：前卦两现父母，取月建丑土为用神，旺于子日，又与日合，蒂固根深，大椿永茂O后卦午火父母动被日冲，初爻子水又动，此午火有克无生，因初爻子水化出丑土，贪合不来克火，防丙子年。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.8","text":"加以太岁冲之，是其时也。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.9","text":"癸酉年占至乙巳年三十余载，复遇其人而问曰：尊翁健否？","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.10","text":"问及堂，答曰：果终于子年。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.11","text":"若以古法，阳为父，阴为母，前卦丑戌两现，俱以旺而断者，如天远矣。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.12","text":"又如巳月乙酉日占父寿得巽之姤卦兄弟卯木′世妻财戌土′子孙巳火′官鬼申金′妻财未土″动子孙午火′应官鬼酉金′应官鬼酉金′父母亥水′父母亥水′妻财丑土″妻财丑土″世断曰：亥水父临月破，又被未土相伤，虽则酉日冲动卯木克土，土旺木衰，不惟不许长年，且无长月，果终于本年冬至日，应子日者冲去午火而未土以克亥水。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.13","text":"又如卯月丙寅日占祖母寿得中孚官鬼卯木′官鬼卯木′父母巳火′父母巳火′兄弟未土″世兄弟未土″世兄弟丑土″兄弟丑土″官鬼卯木′官鬼卯木′父母巳火′应父母巳火′应断曰：巳火父母，日月生之，且有大寿。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.14","text":"伊曰：家父为祖母拜天，许拜七年，我因家父劳于公事，我停妻未娶，代为礼拜。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.15","text":"余曰：可见乔梓大孝，感格天心。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.16","text":"此卦日月相生，勿谓非神之力，戌年占及至次年，偶因痰堵，此子又来卜之。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.17","text":"丑月庚子日占得归妹变复卦父母戌土″应兄弟酉金″兄弟申金″子孙亥水″官鬼午火′动父母丑土″应父母丑土″世父母辰土″妻财卯木′动妻财寅木″官鬼巳火′子孙子水′世刚未装毕，家人来曰：老太已去世矣。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.18","text":"此子急去，余详此卦，丑土父母，既临月建，又有午火暗动相生，虽则木动克土，化退神绝于申日，岂无救耶？","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.19","text":"随即赶到其家，北人上欲临终，不肯停床已抬于门板之上，痰塞于喉，稍有微息，余以白生磨三钱，滚水化开，掀牙灌之，忽而叫曰：冷甚。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c48.20","text":"随即复移烧坑，又活十有三载。","chapter":"卷之四·父母寿元章第四十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.1","text":"凡占兄弟，须宜问明，或因弟兄不睦，将来和好否？","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.2","text":"或因弟兄虽多，将来得济否？","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.3","text":"或问将来有兄弟否？","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.4","text":"或占兄弟寿元，便于判断。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.5","text":"兄弟爻旺相遇生扶，紫荆并茂。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.6","text":"兄弟爻或旺或相，临日月或日月动爻生扶及动而化吉，长杭大被和睦致详。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.7","text":"弟位休囚兼受制，雁亭公飞。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.8","text":"兄弟爻休囚者，若问得济，虽有如无；","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.9","text":"若问将来有否，从此无矣；","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.10","text":"如问兄弟寿元，长年有限。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.11","text":"倘休囚又逢破空及日月动爻刑克或动而化凶者，诸占皆不吉也。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.12","text":"如申月丙辰日占弟兄和好否？","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.13","text":"得大有之乾官鬼巳火′应父母戌土′世父母未土″动兄弟申金′兄弟酉金′官鬼午火′父母辰土′世父母辰土′应妻财寅木′妻财寅木′子孙子水′子孙子水′弟兄临月建，未土爻动以相生，又化出兄爻。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.14","text":"余曰：弟兄虽多，有一位属猴者得济。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.15","text":"余曰：神化于动，动而变出，以临月建，自是超群拨类。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.16","text":"彼曰：果有金弟属猴，克曾功一第，余三人皆从别业，可见数之责验如此，后一年又登申榜。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.17","text":"又如未月辛丑日占兄弟还有得既济变革。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.18","text":"兄弟子水″应官鬼未土″官鬼戌土′父母酉金′父母申金″动兄弟亥水′世兄弟亥水′世兄弟亥水′官鬼丑土″官鬼丑土″子孙卯木′子孙卯木′应余曰：兄弟虽有，必不得滋。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.19","text":"亥水兄爻持世，申父动而生之，此一位得酒之弟，尚未生也，应爻之子水，虽则出现，巳值旬空，故曰必不得薄。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.20","text":"彼曰：果一位舍弟已得颠狂之症，所以再问有无。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.21","text":"余曰：必有，乃异母所生。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.22","text":"余曰：父母化出之爻，是以知之。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.23","text":"又问：子水之兄弟临空而不得力，是也。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.24","text":"亥水持世之兄爻，如何亦不得济。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.25","text":"余曰：第四爻申金化出之亥水，即是此爻，卦之微妙，尔岂得知。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.26","text":"后果异母有出，父亡而扶之。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.27","text":"余曰：投真成人，后事未老。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.28","text":"古法父母而有兄弟胞于异母，余未得试。","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c49.29","text":"（此句不知所谓，乃鲁鱼之讹，待有善本者告知其祥）","chapter":"卷之四·兄弟章第四十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.1","text":"夫妇之占，亦须分别，或占妻寿，或占夫妻偕老否？","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.2","text":"或占夫妻和睦否？","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.3","text":"或占妻有刑伤破败否？","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.4","text":"占妾占婢，一卦只占一人，不可概问。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.5","text":"财福生身可遂唱随之愿。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.6","text":"应爻合世堪为睦和之兆。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.7","text":"黄金策专以应爻为妻，其故何也？","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.8","text":"因其身命章中，父子弟兄妻财官鬼，以一卦而兼断之，设以财为妻者，又以何爻为财帛？","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.9","text":"不得不以应爻而为妻位。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.10","text":"不顾验与不验，竟以应爻为妻，虽然以应爻为妻者，亦非全非理也，占妻财爻为重，应爻次之，财爻旺相，应爻空破，仍以吉断，应爻旺相，财爻空破，即以凶推，应旺财旺，吉而又吉，应破财破，凶而更凶，故以应爻为附和也。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.11","text":"财爻或旺、或相、或临日月、或日月动爻生扶及动而化吉，又与世爻相生合者，如占偕老，定然举案齐眉，若问和睦，必无反目，若问妻命之妍妯入夫门，夫家随旺，占妾占婢，指而问者，亦同此断。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.12","text":"财动化兄，失履遗管之叹，弟兄持世，鼓盆箕踞之悲。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.13","text":"财动化兄者，乃化鬼、化回头克、化退神、化绝、化墓、化破、化空之类是也，不拘何问，玉碎珠沉。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.14","text":"弟兄持世或兄爻动於卦中，或日月临兄弟以伤财，或兄化财爻，不拘问妻问妾，皆不得长年。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.15","text":"财旺兄衰终须反目，克财财退必主生离。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.16","text":"兄爻持世而财爻旺者，不能克妻，终乘琴瑟，相见如仇。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.17","text":"兄爻持世财化退神者，亦同此意，非反目即生离。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.18","text":"酉月辛巳日占夫妇将来和俣否？","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.19","text":"得泰卦子孙酉金″应子孙酉金″应妻财亥水″妻财亥水″兄弟丑土″兄弟丑土″兄弟辰土′世兄弟辰土′世官鬼寅木′官鬼寅木′妻财子水′妻财子水′兄爻持世以克妻财，幸财爻亥水酉金生之，财旺难于克害。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.20","text":"彼曰：目下不和，将来和好否？","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.21","text":"余曰：巳日冲动亥水，又临驿马，妻财临马而暗动，心去难留，生离之象。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.22","text":"此人自此之彼，常为此事而占，十有除次，若非兄爻持世，定遇财化退神，后竟生离。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.23","text":"黄金策：世为一生之本，应为百岁之妻，此卦世应相生，如鲍宣娶恒氏之断者，失千里也。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.24","text":"动妻旺相，续弦堪许白头。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.25","text":"卦中财爻多现，若分正庶者，自当以应爻临财而作正妻之位也，倘被日月动爻冲克及动而化凶，乃结发之妻伤也。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.26","text":"若得他爻之财旺相、或动而化吉及他爻变出之旺相，相生合世爻者，及再醮之事反遂白头。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.27","text":"如若财爻不临于应，又以正卦之财为正妻，之卦之财为再娶。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.28","text":"妻财克身，非刑伤必然姤悍。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.29","text":"妻财克世，世若休囚空破、或墓绝、或动而变凶、或随鬼入墓，但逢一者天命夭亡。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.30","text":"旺财克世，世爻得地者，虽无刑伤，必遭姤悍。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.31","text":"应财生世，非内助即获外财。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.32","text":"卦中但遇财爻生合世爻，亦不可只以和美断之，问有应在得妻家之财力也，否则内助必善于持家。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.33","text":"如巳月丁未日占夫妻偕老否？","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.34","text":"得无妄变观卦妻财戌土′兄弟卯木′官鬼申金′子孙巳火′子孙午火′世动妻财未土″世妻财辰土″兄弟卯木″兄弟寅木″子孙巳火″父母子水′应动妻财未土″应满盘俱是财爻，世爻变出之未土，与世爻相合，此未土之财，乃正妻也，临日建遇月生扶，不独偕老，且许贤比周南，果此公美妾十余，正夫人贤而无妒，夫妻同庚而生，妻活八旬有一，夫年八十二岁。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c50.35","text":"此卦若以世应相冲相克而断之，远如天壤。","chapter":"卷之四·夫妇章第四十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.1","text":"凡问子嗣，须明告之，或已有子后还生否？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.2","text":"或问现在之子，将来可保长年否？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.3","text":"或从未生育，终有子否？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.4","text":"易告未来，不告已往，即如占天时，神报将来之旱潦，不言昨日之阴晴雨，若含糊而问，假使从前有子，问后来还可生否？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.5","text":"后若不生，神必现无子之卦，不报以前之有，乃现将来之无，断卦之人，依卦而断，尔肯服耶？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.6","text":"又有现今有子，将来若难存者，神亦现无嗣之卦，尔虽以曰有，神告曰无，神肯阿谀耶？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.7","text":"即如寅月癸女日占子嗣多少得坤之艮子孙酉金″世动官鬼寅木′世妻财亥水″妻财子水″兄弟丑土″兄弟戌土″官鬼卯木″应动子孙申金′应父母巳火″父母午火″兄弟未土″兄弟辰土″断曰：鬼变子孙，子孙变鬼，有一而遇者，皆无子也。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.8","text":"此卦两现，无子之兆。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.9","text":"彼曰：少年难于子嗣，自五旬之外，连得四子，长子已六岁矣。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.10","text":"余曰：依此卦象，恐俱难存。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.11","text":"彼甚不悦，岂知婢妾甚多，三五年内生者生，而死者死，生过九子，并无一存，临终过侄立嗣，承龙世音。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.12","text":"福德旺隆，育儿贤德。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.13","text":"福德即子孙爻，若旺遇生扶，或临日月，或帝旺长生于日，或动而化吉，必产贤儿。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.14","text":"子孙衰弱，生子愚痴。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.15","text":"子孙多衰弱，必生痴愚之子，衰而被克，休囚无气，或落绝空破，或动而化凶，或日月动爻冲克，或父化子，子化父，鬼变子孙，或父空持世，皆生生而不有，子孙逢空不碍，必得子冲空实空之年。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.16","text":"觉子曰：黄金策，子化兄，生儿不肖，殊不思化兄及回头之生，如何不肖？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.17","text":"注解又曰：化鬼亦不尚，化鬼者百无一活，先不肖而已耶？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.18","text":"申月辛卯日占子嗣得复卦。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.19","text":"子孙酉金″子孙酉金″妻财亥水″妻财亥水″兄弟丑土″应兄弟丑土″应兄弟辰土″兄弟辰土″官鬼寅木″官鬼寅木″妻财子水′世妻财子水′世断曰：身带吉而子扶，日建冲动上爻子孙而生世，有远方之子来。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.20","text":"彼喜而曰：我于三十七岁有子，已十八矣，因乱失散，至今无所出。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.21","text":"余曰：恭喜，明现子从六爻动来生世，此子见归。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.22","text":"彼曰：何时得见？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.23","text":"曰：明岁申辰与酉金相合，定然得意而归。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.24","text":"果于次年六月父子相逢。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.25","text":"财化子，可辨正出庶出。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.26","text":"卦有财而无子孙者，须看变出之爻，变爻子孙。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.27","text":"即断曰：正无所出，定得偏生。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.28","text":"卦有子孙，亦有子孙变爻，又非此论，即变爻之为晚子。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.29","text":"倘若正庶俱已生子，而问贤愚者，以正卦之子为正出，变爻之子为庶出。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.30","text":"子化子，须知本宫他宫。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.31","text":"子孙化子孙得验者二：少年无子得此者，应多生子。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.32","text":"现有子得此者，乃应多子而多孙。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.33","text":"老年无子得此者，扶他人之子而为子，须宜分别化出他宫者，立异姓之子；","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.34","text":"化出本宫，立族中子。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.35","text":"如亥日庚子日占子孙有无？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.36","text":"得屯之节卦兄弟子水″兄弟子水″官鬼戌土′应官鬼戌土′父母申金″父母申金″应官鬼辰土″官鬼丑土″子孙寅木″世动子孙卯木′兄弟子水′妻财巳火′世此公年已六旬，并无所出，自知易理，得此卦甚喜，以为世爻子孙又化子孙，月建合之，日辰生之，有子必多，岂知子孙化子孙，原非已出，次年三月终于任立侄孙承嗣。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.37","text":"父占子，知其易养，子临贵，难曰成名。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.38","text":"父占子，止知易养，难断高贵，子孙旺相，克制官星，子若休囚，马能食禄，所以易养，否则不难知也。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.39","text":"子孙化相，或动而化吉、或临日月、或日月动爻生扶、或长生帝旺，皆许成人，如休囚空破动而变凶，水泡风灯，至于子孙之富与贵者，旺相一遇生扶，自然富贵，若以科甲科名而断者，及欺人之法也。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.40","text":"黄金策曰：子带贵人自有登天之日，又日禄贵临爻，童年拜相。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.41","text":"以贵禄临子孙化鬼者，不为化鬼而为化官，即许登天拜相。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.42","text":"余查天乙贵人临爻并无禄到。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.43","text":"贵人临马上有丁巳日见亥水子孙，乃为贵人，与为同官，余皆不是有禄者，无贵人马，此信笔妄谈也，何尝经验，况余屡占子女，若子孙变鬼，万无一活。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.44","text":"如亥月丙辰日占子易养否？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.45","text":"得姤之旅卦父母戌土′官鬼巳火′兄弟申金′动父母未土″官鬼午火′应兄弟酉金′应兄弟酉金′兄弟申金′子孙亥水′动官鬼午火″父母丑土″世父母辰土″世亥水子孙临月建五爻，兄动以相生，旺莫旺于此也，若以吉神论之，丙日以亥为贵人，贵莫贵于此也，岂知子爻变鬼，死于次年五月。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.46","text":"黄金策曰：有官鬼无伤，曹彬取印终封爵。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.47","text":"觉子曰：官鬼无伤者，必是子孙爻被伤被伤被克休囚无气，所以不能伤克官鬼，既是如此衰弱之子孙，又封官封爵，余不信也。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.48","text":"又曰：父身有气，车微显名。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.49","text":"觉子曰：父占子，父为忌神，或动或旺，必于克子，救死不暇，何得显名？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.50","text":"或曰：疑是婴儿之自占。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.51","text":"余曰：婴儿乃无知无识孩童，占富占贵，全在人之一念，三五岁之婴孩，可知富贵之念耶？","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.52","text":"况身命后章有：若卜婴儿之造化，固知非代占耶。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.53","text":"代占六亲，不宜世爻化鬼。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.54","text":"占父母、兄弟、妻妾、儿孙，先看世爻，虽占六亲，常有带出自身之凶者，世爻化鬼、化回头克、休囚化空破墓绝及随鬼入墓，日月同克，休问他人，且防自己。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.55","text":"虽问父母，亦有应儿孙。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.56","text":"常见占父母之卦爻中带出刑伤兄弟儿孙妻妾者，有占儿孙亦有兼应父母兄弟妻妾者，不可不知。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.57","text":"此谓占此而应彼也。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c51.58","text":"此论前已表明，余占而屡见也。","chapter":"卷之四·子嗣章第四十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.1","text":"儒业者，父母世爻同旺，终须变化成龙。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.2","text":"日月动爻相生，定是王家储器。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.3","text":"世爻父母皆宜旺相，或动而变吉、或父母持世、日月动爻生合世，攀龙附凤，指日可期。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.4","text":"财动卦中，青灯不久。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.5","text":"子孙持世，自首无成。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.6","text":"财动克文章，读书中道而废。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.7","text":"子动无官之象，皓首必不成功名。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.8","text":"九流者，财兴官旺，道重人钦。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.9","text":"兄动世衰，有毁无誉。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.10","text":"财持世，官持世，财官世爻皆宜得地。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.11","text":"卦中兄爻持世，只可糊口，难许成家。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.12","text":"觉子曰：古以九流，皆以官鬼为吉，殊不知天师家及驱邪治鬼之家，巫师医家，皆以子旺，能于治鬼，必以子孙持世及子孙发动而为吉也。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.13","text":"百工皆以财为用神，子孙元神，最忌兄爻持世及兄爻旺动者，劳碌终身，余以求财章同断。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.14","text":"以上皆不宜世爻空破墓绝休囚诸事无成。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c52.15","text":"世若休囚，而又随鬼入墓及受日月动爻冲克，或动而化鬼化绝化克者，不唯学业难成，且防不测。","chapter":"卷之四·学业章第四十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.1","text":"占以金作春秋，毛诗为木，书经为水，火为礼记，土为易经。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.2","text":"觉子曰：不可概问，须指定而卜之，祷于神曰：我习此经何如？","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.3","text":"父旺官兴，王家栋梁。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.4","text":"世空子动，蓬华寒儒。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.5","text":"官鬼持世，父动相生，或日月临父母生世，或官爻旺相、父爻持世，及世爻动而化吉，皆飞腾变化之兆。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.6","text":"世空世破，及动而变凶，或子孙财爻持世，父母官鬼空破，须宜另于一经处，诚心再卜。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.7","text":"如酉月丙子日占木经能发否得益之观兄弟卯木′应兄弟卯木′子孙巳火′子孙巳火′妻财未土″妻财未土″世妻财辰土″世兄弟卯木″兄弟寅木″子孙巳火″父母子水′动妻财未土″应断曰：卦中旺官合世，不宜初爻朱雀子水文章动化未土回头之克，宜于改经。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.8","text":"彼问：宜改何经？","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.9","text":"余曰：古法余占不验。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.10","text":"意欲何经，再占一卦。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.11","text":"得天火同人：子孙戌土′应子孙戌土′应妻财申金′妻财申金′兄弟午火′兄弟午火′官鬼亥水′世官鬼亥水′世子孙丑土″子孙丑土″父母卯木′父母卯木′余曰：旺官持世，难以为吉。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.12","text":"父临月破，宜再更之。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.13","text":"又占书经，得丰之离：官鬼戌土″动妻财巳火′世父母申金″世官鬼未土″妻财午火′父母酉金′兄弟亥水′兄弟亥水′应官鬼丑土″应官鬼丑土″子孙卯木′子孙卯木′旺父持世，官动生之，因今日子日冲午火伤金，此经相宜。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c53.14","text":"下科壬子冲去午火，管许高发，果于子科中魁。","chapter":"卷之四·治经章第四十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.1","text":"父爻旺相，就而正焉。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.2","text":"父母爻既为师长，又为诗书。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.3","text":"延师受教，即以此爻为用神，宜旺相或临日月及动而化吉。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.4","text":"如若休囚空破绝及动而化凶，有素食之讥，无师资之益。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.5","text":"世位相生，博约善诱。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.6","text":"父旺生合世爻，成人有德，若克世爻，而世爻得地者，有责成之功。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.7","text":"世若休囚，必受师尊之累。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.8","text":"父入墓中，懒于教训。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.9","text":"父爻入三墓及临绝者，若非偷安懒惰，定是师不授教。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.10","text":"财临世上，懦弱不严。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.11","text":"财爻持世乃我克父母，若非师不严，定是我师畏凌。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.12","text":"鬼化文书克世，讼由乎学。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.13","text":"鬼动化父母，冲克世爻，异日必主争讼，能使日月动爻制服鬼爻，亦不相宜，此何故也？","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.14","text":"目前虽可制服，他日鬼逢生旺必见灾。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.15","text":"非不唯鬼动化父，但系鬼动克世，或世动变凶，皆不宜从。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.16","text":"月扶世爻日助，青出于蓝。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.17","text":"世爻旺相，或父母持世，或官星持世，日月动爻生扶，及世爻动而化吉，必有长进，青出于蓝。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.18","text":"动衰变旺，先惰后勤。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.19","text":"动旺变衰，先勤后怠。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.20","text":"父化父而殊经，父化财而多病，化鬼显贵之交，父化兄贪财好利。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.21","text":"三合连年受教，六冲半载难留。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.22","text":"世与父爻兼日月作三合者，情同父子，连年受业，门墙始终成就。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.23","text":"卦得六冲，或世克父爻，或父爻克世者，彼此不投，难收一发之功。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.24","text":"父为子而延师者，应为西席，世乃东家，宜世应相生合，不宜相克相冲，应生世，我得其益，应爻空破，延之不就，应动他有变，世空我意不专。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.25","text":"觉子曰：虽以世应为主，父爻不可缺之，父旺与子孙相合，名实兼收，父动克子孙，无益有害，子动化克，不宜延之，子动化鬼，速宜辞绝。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.26","text":"如寅月戊午日占子从师兄弟巳火′兄弟巳火′世子孙未土″子孙未土″妻财酉金′应妻财酉金′妻财申金′官鬼亥水′应兄弟午火″子孙丑土″子孙辰土″世动父母卯木′子动化克，不宜从之，不听。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c54.27","text":"后因师责，逃至桥头，跌折右足。","chapter":"卷之四·延师章第四十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c55.1","text":"野鹤曰：凡占小考，当见占得吉卦，后竟道考无名，何也？","chapter":"卷之四·求名章第四十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c55.2","text":"动之应近而不应远，已应府县之有名也，必须先占县者，再占府考，又占道考，但得吉卦者，许榜上有名。","chapter":"卷之四·求名章第四十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c55.3","text":"若有卦而不吉者，勿望道考而成名也。","chapter":"卷之四·求名章第四十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.1","text":"父旺官兴，堪期首选。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.2","text":"官衰父发，亦论抡收。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.3","text":"官星持世，得日月动爻相生相合，道选无疑。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.4","text":"父爻持世，得日月动爻相生相合者，亦要官星有气，始许成名。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.5","text":"子兴财发于卦中，难游泮水。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.6","text":"子动克官，财动克父，或持于世爻者皆不宜也。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.7","text":"世破身空兼墓绝，再奋芸窗。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.8","text":"世爻空破墓绝，或被日月动爻冲克及动而变凶者，不能遂志。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.9","text":"父旺遭伤，收而复弃。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.10","text":"冲中逢合，见弃复收。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.11","text":"父母旺相，若化休囚空破墓冲，若得日月动爻相合者，谓之冲中逢合必获绩取。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.12","text":"父衰变旺，愈出愈奇。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.13","text":"爻化退神，日长日短。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.14","text":"父衰动而化回头生、化进神，文章得意胜于前。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.15","text":"皆不宜化退神，化退神者，前篇稍遂，后劲不力，衰化退神及化克化空破墓绝或回头克者，窗下午日长，场中一日短。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c56.16","text":"如亥月丙戌日占道考得丰之革卦官鬼戌土″官鬼未土″父母申金″世动父母酉金′妻财午火′兄弟亥水′世兄弟亥水′兄弟亥水′官鬼丑土″应官鬼丑土″子孙卯木′子孙卯木′应父母持世化进神，日建作官而生世，文章愈出愈奇，后胜于前，定蒙首选，果取案首。","chapter":"卷之四·童试章第四十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.1","text":"父宜旺相，最忌休囚；","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.2","text":"官宜生身，不宜克世。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.3","text":"父与世爻旺相及得日月动爻生扶及动而化吉，全无破绽者，定考超等。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.4","text":"若此两爻旺相而逢生上等；","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.5","text":"旺而无生，相而遇扶，无刑冲克破者次之；","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.6","text":"有一而遇刑冲克者又次之；","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.7","text":"世爻受克，教刑不免；","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.8","text":"世父同受克，劣等无疑。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.9","text":"野鹤曰：此云是也，亦要人之通变，观其世父两爻轻重而言之，卦之全美世父两爻有生扶，而六冲变冲反吟伏吟动变克化绝即是破绽。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.10","text":"父爻受克而无救，难免涂鸦；","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.11","text":"世爻受克而有扶，亦业姑许。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.12","text":"觉子曰：此以父爻之旺衰而列等第是也，易之卦得进神考于上等，退而考下等，假使卦无进退之神，何以定之？","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.13","text":"如申月乙巳日占岁考得大过之鼎卦妻财未土″动子孙巳火′官鬼酉金′动妻财未土″应父母亥水′世官鬼酉金′官鬼酉金′官鬼酉金′父母亥水′父母亥水′世妻财丑土″应妻财丑土″断曰：财动克父，乃不通变之论也。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.14","text":"此卦乃亥水父爻持世，申月生之，父旺而身亦旺，巳日冲之，为暗动，未土财爻虽动，喜其生助酉金，酉官生世，名为接续相生，一定篇篇华锦。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.15","text":"后果取超等补禀。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.16","text":"野鹤曰：大凡卦遇六冲变冲及六爻乱动，父旺世旺，还考平等。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.17","text":"倘若父衰受刑克及世爻休囚受克及变凶者，孙山无疑。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.18","text":"飞神无助身无克，荣辱无施。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.19","text":"父爻出现，不旺不衰，虽无生扶，亦无克制而世爻不被冲克者，可保平等。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.20","text":"伏藏旺相也遭伤，赏罚不定。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.21","text":"如午月乙卯日占岁焉得地天泰卦子孙酉金″应子孙酉金″应妻财亥水″妻财亥水″兄弟丑土″兄弟丑土″兄弟辰土′世兄弟辰土′世官鬼寅木′官鬼寅木′妻财子水′妻财子水′午火月建为父母，而卦中之巳火伏藏于寅木之下，旺而又遇飞神之生，爻逢六合，只不宜日辰克世，发落之日，承宗师面叱念，字法古笔，姑取三等，后悔之。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.22","text":"此巳午之火，非又旺也及字端边，但此卦虽多逢，事却少见，存之为法。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.23","text":"以上总而言之，父与世爻旺相遇生扶为上，略有破绽者次之，刑伤有救者又次之，刑伤无救而轻者又次之。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.24","text":"世爻父爻被刑冲克破而重者，劣等必矣。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c57.25","text":"全要通变，须卦之吉凶兼用神衰旺之轻重也。","chapter":"卷之四·岁科考章第五十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c58.1","text":"觉子曰：占禀若不得其秘，而望灵者少也，何也？","chapter":"卷之四·增禀章第五十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c58.2","text":"占禀用财，财乃文章之忌神，不知其窍，卜岁焉而兼问禀，财爻若旺，父母受伤，则如休囚如何得禀？","chapter":"卷之四·增禀章第五十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c58.3","text":"余有法也，先占岁科之吉凶，再占一卦而问禀，即其秘也。","chapter":"卷之四·增禀章第五十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c58.4","text":"禀以财爻为用神，财爻持世或动而生世为吉，与求财章同断。","chapter":"卷之四·增禀章第五十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c58.5","text":"有禀而恐换者，忌兄弟持世，兄爻发动及财逢空破墓绝，动而变凶者，有失也，如官鬼兄爻克世者，轻则草粮，重则道罚，倘卦中三合兄局者，亦主草粮。","chapter":"卷之四·增禀章第五十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c59.1","text":"官爻持世生世，我必业收。","chapter":"卷之四·考道才章第五十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c59.2","text":"父母空破墓绝，他不见用。","chapter":"卷之四·考道才章第五十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c59.3","text":"如世爻受克及空破墓绝，或动而变凶、或子孙持身动于卦中，皆不录之。","chapter":"卷之四·考道才章第五十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c59.4","text":"父母生世持世者吉，休囚空破者凶。","chapter":"卷之四·考道才章第五十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c60.1","text":"父为用神，衰者宜生旺之日；","chapter":"卷之四·发案持榜章第五十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c60.2","text":"旺而静者，逢值冲之日；","chapter":"卷之四·发案持榜章第五十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c60.3","text":"动而逢值逢合之日；","chapter":"卷之四·发案持榜章第五十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c60.4","text":"空与入墓，必待冲开；","chapter":"卷之四·发案持榜章第五十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c60.5","text":"破与旬空，须期填实。","chapter":"卷之四·发案持榜章第五十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c60.6","text":"余又得验，心有忧惧，若得子孙持世，值子孙之日而发案。","chapter":"卷之四·发案持榜章第五十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c60.7","text":"心有欢喜，若得官星持世，逢官鬼之日而挂榜。","chapter":"卷之四·发案持榜章第五十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c61.1","text":"典会场断，官星为用，父爻次之。","chapter":"卷之四·延试章第五十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c61.2","text":"若持世爻得日月岁五生合者，定蒙道拔。","chapter":"卷之四·延试章第五十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c61.3","text":"官爻世爻三合，定蒙异宠隆恩。","chapter":"卷之四·延试章第五十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c61.4","text":"世与官爻有一而逢空墓绝刑冲克害及动而变凶者，不详之兆。","chapter":"卷之四·延试章第五十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c61.5","text":"岁五官鬼冲无世爻者不测之灾。","chapter":"卷之四·延试章第五十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.1","text":"父旺官兴，姓标虎榜。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.2","text":"父官持世而旺相，或临日月、或日月动爻生扶、及动而变生，名登龙虎。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.3","text":"子摇财动，名落孙山。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.4","text":"子孙财爻持世，及动于卦中，终须下第。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.5","text":"兄弟乃夺标之恶客。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.6","text":"俗传兄弟爻兴难上榜，凡见兄爻持世及动者，皆以为之不吉，殊不知有喜有忌，所喜者卦中财爻同兴，喜其兄动以制财也。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.7","text":"卦中父官两动者，又喜兄爻持世，父动以生世也。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.8","text":"兄弟持世，若临日月或旺相，再得官父两旺、或官动生父、父动生世，必添科名。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.9","text":"兄不能抡元而夺魁也，故谓之兄弟乃夺标之客。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.10","text":"觉子曰：卦中官鬼子孙同动，官临旺相遇生扶，子孙弱而被克，再宜父动，最怕兄兴。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.11","text":"日月为制煞之将军。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.12","text":"官星父母世爻有一而被动爻克制，或化回头克，若得日月冲制克神，亦许得意，故谓制恶煞将军。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.13","text":"又如，世爻旺相而官父两爻有一而伏藏不现，倘得日月冲制飞神，提出伏神者，许高发。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.14","text":"又如官父世爻有一而不生者，若得日月生扶亦同此意。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.15","text":"二合无冲，定登甲第。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.16","text":"官父世爻合成父局官局，不遇日月冲破者，定许连登，倘若合成兄局，得遇日月生扶，官星亦旺者，亦许得意。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.17","text":"唯忌合成子孙局者，不为吉也。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.18","text":"合成财局虽不为美。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.19","text":"然亦得验于吉者。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.20","text":"如卯月甲申日占会试得艮之益官鬼寅木′世官鬼卯木′应妻财子水″动父母巳火′兄弟戌土″兄弟未土″子孙申金′应动兄弟辰土″世父母午火″官鬼寅木″兄弟辰土″动妻财子水′寅木旺官持世，申日冲之，暗动又得日辰会成财局，不唯不克世爻，反来生世，一定高捷，果得及第。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.21","text":"六爻竟发空赴科场。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.22","text":"旧系六爻竟发，功名恍惚以难成，此论是理。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.23","text":"余见占功名必中者，卦象一成，若非旺父生身，定是旺官持世。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.24","text":"功名无成者不是子孙持世，即是子孙财爻发动，或是世爻破空，或是六爻乱动，功名必无成。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.25","text":"出现无情，难遂青云之志。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.26","text":"父与官星虽则出现，若不生合世爻，或不持世，或世爻空破，亦属无益。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.27","text":"父与官星生合世爻，若又被日月动爻冲坏者，亦作无情之喻。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.28","text":"伏藏有用，终辞白屋之人。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.29","text":"官父有一而不上卦，须看伏神，若伏而旺相，或得日月冲去飞神，生起伏神，准登科及第。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.30","text":"太岁作官星，终登黄甲。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.31","text":"太岁乃国君，父官临太岁，动而生合世爻，乃人臣面君之象，当主君臣契合，连捷无疑。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.32","text":"太岁必要入爻，入爻亦要发动，或持世爻，始如此说。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.33","text":"日月冲克世，且守青灯。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.34","text":"卦中官父虽旺而世爻休囚空破墓绝及动而变凶，或日月冲克世爻，须知求名在我，我位既失，何以成名。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.35","text":"卦遇六冲，此去难题雁塔。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.36","text":"爻逢六合，这回可夺鳌头。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.37","text":"如午月丙辰日占乡试。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.38","text":"得兑卦父母未土″世父母未土″世兄弟酉金′兄弟酉金′子孙亥水′子孙亥水′父母丑土″应父母丑土″应妻财卯木′妻财卯木′官鬼巳火′官鬼巳火′旧注：卦逢六冲，冲之即散。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.39","text":"余见此卦，虽系六冲，世父皆逢旺地，不敢决之，请再占一卦。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.40","text":"又得临之师卦子孙酉金″子孙酉金″应妻财亥水″应妻财亥水″兄弟丑土″兄弟丑土″兄弟丑土″父母午火″世官鬼卯木′世兄弟辰土′父母巳火′动官鬼寅木″此卦官星持世，虽则不旺，初爻官生父旺，与前卦相合，许之吉兆，果得成名。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.41","text":"凡得六冲卦，官父世爻俱旺者，不必再占，竟许必得。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.42","text":"如父旺者，须再占一卦，再得吉者，以吉断之，后卦凶者，即以凶推。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.43","text":"凡得六合卦，亦要官父世爻得地，有一失陷不遇生扶者，虽六合亦无益矣。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.44","text":"父旺官衰终须下第。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.45","text":"父爻旺相官临空破墓绝及动而变凶变克虽有锦乡。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.46","text":"文章终遇红纱蔽目。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.47","text":"父衰官旺堪许登科。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.48","text":"官爻旺而生世持世，若是父爻不旺，谓之福齐文不齐，反许遂志。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.49","text":"应合日生必资鹗荐。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.50","text":"官父两旺而世爻不旺，或得日月扶助，又得应爻动而生合世爻者，必得推荐之力。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.51","text":"动伤日克还守鸡窗。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.52","text":"应爻动爻虽来生合世爻，而应爻又被日月冲克者，荐亦无功。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.53","text":"世动化官化克蝶梦堪忧。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.54","text":"旧有身官化鬼月扶，连步蟾宫。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.55","text":"又曰：身兴变鬼，来试方成。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.56","text":"又曰：身动化空用旺，豹变翻成蝶梦。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.57","text":"皆以卦身而言，余试总无应验，唯验于世爻，而世爻化鬼亦有两验。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.58","text":"卦中父母旺相而世爻化出官星者，若不回头克世乃为变官，今科即中，岂等来科？","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.59","text":"若休囚被克，动而化出官星者，乃为化鬼，不唯不中，且见危灾。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.60","text":"化出鬼爻克世者更凶。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.61","text":"如卯月戌辰日占得离之既济兄弟巳火′世动官鬼子水″应子孙未土″动子孙戌土′妻财酉金′动妻财申金″官鬼亥水′应官鬼亥水′世子孙丑土″子孙丑土″父母卯木′父母卯木′旧注：身官化鬼，月扶鹏程，连步蟾宫。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.62","text":"谓卦身如得官爻临之，必有成望，若得出现发动化出官爻，又得月建生之合之者，亦必聊捷。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.63","text":"觉子日：此卦已为卦身，又是世爻变出子水官星，又得月建生合，正合此说，竟未见其连捷，不唯不能连捷，且难保其长年，其故何也？","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.64","text":"因变出子水之鬼回头克。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.65","text":"身兴化旺化生，龙池变化。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.66","text":"世爻旺相动而变出官星回头生合世爻者，不作变鬼，乃为变官。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.67","text":"世退官星化退，窗下囊萤。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.68","text":"世与官父相旺内有一而化进神者，名姓高悬，占乡试必连捷。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.69","text":"独不喜化退神，世化退神，若非临场之阻，必无勇往之心，父化退神学问日颓，文章渐腐，官退化神，皓首无成，当于进退章中参考。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.70","text":"财临白虎持身，幛前枕块。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.71","text":"旧财临白虎必丁忧，然亦不唯临虎，凡遇财爻持世，或财动卦中，父母又值休囚空破，及财动化父，父动化财，皆枕块之兆。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.72","text":"乾卦如天亦当官父两旺。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.73","text":"雷声如震犹有空破之嫌。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.74","text":"古以乾震之卦既以为吉，余试务必官父两旺，始以吉断，否则未见为吉卦。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.75","text":"衰旺克冲，轻重须宜细玩。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.76","text":"墓绝空破，应期章内详之。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.77","text":"前应期章宜熟记，各门各类，无不问其应期，熟则触类旁通，随心应变。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c62.78","text":"凡遇用神衰要有根，旺宜冲，刑克要有救，冲要逢合。","chapter":"卷之四·乡试章第五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.1","text":"官爵荣身，须宜持世。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.2","text":"财禄恩养，最喜生身。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.3","text":"旺官持世及日月动爻作官星生合世爻，或世爻发动化出官星生世皆吉。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.4","text":"又日时动生官，得美缺。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.5","text":"官临日月，必超迁。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.6","text":"子孙持世，休望荣荫。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.7","text":"官位空破，勿恩升迁。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.8","text":"子孙持世，子孙动于卦中，升迁无期。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.9","text":"官临空破墓绝及动变凶，补升无望。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.10","text":"雨露承恩，名中逢合。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.11","text":"世与官星三合官局财局，或生世，或世在局中，或官星持世与日月动爻相合，得逢六合卦及卦动变六合者，皆是天赐之恩。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.12","text":"如申月已亥日占缺得否得井之节卦父母子水″父母子水″妻财戌土′世妻财戌土′官鬼申金″官鬼申金″应官鬼酉金′动妻财丑土″父母亥水′应兄弟卯木′妻财丑土″动子孙巳火′世断曰：内卦巳酉丑合成官局，而生应爻，不来生世，正所谓出现无情，此缺不得。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.13","text":"彼曰：如何不得？","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.14","text":"余曰：官生应爻，一定不得，后果另选别人。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.15","text":"风云未际，冲上加冲。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.16","text":"世官不旺，得六冲，或是官被日月相冲，或是卦得六冲，乃风云未际之时也。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.17","text":"元神衰静曳气爻摇，问升迁以无期。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.18","text":"假令官爻司木，衰而不动，火爻发动是也，余仿此。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.19","text":"世爻发动，官化进神，望荣除而在即。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.20","text":"世爻发动，或动而化吉，或禄马日月临世，及官动化吉生合世爻，皆可束装以待。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.21","text":"世官破而休望，世福空而亦升。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.22","text":"世临日破即使官星持世，不独不能升选，且防他变。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.23","text":"子孙持世值旬空，亦不当升。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.24","text":"若占两三日之内者，许之必得，其故何也？","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.25","text":"子孙尚未出空不克官也。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.26","text":"野鹤曰：占过三个，俱皆得官，得官之后，随即死亡。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.27","text":"申月戊寅日占得差否。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.28","text":"得泽天夬卦兄弟未土″兄弟未土″子孙酉金′世子孙酉金′世妻财亥水′妻财亥水′兄弟辰土′兄弟辰土′官鬼寅木′应官鬼寅木′应妻财子水′妻财子水′断曰：子孙持世，此差不得，世空亦不得。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.29","text":"岂知不出三日得差，行至中途而死，其故何也？","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.30","text":"三日之内而得差者，子孙未出空也。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.31","text":"中途而死者世爻空也。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.32","text":"随官入墓，世旺者官升。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.33","text":"助鬼伤身，身衰者祸至。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.34","text":"古以随官入墓，助鬼伤身，皆以为凶。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.35","text":"余屡试之，世旺者竞升，世衰者不吉。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.36","text":"助鬼伤身，元神同动者，其官必升。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.37","text":"世若休囚者，必有祸至。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.38","text":"如寅月乙未日占升迁得比之观妻财子水″应动官鬼卯木′兄弟戌土′父母巳火′子孙申金″兄弟未土″世官鬼卯木″世官鬼卯木″父母巳火″父母巳火″兄弟未土″兄弟未土″应断曰：卯木旺官持世，子水财动相生，虽则墓于未日，幸世反得助，无妨，果得升于亥月。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.39","text":"又如戌月辛酉日占何日补官得蹇之需子孙子水″子孙子水″父母戌土′父母戌土′兄弟申金″世兄弟申金″世兄弟申金′父母辰土′官鬼午火″动妻财寅木′父母辰土″应动子孙子水′应寅木财爻生助午火之鬼，火鬼克世，乃为助鬼伤身。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.40","text":"幸辰土生申金，午火贪生忘克，今年冬月必升，果得升于冬月。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.41","text":"应冬月者，辰土化子水空亡，十一月则不空矣。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.42","text":"古以晋升为吉，又云屯蹇为凶。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.43","text":"晋卦升卦，果得屡验。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.44","text":"亦要世爻得地，若失陷，亦不为吉。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.45","text":"屯卦蹇卦，世爻旺者何妨。","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c63.46","text":"前篇亥月丙寅日占验，世爻旺者，竟超升，岂非屯卦耶？","chapter":"卷之四·升选候补章第又五十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.1","text":"官金而应西，木官应于东，水北火南土中，此古法也。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.2","text":"余之得验，木官而应山东，有应广东者。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.3","text":"金官虽应山西，有应江西，广西者。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.4","text":"又有以住处而定东西南北者。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.5","text":"如未月己巳日住在京都占地方得归妹变解父母戌土″应父母戌土″兄弟申金″兄弟申金″应官鬼午火′官鬼午火′父母丑土″世官鬼午火″妻财卯木′父母辰土′世官鬼巳火′动妻财寅木″彼时有山东真定两缺，此卦巳火官星，许之真定。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.6","text":"余曰：巳火官星，乃南方也，必得真定，真乃都门之南也。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.7","text":"又有以初爻为内地，以五爻六爻为边缺。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.8","text":"应初爻者，世与官星皆在初爻者是也。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.9","text":"应五六爻者，或世在五爻，官在六爻；","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.10","text":"或世在六爻，官在五爻；","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.11","text":"戌土官星持世，同在五爻六爻是也。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.12","text":"若在二三四爻以五行决之。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.13","text":"野鹤曰：大概问其地方，虽则有验，然不如指其缺而问之，此缺我得否？","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.14","text":"官星持世者，必得。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.15","text":"官动生合世爻者，必得。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.16","text":"三合官局而生世者，必得。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.17","text":"世空世破官破官空，俱不得。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.18","text":"子孙持世、子孙发动，不得。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.19","text":"官临应爻，不得。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c64.20","text":"三合局而生应爻，不得。","chapter":"卷之四·升迁何方章第五十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.1","text":"官旺财兴，仕途显赫。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.2","text":"子摇兄动，减俸休官。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.3","text":"官旺遇生扶，或动而化吉，世旺财动以生世，皆主兵民颂德，官新无波。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.4","text":"官临日月生合世爻，三合官局生合世爻，或官星持世日月生扶，岁五又相生合，近君者，蒙异宠，在位者，不久超升，外任者必为卓异。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.5","text":"兄弟持世，兄爻发动，若非破耗财物，定然咸俸除粮。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.6","text":"子孙持世及子动而有制，降级而已。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.7","text":"官旺兄兴，清风两袖。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.8","text":"父发鬼旺，恩露三赐。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.9","text":"兄动虽有为减俸耗财之神，亦不可执之，若得官星旺相，乃是为官清正，非义不取，非无财也。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.10","text":"官星旺相，财临空破者，亦同此断。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.11","text":"旺父临世，官动临岁五，或日月生扶，外任者必蒙上官推荐，近君及大位者三赐荣加。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.12","text":"兄鬼安静，地方无事。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.13","text":"兄鬼乱动于卦中，旱涝兵星、地方不宁之兆。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.14","text":"日月冲克，诽谤多招。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.15","text":"日月克官，或克世爻，及朱雀腾蛇克世，世爻休囚者，得祸不轻，世爻旺相有敕者，多招是非，须且检点，政事勤慎，以免愆尤，官鬼克世，世旺官衰者，亦主诽谤，世衰官旺，若临蛇雀，必见弹章。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.16","text":"化进神，冲变合，加官晋爵。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.17","text":"世爻旺相，官化进神，官星旺相，世化进神，及世官得地，财化进神，皆有晋爵之征。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.18","text":"爻反吟，入三墓，反复昏庸。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.19","text":"卦得反吟，虽是身动不宁，若得世与官多旺相，一定升迁，世爻若与官星衰者，必遭降罚，降后还忧虑焦灼。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.20","text":"世与官星被克者，定有不测之祸。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.21","text":"世爻休囚被克化墓者，多反复立见灾非。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.22","text":"世爻有气化墓入墓者，亦主朦胧昏愤。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.23","text":"世破兄空，居官不久。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.24","text":"身衰化鬼，命尽当危。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.25","text":"世破世空官空破，在任无多日矣。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.26","text":"世衰动而化鬼及化回头之克者，须防寿命无(坚)世化官而遇官，政权多摄。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.27","text":"世爻旺相，化出官星生合比助世爻者，得权摄。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.28","text":"化出官星刑伤克害世者，反受权摄之害也。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.29","text":"化出官星拱助比合者，亦主政权摄。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.30","text":"世临官而遇马，差遣烦劳。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.31","text":"官星持日月动加临驿马者，多有差遣，日月动爻作财而扶者，差中得利。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.32","text":"卦中兄爻发动，日月动爻刑克世爻者，辛苦赔财，心有望于差遣者，不待驿马加临，但遇世动即有差矣。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.33","text":"官合龙兴恩命至。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.34","text":"青龙官星持世，或世临日月，或日月动爻生合世爻，或世临岁五之爻，或岁五生合世，或世官三合皆为吉兆。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.35","text":"大位者上恩特殊，平位者加级超升。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.36","text":"财临福动佳音来。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.37","text":"财爻持世及卦中财动，或父母爻休囚空破，若有尊长，切不可以财断之，须防孝服。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.38","text":"如寅月壬午占在任平安否得颐之噬嗑卦兄弟寅木′子孙巳火′父母子水″妻财未土″世妻财戌土″世动官鬼酉金′妻财辰土″妻财辰土″兄弟寅木″兄弟寅木″应父母子水′应父母子水′有人出此卦而问余曰：今岁占在任之流年，世爻变鬼，我甚忧之、余曰：财休囚得午火生之，自身不妨，须防孝服。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.39","text":"彼曰：财非临虎，如何主孝？","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.40","text":"余曰：迂也，午日冲动子水，父母被戌土财爻克，世化官空，八九月必见，果于八月丁艰。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.41","text":"援例章第五十八（凡用财图名者同此）财旺官空，且有堆金于白屋。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.42","text":"财旺世旺而官临月破旬空，或被日月冲克，及动而变凶，官如朽木枯枝，虽有旺相之财，生之不起，终与属日月之富翁，难食王家之天禄。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.43","text":"妻摇鬼旺，定然执王拜丹(墀)。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.44","text":"世与官星二者不可一陷，若财官两旺而世爻失陷者，终使得官难安享。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.45","text":"若官世两旺财星失陷者，乃有例而无财也如丑月乙卯日占援例得豫之否卦妻财戌土″动妻财戌土′应官鬼申金″动官鬼申金′子孙午火′应子孙午火′兄弟卯木″兄弟卯木″世子孙巳火″子孙巳火″妻财未土″世妻财未土″断曰：财动生官，不宜世临月破，破而被克者，有官不能享也。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.46","text":"后竟纳之，名败身丧。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.47","text":"财静子飞空用意。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.48","text":"子孙持世，财爻动与不动者皆不可行，财临空破亦不可行。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.49","text":"子孙财星官星同动者又可行，其故何也？","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.50","text":"子动生财，财动生官，故可行。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.51","text":"兄兴财动枉劳心。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.52","text":"兄弟爻持世或兄爻发动乃是破耗之神，白费其财，终不成名，若得官星同动者，又可以行之，何也？","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.53","text":"以官鬼而制兄也。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.54","text":"野鹤曰：卦中官星不动，但遇兄弟持世、兄父发动、及财爻持世化兄弟，百无一成，即使成，后凶，有他故，终无食禄之方武试章第五十九亦可以与文试看文试者，官父而重。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.55","text":"武试者，首重官爻。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.56","text":"世破官空休指望，官兴财旺亦堪图。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.57","text":"世与官星有一而逢空破者，不须指望。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.58","text":"武场虽不以父为重，余常得验官父两旺者，竟得抡元。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.59","text":"然又有财动生官竞得中者，何也？","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.60","text":"然其中必有隐事。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.61","text":"空赴武阁皆为子孙持世。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.62","text":"子孙发动，即使力能扛鼎，百步穿杨皆无益于事矣。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.63","text":"试期病阻乃因官鬼克世。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c65.64","text":"日月动爻克世，世动化鬼、化克世，非临场病阻，即有灾祸临身到。","chapter":"卷之四·在任吉凶章第五十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c66.1","text":"官宜旺相不宜空破休囚，财世两爻怕见刑冲克破。","chapter":"卷之四·投麾效用入武从军章第六十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c66.2","text":"世与官星皆旺动而化吉。","chapter":"卷之四·投麾效用入武从军章第六十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c66.3","text":"财为禄养，岂宜日月刑冲？","chapter":"卷之四·投麾效用入武从军章第六十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c66.4","text":"世爻失陷及动而变凶，有难；","chapter":"卷之四·投麾效用入武从军章第六十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c66.5","text":"官星失陷及动而变凶，难许成名；","chapter":"卷之四·投麾效用入武从军章第六十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c66.6","text":"财爻失陷及动而变凶，乏粮无禄，即使官旺厨(灶)无烟；","chapter":"卷之四·投麾效用入武从军章第六十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c66.7","text":"唯喜官星持世，财动相生，或世动化吉，将来之封候拜将可期，岂唯百夫之长而已耶。","chapter":"卷之四·投麾效用入武从军章第六十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c66.8","text":"觉子曰：虽以此断，无不验者，但要识来人之意，彼若以名利而问，以此而决者是也。","chapter":"卷之四·投麾效用入武从军章第六十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c66.9","text":"如若尚未见用，占问可能收用，又以官星为收用之官，官来生合世爻者必收。","chapter":"卷之四·投麾效用入武从军章第六十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c66.10","text":"官爻克世及空破者，不禄。","chapter":"卷之四·投麾效用入武从军章第六十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c66.11","text":"如不知其此窍，竟以此官星断自己之功名，如天远也。","chapter":"卷之四·投麾效用入武从军章第六十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c67.1","text":"财与官星不可有一而不旺，子孙兄弟不可一而动摇，世陷财空，不如守己，官空世破，且让他人。","chapter":"卷之四·署印谋差章第六十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c67.2","text":"用财而图者与援例同推。","chapter":"卷之四·署印谋差章第六十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c67.3","text":"衰世随鬼入墓，世动化克化鬼，子孙兄弟持世，谋署谋差，自投罗网。","chapter":"卷之四·署印谋差章第六十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.1","text":"凡占文书亦须采用旺父持世，宜日月岁五以维持。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.2","text":"父母为文书章奏，持世合世，奏必见准，再得岁五及日月动爻生合者见用、兄弟临身，喜父母化吉而拱合。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.3","text":"兄弟持世，日月生之，或世爻父母爻动而化吉，或化父母生世。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.4","text":"皆得喜动龙颜，因文见用。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.5","text":"财爻持世破文书。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.6","text":"财爻持世，财爻发动，克破文书，无益之奏。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.7","text":"倘得父母持世，财官同动者而又喜之，其故何也？","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.8","text":"以财动而生官，官动而生世也？","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.9","text":"子福临身防降罚。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.10","text":"子孙为克官之神，有职之官章奏者不宜见之，或持世或发动，轻则降罚，重则休官，无职之人而章奏者有两论之，须查来人之念，彼行此事原为名者，见之不成名；","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.11","text":"彼此事恐其有祸，若见之则无祸。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.12","text":"世临空破难以回天。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.13","text":"世临旬空月破及临绝及入三墓者，不蒙见准。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.14","text":"世动变凶或日月岁五动爻冲克世爻者，不唯难以回天，且防不测之祸。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.15","text":"子动临身力能折槛。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.16","text":"或曰：前说子动克官，不宜见之，此喜子孙持世者，何也？","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.17","text":"野鹤曰：须看事之大小，有职之官行此事，若预料此事即不准，行无过于革职而巳，子孙者即为克官之神也。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.18","text":"欲保全功名，子孙发动，切勿行之，倘若条陈，将相谏君，非若得准行，名垂竹帛，如不见准，祸及其身，所以反喜子孙持世，即使殿折廷诤，可保无祸。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.19","text":"古以子发乾官为吉，非也。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.20","text":"子孙为制鬼之神，未闻独在乾官而为福神也。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.21","text":"最怕官爻克世，不宜助鬼伤身。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.22","text":"卦中官爻发动克世者大凶，若又得财爻发动助鬼爻伤身，灾祸难免。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.23","text":"若世动化鬼、发动化回头克、随鬼入墓、卦得反吟、卦变绝、世被冲者，事非重大，急宜止之。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.24","text":"岁五生身防受制，六爻恍惚且休行。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.25","text":"太岁生世要入卦，不在爻中，不能生世。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.26","text":"且如今岁子年，须看卦中有生之名，无生之实。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.27","text":"如申月戊辰日占上书得中孚之损官鬼卯木′官鬼寅木′应父母巳火′动妻财子水″兄弟未土″世兄弟戌土″兄弟丑土″兄弟丑土″世官鬼卯木′官鬼卯木′父母巳火′应父母巳火′断曰：五位巳火生世，不宜巳火受克，此书宜上。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.28","text":"余曰：巳火虽则不能生世，卦中无克之爻，利害皆无从言起，上与不上皆可。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.29","text":"后此人上书，不准。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.30","text":"野鹤曰：凡上书劾奏，果有兴利除害，益于国者，舍身而为国虽蹈汤赴火而不辞，何用占卜？","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.31","text":"倘若事无关系、或因忿而抱不平、或以直而报怨、事在两可之间者，得世与父爻皆无刑冲克破，及岁五日月相生，方可行之。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.32","text":"倘爻中乱动而用神衰或生少克多，六爻恍惚者，即宜止之，言出祸随，得不慎乎？","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.33","text":"父旺官生叨蒙赠爵，旺官持世平步登云。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.34","text":"旺父持世，官动生之，旺官持世，官持日月生之，官则上加官，士则登(台)阁，平人得者，立见平步登云。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.35","text":"野鹤曰：断卦者最重来之一念：有为人者，有为己者，有为自身而要怨者，有为保全人己立功名，有为财利者，有为免自己之赔累者，有为辨下属之赔累者，有事之多端，在人通变，士民上书，虽则亦有忠心为国，亦有借此以作梯阶而求名也，倘若得官旺而父不旺，亦可许之赠职。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.36","text":"我念为名，忌子孙之发动，我念利，忌兄弟以临身。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.37","text":"如丑月丙辰日出具文伸枉保全功名得大壮之夬卦兄弟戌土″兄弟未土″子孙申金″动子孙酉金′世父母午火′世妻财亥水′兄弟辰土′兄弟辰土′官鬼寅木′官鬼寅木′应妻财子水′应妻财子水′父母持世，月建文书生旺，但不宜子动伤官，七八月申金得令之秋功名坏矣，果蒙上台题保，未劳准行，八月削职，此乃为名，父旺亦属无益。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.38","text":"占防劾、虑大计、及已有事尚未结案者：世旺官崇，忧心冰解。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.39","text":"旺官持世，喜照双眉。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.40","text":"世与官星旺相何忧？","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.41","text":"再得日月动爻生扶，或得世爻官爻临于日月，及动而变吉，防参劾者何虑？","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.42","text":"已(参)而未结案者无忧，定蒙卓异。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.43","text":"凡得旺官者亦同此推。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.44","text":"如未月戊申日占因避误军粮己被劫得丰之旅官鬼戌土″动妻财巳火′父母申金″世官鬼未土″妻财午火′父母酉金′应兄弟亥水′父母申金′官鬼丑土″应妻财午火″子孙卯木′动官鬼辰土″世断曰：世临日建月建生之，动出戌宫又来相生，官爵无恙，彼不以为然，岂知因获奇功，保本随至，功名仍复保全。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.45","text":"或曰：卯木子孙发动，如何不克官？","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.46","text":"余曰：木绝于申，所以有救。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.47","text":"福世孙摇身化福，官空鬼破变爻克。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.48","text":"子孙持世、子孙动于卦、世动化子孙、官空及动化回头之克，皆主罢职休官。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.49","text":"子动财空，减禄罚奉。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.50","text":"兄弟持世、兄弟发动、或财破及财动化凶，倘得官爻旺相，罚俸而已，官爻失陷，利名双失。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.51","text":"身衰鬼克，贬责凌辱。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.52","text":"世衰不遇生扶，又有岁五日月动爻刑冲克世，或世随鬼入墓、动化鬼化克、及虎蛇刑克世爻者，轻则贬罚，重则刑狱。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.53","text":"或曰：何以谓之轻重？","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.54","text":"余曰：轻者乃世爻有救，重者乃世爻休囚，又被刑伤冲克也。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.55","text":"卦静世空官又陷，林下闲人世空者退休之兆，官又空破休囚者削职无疑。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.56","text":"世陷逢杀兴何碍。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.57","text":"古有身空杀动避祸之征，余以为非。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.58","text":"殊不知世者动于卦中世爻空者，持世爻出空之月日必遭其害，岂能避之？","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.59","text":"惟世空逢六神动而相生，卦中虽有忌神发动亦无碍矣。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.60","text":"待世爻出空之日，忌神反生六神而生世也。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.61","text":"官隆世陷，身辱官存。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.62","text":"古有身边伏鬼若非空，官职犹在，谓凡遇凶兆，若得官爻持世或官伏世下而旺，虽见责罚而官职犹存。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.63","text":"野鹤曰：世遇五爻之克，若得旺官持世，虽受辱，仍可为官。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.64","text":"身旺官陷，位去身安。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c68.65","text":"世爻旺相不受伤克，官破官空及被刑冲克害或动而变凶者，官禄虽失，身不逢伤。","chapter":"卷之四·面圣上书、叩阉、献策、入条陈、劾奏章第六十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c69.1","text":"子旺子兴，必能遂愿，官旺克世，总不如心。","chapter":"卷之四·养亲告病辞官章第六十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c69.2","text":"子孙持世子孙发动，乃无官之果，必能遂我偷闲。","chapter":"卷之四·养亲告病辞官章第六十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c69.3","text":"若官星持世或官动克世合世，难脱利名靼锁。","chapter":"卷之四·养亲告病辞官章第六十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c69.4","text":"告假不忌反吟，休致须宜化退。","chapter":"卷之四·养亲告病辞官章第六十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c69.5","text":"告病及养亲乃暂归之事，得反吟卦者，乃应将来再任，故不忌之，惟辞官者，不宜见之，非目下屡辞反复，乃将来远入留(台)，若得伏吟必不能行。","chapter":"卷之四·养亲告病辞官章第六十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c69.6","text":"世与官星化退神者如愿，世与官星而化进神者，五事羁身，难于歇手。","chapter":"卷之四·养亲告病辞官章第六十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.1","text":"福摇子动无尤，鬼克兄冲有患。","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.2","text":"子孙持世子动卦中事无尤虑，有始有终。","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.3","text":"官鬼克世而受累，兄动以赔财，鬼兄持世同推。","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.4","text":"父世官生因公加爵。","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.5","text":"父母持世，官星动而生合世爻者，必因公事加官。","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.6","text":"财兴官旺获利荣名。","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.7","text":"旺官持世，财动而相生，不独因公得利，远许名荣旺，财爻持世世动化财生世，皆同此断。","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.8","text":"六冲不久六合坚牢。","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.9","text":"工程皆以父爻为用神，不旺或受冲克又得六冲卦者必不坚久，化冲者亦然，又看世爻旺相，又得六合卦者永远坚。","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.10","text":"野鹤日：凡占公务，初入工程而防患，宜子孙动摇无尤，倘若已见(疏)(忧)而防患者，必有功名之虑，子动以伤官也。","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.11","text":"岂曰：子动而无尤耶？","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c70.12","text":"初入工程，兄动以防赔财，已见(疏)(忧)兄动而防罚俸。","chapter":"卷之四·修陵修河一切营造公务防患章第六十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c71.1","text":"僧官医官亦喜官爻发动。","chapter":"卷之四·僧官道纪医官(杂)职阴阳寺官章第六十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c71.2","text":"旧系岂可爻书发动，谓僧道医官占功名，乃以子孙为用神，不宜父动而克子也。","chapter":"卷之四·僧官道纪医官(杂)职阴阳寺官章第六十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c71.3","text":"野鹤曰：此非理也，若他占僧道医人，乃以子孙旺相，道业高强，父母兴隆，庸愚懦弱。","chapter":"卷之四·僧官道纪医官(杂)职阴阳寺官章第六十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c71.4","text":"若僧道医家自占道艺，亦以子孙为用神，子孙旺相，鬼服龙降。","chapter":"卷之四·僧官道纪医官(杂)职阴阳寺官章第六十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c71.5","text":"今以自占功名，子动而克官也，如何反为用？","chapter":"卷之四·僧官道纪医官(杂)职阴阳寺官章第六十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c71.6","text":"非也，仍看官爻。","chapter":"卷之四·僧官道纪医官(杂)职阴阳寺官章第六十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c71.7","text":"官星持世或日月动爻以相生，父母持世或得旺官相生，其名必成。","chapter":"卷之四·僧官道纪医官(杂)职阴阳寺官章第六十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c71.8","text":"阴阳(杂)职俱以子动为嫌。","chapter":"卷之四·僧官道纪医官(杂)职阴阳寺官章第六十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c71.9","text":"子孙动子持世皆许必不成名，笃则以俗家求名同断。","chapter":"卷之四·僧官道纪医官(杂)职阴阳寺官章第六十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.1","text":"占法：水一火二木三金四土五，官临火者，官居二品，官星属水，一品之尊。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.2","text":"野鹤曰：水至二数位至公侯者，何以定之？","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.3","text":"官设九品，数止于五六七品者，何以定之？","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.4","text":"余得其法者，指占之法也。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.5","text":"旺官临日月，指日可期，官破及刑冲终生失望，子孙持世，犹如止渴望梅，官动生身，恰似探囊取物。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.6","text":"曾有邑宰问将来官至方面否巳月乙卯日占得雷山小过父母戌土″父母戌土″兄弟申金″兄弟申金″官鬼午火′世官鬼午火′世兄弟申金′兄弟申金′官鬼午火″官鬼午火″父母辰土″应父母辰土″应午火官星持世后，果官至命事，又子月乙亥日官至方伯。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.7","text":"问将来能于开府否？","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.8","text":"连占三卦子孙持世，后果降调而归。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.9","text":"又因占会试许之必中，又问可能鼎甲否？","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.10","text":"余曰：必须再占一卦。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.11","text":"卯月甲申日得节之蹇兄弟子水″兄弟子水″官鬼戌土′官鬼戌土′父母申金″应父母申金″世官鬼丑土″动父母申金′子孙卯木′动妻财午火″妻财巳火′世动官鬼辰土″应断曰：古以蹇为不吉，余重用神。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.12","text":"此卦世临巳火，卯月生之，申日合青龙持世，中鼎甲而无疑，但非今科之鼎甲也。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.13","text":"余曰：世爻变出辰土之官，乃辰年之鼎甲也。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.14","text":"公曰：此数暗含我机，我少年得一预兆，亦应辰年。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.15","text":"伤(毕)即回，至甲辰科殿试，果得首唱传(胪)。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c72.16","text":"以教人指其事而占者，无不验也，何必谆谆执古法而猜耶。","chapter":"卷之四·功名到何品级章第六十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c73.1","text":"父动官动相生，日月作官星而生父母，父旺化官动而化吉，皆许成名。","chapter":"卷之四·子占父动名章第六十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c73.2","text":"财克父，子动伤官，父官动而变凶，日月克官克父，或父爻衰墓破绝皆许无益。","chapter":"卷之四·子占父动名章第六十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c73.3","text":"如卯月壬辰日占父何时起用得风水涣变夬父母卯木′动子孙未土″兄弟巳火′世妻财酉金′世子孙未土″动官鬼亥水′兄弟午火″动子孙辰土′子孙辰土′应父母寅木′应父母寅木″动官鬼子水′内卦寅木父母旺而化出子水之官，许寅年仍以原品起用，果应于寅年。","chapter":"卷之四·子占父动名章第六十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c73.4","text":"又以此卦悟之，初爻寅年而起用，上爻卯木父动而化未年，占时未墓爻空，谓之空墓以待死，所以终于实墓之年，又因用神重叠墓库以收藏也。","chapter":"卷之四·子占父动名章第六十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.1","text":"诸书之论求财，弗如黄金策里真论，余屡试验，惜乎未经分别，今以前段为总论，以后贤易晓，内有屡试而不验者，删之，余另得验者，增之。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.2","text":"财旺福兴，公私称意。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.3","text":"财空福绝，上下连心。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.4","text":"上至国计，下至营谋，无不以财为用。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.5","text":"公私占卜皆以财为用神，子孙者乃生助财爻之元神也，俱宜旺而化吉，又宜生合世爻，公私皆得如意。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.6","text":"若逢衰墓绝空刑冲克害，动而变凶，日月冲克破者，上下皆连心矣。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.7","text":"有福无财，兄弟交重偏有望。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.8","text":"兄弟乃劫财之神，占财之忌也，财与兄爻同动，必主阻隔破耗，倘若得子孙与兄弟同动，又为可喜，兄动生子，故谓之有望。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.9","text":"财爻兄爻子孙爻俱动于卦中者，更为可喜，其故何也？","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.10","text":"兄动生子，子动生财，其利甚厚且有久远源流长之利益也。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.11","text":"兄与财振，官爻发动亦堪求。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.12","text":"兄爻与财爻同动而官鬼亦动者，亦许得财，以官鬼克制兄爻之故耳。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.13","text":"财福俱无，莫若守株待兔。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.14","text":"财与子孙爻俱不现于卦中，或现于卦中又值休囚空破墓绝，或被刑冲克害，求则无益，不如守株待兔。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.15","text":"觉子曰：倘得日月为财，或伏而旺者，亦可求也。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.16","text":"父兄爻动，无殊缘木求鱼。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.17","text":"父动克福神，兄动克财爻，此二爻动于卦中，凡有所图，水中捞月。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.18","text":"如酉月戊午日占求财得革卦官鬼未土″官鬼未土″父母酉金′父母酉金′兄弟亥水′世兄弟亥水′世兄弟亥水′兄弟亥水′官鬼丑土″官鬼丑土″子孙卯木′应子孙卯木′应断曰：卦中财爻不现，亥水兄爻持世，父临月建生助兄爻，如缘木以求鱼也。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.19","text":"多财反覆，必须墓库以收藏。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.20","text":"卦中财临日月，谓之重叠，若许求谋得意之时，须待财爻入墓之日。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.21","text":"且如水作财神辰日而得，余仿此。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.22","text":"无鬼分争，又怕友重而阻滞。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.23","text":"兄弟乃争夺阻隔耗财之神，宜官鬼动而制之，以免分争之患。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.24","text":"觉子曰：兄爻发动，喜鬼动以制之，倘卦中兄爻安静者，又不宜乎鬼动，反曳财爻之气也。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.25","text":"兄如太过，反不克财。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.26","text":"旧注卦中一位兄爻动者，最为利害，如若兄弟爻多动者，反不劫财。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.27","text":"觉子曰：非也，兄爻多者，待兄爻入墓之日，及克损爻之日，必劫其财，谓之太旺者损之斯成。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.28","text":"世遇兄临，必难求望。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.29","text":"古以卦身临兄爻，难于求望，余因卦身不验，以兄爻持世，难遂图谋。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.30","text":"野鹤曰：全在人立通变，兄弟而持世者，虽则为忌亦有不当忌者。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.31","text":"如未月丁卯日借贷得晋卦官鬼巳火′官鬼巳火′父母未土″父母未土″兄弟酉金′世兄弟酉金′世妻财卯木″妻财卯木″官鬼巳火″官鬼巳火″父母未土″应父母未土″应断曰：虽则兄爻持世无财，但喜卯日即是财星，古以财爻持世冲世者必得，况应爻未土旺而生世，明日必获，果得财，应辰日者，世动逢合之日也。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.32","text":"又如巳月丁巳日占求财得即济变涣卦兄弟子水″应动子孙卯木′官鬼戌土′妻财巳火′世父母申金″官鬼未土″兄弟亥水′世动妻财午火″官鬼丑土″动官鬼辰土′应子孙卯木′动子孙寅木″断曰：若逢久远之财有否，则无财。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.33","text":"若问目下之财，明日戊午必得，其故何也？","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.34","text":"兄临世爻日破月破，不克变出之财，日月俱作财来冲世，只因应爻而逢空，明日冲实，定送财来，果于次日送来。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.35","text":"财来就我终须易，我去寻财必是难。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.36","text":"旧注凡遇财爻生世合世克世持世，皆谓之财来就我，若卦中虽有财爻，不来生合世爻亦非我之财也。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.37","text":"野鹤曰：此说财不生合世爻，非我之财，即如前二卦兄爻持世，何当财来生合，总要断卦之灵机应变，彻悟其理，自然触类旁通，不可拘执。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.38","text":"福变财生利源滚滚。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.39","text":"财得子动生之，如财之有源也，其利丰厚，倘得子动化财，财动化子，皆同此断。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.40","text":"兄伤鬼克，口舌纷纷。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.41","text":"财爻持世，兄爻亦动者，不独劫财，还防伤已，如若鬼动克世者更凶。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.42","text":"觉子曰：黄金策云，兄连鬼克，口舌难逃，谓兄动变鬼冲克世爻者，不独无财，还防口舌，殊不知兄动变鬼，即是兄化回头之克，自顾不暇又焉能冲克世爻耶？","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.43","text":"财局合福德，万倍利源可追。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.44","text":"世与财爻或与子孙爻三合成局，诸占物追财丰。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.45","text":"野鹤曰：须要在局中或是合成子孙财局生世，方为全美，倘如合成父局，劳碌卒苦，合成兄局破耗多端，合成鬼局，口舌灾非，克世者更凶。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.46","text":"岁君逢劫杀，一年生意无聊。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.47","text":"劫杀者乃兄弟之爻也，兄临太岁一年破耗。","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c74.48","text":"增删卜易卷之四野鹤老人著，楚江李坦我鉴定湖南李文辉觉子增删婿阵之吉茂生男茹芝山秀","chapter":"卷之四·求财章第六十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.1","text":"世克官，官生世，须宜谒见；","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.2","text":"财临破，鬼克世，枉费奔驰。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.3","text":"野鹤曰：见贵有两间也，为名者用官，为利者用财，皆宜持世及生合世爻为吉，如逢空破，墓绝及动而变凶者，徒劳奔驰之力耳。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.4","text":"倘若世爻化鬼化克及随墓助伤者，更不宜行，若非到彼之凶，定在中途遇祸，凡谒贵者同断。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.5","text":"世动遇空，身兴遇破O世动化空破者，勿曰不吉，乃应到彼之月日也。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.6","text":"如申月丁卯日占出行谒见贵人得同人子孙戌土′应子孙戌土′应妻财申金′妻财申金′兄弟午火′兄弟午火′官鬼亥水′世官鬼亥水′世子孙丑土″子孙丑土″父母卯木′父母卯木′断曰：官星持世而空，出亥日得见，官府财利如心，果于出空之日见官，财利得意，月建财爻生世之故耳，官世相合，财动相生，财持世，官无缺陷，再得日月照临，彼此缘投有幸。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.7","text":"日月照临者，日月生世生财，或世爻财爻而临日月是也。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.8","text":"为名宜父动，因利忌兄兴O凡与谒贵既得世与官星相合相生，必然得见，若为名利，须宜另占，不可此卦而断之，为名者宜父官两旺，为利者宜财福两旺。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.9","text":"六合六冲须看用，反吟化退枉奔驰O爻逢六合亦要用神旺相，世与财官相合乃为吉兆，卦逢六冲必须用神受克失陷始作凶征O卦得反吟及世动化退多见难于行动，勉强而去，空返而归。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.10","text":"贵人谒贵宜世应以相生，平人见贵宜官贵而相合。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.11","text":"贵人谒贵人，宜于世应相合相生，平人见贵人，宜官贵相合相生及官星持世觉子曰：有心而问见贵求名者，官星持世生世必得官。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.12","text":"有心问谒贵者，官星生世合世而得见，切勿以此得见贵人之官星换作成名而断也。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.13","text":"贵人谒贵，世应若相冲克，财伏而空，去之何益？","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.14","text":"平人见贵，官克世世变鬼变克更凶。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.15","text":"平人见贵，官克世变鬼变克勿去，去则须防不测，财官生世合世为吉。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c75.16","text":"凡出行求财谒贵出行章参看。","chapter":"卷之四·谒贵求财章第六十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c76.1","text":"最重财官两旺，不宜世应皆空。","chapter":"卷之四·为贵人奔走效力财章第七十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c76.2","text":"世遇财应临福，我益他损；","chapter":"卷之四·为贵人奔走效力财章第七十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c76.3","text":"应临官世逢破，他益我损。","chapter":"卷之四·为贵人奔走效力财章第七十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c76.4","text":"兄爻持世，不如闲处安身；","chapter":"卷之四·为贵人奔走效力财章第七十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c76.5","text":"应克世爻，防虑他人反目。","chapter":"卷之四·为贵人奔走效力财章第七十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c76.6","text":"世遇财官临应，无不遂也。","chapter":"卷之四·为贵人奔走效力财章第七十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c76.7","text":"世逢空破墓及动而变凶，皆非吉也。","chapter":"卷之四·为贵人奔走效力财章第七十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c76.8","text":"应克世兄克世，见灾还浅。","chapter":"卷之四·为贵人奔走效力财章第七十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c76.9","text":"鬼克世世化鬼，得病不轻。","chapter":"卷之四·为贵人奔走效力财章第七十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.1","text":"世为已，应为人，大宜相合。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.2","text":"财为本，福为基，最喜同兴。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.3","text":"古法应为伙计，又为下顾之客。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.4","text":"黄金策曰：开行定主有人投。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.5","text":"觉子曰：须在来人之念；","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.6","text":"有心而问伙计，应为伙计，若得世应相生相合，彼此同心。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.7","text":"应生世，他益于我。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.8","text":"世生应，我益于他。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.9","text":"相克相冲而情有变，应爻克世，我被他瞒；","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.10","text":"世克应爻，他从我愿；","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.11","text":"应临元武兄爻，暗中盗骗；","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.12","text":"应临官鬼克世，明降灾非；","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.13","text":"世财应兄，受他之累；","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.14","text":"世财应子，得他之力。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.15","text":"世应空合，彼此有虚诈之心也。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.16","text":"来人之念重在买卖者，须以应爻为下顾之客，应爻生合于世，生客来交成故旧；","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.17","text":"世应相冲相克，熟人终久变成仇。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.18","text":"鬼作灾非须忌动，财为活计畏刑冲。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.19","text":"鬼动招非克世最忌，古云：鬼现爻中见非，日有鬼摇克世灾祸连系，须看鬼值何神克世，须于家室章内详之。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.20","text":"财为资本，忌衰墓空破及动而变凶，或日月刑冲克，更忌世与财空，俱开不成。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.21","text":"鬼兄发动有制何妨，随墓助伤多凶少吉。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.22","text":"鬼动招非，若得子孙制鬼，或日月冲克鬼爻，谓之有制O觉子曰：凡遇兄鬼同动者，不可曰鬼动招非，以鬼能制兄爻，不劫财也。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.23","text":"兄弟又为阴隔破耗之小人，得此鬼动可以制服，独不宜乃为助鬼以伤身也。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.24","text":"卦得反吟多反复O卦得反吟，欲行不行，行而又止。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.25","text":"才开而又剪，剪而又开，倘店开久矣，遇此一定更迁。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.26","text":"冲中变合再重兴O爻逢六合及六冲卦变六合或世财爻子孙共成三合，定是前后重兴，惟六合变冲则不宜也，眼前热闹，终久萧条。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c77.27","text":"合伙不嫌兄弟，蚀本内外无财O世应临兄不吉，兄爻发动不吉，倘若世临兄爻，日月作财星冲克世者，反为吉也O内外无财伏而又空，必然之蚀本，屡验。","chapter":"卷之四·开行开店及各色铺面章第七十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c78.1","text":"官若兴隆，行主可千金之托；","chapter":"卷之四·投行损益章第七十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c78.2","text":"应如空破，牙人无毫忽之能；","chapter":"卷之四·投行损益章第七十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c78.3","text":"官旺应旺，生合世爻，其人可托，如静衰空破，即是奸险小人。","chapter":"卷之四·投行损益章第七十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c78.4","text":"倘若交财，定遭欺骗。","chapter":"卷之四·投行损益章第七十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c78.5","text":"世被应伤，遭他陷害，财逢兄克，虑彼相瞒；","chapter":"卷之四·投行损益章第七十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c78.6","text":"应克世爻，帐目难清，兄克财爻已入套矣。","chapter":"卷之四·投行损益章第七十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c78.7","text":"兄动货难脱卸，子兴物宜交共；","chapter":"卷之四·投行损益章第七十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c78.8","text":"兄雀并摇，难逃口舌，武鬼同发，须虑盗贼；","chapter":"卷之四·投行损益章第七十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.1","text":"财爻衰者须停脱，妻旺当时可脱之；","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.2","text":"积货卖货皆不宜财逢空破及动而变克；","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.3","text":"财衰宜囤，财旺宜脱；","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.4","text":"如春天占得财爻属木，谓之旺，宜速发卖；","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.5","text":"若临金水土者，宜堆积也。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.6","text":"临火为旺，亦不宜堆；","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.7","text":"此论四时之衰旺也。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.8","text":"觉子曰：衰虽可买，须查其根底，虽衰宜有根，将来再发，若无根底，终久难于出脱，不可不知。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.9","text":"如寅月己亥日占收货得颐卦。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.10","text":"兄弟寅木′兄弟寅木′父母子水″父母子水″妻财戌土″世妻财戌土″世妻财辰土″妻财辰土″兄弟寅木″兄弟寅木″父母子水′应父母子水′应古以财爻衰者宜收货，此卦辰戌之财衰而不遇生扶，谓之无根，将来终不得价，不可收买，但求问者不听，后来存货堆积四年，朽坏大半，大亏其本。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.11","text":"货有定时，须凭时令，物无定者，指利而占。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.12","text":"定时者有贵贱之时也，比之麻葛得价于夏令，棉花得价于冬天，又如木料绸缎无定时也。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.13","text":"财化进神不可收积，化退者，其价将落，有货速宜出脱。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.14","text":"兄爻持世，破败之端；","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.15","text":"觉子曰：算甚命，问甚卜，亏人是祸，财将义取者，神告显然。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.16","text":"财之不义者，神不告矣。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.17","text":"财值旺衰墓绝，自有得令之秋，妻逢冲破伏空，岂无乘除之日。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.18","text":"财爻太旺旺者得利于墓库之月，休囚者出脱于生旺之时，入墓必待冲开，逢绝当逢生旺，月破者填实之，被克者冲去克神之秋，伏藏者得价于出现之时，旬空者冲空实空之月，如逢合住亦待冲开。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.19","text":"如子月己丑日占何时得价得归妹之兑父母戌土″应父母未土″世兄弟申金″动兄弟酉金′官鬼午火′子孙亥水′父母丑土″世父母丑土″应妻财卯木′妻财卯木′官鬼巳火′官鬼巳火′断曰：卯木财爻子月生之，财有根蒂，目下不得价者，被申金动而克制，待寅月冲去申金，其价必涨，果于正月勃然大长，此乃财爻被克待冲去克神之月。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.20","text":"遇合者有应动而逢合之月而得价也。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.21","text":"亦有财爻衰静，占时得遇日月生合者，其价目下正及时也。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.22","text":"如寅月己酉日占脱货于何时得贲卦官鬼寅木′官鬼寅木′妻财子水″妻财子水″兄弟戌土″应兄弟戌土″应妻财亥水′妻财亥水′兄弟丑土″兄弟丑土″官鬼卯木′世官鬼卯木′世断曰：亥水财爻，酉日生之，寅月合之，目下正及时也。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.23","text":"但因世爻暗动，身动方可出脱。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.24","text":"彼曰：我闻某处得价，欲移货去卖，不知可否？","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.25","text":"余曰：卦已明现，速宜行之，果去，不数日，得价出脱。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.26","text":"此乃爻逢六合，财逢月合，及时脱货也。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.27","text":"财旺而静或旺而空得今日之日神冲者，其价渐渐涨矣；","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c79.28","text":"倘若静而休囚，日冲为破，勿以此断。","chapter":"卷之四·囤货卖货章第七十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.1","text":"内财衰而外财旺，往他乡。","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.2","text":"外卦财旺生合世爻者，持世者，宜往他乡；","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.3","text":"倘若财不生合世爻及世动化凶者，他乡花如锦，我去不逢春。","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.4","text":"应财外而世财内，须查动静；","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.5","text":"应爻以外财爻持世者，最好收财，必须待应爻发动而与世爻相生相合，不然的话，应财再旺，我也收不到好处。","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.6","text":"六冲须宜别图，六合还宜坐守。","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.7","text":"卦得六冲，虽宜改图，余屡试之财旺者何须更改，财衰者改亦无益。","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.8","text":"野鹤曰，凡得此象，须令本人再占，占问更改何如？","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.9","text":"卦得财世两旺，许之改图，再逢衰者还须耐守。","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.10","text":"卦得六合，亦看财爻衰旺，财持世而动者，不可坐守，衰而静者，守待旺时可也。","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.11","text":"财衰变旺，先屈后生，财旺变衰，先金后土。","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.12","text":"谓财爻动而变也，财衰变旺，目下虽贱，将来必长。","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.13","text":"财旺而变衰绝，如若卖货宜于急卖，倘若收货，切不可收。","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c80.14","text":"买货与卖货相反，财爻旺而可卖，衰者宜买，内卦财衰，宜于外卖，世爻财旺，近地相宜，财化进神，宜往外方发卖，世爻化退，宜回近地出脱。","chapter":"卷之四·卖货宜守宜动章第七十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c81.1","text":"屡次试验都须指明方向才能占卜。","chapter":"卷之四·往何方买卖章第七十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c81.2","text":"如午月戊子日占往楚买豆得临卦子孙酉金″子孙酉金″妻财亥水″应妻财亥水″应兄弟丑土″兄弟丑土″兄弟丑土″兄弟丑土″官鬼卯木′世官鬼卯木′世父母巳火′父母巳火′断：亥水财爻休囚于外，所以楚地豆子必贱，子水日建而生世爻，必能得厚利。","chapter":"卷之四·往何方买卖章第七十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c81.3","text":"但闲间爻兄弟月生日合，耗费的钱一定多。","chapter":"卷之四·往何方买卖章第七十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c81.4","text":"后果中间人作弊，告到官府，误了一个月。","chapter":"卷之四·往何方买卖章第七十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c81.5","text":"幸好到地头上价格上涨，果然得了厚利。","chapter":"卷之四·往何方买卖章第七十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c81.6","text":"此乃指其地而占者无不验也。","chapter":"卷之四·往何方买卖章第七十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c82.1","text":"古以金财而像珠宝玉石，水财以类鱼盐，火财陶冶东品，五谷为土财，青龙水利又兼喜庆之用，白虎金财，丧仪屠宰之物，玄武水利，朱雀火宜，蛇利于出入，勾陈利于农工。","chapter":"卷之四·买何货为吉章第七十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c82.2","text":"如未月戊申日占往粤东探亲可带何货归来得利得旅卦兄弟巳火′兄弟巳火′子孙未土″子孙未土″妻财酉金′应妻财酉金′应妻财申金′妻财申金′兄弟午火″兄弟午火″子孙辰土″世子孙辰土″世断曰爻逢六合，世应相生，此行遂意，如问置实何货，余无此法，不敢相误，但喜既得吉卦，任尔冬天买扇，夏天买毡亦得厚利。","chapter":"卷之四·买何货为吉章第七十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c82.3","text":"后此人买攒香翠毛而归，俱得大利。","chapter":"卷之四·买何货为吉章第七十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c82.4","text":"若执古法断者，此卦酉金为财可买珠宝玉石耶？","chapter":"卷之四·买何货为吉章第七十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c82.5","text":"财临玄武，可买水利鱼盐耶？","chapter":"卷之四·买何货为吉章第七十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c83.1","text":"世逢兄，何须开口，应空破，难遂我心，财若空破，休指望。","chapter":"卷之四·借贷章第七十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c83.2","text":"子兴财发可相求，世应两爻皆不宜月破旬空，兄弟一爻切不可临身及动。","chapter":"卷之四·借贷章第七十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c83.3","text":"如未月丁卯日占借贷得兑之震父母未土″世父母戌土″世兄弟酉金′动兄弟申金″子孙亥水′官鬼午火′父母丑土″应父母辰土″应妻财卯木′动妻财寅木″官鬼巳火′子孙子水′断曰兑卦属金变震卦属木，金克木为财，卯木财爻化退神酉金兄动亦化退神，幸得财临日辰旺而不退，明日辰日合住酉爻必得，果于辰日。","chapter":"卷之四·借贷章第七十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c84.1","text":"兄临世，放则无归。","chapter":"卷之四·放债索债章第七十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c84.2","text":"兄弟爻持世，索财不予。","chapter":"卷之四·放债索债章第七十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c84.3","text":"应鬼克身，防负义。","chapter":"卷之四·放债索债章第七十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c84.4","text":"应财生世，定怀忠。","chapter":"卷之四·放债索债章第七十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c84.5","text":"古以世应同人，放债必然连本折，谓不独世临兄弟忌之，应临兄者亦忌。","chapter":"卷之四·放债索债章第七十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c84.6","text":"官鬼克身，美意终成恶意。","chapter":"卷之四·放债索债章第七十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c85.1","text":"山野兽禽，须寻福德。","chapter":"卷之四·买卖六畜章第七十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c85.2","text":"六畜牛犬，亦看子孙O不拘家禽野兽皆以子孙为用神，末看财爻持世，子动生之，或日月动爻生财或财动化子孙，乃吉象也。","chapter":"卷之四·买卖六畜章第七十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c85.3","text":"不拘买卖畜禽，多多益善，大有利息O子孙持世，财爻合世，亦有利益。","chapter":"卷之四·买卖六畜章第七十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c85.4","text":"独防鬼变子孙，子孙变鬼，父化子，子化父，父兄持世，财临空破，不可行之。","chapter":"卷之四·买卖六畜章第七十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c85.5","text":"如丑月丁卯日买马往南发卖得鼎之大有兄弟巳火′兄弟巳火′应子孙未土″应子孙未土″妻财酉金′妻财酉金′妻财酉金′子孙辰土′世官鬼亥水′世父母寅木′子孙丑土″动官鬼子水′断曰：内卦子孙虽临月建，不宜动而变鬼，外卦未土子孙，又临月破，不宜买，幸而间爻酉财暗动生世，马虽多死，财不致于大耗，后果买马七十余匹，一路多死，仅存二十八匹，幸而得价不然大亏其本。","chapter":"卷之四·买卖六畜章第七十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c86.1","text":"有技力，首重世应，若胜以得财者，兼用财。","chapter":"卷之四·博戏章第八十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c86.2","text":"又世喜临于日月，财宜日月生扶，世爻动而化吉，应带财而生世，皆我胜。","chapter":"卷之四·博戏章第八十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c86.3","text":"世财休囚空破或被刑冲克害，及卦中父动者，多破其财。","chapter":"卷之四·博戏章第八十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c86.4","text":"如巳月戊申日占鹌鹑得渐之巽卦官鬼卯木′应官鬼卯木′世父母巳火′父母巳火′兄弟未土″兄弟未土″子孙申金′世子孙酉金′应父母午火″动妻财亥水′兄弟辰土″兄弟丑土″断曰：子孙持世以临日辰，父爻虽动，亥水制之，独不宜亥为月破，虽可制火，今日巳午时切不可斗。","chapter":"卷之四·博戏章第八十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c86.5","text":"余曰：巳午时午火父母得令，必克子孙，果于早胜，午时又大败破财。","chapter":"卷之四·博戏章第八十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c87.1","text":"请会须宜财旺，更宜世应相生。","chapter":"卷之四·请会摇会章第八十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c87.2","text":"卦遇六冲，财虽旺而不久。","chapter":"卷之四·请会摇会章第八十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c87.3","text":"六冲变合，世应相克亦成。","chapter":"卷之四·请会摇会章第八十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c87.4","text":"六合变冲，有始无终。","chapter":"卷之四·请会摇会章第八十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c87.5","text":"财逢绝破，速宜止之。","chapter":"卷之四·请会摇会章第八十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c87.6","text":"摇会得否，旺财持世必得。","chapter":"卷之四·请会摇会章第八十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c87.7","text":"如占何时可得，财破财空填实之日，财若伏藏，出现之日。","chapter":"卷之四·请会摇会章第八十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c87.8","text":"财太旺者，逢墓之日。","chapter":"卷之四·请会摇会章第八十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c87.9","text":"财衰绝者，逢相生之日。","chapter":"卷之四·请会摇会章第八十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c87.10","text":"倘得财化回头之克及衰静而逢空破又土遇六冲者，会场必散，终无得会之日矣。","chapter":"卷之四·请会摇会章第八十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c88.1","text":"觉子曰：古以青龙财爻为吉，余以此非营生之本，乃丧心之事也。","chapter":"卷之四·行险求财章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c88.2","text":"行此丧心之事，亦敢告之于神耶？","chapter":"卷之四·行险求财章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c88.3","text":"既告之于神而神若以吉凶而报者，乃神之教人而作丧心之事也，可谓之大道之易卦耶？","chapter":"卷之四·行险求财章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c88.4","text":"可谓之伏羲之大神耶？","chapter":"卷之四·行险求财章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c88.5","text":"然不独此，凡占非礼非义之事，不忠不孝之谋，一念之恶，神随知之，即不告之于神，亦遭天谴。","chapter":"卷之四·行险求财章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c88.6","text":"书曰：惠迪吉，从逆凶，何须问卜？","chapter":"卷之四·行险求财章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.1","text":"觉子曰：男家占女，不拘父母亲朋而代占者，无不以财为用。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.2","text":"女家占男，皆以官为用。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.3","text":"用官者，官有生扶。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.4","text":"用财者，财爻旺相，即许婚。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.5","text":"今见古今诸书文，以财旺伤克父母爻，不知宜财之旺而为吉也？","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.6","text":"宜财不旺而为吉也？","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.7","text":"或曰：黄金策云，翁姑不睦，皆因妻位交重。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.8","text":"海底眼曰：财动丧双亲。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.9","text":"易冒亦曰：妻财动父母参商。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.10","text":"俱以财动伤克父母，未说旺也。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.11","text":"余曰：动能伤父母，旺则不能伤耶？","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.12","text":"假令春天占卦，财爻属木，谓之女命旺而可取，但父母爻定然属土，如此当权得令之财爻不克休囚之父母耶？","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.13","text":"殊不知者人言动而不言旺者，正恐后人驳论，所以不言其旺，不得己而言动也，岂知亦被看破。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.14","text":"或曰：据尔之论，何以为法？","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.15","text":"余曰：分占之法也。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.16","text":"先要财官旺相，既得吉卦，再占妨克父母，是其法也。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.17","text":"黄金策专以应为妻位，易冒亦以应为妻，欲其旺相乃为贤良发福之女，又以应为女家父母，谓之应爻旺相，必是富贵之家，若休囚必宅贫寒之宅。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.18","text":"执此论，则旺相贤良之女皆出于富贵之家？","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.19","text":"种种悖谬，余不知何以千百年来竟无一人道破。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.20","text":"男卜女，姻财要旺。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.21","text":"女占男，配鬼宜兴O男家代占女，专以财为用神，以应爻为女家，财宜旺相动而化吉，应爻不宜空破又克世爻O女家代占男，专以官为用神，以应爻为男家，宜官生旺相动而化吉，应爻不宜空破墓绝，不宜克世。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.22","text":"男人自占妻者，亦以财爻为用神，以应爻为女身，财与应爻皆宜生世持世合世，必忌破墓绝空。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.23","text":"财旺生身，应值破空当取，应爻生世，财爻破绝勿求O野鹤曰：财爻应爻同来生合世爻者更吉，大抵以财爻为重，他爻为附和耳。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.24","text":"黄金策曰：应为白发之妻，重应而又重财，谬也。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.25","text":"子月癸酉日自占婚得恒变鼎妻财戌土″应动子孙巳火′官鬼申金″妻财未土″应子孙午火′官鬼酉金′官鬼酉金′世官鬼酉金′父母亥水′父母亥水′世妻财丑土″妻财丑土″断曰：酉官持世，戌土财爻动而生世，又得世应相生，戌土虽值旬空，动不为空，明日出空之日，求之必允，果于次日巳时允婚，夫妻白头相守，儿女成行。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.26","text":"又如寅月丙午日女家代占婚得临之既济卦子孙酉金″妻财子水″应妻财亥水″应动兄弟戌土′兄弟丑土″子孙申金″兄弟丑土″动妻财亥水′世官鬼卯木′世动兄弟丑土″父母巳火′官鬼卯木′觉子曰：女家占男，以官为用，以应爻为男家，此古法也，亦死法也，断卦之时，须要人之活变，未必全得显而易见者，即如此卦，女家占男，卯木旺官持世，其婚必成，而应爻受克，又为男家不允，似此何以决之，要知财官为重，世应为轻，虽是女家占男，亦要财爻不致于换陷，此—卦也，男女二人财被回头克又逢丑土之克，如何能生卯木之官？","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.27","text":"男女不能相合相生，婚虽成终有他变，后果聘定于四月，未及成婚被贼兵劫去，应巳月者亥水逢月破也。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.28","text":"财值休囚破散，终非举案之姻。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.29","text":"官逢衰墓绝空，难遂齐眉之愿。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.30","text":"财爻官爻不宜墓绝空破，又不宜动而化破化散化克化鬼，乃夭折贫寒之合。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.31","text":"男占忌财爻犯之，女占忌官爻犯之O男女自占，世爻忌犯，参商难免。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.32","text":"世爻空亡，动化退，终须失望O动而空者实空之月日必成，静而空者终不成也。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.33","text":"世动化进神，事在必成。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.34","text":"若化退神，终须难就O应爻静而空破及化退神，亦同此推应一何空，财化进，夙有良缘O应空他人不实，若动化退神，必有退悔之心，若得财爻动化进神而生世者，虽见退悔，终是良缘。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.35","text":"若世应动而破者。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.36","text":"亦应实破之时、世应皆空多费力，反吟多变事难成O世应俱空，皆无准实，反吟卦变，反覆难成O野鹤曰：倘得空而逢旺财鬼相生，先虽不允，后终还成。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.37","text":"男占兮兄动，卦中非配偶。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.38","text":"兄爻持世或兄动，乃伤妻阻隔之神，此婚必难成，已成者，遇此不免刑伤。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.39","text":"觉子曰：兄爻持世，若得财爻动来相合，此婚必成。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.40","text":"世兄爻化出财爻，此婚亦能成。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.41","text":"女占兮官爻持世是良缘。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.42","text":"女占男不宜子孙持世发动，子孙乃伤夫之神，未成者不成，已成者伤夫再嫁。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.43","text":"惟官星持世合世生世旺相者，不独姻缘必就，可期举案齐眉。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.44","text":"卦中官鬼重叠亦主再嫁。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.45","text":"财官世应刑世夫妻反目。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.46","text":"如巳月已亥日占夫妻不和将来如好否？","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.47","text":"得需之大过卦妻财子水″兄弟未土″兄弟戌土′子孙酉金′子孙申金″世动妻财亥水′世兄弟辰土′子孙酉金′官鬼寅木′妻财亥水′妻财子水′应动兄弟丑土″应断曰：女占夫，不宜子孙持世，乃克夫之象，幸寅木子水相生，不能伤之，所以不和，今兼应爻为夫，应逢子丑作合，夫已有外遇，水木相生，两人情密。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.48","text":"余曰：两人不是姻缘，虽则不能死别，必有生离，果于次年寅月休妻，此人六月再取彼妇，应寅月者，夫临寅木而冲世也，应六月者未土冲开初爻丑土，子水来生其寅木也。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.49","text":"旺相爻逢六合彼此同心O爻逢六合占婚最宜，更要财官旺相为吉，男忌财逢破墓，女防官位克绝，六冲变六合者更吉，眼下不允，日后必成。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.50","text":"已成婚不和睦者，终究和美。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.51","text":"忌六冲，卦无财官，主婚不成，勉强成之，若非死别，定是生离。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.52","text":"六合变六冲，虽许允后必更张，已成者终须折枕。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.53","text":"占用咸临节泰，忌逢暌革解离O觉子曰：易冒有云，卦得咸临节泰，若不遇合冲变，虽财官衰陷随墓助伤，皆不为凶。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.54","text":"暌革解离，则为凶兆，虽用神全备而化合，亦不为吉，此言用神不腾于卦，验也。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.55","text":"财化财未必婚姻两度，鬼化鬼难曰相守百年。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.56","text":"黄金策曰：财爻重叠，重作新人，余屡试之，男家占女家，财爻重叠旺相生合世爻者，多主贤妻美妾，财化财，或应双娶、或应婢妾同来、或应妻妾之多、或应收妆奁甚厚，惟忌爻中兄动及日月冲克财爻，花烛重重亦不免耳。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.57","text":"兄临元武，防劫骗。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.58","text":"鬼临白虎，遇凶丧O兄鬼动临元武，防局中奸诈骗财，纵使世应相生，财官无害，必须大费，鬼临虎动或不来过门或遇门不久，必见丧事。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.59","text":"应财世鬼，夫唱妇随。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.60","text":"应鬼世财，夫权妻夺O世持鬼应持财，谓之阴阳得位，必然鸾凤和鸣。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c89.61","text":"鬼临应财持世，牡鸡司晨，妻夺夫权，惟赘婿得之反吉。","chapter":"卷之四·婚姻章第八十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c90.1","text":"子孙旺相或休囚而动及动而化吉，皆主有子。","chapter":"卷之四·此婚子嗣有无章第八十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c90.2","text":"子化进神化回头生，有子必多。","chapter":"卷之四·此婚子嗣有无章第八十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c90.3","text":"如逢子孙墓绝动而变鬼鬼变子孙父化子子化父父动克子，皆因我命无儿，不成此婚亦无子也，惟多积阴德以培之。","chapter":"卷之四·此婚子嗣有无章第八十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c90.4","text":"如申月丁丑日因有妾多占何命者有子得革之夬卦官鬼未土″官鬼未土″父母酉金′父母酉金′世兄弟亥水′世兄弟亥水′兄弟亥水′官鬼辰土′官鬼丑土″动子孙寅木′应子孙卯木′应兄弟子水′断曰：卯木子孙绝于申月，鬼变子孙又逢月破，公命无子，与女命何干？","chapter":"卷之四·此婚子嗣有无章第八十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c90.5","text":"即出八字看之，甲寅甲戌甲子戊辰，余曰：八字虽有纯阳包阴，兵权显赫，但嫌并头重重叠叠克罡，亦主无子。","chapter":"卷之四·此婚子嗣有无章第八十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c90.6","text":"公曰：有何法耶？","chapter":"卷之四·此婚子嗣有无章第八十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c90.7","text":"余曰：多积阴德以培之。","chapter":"卷之四·此婚子嗣有无章第八十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c90.8","text":"公曰：不孝有三，无后为大。","chapter":"卷之四·此婚子嗣有无章第八十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c90.9","text":"嗣后施济贫寒，全人夫妇，修桥砌路，施药施棺，连生二子，临终嘱其子曰：我非阴功，不能有尔，尔皆成人，多宜积德。","chapter":"卷之四·此婚子嗣有无章第八十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c91.1","text":"专以父母为用神，父母爻或旺或衰，皆不忌也。","chapter":"卷之四·此婚有宜于父母否章第八十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c91.2","text":"所忌者财爻发动，必此婚之有妨。","chapter":"卷之四·此婚有宜于父母否章第八十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c91.3","text":"如财化父母，父母动化墓绝空破及回头克，动而破散或日月克父母，乃桑榆暮景之秋，不成此婚亦难免耳。","chapter":"卷之四·此婚有宜于父母否章第八十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c92.1","text":"为子嗣故，以子孙为用神，与前段同断，否则专看财爻，亦与占子同断o占配仆，以财爻为用，财爻持世，或动而生合世爻，动而化进、化生、化财，皆得忠诚效力；","chapter":"卷之四·纳宠章第八十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c92.2","text":"散破空绝，非懒惰即疾病。","chapter":"卷之四·纳宠章第八十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c92.3","text":"财爻克世冲世，负义忘恩之徒也。","chapter":"卷之四·纳宠章第八十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c92.4","text":"财化鬼化绝化墓化克及鬼化财爻，贫穷寿夭。","chapter":"卷之四·纳宠章第八十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c93.1","text":"防患者，用子孙。","chapter":"卷之四·取离妇跳娼妇章第八十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c93.2","text":"子孙持世，子孙发动，皆无忧也。","chapter":"卷之四·取离妇跳娼妇章第八十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c93.3","text":"财爻持世，子动相生者，更吉。","chapter":"卷之四·取离妇跳娼妇章第八十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c93.4","text":"鬼兄克世随助伤，鬼爻持世，婚姻虽就，病患随之。","chapter":"卷之四·取离妇跳娼妇章第八十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c93.5","text":"财克世，兄持世，落人之局，必人财两失。","chapter":"卷之四·取离妇跳娼妇章第八十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c93.6","text":"防拦阻者，鬼动有祸，兄爻持世，到底难成，财动相生，不谋而就，六冲变冲为凶。","chapter":"卷之四·取离妇跳娼妇章第八十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c93.7","text":"六合变冲，成而不久。","chapter":"卷之四·取离妇跳娼妇章第八十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c93.8","text":"六冲变合，终必有成。","chapter":"卷之四·取离妇跳娼妇章第八十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c93.9","text":"强夺婚、遂私约，非祥非义，勿告于神。","chapter":"卷之四·取离妇跳娼妇章第八十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c93.10","text":"出妾休妻，原非所欲，有不得己而出者，必去难留。","chapter":"卷之四·取离妇跳娼妇章第八十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.1","text":"卜胎之虚实，占孕之安危，问产妇之吉凶，测胎中之男女，各宜分占，亲占代占，皆用子孙，惟子占母孕，以弟兄爻为用神也。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.2","text":"福神旺相遇生扶，麟捶兆瑞。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.3","text":"子孙休囚逢破衰，泡孕空虚O子孙临日月、或遇日月动爻生扶、或动而化吉，皆许成孕。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.4","text":"若临空破衰绝、或被刑冲克害、或动而变鬼化绝化破、或鬼变子、父变子、子化父，水泡空灯，惟动而空者不防。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.5","text":"子化子双生有准O子动化子孙、或卦中子孙动、或已有旺相之子孙动者他爻又变出旺之子孙，皆主双胎。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.6","text":"卜筮元龟云：子孙两旺，定是双胎O觉子曰：两动两旺者，此断是也。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.7","text":"内有一衰，一死一生，一阴一阳者一女一男。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.8","text":"两现一不动者，非也。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.9","text":"阳变阴男女可辨。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.10","text":"六爻静，先看卦包阴包阳，生女阳包阴，生男阴包阳，坎卦、大过、小过、咸、恒卦是也。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.11","text":"阳包阴，离卦、中孚、颐、损卦是也，其余非也。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.12","text":"六爻既静若无包，须看子孙值阳为男，值阴为女O卦有动爻虽有子包而不用，神兆机于动，先看动爻。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.13","text":"一爻动者，阳动为女，阴动为男；","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.14","text":"两爻动者，看上爻；","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.15","text":"若有三爻发动，看中爻；","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.16","text":"卦中多动者，来心不诚，改日再占。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.17","text":"即刻连占亦不验也。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.18","text":"如辰月戊辰日占孕男女得小过之豫卦父母戌土″父母戌土″兄弟申金″兄弟申金″官鬼午火′世官鬼午火′应兄弟申金′动妻财卯木″官鬼午火″官鬼巳火″父母辰土″应父母未土″世余曰：尔之来意，还是问妻孕平安？","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.19","text":"还是问孕之男女？","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.20","text":"彼曰：两事俱问。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.21","text":"余曰：日后须宜分占，不可同问。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.22","text":"幸此卦两事俱现，兄爻虽动，不克变出之财爻，草正坐草无虞，卦中阳动变阴，必然主女。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.23","text":"彼曰：小过卦谓之阴包阳，如何生女？","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.24","text":"余曰：神兆机于动，先重动爻。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.25","text":"果于壬申日生女，产母平安。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c94.26","text":"觉子曰：占妻平安及占男女，原宜分占，彼若闲时而问兼问者，还可同断，若在临产危急时而问者，切不可以男女而断。","chapter":"卷之四·胎孕章第八十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.1","text":"坐草临盆嫌鬼动，胎前产后忌兄摇。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.2","text":"财临绝破妻难保，鬼化妻财命不牢。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.3","text":"问产妇夫占代占，皆以财为用神。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.4","text":"虽则不宜鬼动，倘若兄动克财，又宜鬼动制服兄爻。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.5","text":"不宜财变鬼、鬼变财、兄化财、财化兄，及妻逢月破休囚破绝化墓化绝，或日月冲克，皆为凶兆。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.6","text":"觉子曰：问胎产妇，虽宜分占，另有不待分占，而卦中先现者，须宜留心。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.7","text":"如子月乙亥日占妻孕平安否得丰之小过卦官鬼戌土″官鬼戌土″父母申金″世父母申金″妻财午火′妻财午火′世兄弟亥水′父母申金′官鬼丑土″应妻财午火″子孙卯木′动官鬼辰土″应断曰：午火妻财临月破，又被亥日克之，冬天之火囚被克，全无生扶，命之难保。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.8","text":"彼曰：卯木子孙，动而生火，何谓全无生扶？","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.9","text":"余曰：卯木子孙动而变鬼，神曰：母子皆丧。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.10","text":"非生火之卯木也。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.11","text":"断卦者须以知机，会神之意。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.12","text":"彼又曰：财虽不旺，卯木子孙得子月亥日以生之，何谓子亦难保。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.13","text":"余曰：变鬼之子孙，纵临日月亦无益矣。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.14","text":"卦得六冲，子旺财强终是喜。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c95.15","text":"爻逢六合，财空子破亦为忧。","chapter":"卷之四·问产妇安否章第八十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c96.1","text":"产期有远近之分，远则应月，近则应日。","chapter":"卷之四·产期章第八十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c96.2","text":"子孙动者逢合逢值，静者逢值逢冲，空者冲空实空之日，破者实破逢合之期。","chapter":"卷之四·产期章第八十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c96.3","text":"白虎兄弟而动，值日而生。","chapter":"卷之四·产期章第八十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c96.4","text":"子孙临绝，待生旺之日。","chapter":"卷之四·产期章第八十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c96.5","text":"又有子遇长生胎养之日。","chapter":"卷之四·产期章第八十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c96.6","text":"伏藏者出现之日而生也。","chapter":"卷之四·产期章第八十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.1","text":"人为利名，奔驰道路，风波不测。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.2","text":"占卜应以世爻为先，旺相宜行，空亡宜止。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.3","text":"世为出行人，生旺有气则吉，动而化吉，及化子孙者更吉。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.4","text":"如若休囚空破，动而化凶者不宜行也。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.5","text":"应为地头，又为傍倚人，他若空破墓绝或动而化绝化回头克者，去之无益。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.6","text":"世伤应位，不拘远近相宜。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.7","text":"应克世爻，公私皆主不利。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.8","text":"我去克他，所向通达。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.9","text":"应来刑冲克世，不可行之。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.10","text":"八纯乱动，在处皆凶。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.11","text":"两间齐空，独行则吉。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.12","text":"六冲卦及动而变冲，世爻休囚被克者，终去不成，有始无终，去亦诸般不就O两间爻者，乃同行附载之人，动而克世，必遭其害，动临兄爻，破我之财，生合我者为吉，倘两间齐空，若非中途梗阻，定然无伴孤行。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.13","text":"静遇日冲必动，动逢合住而留O世爻暗动者必去，世爻旺静逢冲之日必去，世爻动而化合或被日月动爻合者，必有事故，阻滞不行。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.14","text":"觉子曰：余常得验，亦有应在冲开之日而行。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.15","text":"官鬼交重灾祸重O武鬼动忧盗贼，雀鬼发防讼非，虎鬼疾病缠绵，蛇鬼风波警验，勾陈鬼动，事有勾连。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.16","text":"鬼动逢龙，戒于嫖赌。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.17","text":"鬼发震乾车马患，鬼发兑坎虑风波。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.18","text":"坤艮之鬼，山间道野逢殃。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.19","text":"巽离之官，炎厂林窖罹难。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.20","text":"余在趋避章中详之。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.21","text":"福神发动患殃消O出行得子孙发动，子孙持世、世化子孙，程途万里，百祸潜消，子孙克世者亦吉。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.22","text":"父克世爻，风雨舟车行李O父母持世而动或被父动冲克世爻，余得验者，有应舟车行李之累，有应风雨淋漓。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.23","text":"世爻旺者无妨，最怕休囚而为凶也。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.24","text":"兄冲世位，花月散耗灾非O财爻持世，兄爻冲克，有应在花朝月夕，无端浪费，有应小辈明欺暗骗，致成灾非，破耗百出。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.25","text":"反吟化退中途返，六冲随墓始终凶O卦得伏吟世动者，冲开之日月成行。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.26","text":"卦得反吟可到中途亦返，世逢冲克大凶，六冲卦世静世空必不能行。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.27","text":"随鬼入墓，世若休囚，不返之兆。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c97.28","text":"六合化冲不吉，六冲化合方亨O六合卦变六冲，及卦变克绝者，坐家亦恐凶危。","chapter":"卷之四·出行章第九十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c98.1","text":"登舟问何日至，世爻发动，合日值日而到。","chapter":"卷之四·舟行章第九十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c98.2","text":"若得子孙持世及子孙他爻发动者，值日而到。","chapter":"卷之四·舟行章第九十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c98.3","text":"世化退及反吟卦，中途而返O问舟行平安否？","chapter":"卷之四·舟行章第九十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c98.4","text":"子孙持世克世生世合世，一路平安。","chapter":"卷之四·舟行章第九十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c98.5","text":"官鬼持世忧郁惊恐，官鬼冲克世爻灾非必见，兄动破财O风阻者勿以兄弟为风云，乃以子孙为顺风，动而逢合逢值，静而逢冲之日，空逢冲实之日，与天时章阴晴同断。","chapter":"卷之四·舟行章第九十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c99.1","text":"同行共处应为尊，南路同舟一样论。","chapter":"卷之四·同舟共行章第九十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c99.2","text":"应伤世位遭他害，墓绝空破见吾恩，只宜生合相扶助，永赖维持如至亲。","chapter":"卷之四·同舟共行章第九十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c99.3","text":"三合同途皆遂意，六冲半路便灰心。","chapter":"卷之四·同舟共行章第九十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c99.4","text":"起居为害摇兄鬼，水睦清平动子孙。","chapter":"卷之四·同舟共行章第九十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c99.5","text":"占他人以应为用，占亲戚必看用神，不宜兄鬼动而克世，最宜相合相生。","chapter":"卷之四·同舟共行章第九十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.1","text":"问行人之归期，有远有近，远则应月，近则应日，亦有去久，若在日下当归，又可以日断也。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.2","text":"问行人之否泰，另占一卦，不可一卦而兼断也。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.3","text":"世克用兮人未动，用爻克世必然归O占亲人在用神章中求之，疏者以应爻为用神，世克用神且无归志，用神克世近日回家。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.4","text":"墓绝空破，归信杳然，明摇暗动，归鞭发矣。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.5","text":"伏藏才出现之日，动而逢合之日，动化进神不返，用神化退而归，动逢合有事阻隔，动化鬼在外危灾，最怕动而化克，还防卦变反吟。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.6","text":"世爻空者行人即至，用神静逢休囚空破者且不思归，动空旺空者实空冲空之月日必归，惟恐卦变克绝及反吟卦，用神被克被冲者，皆难望其归也。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.7","text":"用神三合，冲开之月日而来。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.8","text":"卦逢六冲，行人无定而不返。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.9","text":"用爻墓者开墓之日，用爻无病可断归期，用爻有病在外不安。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.10","text":"野鹤曰：用神墓绝空破受伤，谓之有病。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.11","text":"来人问行人在外平安否，须看有病无病。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.12","text":"若问归期，只可看卦象来与不来而断也。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.13","text":"如酉月戊申日占母在外何时来得旅之艮卦兄弟巳火′父母寅木′世子孙未土″官鬼子水″妻财酉金′应动子孙戌土″妻财申金′妻财申金′应兄弟午火″兄弟午火″子孙辰土″世子孙辰土″此卦若问父母平安否，父母卯木日月动爻冲克，必不安矣。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.14","text":"今问其来否，不以此断，只可断用神伏藏也，克而不来，六合冲亦不来，后果在外平安。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.15","text":"又如亥月甲子日占仆人何日回得革之夬卦官鬼未土″官鬼未土″父母酉金′父母酉金′世兄弟亥水′世兄弟亥水′兄弟亥水′官鬼辰土′官鬼丑土″动子孙寅木′应子孙卯木′应兄弟子水′此卦若问仆人在外之吉凶者，必不归矣，何也？","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.16","text":"午火财爻伏而破日月之克，今问何日可到，不以此断，世空者速至，此人来矣，巳日必到，应巳日者，冲空之日也，巳火又是财爻，果于巳日到。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.17","text":"未月戊戌日占伯何日来得屯之随卦兄弟子水″官鬼未土″应官鬼戌土′应父母酉金′父母申金″动兄弟亥水′官鬼辰土″官鬼辰土″世子孙寅木″世子孙寅木″兄弟子水′兄弟子水′父母为用神，克世者速至，七月必到，后于亥月方到，应亥月者父母化出之爻也。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.18","text":"如丑月庚午日占父远去何日回得履卦兄弟戌土′兄弟戌土′子孙申金′世子孙申金′世父母午火′父母午火′兄弟丑土″兄弟丑土″官鬼卯木′应官鬼卯木′应父母巳火′父母巳火′断曰：今日乃是午日，午火父爻克世爻，今日必到。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.19","text":"寅月亥日占主人何时回，以父母为用。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.20","text":"得大畜之益官鬼寅木′官鬼卯木′应妻财子水″应动父母巳火′兄弟戌土″兄弟未土″兄弟辰土′动兄弟辰土″世官鬼寅木′世动官鬼寅木″妻财子水′妻财子水′断曰：子水财爻化出巳火父爻，动爻不克变爻，巳日必到，果于巳日到。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.21","text":"亥月甲子日占夫在外还往他省去否得大壮之大过兄弟戌土″兄弟未土″子孙申金″动子孙酉金′父母午火′世妻财亥水′世兄弟辰土′子孙酉金′官鬼寅木′妻财亥水′妻财子水′应动兄弟丑土″应断曰：妻占夫官为用神，申动克之，寅木夫爻受克不往他处去矣。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.22","text":"彼曰：何以其回也。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.23","text":"余曰：日月生扶，夫生世爻必有归志。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.24","text":"问曰：何日可到。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.25","text":"余曰：巳日必到，应巳日者，合住申金之日也。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.26","text":"或曰：用爻有病，莫问归期，此卦申金化进神以克寅木，如何许回？","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.27","text":"余曰：彼问夫之平安，即以不利断之，今加往他处去否，夫爻受到制，不往他乡，断卦者各有取用耳。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c100.28","text":"余于戌月丙戌日由江右登舟占一路平安否得蛊之巽兄弟寅木′应兄弟卯木′世父母子水″动子孙巳火′妻财戌土″妻财未土″官鬼酉金′世官鬼酉金′应父母亥水′父母亥水′妻财丑土″妻财丑土″余疑酉金鬼爻持世，一路忧疑之象，初不知风阻之说也，及至戊子日，风雨大作，舟泊南康，始悟此卦，子水父动，子日之风雨也，见其化出巳火子孙，即知巳日方晴，果泊五日，巳日天晴得风顺矣，自此始悟子孙乃行舟之顺风也。","chapter":"卷之四·行人章第九十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c101.1","text":"忧虑官可邦，喜官居空破，最宜子动，子若持世无非，鬼雀同兴口舌不免，蛇鬼克世灾患相侵，武鬼必凶盗贼阴人，白虎鬼定有伤痕见血，世动克应我兴词，应克世爻他有讼。","chapter":"卷之四·防非避讼章第九十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c101.2","text":"子孙动子孙持世必不成非，鬼持世鬼克世应动克世定然成讼。","chapter":"卷之四·防非避讼章第九十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c102.1","text":"彼此相争寻世应，不宜冲克喜相生，日月克身我必受辱，动爻克应他必遭刑，应克世者他胜，世克应者我赢，世空破世动化退我心怯焉，应动应旺化进神他得势耳，卦遇六冲必散，卦逢六合必成O亦不离乎子孙爻，子孙发动子孙持世争不成，日月动爻宜于克应不宜克世，世宜旺动克应，及动而化吉官事必赢。","chapter":"卷之四·斗殴争竞章第九十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c103.1","text":"官父同兴公庭有理，父官克世受屈含冤O世化退神世空世破，卦变六冲，世被刑冲，终不成讼。","chapter":"卷之四·兴词举讼章第九十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c103.2","text":"财与子孙发动克破文书官鬼亦不成之。","chapter":"卷之四·兴词举讼章第九十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c104.1","text":"福宜旺相最忌官兴O子孙持世子孙发动已到法场终必赦免。","chapter":"卷之四·已定重罪章第九十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c104.2","text":"官鬼克世或官鬼持世，又被日月动爻冲克或世动化凶，虽定轻罪疑改重。","chapter":"卷之四·已定重罪章第九十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.1","text":"野鹤曰：人有七情，致生百病，急于问卜，以慰其心，奈何卜筮诸书舛错悖谬，奈人反无定见，既取用卦身世身，兼用本命，又有不看身命用神，单看卦验，卦得明夷、大过、观，贲、蛊、夬、丰、同人、大畜、需卦，断之必死。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.2","text":"又云：死气丧门临本命，早备衾棺。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.3","text":"又云：蛇动主死，虎动主丧，以星煞六神而断生死，独不思假使恶煞凶神临身守舍，若得用神二身旺相，断之生耶？","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.4","text":"余试多年或生或死，全凭用神，余皆不验，人有不看用神而断生死者，卦变为六冲是也。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.5","text":"六冲变冲，久病难于调治O久病者，卦逢六冲，卦变六冲，不论用神之衰旺，乃不治之疾也，近病逢之，不药而愈。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.6","text":"卦变克新病亦主危亡O卦变者，亦六冲而变六冲，何其近病亦危？","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.7","text":"乃因化回头之克也。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.8","text":"如巽木变乾金，艮坤化震巽，皆谓之回头相克，虽非墓绝，亦主危亡，若化比和、化克去、及化回头相生，近病吉久病凶，六冲之故耳O除此冲克之外，必看用神。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.9","text":"用遇旬空，近病何须忧虑，用逢月破，久病难许安宁O自占病，世为用神，占父母弟兄取用神者皆在用神章内详之，用神动静而值旬空，及化空者，若无日月动爻冲克，许之冲空实空之日即愈，倘逢冲克病虽重而不死，若值月破须看用神之衰旺，旺则愈于实破之日及出月而愈，衰而受克者必危。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.10","text":"久病用神值旬空月破者，即使用神旺相，亦无法以治之O野鹤曰：海底眼黄金策皆云，主空无救中殂，不分近病久病，非经验也。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.11","text":"觉子曰：余得验者，近病值旬空，若逢三合六合者必成久病而终。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.12","text":"用化鬼鬼化用慎防不测，忌化用用化忌最难调医O自占病，不宜世爻变鬼及化回头克，占兄弟妻子皆不宜鬼变弟兄妻子及弟兄妻子而变鬼，又不宜兄变财财化兄，父化子子化父。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.13","text":"野鹤曰：鬼乃父母之元神，父动化鬼乃为化生，轻病者即愈，久病者鬼化父，父化鬼皆主危亡，或曰：用神化鬼即为凶兆，假使又值旬空，近病者何以断之？","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.14","text":"余曰：曾有占验请试详申月庚寅日占子近病得恒之解卦妻财戌土″应妻财戌土″官鬼申金″官鬼申金″应子孙午火′子孙午火′官鬼酉金′世动子孙午火″父母亥水′妻财辰土′世妻财丑土″兄弟寅木″断曰：鬼变子孙，夭折之兆，幸得子孙值旬空，近病即愈，恐其难过午年，果在出空之日而愈，辰年占卦至午年出花而死。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.15","text":"动墓绝化墓绝须忌生旺，日月克动爻克最怕休囚。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.16","text":"用神逢墓绝及动而化墓化绝全看衰旺，用神旺者何须虑，用神衰者实堪优。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.17","text":"日月动爻冲克者亦须看用神旺衰，旺相者冲去克神之日而愈，休囚者生助克神之日而危。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.18","text":"散破无援脱气，忌摇元动仇兴O用神临散遇破乃全无生扶，或脱气休囚者，皆无根蒂，少吉多凶，忌神动克用神，若有元神发动许之有救，只恐仇神又动，当许凶危，须于元神章内详之。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.19","text":"世持鬼病虽轻而难疗。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.20","text":"此有两说，自占病，官鬼持世，其病难痊，虽得子动克去身边之鬼，目下虽愈，终不断根，不然迟迟又生他病，此之谓病不离身，身不离药，世临官鬼以临帝旺长生，必得久远疾病。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.21","text":"代占六亲之病，若见官鬼持世，为忧疑之状，惟喜子孙发动克去我之忧疑，即使用神衰弱，管许平安。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.22","text":"如申月壬子日占子病得遁卦父母戌土′父母戌土′兄弟申金′应兄弟申金′应官鬼午火′官鬼午火′兄弟申金′兄弟申金′官鬼午火″世官鬼午火″世父母辰土″父母辰土″断曰：令郎今日即愈。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.23","text":"余曰：官鬼持世，忧也，今日子日冲去忧心，管许立愈，果於本日愈。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.24","text":"觉子曰：如占自身及兄弟妻儿者，此法是也，若占父母之灾，官鬼为父母之元神，岂宜子动而伤耶？","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.25","text":"妻占夫宜鬼为用神，又岂子动以伤官耶？","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.26","text":"不惟不能解忧反添优也。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.27","text":"身临福德，势虽险以堪医。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.28","text":"亦有两说，自占病子孙持世不药而痊，临应破者空实破之日而愈。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.29","text":"代占六亲之病不必看用神之衰旺，即知其安。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.30","text":"子孙乃喜悦之神，只要旺相，若动於卦中者亦为吉庆。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.31","text":"鬼化长生，忌化进，须虑添灾。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.32","text":"鬼爻发动病势必重，若长生，病势必轻，克用神者为忌神，若动化进神，亦同此意。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.33","text":"忌神化退，其疾病渐减。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.34","text":"觉子曰：鬼为父母之元神，占父母者，其病即愈。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.35","text":"亦为女人占夫之用神，占夫者亦即愈。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.36","text":"福摇化克卦反吟，病必反复。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.37","text":"o自占病及占兄弟病，得子孙动者，制服官鬼，其病即愈。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.38","text":"倘子孙动而化克，即使病愈后还发，反复之象，卦得反吟者亦同上意。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.39","text":"用绝逢生危而有救，主人得助，重亦何妨。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.40","text":"用爻受刑冲克害，但得日月动爻有一而生扶者，乃为绝处逢生，临危有救。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.41","text":"用神不宜太弱，弱则体虚，卒难痊愈，但得生扶拱合，虽得重病亦不至死，觉子曰：用神亦不宜於太旺，易理贵乎中庸，过犹不及。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.42","text":"用临日月休寻伏。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.43","text":"凡用神不现再占。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c105.44","text":"卦前卷伏神章中注解明白。","chapter":"卷之四·疾病章第九十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.1","text":"平时而问男女何时出花鬼，鬼爻为用，鬼爻静者逢值逢冲，鬼爻动者逢值逢合，鬼衰逢生旺之年，鬼旺鬼多逢墓库之岁。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.2","text":"鬼空鬼破填实之时，鬼若伏藏出现之岁。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.3","text":"出花而问吉凶，卦忌六冲兼忌子孙化鬼及鬼化子孙，父化子孙、子孙化父、子孙伏而空破，皆非吉兆。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.4","text":"问花之密者，鬼动而临日月及动爻生扶，花必稠密，如值空破休囚墓绝，痘必来朗。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.5","text":"鬼动乾宫，多生头上。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.6","text":"鬼摇坤卦，腹上多丛。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.7","text":"艮宫多於手，兑宫多於口，坎离上身，震巽下身。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.8","text":"火鬼其色红紫，金鬼其色虚白，水鬼颂防痘，木鬼杂细，土鬼肿大。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.9","text":"以上四条，分占四卦，不可一卦而断之，大抵全在子孙爻也。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.10","text":"子孙临日月及日月动爻相生，动而化吉不受刑伤冲克，爻不乱动，花中密以全生，痘虽暗仍收功。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.11","text":"病源章第一百零一火属心经，发热咽乾口燥。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.12","text":"水归肾部，恶寒盗汁遗精。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.13","text":"金肺、木肝、土为病归脾胃。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.14","text":"衰轻旺重，动则牵连身躯，腾蛇心惊，青龙则酒色过度，勾陈肿胀，朱雀则言语颠狂，白虎有损伤，女子则血崩血晕。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.15","text":"元武忧郁，男人则阴症临虚。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.16","text":"野鹤曰：此乃黄金策占疾病之首论也，余以为之撞门槌，对俗人而言，不得不以此而断之。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.17","text":"若知分占之法，另占一卦以定吉凶，庶有后验，若即以此卦，兼断其生死者，如若有灵，吾不信也。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.18","text":"要知来人而问病，有何所犯？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.19","text":"我且以发寒发热而妄猜，而病人不得趋避之旨，问卦何益？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.20","text":"今见此章，单言病症，并不言及何法治之，如果心经发热，来人岂不知也？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.21","text":"请问治其热者是何法也？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.22","text":"无益之论，故书删之。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.23","text":"余尝以来人问病，先命占其吉凶，卦得吉者，许之调理即愈，不必服药求神，卦得凶者，命之延医，卦得鬼动克用神者，命之再占，或占家宅、或占坟墓、务必求其是何所犯？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.24","text":"庶不负来人之问也。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.25","text":"鬼神章一百二凡占鬼神，卦中鬼值休囚及空破墓绝，非鬼神之害也。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.26","text":"官鬼属金旺相者，武神及西方之神。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.27","text":"休囚者，刀剑身之鬼。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.28","text":"鬼临木者，旺则文神及东方之神。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.29","text":"衰则倚草附木之妖，或是刑杖悬梁之鬼。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.30","text":"水为河海及北方之神，休囚者池井江湖水死之鬼。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.31","text":"火鬼火神及雷公电母窑之神，休囚者汤火焚烧之鬼也。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.32","text":"土鬼土神及中央之朝及掌管山川社稷之神，休囚者墙倒屋塌土死之鬼。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.33","text":"古以金木水火土各有其神，即如金官者，谓之天将辟公金刚伍公岳公等神，余以为非武神者不可，书断之神也有敕卦者有来卦者，各方土俗不同，书之未载者更多，何得各朝而祭之？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.34","text":"须问病人或于某武神朝中许愿信而未还？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.35","text":"或于何朝城秽污作践？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.36","text":"心有所疑者，指其神而占之，鬼爻或旺或动，是此神也。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.37","text":"如不上卦，再占他处之神可也。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.38","text":"鬼值木火水土者，皆用此法，得罪於正神者，香花纸马祭之。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.39","text":"勾惹邪祟之鬼者，用浆纸钱夜静之时金鬼者向西送之，水鬼者向北送之，余仿此。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.40","text":"野鹤曰：凡得时灾瘟癖，照此法而祭送者，余屡验之。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.41","text":"倘系疯痨气蛊，既失调於前，酒色伤身，又失慎重于后，与鬼神何干？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.42","text":"发之送之皆无益矣，惟节饱食、远色欲、息气养神，其病自减。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.43","text":"余游遍江湖，曾至黔蜀粤，见其病不服药，专祭祀鬼神，先用三牲五牲，后至杀牛宰马一次不愈，甚至二三十次，因病致穷者多矣，殊不知害他命而救命，其罪愈彰，所以屡见割性命之多者，终不能救其死，可不戒与？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.44","text":"今下路读书人亦信此邪神者，余实不解。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.45","text":"神农当百草遗救生灵，未闻有何圣贤，教人宰牲命以救命也。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.46","text":"李我平日：易冒以鬼临金者为关公，岳王补遗，又以青龙神为寺亭候第，不知关公之前，金鬼与青龙，是何神也？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.47","text":"又曰祭者降之以福，不祭者降灾，岂非邪神与？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.48","text":"正直之神岂能为此事？","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c106.49","text":"此书前后无一不合於理，独此疾病章中，亦言鬼神之事，余实不服，因今人问病，开口先问鬼神，不得不从俗耳，智者察之。","chapter":"卷之四·痘疹章第一百","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.1","text":"野鹤曰：有人而问余日，问卜以求神延医而服药，有是理乎？","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.2","text":"余曰：若无此理，伏羲书卦，神农尝药，作何事耶？","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.3","text":"彼曰：然则又有不能救者，何也？","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.4","text":"余曰：有根者可以救之，无根者则不能也。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.5","text":"人之星辰过宫或是交运脱运，谓之移花接木之年，移其有根之花木者，上则遮盖，下宜浇溉则活矣，不洗不溉，见日则枯，服药求神者即此意也。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.6","text":"若使无根之木无蒂之花，虽浇虽盖，亦无用矣。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.7","text":"自占求医，应爻为医人，代六亲而求医者，亦以应为医人。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.8","text":"鬼作忧神休妄动，福为喜悦而生扶。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.9","text":"自占代占，鬼虽忧疑之神也，若持世及动于卦中，得子孙动而制之，此医可请，手到成功。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.10","text":"若得子孙临应爻者乃明医也，其故何也？","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.11","text":"子孙乃制鬼之神，非真正能制法魔之鬼也，乃先去忧神，我无优也。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.12","text":"应作医人，不宜空破墓绝。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.13","text":"应爻空破墓绝休囚衰弱，或旺相而被日月动爻冲克，或动而化鬼化绝化回头克，药不见效。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.14","text":"子孙制鬼，最喜旺相生扶。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.15","text":"子孙临在应或发动於卦中亦要旺相，不受刑冲克害破墓绝空，药必见效。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.16","text":"子动化鬼化克，其药不精，子动化空实空之日有效。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.17","text":"子动化生化旺化进神者，其药更灵。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.18","text":"古以子动化子孙，其药必杂，非也，子动化子孙而旺相者另改药品，即比仙丹。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.19","text":"医克用爻近病即愈。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.20","text":"自占病，应爻克世者制我之病也，应爻克用神亦如此断。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.21","text":"惟不宜乎久病及体弱之人，非得克病身亦受其伤矣。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.22","text":"应爻临兄鬼而克用神及克世爻者不拘久病近病必遭其殃。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.23","text":"父爻持世妙药难调。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.24","text":"自占病，父持世药不见功，宜於静养，远色欲息气恼可也。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.25","text":"兄弟持世有子孙动於卦中者，医再延之，惟嫌鬼旺鬼兴误服药饵。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.26","text":"才爻持世切莫误食肥甘，旺相遇生扶良医有见，休囚逢冲克无药可医。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.27","text":"子不代父以占药，妻不代夫而卜医。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.28","text":"子占父宜父爻旺相，占药占医又以子孙为用神，父旺以伤子也，一爻不能两用。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.29","text":"妻占夫宜官鬼旺相占医占药亦以子孙为用神，子旺又能伤夫，所以不能代占医也。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.30","text":"延医于子孙方，治病以应爻定。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.31","text":"卦中子孙爻旺者，延医于子孙之方。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.32","text":"且如午火子孙或旺或动，请南方之医，余仿此。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.33","text":"卦中子孙休囚空破者又看应爻旺否，若得应爻旺相生合用神即于应爻之方请之。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.34","text":"且如应爻临申金，延医必在西南，余仿此。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.35","text":"如卦中有一爻独发而生用神者又以此方而延医。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.36","text":"以五行而定名姓，水爻动黠水之姓，火爻动姓名像火，木爻草头木，傍土爻姓氏有土。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.37","text":"且如占妻病，妻爻属水，得申金发动以相生，请钱姓之医以治之，余仿比。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.38","text":"不起之病，卦中不现其医。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.39","text":"立愈之灾，爻中不见服药。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.40","text":"屡见占医之卦，无药可医之病者，神不现其医矣。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.41","text":"若非用神化鬼、鬼化用神，即是忌神化六亲、六亲化忌神，及用神化绝、化克、化墓，久病逢冲、逢空、随鬼入墓，此皆无药而医也。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.42","text":"病之即愈，神亦不现其医。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.43","text":"近病者，若非卦得六冲，即观用值旬空，或用神化回头生。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c107.44","text":"自占者，子孙持世，此皆不药而愈也。","chapter":"卷之四·延医章第一百三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.1","text":"大抵与医卜相仿。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.2","text":"世为已，应爻为病人，若得世爻旺相，子孙财爻持世，世生应爻，世爻动化进神，化回头生，日月动爻临财星子孙而生，在此皆手到病除。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.3","text":"近病者应值旬空，或动而化空、化回头生、化旺、化退，日月动爻生应爻，及卦逢六冲、卦变六冲，此皆速宜往救，莫令他人先到以成功也。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.4","text":"久病者应爻旺相，或逢日月动爻相生，或动而化生化旺，应临子孙，应临财动生世，虽然久病，我必除根，除此之外，皆不宜往，徒累盛名。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.5","text":"野鹤曰：诸书无不以官为鬼为病，应为医人，子孙为药，理固然也，但此宜鬼者非鬼非病，乃忧神耳。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.6","text":"占子病者，父母爱子之心，未病忧疾，况已病乎？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.7","text":"自占病者，性命在呼吸之间，且一人不起，举室惊惶，谁不忧乎？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.8","text":"此官鬼者，即一家之忧神也，惟除此忧者，乃赖子孙爻也。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.9","text":"如午月甲寅日一人病在危笃，医家不治，迎余到宅，见有三十余人至亲，泪眼不乾，密友愁容可掬，此非一家之忧乎？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.10","text":"及至弟占兄病得屯之中孚卦．","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.11","text":"兄弟子水″动子孙卯木′官鬼戌土′应妻财巳火′父母申金″官鬼未土″世官鬼辰土″官鬼丑土″子孙寅木″世动子孙卯木′兄弟子水′妻财巳火′应余即笑而言曰：列位放心，今日半夜退灾，明日卯日即起床。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.12","text":"只见大小一门愁容变喜，此卦中之子孙爻者，是药耶？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.13","text":"此人虽是险痘，其实近病，子水兄爻值旬空，近病逢空好，值半夜子时而不空也。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.14","text":"或曰：近病逢空，何不许冲空之午日，实空之子日？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.15","text":"余曰：因子水化卯木子孙，世爻又临寅木子孙动化卯木子孙，次日即是卯日，正一家解忧疑之时，所以许半夜实空之时也，果於子时退灾，次日起床，此何尝用药而制鬼耶？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.16","text":"又如一日时值初更叩门入曰：家小主有病相迎占卜。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.17","text":"余问得病源自山东回后顷刻得病，余即自占一卦。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.18","text":"未月壬子日得节之比卦兄弟子水″兄弟子水″应官鬼戌土′官鬼戌土′父母申金″应父母申金″官鬼丑土″子孙卯木″世子孙卯木′动妻财巳火″妻财巳火′世动官鬼未土″巳火财爻持世，子动生世，子孙乃喜悦之神，此行有益。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.19","text":"及到达伊家，值医检药。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.20","text":"壬子日占子病得解之坎卦妻财戌土″父母子水″世官鬼申金″应动妻财戌土′子孙午火′动官鬼申金″子孙午火″子孙午火″应妻财辰土′世妻财辰土′兄弟寅木″兄弟寅木″余见此卦生疑，近病得六冲不死之症耶？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.21","text":"是子孙变鬼必死之病耶？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.22","text":"不敢断之，再请亲人卜之。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.23","text":"叔占侄病得坤卦子孙酉金″世子孙酉金″世妻财亥水″妻财亥水″兄弟丑土″兄弟丑土″官鬼卯木″应官鬼卯木″应父母巳火″父母巳火″兄弟未土″兄弟未土″又见六冲，知不死矣。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.24","text":"彼曰：从无病根，便自山东一路而来，亦无病起，适间日落之时，忽而满床乱滚，口不能言。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.25","text":"余曰：既无旧病，余敢保之即愈，再请医者卜之。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.26","text":"得井之明夷卦父母子水″官鬼酉金″妻财戌土′世动父母亥水″官鬼申金″妻财丑土″世官鬼酉金′父母亥水′父母亥水′应动妻财丑土″妻财丑土″动兄弟卯木′应应为病人，世克应爻还不妨，乃是克制病人之病也，但不宜应爻化回头克，定用药有误。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.27","text":"余问东家：药曾吃否？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.28","text":"问医者曰：所得何病？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.29","text":"伊曰：三伏之天中受暑，不过解暑之凉药耳。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.30","text":"余私对东家曰：令郎不死，却得必死之卦，恐此药来必对症者，再请复看。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.31","text":"医者曰：床上乱滚，不能把脉，随以家人问途中何如，家人言曰：到家热极，移床於此有风之处，再用大冰二块，安於凉床之下，命侄女掌扇，一觉睡熟，忽然醒来呼唤几声，即不言矣。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.32","text":"余想热极之人，卧冰临风，空旷之场，使人掌扇，其病可知，医者亦曰：适看病已扶入喜矣，不知此节，看来寒药实不可服。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.33","text":"余曰：竟用附子肉桂，方可治之，更命伊父占之。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.34","text":"壬子日占用附子可否得大有之大畜官鬼巳火′应妻财寅木′父母未土″子孙子水″应兄弟酉金′动父母戌土″父母辰土′世父母辰土′妻财寅木′妻财寅木′世子孙子水′子孙子水′子孙临日辰，酉金兄动以相生，服用一剂，保管立愈。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.35","text":"医家先用乾姜汤试之，少刻开言肚疼之甚。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.36","text":"余曰：何如快服此药。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.37","text":"医家加减调理一夜，次日曰愈，此人之不死也。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.38","text":"因我出门子孙发动一卦而断定矣。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.39","text":"厥后连占数卦，皆合前象，方敢用大热之剂，起死回生，不然一剂凉药，寒上加寒，能於治耶？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.40","text":"觉子曰：此卦酉金兄动以生子孙，服此热药而病愈者。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.41","text":"使前贤见之，又以酉金兄爻而为药也。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.42","text":"凡卜药亦有当卜之道，或医家看临危之症，欲投此药，可以起死回生，惟恐一失，系不少得子孙动者必喜悦也，即可用之，用而必效，或泛询行用，或长途穹旅，无处得寺医，有人传一奇方占得子孙动者其方必效，或半夜更深，延医不及，检黠古方，及家藏凡药，实对此症，不敢擅用，不可不占，皆以子孙为用神，但得子孙持世，子孙发动，服之立可解忧，此诸占之子孙者，不拘金木水火土也，或旺或动，即为喜悦之神，（用此方而兄爻不动，何喜之有，）切不可又以金临子孙而用针，火属子孙而用炙，错也误也。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.43","text":"一日到一府中，众客告曰：老先生昨日在后园仆倒，扶起出狂言，至今不知人事，诸位医者内有曰：不服人参不能提气。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.44","text":"有曰：幸无痰上，若吃人参，痰上则难治矣。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.45","text":"余曰：就卜人参吃得否。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.46","text":"寅月丁卯日子占父病吃人参好否。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.47","text":"得萃之否卦父母未土″动父母戌土′应兄弟酉金′应兄弟申金′子孙亥水′官鬼午火′妻财卯木″妻财卯木″世官鬼巳火″世官鬼巳火″父母未土″父母未土″占人参必以子孙为用神，若不通变，见卦中父动克子孙不过曰人参不可服也。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.48","text":"余非此断，子占父病，父爻为用神，未动化戌，父戌旬空，人参莫用，药亦莫服，明日辰日冲空即愈，果於鸡鸣苏醒，次日不药而愈。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.49","text":"又如一日在席间，见东翁口歪眼斜痰涎长流，余亦在座，乃即问曰：家有牛黄，但不知可服否？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.50","text":"亥日辛酉日子占父病吃牛黄丸可否得夬卦兄弟未土″兄弟未土″子孙酉金′世子孙酉金′世妻财亥水′妻财亥水′兄弟辰土′兄弟辰土′官鬼寅木′应官鬼寅木′应妻财子水′妻财子水′余曰：灌服此丸可保立愈，服之便醒，喜子孙持世也。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.51","text":"或曰：同是子占父药，一卦看父爻，一卦看子孙，其故何也？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.52","text":"余曰：前卦父爻发动，神兆机於动，以父母断之，后卦子孙持世值日，子孙乃喜悦之神，父病即安则喜悦矣，卦无不灵，在人通变。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.53","text":"又如申月癸卯日因杨梅疮占医好否。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.54","text":"得履之否卦兄弟戌土′兄弟戌土′应子孙申金′世子孙申金′父母午火′父母午火′兄弟丑土″官鬼卯木″世官鬼卯木′应动父母巳火″父母巳火′动兄弟未土″断曰：此医不可用之，虽系子孙持世，应为医人，不宜应爻与巳火克申金，又有卯木生火，世爻虽旺，巳日一定添灾，不听，竟延此医治之，卯辰日服药还保平常，巳日忽然变症，遍身疼痛难当，病人着急而问余曰：可伤命否？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.55","text":"余曰：世值日建，何如伤命？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.56","text":"快服解药，过此巳午日则止疼矣，即服解药至申日其病如常。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.57","text":"野鹤曰：前篇俱言子孙持世，其病即愈，必要子孙不受克可也，后贤不可不知。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.58","text":"李我平曰：此论官鬼为忧神，子孙为喜悦解忧之神，虽系古法，用之得当，非合鬼神之机，不能幻想至此，然又有不以鬼作忧神者，全在来人念之所指，彼问病之吉凶，若得鬼爻持世，鬼动卦中，岂为忧神？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.59","text":"子孙持世，子孙发动则为解忧喜悦之神是也。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.60","text":"彼问犯何鬼神者，卦现金鬼，必冲犯于武神。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.61","text":"水鬼者犯罪於河神也。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.62","text":"彼问病原，火鬼必属心经，水鬼必肾部，子孙旺而动者不药而愈，非教人以此子孙爻为治病之药，金为子孙而用针，火持子孙而用炙，殊不知子孙若旺，其病自痊，何用针炙？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.63","text":"子孙者值空破，用针炙而何益？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.64","text":"诸书皆曰：土鬼忌热，水鬼忌寒，水鬼若生旺之地，须用大热之药以治之。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.65","text":"水鬼寒者，宜大寒之药以功之，余不知从何见此。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.66","text":"假使用神属土及子占父病，父爻临土，若得火爻发动，乃生用爻之元神也，岂可以大寒之药而治元神耶？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.67","text":"又如妻占夫病，鬼为用神，假令夫临水鬼，又可以大热之药以攻夫爻之用神耶？","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c108.68","text":"常见穷乡僻壤，无处觅医，只谓周易乃大圣大贤之书，遵之必灵，以此大寒大热之药，不知坑陷如许之命，言及发指，此书一出，寒热之药不可轻用，从此泉下无冤鬼矣。","chapter":"卷之四·医卜往治章第一百四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.1","text":"野鹤曰：诸书皆曰，一卦之中，可决一家休咎，六爻之内，能分六事吉凶，以卦中之父母爻为屋，又以父母爻为双亲，既为二亲，又以五爻为父，四爻为母，如此悖谬糊涂，尚有刊传为法，余实不解。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.2","text":"如戌月丙午日占得乾之小畜父母戌土′世妻财卯木′兄弟申金′官鬼巳火′官鬼午火′动父母未土″应父母辰土′应父母辰土′妻财寅木′妻财寅木′子孙子水′子孙子水′世古法有出卦无父母，不免堂上之忧。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.3","text":"此卦不独有父母戌土临月建，午火官动以相生，即父母双庆之祥也。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.4","text":"若又以五爻为父四爻为母断者，鬼临四位，老母多灾，执此问之，老母多灾即堂上无忧耶？","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.5","text":"又曰：好爻受克即此逢伤，今五爻申金被午火鬼克，此又老父以生灾耶？","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.6","text":"又曰：鬼动乾宫老父之咎，此卦鬼发乾宫又为老父之咎？","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.7","text":"又云：火鬼动以防回禄，白虎鬼为丧服之忧。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.8","text":"又云：世逢生旺，宅旺家安。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.9","text":"此卦世已旺矣，奈因火鬼临於虎动，可谓之回禄乎？","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.10","text":"又以官鬼为厅堂，谓之官旺屋宇轩昂。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.11","text":"又云：鬼旺鬼兴，为灾为咎。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.12","text":"此卦鬼临日辰旺动，屋宇轩昂乎？","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.13","text":"又云：财官旺相，热闹门庭。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.14","text":"又曰：财爻发动，父母遭伤，岂门庭热闹之家，皆无父母之家耶？","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.15","text":"又云：兄爻旺相，紫荆并茂於堂前。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.16","text":"又云：兄弟持世，丝弦再理。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.17","text":"岂雁行队队者皆失履遗之宅耶？","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.18","text":"种种悖谬，难以枚举，余不得已而正之。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.19","text":"盖造买宅赁宅第一百六父旺持世，此处清安宜久住。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.20","text":"父爻旺相持世、生世、合世、及世爻动而化父相生，或得日月作父母生合世爻，皆为发福之兆。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.21","text":"财爻发动，他方仁里另宜求。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.22","text":"财动以克父爻，另于他处图之。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.23","text":"爻逢六合，终见享通。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.24","text":"卦遇反吟，多於愁叹。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.25","text":"世爻父爻旺相，又得六合卦者事之必成，成而久远，但不喜其六冲，六冲不久之象。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.26","text":"卦遇反吟，倘加世破，冲克大凶之兆。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.27","text":"世动而化进，绵长百代，父兴不化退，增置千间。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.28","text":"世动化退，勉强成之，终须退悔。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.29","text":"世动而化进神者，成后长远兴隆，名高利厚。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.30","text":"父动化退神，成后凋零破败，倘得化进，此后再置千间。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.31","text":"最忌随官入墓，须防鬼动伤身。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.32","text":"世爻随鬼入墓，财爻助鬼克世，及世爻动而变凶，或日月动爻克世，皆不宜行。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.33","text":"父动克世及世爻父爻空破墓绝者，亦不宜行。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.34","text":"野鹤曰：凡盖造买宅赁宅，世与父爻旺相不犯冲克者即宜成之，自是荣华昌盛。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.35","text":"如问一家之吉凶，虽则须宜分占，亦待迁居入火之时，择其吉日而占之，告于神曰：今某日迁居，有碍于父母妻子否？","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.36","text":"若有妨碍，须另择一时以入门者可也。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.37","text":"朝迁以便民间之用者此也。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c109.38","text":"如若盖造买造占问一家俱宜吉庆，假令家有百口，欲使人人合其吉者百年买不成矣。","chapter":"卷之四·家宅章第一百五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c110.1","text":"创造兴工，卦忌六冲，鬼动克世最凶，随鬼入墓，祸事多逢。","chapter":"卷之四·创造宫室章第一百七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c110.2","text":"父爻旺相，世位兴隆，世父两爻发动化吉大安宅盛，事事享通。","chapter":"卷之四·创造宫室章第一百七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c111.1","text":"世临福德最相宜，官鬼交重有祸基。","chapter":"卷之四·修方动土章第一百八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c111.2","text":"世旺逢生宜化吉，世衰受克且停工。","chapter":"卷之四·修方动土章第一百八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c111.3","text":"子孙之方宜起手，官鬼之位莫挑泥。","chapter":"卷之四·修方动土章第一百八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c111.4","text":"譬如子孙属水，起手动工宜於北方。","chapter":"卷之四·修方动土章第一百八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c111.5","text":"官鬼属火，不可动土於南方。","chapter":"卷之四·修方动土章第一百八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c111.6","text":"鬼在辰戌丑未，此方切忌动土。","chapter":"卷之四·修方动土章第一百八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c111.7","text":"岂嫌子象发，偏忌父爻虚，造成屋宇忧冲散，父爻旺相久长居。","chapter":"卷之四·修方动土章第一百八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c112.1","text":"占以内三爻为久居之宅，外三爻为未居之房。","chapter":"卷之四·迁居过火章第一百九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c112.2","text":"内克外者外宅不利，不宜迁之，内生外者，外宅兴隆，过迁为吉。","chapter":"卷之四·迁居过火章第一百九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c112.3","text":"野鹤曰：余以此法不善，宅已盖造买成，今欲入火，假使占得外宅不吉而不迁耶？","chapter":"卷之四·迁居过火章第一百九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c112.4","text":"既有新宅成，旧宅或已弃矣，倘若占得内卦吉者，岂可仍居旧宅耶？","chapter":"卷之四·迁居过火章第一百九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c112.5","text":"觉子曰：此法亦有使处，来人有问欲弃旧宅而买新宅可乎？","chapter":"卷之四·迁居过火章第一百九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c113.1","text":"宅之吉凶，已于盖造买宅卦中卜就之矣，今占入火之日，须将父母兄弟妻儿各为分占，宜于此日者用之，不宜此日者改之，或改日，或另择一时以入门，皆可化凶为吉。","chapter":"卷之四·归宅入火章第一百十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.1","text":"择于某日入宅，宜於父母否？","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.2","text":"再占一卦，宜於兄弟否？","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.3","text":"再占一卦，宜于妻儿否？","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.4","text":"占父母，父母宜于旺相。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.5","text":"占兄弟妻儿，皆宜旺相而遇生扶，不宜变动而化鬼，及刑冲克害。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.6","text":"或兄弟或妻子内有一卦不利者即令另择一日或另择一时俱可。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.7","text":"野鹤曰：余得周公克制之法，凡六亲所犯之神，令之趋避，无一不验。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.8","text":"且如木临父母命爻，财动以伤之父母，入宅须择克制金爻之日，安父母之床榻宜克制金爻之方，屡试屡验。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.9","text":"子月丁酉日占择某日入宅是否有碍父母得萃卦父母未土″父母未土″兄弟酉金′应兄弟酉金′应子孙亥水′子孙亥水′妻财卯木″妻财卯木″官鬼巳火″世官鬼巳火″世父母未土″父母未土″断曰：此日入宅，卯木暗动以克父母。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.10","text":"彼曰：即烦另改一日。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.11","text":"余曰：不必改日，此日寅卯时吉，申月亦吉，保尔清静吉祥。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.12","text":"余曰：申时卯木绝於申也。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.13","text":"父母未土及长生於申是以吉也。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.14","text":"入宅之时宜父母安床於西南，后照此行，余目其平安一十七载。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.15","text":"马房猪圈章一百十二凡作牛棚马房鸡窝羊栏，亦宜分占。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.16","text":"子孙须宜旺动，父母切忌兴隆。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.17","text":"凡占一切六畜，皆以子孙为用神，不拘猪羊牛马，皆忌父母发动，动则六畜受伤，亦忌子孙空破墓绝，及被日月动爻刑冲克害，及子孙动而化空破墓绝、化鬼、化父回头克，皆主刑伤，此地不宜用之，或更择地方，或另改一日，改日改地方者另占。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.18","text":"生相必须兼看，日月更喜相生。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.19","text":"六畜虽以子孙为用神，又宜兼看生相。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.20","text":"假令作马房，子孙不被冲克为吉也，不宜午爻，亦不宜临鬼，不宜动而化鬼，余仿此。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c114.21","text":"凡占六畜，最宜日月生扶，谓之卦得日月生扶，六畜必然繁盛，倘受日月冲克，牲口绝种无根。","chapter":"卷之四·入宅六亲凶吉章第一百十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.1","text":"野鹤曰：以前之卜宅者乃卜盖造买宅之新居也。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.2","text":"常见来人而占久住之家宅，古法亦以一卦兼断诸般之吉凶，先论官鬼次论八宫，以十二生相定六畜之灾，午鬼而夭良马，丑鬼而伤耕牛。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.3","text":"又以之定人口之匹，午爻临鬼马命者夭，巳鬼爻兴蛇命有难。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.4","text":"假使午爻临鬼马之人不禄耶？","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.5","text":"悖谬不堪，难以数说，余不知昔人其何以回复来人之问也，要知彼之来意，或因连年破耗，疑家宅之不安，或因屡科之不第，或因有子求名，疑此宅能兴旺子孙否，必用子孙亲卜，或因官不升转，或因子女不孝，或因官灾火盗，或因父母六亲多病，或因前后左右他人造疑其冲犯，或因家有响动，邪崇鬼形。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.6","text":"须问来人而判，曾因官府十载不升，疑其家宅有碍。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.7","text":"余曰：若以一卦而断全家之事者余则不能，须指其所疑之事而占之，其应如是。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.8","text":"余曰：卦中不过干支五行虽有现出，难以直指一处，即如火鬼发动为灶神，府上二百余间，其灶不少，谁知何灶而不安。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.9","text":"又如卯木鬼，门户不安，古以四爻为门，尊府门户不少，即以六爻全为门户，不过定得六重，难知何门而不利，所以指其所疑之处而占之，无不响应，公曰：余疑院内不宜有井，占问是否。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.10","text":"酉日戊寅日占得师之临父母酉金″应父母酉金″兄弟亥水″兄弟亥水″应官鬼丑土″官鬼丑土″妻财午火″世官鬼丑土″官鬼辰土′子孙卯木′世子孙寅木″动妻财巳火′断曰：子孙发动非此井也。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.11","text":"公曰：大门对向不利，意欲改之，可否？","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.12","text":"又占一卦又得同人卦子孙戌土′应子孙戌土′应妻财申金′妻财申金′兄弟午火′兄弟午火′官鬼亥水′世官鬼亥水′世子孙丑土″子孙丑土″父母卯木′父母卯木′断曰：官持世是此门也，速宜迁改，须再占一卦，改门之后功名何如又得小过之剥父母戌土″动妻财寅木′兄弟申金″子孙子水″世官鬼午火′世动父母戌土″兄弟申金′动妻财卯木″官鬼午火″官鬼巳火″应父母辰土″应父母未土″断曰：午火官鬼持世，寅日生之，外卦巳合官局，明年、巳年、午年连升大位，果于次年一岁两升，午年又升官至二品。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.13","text":"福德动摇，不是此方之祸。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.14","text":"子孙持世，或动于卦中，或官鬼不动，及六爻安宁，非此处也。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.15","text":"官鬼发动，的于此处兴妖O官鬼持世克世，官鬼动爻，实因此处有害O野鹤曰：占得果是此处不利，即是修补，再占一卦，修补之后何如？","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.16","text":"问功名功名章内断之，求财者求财章内断之，防患者防患章内断之，疾病者灾病章内断之。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.17","text":"曾有士子才重当时，屡科不第，卜家宅何如。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.18","text":"余曰：虽则为名而占贵宅，有疑相犯之处否？","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.19","text":"彼曰：疑宅后有庙。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.20","text":"巳月己丑日占得大有之乾卦。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.21","text":"官鬼巳火′应父母戌土′世父母未土″动兄弟申金′兄弟酉金′官鬼午火′父母辰土′世父母辰土′应妻财寅木′妻财寅木′子孙子水′子孙子水′断曰：世为本宅，庙为应，世应相生如何有犯？","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.22","text":"庙前另有一物，未土发动刑世，乃此故耳。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.23","text":"彼曰：庙前有一照壁，照壁之后有一株大树，数百年矣。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.24","text":"余曰：即此物也。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.25","text":"尔用大兽头安于尾脊，张口对树则吉。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.26","text":"再一卦修补之后如何得归妹之豫卦父母戌土″应父母戌土″兄弟申金″兄弟申金″官鬼午火′官鬼午火′应父母丑土″世妻财卯木″妻财卯木′动官鬼巳火″官鬼巳火′动父母未土″世断曰：修补之后，包尔今科必中，财动生官，官动生世，大吉之兆。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.27","text":"果中经魁，下科胞弟又发。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.28","text":"福德临身，转灾为福。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.29","text":"旺财持世，宝藏兴焉。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.30","text":"子孙持世子孙发动者，鬼崇潜行，即有活鬼出现，可保平安。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.31","text":"子动无忧，神藏兔没O旺相之财持世财动生世合世，必有古窖。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.32","text":"若问在于何方，财来寻我，我莫寻他，是我之财，自然出现。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.33","text":"若问何时可得，即以此财爻应期章内断之。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.34","text":"鬼动爻中真祟真妖O鬼临白虎，必有伏尸。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.35","text":"鬼临元武，水怪山魑。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.36","text":"勾陈鬼牢狱羁身。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.37","text":"青龙鬼色欲而丧。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.38","text":"亥子鬼投河溺井之魂，或因水沟池塘之患。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.39","text":"辰戌丑未之鬼墙倒屋塌，或因墙垣兽头之犯。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.40","text":"寅卯鬼悬梁自缢，又为门户栋梁。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.41","text":"巳午鬼火伤窑死，兼为炉灶不安。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.42","text":"鬼临申酉之乡，刀剑之身之魄，或因金钱为怪，又为狐狸为精。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.43","text":"鬼在变爻冤家债主，鬼临日月供养正神，受克者必受其殃，生世者反得其济。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.44","text":"古法制鬼於庚申日甲子日，或于除夕日，黄钱数张，浆水一碗，卦现金鬼者向西送之，水鬼者向北送之，在人静处送。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.45","text":"屡验平安，余仿此。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.46","text":"觉子曰：余有泊云之法，一正可夺百邪，见怪不怪，其怪自灭。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.47","text":"官克在位，为灾为祸。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.48","text":"鬼动克世，或世爻随鬼入墓，及世动变鬼克世，乃是冤家债主，难免祸殃，宜修德作福，自然改祸为祥。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.49","text":"财动克父，财化父，父化财，堂上之忧。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.50","text":"父动克子，鬼化子，子化鬼，膝前有损。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c115.51","text":"兄弟变鬼，鬼变兄弟，鬼动克兄，妻财变鬼，鬼变妻财，兄动化财，财化兄弟，既防手足刑伤，又主分衾折枕。","chapter":"卷之四·旧宅章第一百十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c116.1","text":"与六亲同居用六亲，与外人同居看应爻。","chapter":"卷之四·同居章第一百十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c116.2","text":"世为已，应为人，世应相合相生，日月动爻生合世应者，彼此俱祥。","chapter":"卷之四·同居章第一百十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c116.3","text":"克世我遭丧，克应他遭害，世克应，他畏于我，应克世我被他欺，刑冲者同。","chapter":"卷之四·同居章第一百十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c116.4","text":"与六亲同居，宜于财兴用神相生，不宜相冲相克。","chapter":"卷之四·同居章第一百十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c117.1","text":"官府自占，世与官星皆宜旺相，子孙持世及子孙动者且勿行，变克变绝反招奇祸，六冲化合，必获奇祥。","chapter":"卷之四·盖造官衙章第一百十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c118.1","text":"野鹤曰：凡占旧衙署者，与占旧家宅者同断，有因人口多病，有因连任不得升迁，有因鬼祟显见其形，皆可指其疑者而占。","chapter":"卷之四·占衙宇章第一百十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c118.2","text":"曾有一官因连任不得升迁，疑官衙有不利，迎于府中，卜过半月，但有所疑，俱曾占过，皆不现爻，又卜后沟从后流宜否。","chapter":"卷之四·占衙宇章第一百十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c118.3","text":"如戌月已亥日占得鼎卦兄弟巳火′兄弟巳火′子孙未土″应子孙未土″应妻财酉金′妻财酉金′妻财酉金′妻财酉金′官鬼亥水′世官鬼亥水′世子孙丑土″子孙丑土″断曰：即此处违也，宜改往东流，后开沟见许多尸体白骨，余始悟曰：虎鬼持世，是以有之，再请占一卦。","chapter":"卷之四·占衙宇章第一百十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c118.4","text":"修沟之后何如得噬嗑之无妄子孙巳火′妻财戌土′妻财未土″世动官鬼申金′官鬼酉金′子孙午火′世妻财辰土″妻财辰土″兄弟寅木″应兄弟寅木″父母子水′父母子水′应断曰：未土财化申金官，未年一定高升，后于申年升任，应申年者，值官之年也。","chapter":"卷之四·占衙宇章第一百十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.1","text":"大抵与家宅同推，不宜六冲、卦变墓绝及反呤，住持或山主占者皆宜世旺日月动爻相生，宜子孙爻动，忌官鬼爻与兄爻持世，多费无益之事。","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.2","text":"官鬼持世疾病灾殃之累，兄爻动而克世者欲造福反成祸胎，财官生世者虽钱少自有增助，子孙旺相而化进神，多招徒弟，财爻休囚而化退者，有始无终。","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.3","text":"李我平曰：卜筮诸书，二十余种，所论家宅，理不归一，不知昔贤是何宅见。","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.4","text":"卜筮大全：初井二灶三床四门五爻为人六爻栋宇。","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.5","text":"黄金策：初爻是宅二爻宅舍三爻为门四为父母五兄弟六妻财。","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.6","text":"易冒以初爻为幼二爻为妻三弟四母五爻为父上爻为老。","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.7","text":"他书俱各不同，不暇细具。","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.8","text":"易冒又云：鬼动於内，宅室之灾。","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.9","text":"鬼动于外，人口之咎。","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.10","text":"既以二爻为妻，三爻为弟，假令内爻鬼动，宅室之灾乎？","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.11","text":"至於五行之鬼，八宫之鬼，既以之定祸灾炎盗，又以之定头目，定病灾，彼谓炎鬼主回禄，鬼在乾宫主头目之患，若以一卦而兼断，岂失火盗之家，必染头目之病耶？","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.12","text":"有曰：合为门，冲为路，不论卦内之有无，但有暗冲与暗合，也应作数。","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.13","text":"假使有冲无合，有合无冲，岂有门无路之家耶？","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c119.14","text":"殊不知占家宅之趋避，愿人口以为安，财福旺，而宅与鬼安静而家宁，於斯而已，何必多生枝条，以乱后人耳目。","chapter":"卷之四·盖造寺院章第一百十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c120.1","text":"野鹤曰：卜墓卜穴，古法之谬与家宅相同，后贤放诸书而自晓，余因求验之法，每遇拜扫之时，到各家，命伊占之，或知人觅地而占之，如此多年，始得其秘。","chapter":"卷之四·墓葬章第一百十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.1","text":"世爻旺相，祖父魂安。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.2","text":"福德兴隆，儿孙缩杞。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.3","text":"古以二爻为穴，内卦为穴，腾蛇为穴，屡试不验，所验者，世为穴也，世宜旺相，或临日月，或日月动爻生扶，乃吉地也。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.4","text":"儿孙乃祭杞之裔，宜於持世，或在他爻旺相，振振螽斯。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.5","text":"三合六合，聚气藏风。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.6","text":"世冲六冲，飞砂走石。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.7","text":"卦逢六合或世与子孙爻作六合，乃藏风吉穴，代代兴隆。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.8","text":"若得六冲卦，或六冲变六冲，或世应相冲，冲者散也，必无气耳。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.9","text":"六冲变六合，吉地失而复得；","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.10","text":"六合变六冲，吉地得而复失；","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.11","text":"此亦有二说：六冲变六合，寻得吉地，先欲买而不成，后又买成，或是地运已衰，真龙去后今复重来，凡得此者，再得世遇子孙旺相，急宜用之。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.12","text":"曾验数占，绵绵科甲。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.13","text":"六合变六冲者，或是已得之地而复失，或是地运将衰，龙将去矣，不宜用之。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.14","text":"世旺而化绝破，吉处藏凶。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.15","text":"世衰而化生合，凶中有吉。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.16","text":"世爻虽旺不宜化破及化墓绝化回头克，主先得吉地，后有破绽，若非将来下葬，不得吉日，定因葬后被人伤根，吉变为凶之象。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.17","text":"世若衰弱，动而化回头相生化长生帝旺化日月化合化进神者，先否后喜之兆，目下观其形势，虽是不宜下葬之地，将来地运兴隆，变成富贵之大地也；","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.18","text":"寅月戊午日占地得颐变无妄卦兄弟寅木′妻财戌土′父母子水″动官鬼申金′妻财戌土″世动子孙午火′世妻财辰土″妻财辰土″兄弟寅木″兄弟寅木″父母子水′应父母子水′应断曰：世爻戌土，春天休囚，化出午火子孙回头生世，日月世爻其成三合，青龙戏水，以化长生，水源极远，只因申为月破，戌土克子水，又被日神冲散，春夏有水，秋冬必动。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.19","text":"彼曰：正是如此。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.20","text":"余曰：不妨，不可求全责备，卦中日月世与子孙共成三合，死者安而生者乐，子孙昌盛，何愁不发，后竟葬之，辰年下葬，酉年孙中亚魁，及至子年，次孙又登乡榜。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.21","text":"世化进神，千秋绵远。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.22","text":"福德化进，百代兴旺，世宜旺相化进神、化日月、化回头生、化合、化长生帝旺，龙安水源地脉长。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.23","text":"子孙旺相化进神、或化吉、化生、化日月，贤孙贵子布满朝堂。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.24","text":"世化退神，终须迁改，子孙化退，代代不如。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.25","text":"日月宜生福德，动爻不可伤身。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.26","text":"世与子孙爻宜日月动爻生扶，不宜日月冲克。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.27","text":"旺世临虎，棺上加棺。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.28","text":"旺福逢龙，寅葬卯发。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.29","text":"世临白虎鬼爻，或是随鬼入墓，皆主地有伏尸。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.30","text":"世爻旺相又遇生扶，乃为棺上加棺。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.31","text":"曾见两人葬者后竟大发。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.32","text":"休囚者则不可耳。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.33","text":"子孙旺相又遇日月生扶又遇青龙，即为吉地，寅年葬而卯年发也，皆言其发旺之速。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.34","text":"散绝墓空，世与子孙勿见。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.35","text":"化克化鬼，弟兄妻子休逢。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.36","text":"世爻子孙爻，不宜休囚墓绝空破，不宜动逢破散及化破散、化绝、化墓、化鬼、化退神、化回头克，但逢一者皆非吉地。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.37","text":"六亲不宜化鬼、父化子，子化父，鬼化子，子化鬼，兄化鬼，鬼化兄，兄化财，财化兄，财化鬼，鬼化财，此不宜于兄弟妻子。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.38","text":"有父母在堂亦不宜鬼化父、父化财、财化父。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.39","text":"应冲世合处逢冲，流移迁徒。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.40","text":"反伏卦变化克，洪泛陵墓。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.41","text":"择地不但不喜六冲卦，应冲世者亦非吉也，倘应世相合，爻逢六合，世应子孙三合成局，即为美地。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.42","text":"卦得反吟，遇冲开之年月必迁。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.43","text":"卦得反吟，遇冲年冲月必变。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.44","text":"内外反吟者乃卦变也，如巽变乾，坤变震之类，名为化绝化克得此卦者，重则冲决，轻则迁徙。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.45","text":"如卯月戊子日占地得巽之升兄弟卯木′世动官鬼酉金″子孙巳火′动父母亥水″妻财未土″妻财丑土″世官鬼酉金′应官鬼酉金′父母亥水′父母亥水′妻财丑土″妻财丑土″应世为穴，世临月建，日辰生之，是为吉也，但不宜外卦反吟，世被酉金冲克，子孙被亥水冲克，不宜用之。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.46","text":"彼曰：已买成矣。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.47","text":"余曰：不葬何妨。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.48","text":"又曰：地师言为美地，后竟葬之。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.49","text":"四年之内，二男一女，相继而亡，自身又得半身不遂之疾，愚人不怨於已，反怨祖父棺材暴露，竟至二年后没，应酉年者，谓之再冲之年。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.50","text":"父化父，儿孙夭折。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.51","text":"子化子，子女成行。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.52","text":"卦中不宜父动，父动化父更凶。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c121.53","text":"子孙化子孙不遇伤克，代代儿女成行，决非单传。","chapter":"卷之四·寻地章第一百十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.1","text":"世旺遇长生，来龙甚远。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.2","text":"世衰逢应克，对案山欺。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.3","text":"两间旺而明堂宽，龙虎衰而左右陷，左山旺头角峥嵘，右山衰爪牙埋伏。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.4","text":"朱雀遇刑冲前山杂乱，元武逢破散后脉空虚，龙虎世爻合局，虎踞龙蟠之地。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.5","text":"世应相合，山环水绕。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.6","text":"水口不固，上爻一定逢空。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.7","text":"道路参差，腾蛇必然破散。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.8","text":"世爻当令又长生帝旺于日辰，来龙远大。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.9","text":"倘若应爻冲克世爻者，必因对山高耸，或因临葬错对向山，如应爻受克者无碍，改向可也。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.10","text":"世爻应爻中间两间爻以为明堂，旺相者明堂宽大，休囚者明堂下陷，近世之爻而为案山，亦不可克世。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.11","text":"龙为左山，虎为右山，两山旺者，有环抱之势。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.12","text":"俱衰者，不能环抱。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.13","text":"大抵青龙宜旺扶头角轩昂，虎山宜衰宜克爪牙埋伏，朱雀遇刑克冲散及破墓绝空者，前山杂乱。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.14","text":"元武逢破散后脉空虚。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.15","text":"若得世应龙虎子孙共成三合者乃虎踞龙蟠之大地也。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.16","text":"第六爻为上爻，若逢空破，水口不固，逢绝者水涸泉枯。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.17","text":"看河道之水者，非论水口，须看卦中之水爻休囚被克，涨退不长。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.18","text":"逢生化生长流源远，再遇青龙源长。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.19","text":"看腾蛇为路，如逢冲散小路必多，旺相者必有官道。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.20","text":"勾陈为田坡，旺相则有，衰破则无。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.21","text":"丑月庚申日占地形势得咸卦父母未土″应父母未土″应兄弟酉金′兄弟酉金′子孙亥水′子孙亥水′兄弟申金′世兄弟申金′世官鬼午火″官鬼午火″父母辰土″父母辰土″青龙持世，日辰临世，来龙由左而至，旺而有气，左右皆无伤克，龙虎环抱，向山未土虽临月破，朱雀亥水为前山，申日生之必有朝水，或是带水，水有其源。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.22","text":"腾蛇为路，上爻为水口，俱临月破，道路参差，水口散乱，两间爻旺相，明堂宽大，彼曰：果一一无错，此地吉否？","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.23","text":"余曰：此乃占地穴之形势耳，非关吉凶祸福，余笑前贤以一卦而断父子弟兄妻财官禄，余岂效颦耶。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.24","text":"若问功名，再占一卦，祷于神曰：安葬此地，我名成否？","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.25","text":"以官禄章中断之。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.26","text":"以求财章内断之。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.27","text":"伤克父母兄弟妻妾否？","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.28","text":"皆在身命章中父母兄弟章内断之。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.29","text":"若以占形势之卦兼断六亲及名利者，即如此卦，兄弟持世乃贫乏艰难无衣而短食矣，请试思之，既得如此吉地，若使家徒壁立，抱衾孤眠，亦可谓之吉地耶？","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.30","text":"所以余得分占之法，实则可以醒世，作千古不易之法也。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.31","text":"或曰：前说父不宜旺，不宜父动化父，是何说也？","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.32","text":"余曰：占地以世爻子孙爻为主，父动克子，如何不忌？","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.33","text":"或又问曰：前说化克化鬼兄弟妻子休逢，又何说也？","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.34","text":"余曰：凡占地者，世与子孙爻旺，即可用之，至于父母兄弟妻财功名，须宜另占一卦，不可兼断，倘若得地之凶，不待另占，即此占地之卦而先现出六亲化鬼、鬼化六亲，即是刑伤之地耳。","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c122.35","text":"只看六亲动而化克化鬼，不必看衰旺空破刑冲，神兆机于动，动而化凶，愿益而告我也，我岂能不看又另占耶？","chapter":"卷之四·占地形势章第一百二十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c123.1","text":"世为用神，静者逢冲逢值，动者逢值逢合，世空者冲实之秋，世破者填实之候，逢合入墓，须待冲开，独静独发值之而遇，世若休囚须旺相，若逢旺相待休囚O世为坟地，静者逢冲逢值之年月O即如世值子水，静者应在于午年月，动者应在丑年月亦有应子年，余仿此O世空者冲空实空之年，世破者实破之年，世逢三合六合，或世爻化合，或墓于日辰或化墓，皆应冲开之日。","chapter":"卷之四·卜得地于何时章第一百二十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c123.2","text":"卦中一爻独发，一爻独静，亦应逢值之动逢合静逢冲，即如卦中子爻独动，应在于丑年，如子爻独静，应在于午年，余仿此。","chapter":"卷之四·卜得地于何时章第一百二十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c123.3","text":"又如辰月乙卯日占何时得地得复之屯卦子孙酉金″妻财子水″妻财亥水″动兄弟戌土′应兄弟丑土″应子孙申金″兄弟辰土″兄弟辰土″官鬼寅木″官鬼寅木″世妻财子水′世妻财子水′断曰：亥水财爻独发，拱扶世爻，被戌土回头克制，今为月破，九月实破，戌土更旺，交冬水旺而得矣。","chapter":"卷之四·卜得地于何时章第一百二十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c123.4","text":"彼曰：得在何方？","chapter":"卷之四·卜得地于何时章第一百二十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c123.5","text":"余曰：占此应此，占彼应彼，如问何方再占一卦。","chapter":"卷之四·卜得地于何时章第一百二十一","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c124.1","text":"野鹤曰：卜得地于何时，还以世爻为用，卜得地于何方，当以父爻为用也。","chapter":"卷之四·得地于何方章第一百二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c124.2","text":"己葬之后，皆以父爻为用可也O父值亥子，北方自有吉穴。","chapter":"卷之四·得地于何方章第一百二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c124.3","text":"父临巳午，东南必获牛眼。","chapter":"卷之四·得地于何方章第一百二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c124.4","text":"父值土爻，得地于辰戌丑未之方。","chapter":"卷之四·得地于何方章第一百二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c124.5","text":"父爻临木，东北寅卯堪寿。","chapter":"卷之四·得地于何方章第一百二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c124.6","text":"夫临申酉地在西南O间有验于墓方者即如父母爻属木得地于未方，父母爻属金得地于丑方，余仿此。","chapter":"卷之四·得地于何方章第一百二十二","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c125.1","text":"应为用神，旺相生合世爻，虽愚亦用。","chapter":"卷之四·占地师章第一百二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c125.2","text":"休囚冲克世爻，贤亦不宜。","chapter":"卷之四·占地师章第一百二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c125.3","text":"世应俱空莫用，应临空破非奇O应爻旺相与世爻相生相合，或与世爻作三合，不论应临才鬼兄父，人恶之而无才，我喜之而有缘。","chapter":"卷之四·占地师章第一百二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c125.4","text":"休囚冲克世爻者，曾使应临官父，他有博学，我被他愚。","chapter":"卷之四·占地师章第一百二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c125.5","text":"世应皆空，彼此无缘。","chapter":"卷之四·占地师章第一百二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c125.6","text":"应逢空破，无大无从。","chapter":"卷之四·占地师章第一百二十三","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c126.1","text":"世在初二爻穴宜下，在五六爻穴在上，三四爻穴宜于中。","chapter":"卷之四·点穴章第一百二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c126.2","text":"水持世爻穴近于水，或是坑高之地。","chapter":"卷之四·点穴章第一百二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c126.3","text":"世临土者，即于高堆点穴。","chapter":"卷之四·点穴章第一百二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c126.4","text":"世临寅木，从木盛草之方。","chapter":"卷之四·点穴章第一百二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c126.5","text":"申酉持世，有块石堆。","chapter":"卷之四·点穴章第一百二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c126.6","text":"火乃枯焦，红泥焦土及草木枯焦之处是也。","chapter":"卷之四·点穴章第一百二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c126.7","text":"如未月乙巳日占穴得大壮卦兄弟戌土″兄弟戌土″子孙申金″子孙申金″父母午火′世父母午火′世兄弟辰土′兄弟辰土′官鬼寅木′官鬼寅木′妻财子水′应妻财子水′应此地经过法眼，皆言其吉，久占此地，亦许其吉，因屡掘逢石，无处导穴，央余到冢下，得此卦。","chapter":"卷之四·点穴章第一百二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c126.8","text":"余曰：世在四爻，穴在中段，因午火持世，即往中段观看，有一处草木枯焦，有几朵野花红色，别处皆无。","chapter":"卷之四·点穴章第一百二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c126.9","text":"余曰：即此穴也，掘之必逢土穴。","chapter":"卷之四·点穴章第一百二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c126.10","text":"余曰：我有一法，将钱一丈点记红原乳，入数百钱内，公可设下香案，祷告于天，得红原钱者，即其穴也，令人遍地洒之，果得原钱于红花之下，掘之周围仅有丈余，皆泥土也，余皆石块，此公次年开府，两公郎五年之内俱登甲榜。","chapter":"卷之四·点穴章第一百二十四","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c127.1","text":"觉子曰：谋地偷葬，乃损人利己之事，以此丧心之为，而问于神，卦若有灵，是神教人而作丧心之事也，殊不知先有心地而后得遇阳地，昔有人恃财倚势，期陷贫人，谋夺其地以葬亲，后遇识者而曰：此地不发，必无地理，此地若发，必无天理，既有天理循环之报，能久远昌盛者，未之有也。","chapter":"卷之四·谋地偷葬章第一百二十五","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.1","text":"祖父之墓或葬多年或未久，如来卜者必有其因，须宜悉明，方可决断O有因连年困苦疑，坟茔之不利。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.2","text":"有因屡科不发，或有子入场，疑此风水可能发科否？","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.3","text":"为己者须宜自占，为子孙者命子孙来占，有因仕途蹭蹬连岁不升，疑其风水有碍。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.4","text":"有因子孙不存，疑其风水相关。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.5","text":"有因六亲中父母兄弟妻儿或自身多生疾病，疑因风水所致。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.6","text":"有因连年官非火盗。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.7","text":"有因风水被伤，卜其何法而修补。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.8","text":"有因闲问祖茔有地脉否。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.9","text":"有问祖茔有伤损否。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.10","text":"皆以父母为用神。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.11","text":"卦遇六冲全无地脉，卦变化绝，势若倒悬，爻遇伏吟，欲迁不遂，反吟卦现，不迁亦迁，卦变六冲龙巳去，于孙有陵替之危。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.12","text":"冲中变合运将来，后代有兴隆之象O正卦六冲，变卦六冲，全无脉气，卦变化克，如倒悬之热，危之急矣，凶灾立至，伏吟卦地脉全无，虽有迁意而不能迁。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.13","text":"卦得反吟，心不欲迁而终迁矣。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.14","text":"卦变六冲有龙已去，子孙从此衰颓。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.15","text":"六冲变合，先无地脉，目今地运将兴，后代从此发矣。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.16","text":"父母旺相祖坟安然，墓绝休囚后裔零落O已葬之地，父母为用神，宜旺相，或日月动爻生扶，或动而化生日月化比助化进神乃吉地也，儿孙兴发之象，亡者安而生者乐。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.17","text":"旺而又遇帝旺长生者，来龙久远，世代兴隆，不宜墓绝空破，及动而破散化退神化绝墓化回头克化旬空化破散，乃凶象也，亡者不安，生者寥落。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.18","text":"世爻变鬼，占者不祥，鬼化六亲，各属不吉。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.19","text":"世爻变鬼及随墓助伤，所占之人不吉，兄弟妻子动而化鬼、鬼化兄弟父母妻子者，查其所犯而断也O又有子命化鬼，鼠命者殃。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.20","text":"午命变鬼，马命不利，余仿此。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.21","text":"野鹤曰：古以父爻不宜旺相，父旺父动子孙不安，余以为谬也。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.22","text":"占旧冢以父为用神，父母旺及动而化吉祖父安，然又扯到伤克子孙者是宜旺耶？","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c128.23","text":"惟子孙动而化父及父动化子孙，不利于子孙者是也。","chapter":"卷之四·祖茔旧家章第一百二十六","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.1","text":"野鹤曰：须宜另占，不可以前卦兼断，专看冲克父母之爻为忌神，如得六爻安静，父母有气，久后自安，不必补修。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.2","text":"克神临火或临朱雀，祸必起于窑灶。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.3","text":"倘临土动或兼元武，定因偷葬相伤。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.4","text":"木龙有蟠根之碍。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.5","text":"克神以带腾蛇，蛇蚁为巢。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.6","text":"土鬼勾陈挖掘动土。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.7","text":"元武临水水浸衾棺。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.8","text":"克神临火恐近处开窑作灶或因火烛之事。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.9","text":"土克父母兼元武者必有偷葬。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.10","text":"临勾陈腾蛇者筑墙盖屋以致相伤。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.11","text":"木逢龙动，穴下有竹木根伤。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.12","text":"火与蛇兴，冢内有蚁蛇为害。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.13","text":"元武水爻克父母，穴中黑水相侵。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.14","text":"父母被冲，地风水漫。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.15","text":"金克父母，石块山罔。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.16","text":"水冲克者，低洼水涌。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.17","text":"木爻克父，树木相伤。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.18","text":"火克者，穴藏蛇蚁。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.19","text":"土动者，盖造墙垣。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.20","text":"父母爻被日月动爻冲克及卦动化冲，如在艮坤之宫，卦得亥卯未合成木局克父，必有地风冲歪棺椁。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.21","text":"如在离宫，卦得申子辰水局克父者，穴中水涌，水泛棺歪。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.22","text":"如在震巽之宫，金局冲克者，山罔石块。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.23","text":"如在乾兑之宫逢火局冲克父母者，定因窑火雷惊。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.24","text":"爻中水动，地洼水浸。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.25","text":"卦得木动，竹木根滕。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.26","text":"火主虫蛇，土因动土，果有犯之，速宜修补。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.27","text":"爻无乱动，须观五行之有无，卦若安逸，又看地支之缺陷。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.28","text":"O六爻安静并无冲克父母之爻者，又看五行之所少也，卦中无土，须筑墙垣。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.29","text":"卦无金星，石碑可立。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.30","text":"六爻火星缺陷，可立烟灶，或安看守坟茔之宅舍。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.31","text":"水爻不现，可作池塘及开河道。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.32","text":"木爻不现，多栽树木。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c129.33","text":"此言五行之所少者，非独不上卦也，有现于爻空破墓绝无气者亦如无也。","chapter":"卷之四·因何事所伤章第一百二十七","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c130.1","text":"因窑灶而伤者，命道祭火神设火醮而安之。","chapter":"卷之四·修补秘法章第一百二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c130.2","text":"偷葬及动土相伤，命道设蘸以安土神。","chapter":"卷之四·修补秘法章第一百二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c130.3","text":"因受惊恐而伤者，命道设醮而安坟。","chapter":"卷之四·修补秘法章第一百二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c130.4","text":"或因有竹木蟠根及石块相伤者，须于坟旁挖坑三尺以探之，轻轻去其竹木石块，仍命道安坟则吉。","chapter":"卷之四·修补秘法章第一百二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c130.5","text":"倘因蛇蚁为巢者，多栽苦楝树其蛇蚁自散，勿信人以焚之其巢穴，伤损性命，余曾亲见两家见蛇为巢，用火焚之，后子孙衰败不堪。","chapter":"卷之四·修补秘法章第一百二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c130.6","text":"倘穴中因水淹没者，若有消水之法，设法以消之，倘因地洼终无消水之法，不得不选地而迁也。","chapter":"卷之四·修补秘法章第一百二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c130.7","text":"或因地风吹歪棺木者，前得挖坑二三尺，以探之，后果歪者仍归于正向，命道安坟则吉。","chapter":"卷之四·修补秘法章第一百二十八","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c131.1","text":"子孙持世，子孙动摇，修之则吉。","chapter":"卷之四·再占修补吉凶章第一百二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c131.2","text":"既问修补之吉凶，则认世爻为用，子孙持世，子孙发动，修之必获清安。","chapter":"卷之四·再占修补吉凶章第一百二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c131.3","text":"宜鬼世父爻空，迁则获福。","chapter":"卷之四·再占修补吉凶章第一百二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c131.4","text":"鬼克世，我必有害，父空破墓绝再被日月动爻伤克者，乃因伤者重，培补亦无益矣，当宜迁之。","chapter":"卷之四·再占修补吉凶章第一百二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c131.5","text":"觉子曰：古以迁茔之说，谓父母之墓受伤，儿孙一体之感，致生灾祸，理之有也。","chapter":"卷之四·再占修补吉凶章第一百二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c131.6","text":"迁茔改葬不得不行，观世人富者不贵，改祖墓以求荣，有子不富迁父冢以求富，将父母之遗体为市井之贷利，不意天理难容，身之未荣家产荡尽，财之未发绝减儿孙。","chapter":"卷之四·再占修补吉凶章第一百二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c131.7","text":"余之见者不可胜数，附此戒之。","chapter":"卷之四·再占修补吉凶章第一百二十九","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c132.1","text":"六冲变冲，卦变绝克，父母受伤，内外反吟，且宜他葬。","chapter":"卷之四·新亡附葬祖茔章第一百三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c132.2","text":"世爻受克随墓助伤，世动化克化鬼，附葬不宜。","chapter":"卷之四·新亡附葬祖茔章第一百三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c132.3","text":"父母兄弟妻儿动而化鬼化克，俱有刑冲伤重，惟喜世及六亲不逢变克，随卦静六合，必得存亡之安。","chapter":"卷之四·新亡附葬祖茔章第一百三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c132.4","text":"如子月丙申日占以父柩附葬祖苗得复之坤卦子孙酉金″子孙酉金″世妻财亥水″妻财亥水″兄弟丑土″应兄弟丑土″兄弟辰土″官鬼卯木″应官鬼寅木″父母巳火″妻财子水′世动兄弟未土″断曰：世爻被克，不宜附葬之。","chapter":"卷之四·新亡附葬祖茔章第一百三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c132.5","text":"数月后不断曰：腰疼欲死，欲迁其坟。","chapter":"卷之四·新亡附葬祖茔章第一百三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c132.6","text":"余曰：坟不必迁，卦中世爻被克，幸而旺相，土来克水，命道安土神则吉，果於安坟而愈。","chapter":"卷之四·新亡附葬祖茔章第一百三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c132.7","text":"余曰：目下虽不迁改，终有迁改。","chapter":"卷之四·新亡附葬祖茔章第一百三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c132.8","text":"余曰：化六冲不久之象。","chapter":"卷之四·新亡附葬祖茔章第一百三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c132.9","text":"果於子年死母，起此冢合葬於他处也。","chapter":"卷之四·新亡附葬祖茔章第一百三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"},{"segId":"zsby.c132.10","text":"增删卜易卷之四终。","chapter":"卷之四·新亡附葬祖茔章第一百三十","book":"增删卜易","canonicalId":"zengshanbuyi.ws.1912","author":"野鹤老人","edition":"公有领域转录（网络流传本）","confidenceLevel":"A","license":"公有领域"}];
